/**
 * Optional FZWR / @w web-ref helpers (omit file on minimal deploys).
 */
function fractal_zip_ensure_web_ref_loaded(): void {
	static $done = false;
	if ($done) {
		return;
	}
	$done = true;
	$path = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_web_ref.php';
	if (is_file($path) && is_readable($path)) {
		require_once $path;
		$probePath = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_web_ref_probe.php';
		if (is_file($probePath) && is_readable($probePath)) {
			require_once $probePath;
		}
		$applyPath = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_web_ref_apply.php';
		if (is_file($applyPath) && is_readable($applyPath)) {
			require_once $applyPath;
		}
		return;
	}
	if (!function_exists('fractal_zip_web_ref_strip_fzwr_suffix')) {
		function fractal_zip_web_ref_strip_fzwr_suffix(string $blob): string {
			return $blob;
		}
	}
	if (!function_exists('fractal_zip_web_ref_expand_fractal_string')) {
		function fractal_zip_web_ref_expand_fractal_string(string $fractalString): string {
			return $fractalString;
		}
	}
}
