}

/**
 * Run shell command with optional wall timeout; kill process group on expiry or PHP shutdown.
 *
 * @return array{ok: bool, exit: int}
 */
public static function exec_shell_with_timeout_and_kill(string $cmd, float $timeoutSec = 0.0): array {
	if(!function_exists('proc_open')) {
		exec($cmd . ' 2>/dev/null', $xo, $ret);
		return array('ok' => ((int) $ret) === 0, 'exit' => (int) $ret);
	}
	$desc = array(
		0 => array('file', '/dev/null', 'r'),
		1 => array('file', '/dev/null', 'w'),
		2 => array('file', '/dev/null', 'w'),
	);
	$proc = @proc_open($cmd, $desc, $pipes, null, null, fractal_zip::proc_open_bypass_shell_array());
	if(!is_resource($proc)) {
		exec($cmd . ' 2>/dev/null', $xo, $ret);
		return array('ok' => ((int) $ret) === 0, 'exit' => (int) $ret);
	}
	$finished = false;
	$killed = false;
	$terminate = static function () use ($proc, &$killed, &$finished): void {
		if($finished || $killed) {
			return;
		}
		$killed = true;
		$st = @proc_get_status($proc);
		if(is_array($st) && !empty($st['running'])) {
			$pid = (int) ($st['pid'] ?? 0);
			if($pid > 0 && function_exists('posix_kill')) {
				@posix_kill(-$pid, 9);
				@posix_kill($pid, 9);
			}
			@proc_terminate($proc, 9);
		}
		@proc_close($proc);
	};
	register_shutdown_function(static function () use ($terminate): void {
		$terminate();
	});
	$deadline = $timeoutSec > 0 ? (microtime(true) + $timeoutSec) : 0.0;
	$exit = -1;
	while(true) {
		$st = proc_get_status($proc);
		if(!is_array($st)) {
			break;
		}
		if(!$st['running']) {
			$exit = (int) ($st['exitcode'] ?? -1);
			break;
		}
		if($deadline > 0 && microtime(true) >= $deadline) {
			$terminate();
			return array('ok' => false, 'exit' => 124);
		}
		usleep(50000);
	}
	$finished = true;
	if(!$killed) {
		$exit = proc_close($proc);
	}
	return array('ok' => $exit === 0, 'exit' => (int) $exit);
}

/**
 * Cached interpretation of FRACTAL_ZIP_ZPAQ_OUTER_SWEEP (read on every zpaq outer trial and native zpaq compare).
 *
 * @return array{env_nonempty: bool, explicit_on: ?bool, is_exactly_one: bool}
 */
public static function zpaq_outer_sweep_env_flags_cached(): array {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_ZPAQ_OUTER_SWEEP');
	if($e === false || trim((string) $e) === '') {
		return $cached = array(
			'env_nonempty' => false,
			'explicit_on' => null,
			'is_exactly_one' => false,
		);
	}
	$t = trim((string) $e);
	$v = strtolower($t);
	$on = !($v === '0' || $v === 'off' || $v === 'false' || $v === 'no');
	return $cached = array(
		'env_nonempty' => true,
		'explicit_on' => $on,
		'is_exactly_one' => ($t === '1'),
	);
}

/**
 * Parsed FRACTAL_ZIP_ZPAQ_OUTER_METHODS (comma-separated argv fragments). Empty ⇒ use default -method ladder.
 *
 * @return list<string>
 */
public static function zpaq_outer_methods_argv_fragments_cached(): array {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$list = getenv('FRACTAL_ZIP_ZPAQ_OUTER_METHODS');
	if($list === false || trim((string) $list) === '') {
		return $cached = array();
	}
	$out = array();
	foreach(explode(',', (string) $list) as $piece) {
		$piece = trim($piece);
		if($piece === '') {
			continue;
		}
		$out[] = ($piece[0] === '-') ? (' ' . $piece) : (' -method ' . $piece);
	}
	return $cached = $out;
}

/**
 * Default upper bound for full zpaq method ladder on native folder compare (same default as getenv branch in maybe_folder_zpaq_*).
 */
public static function zpaq_native_full_sweep_max_raw_bytes_cached(): int {
