	}
	$v = (int) trim((string) $e);
	return $cached = ($v <= 0 ? 0 : min(2147483647, $v));
}

private static function php_memory_limit_bytes_for_guard(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$raw = ini_get('memory_limit');
	if($raw === false) {
		return $cached = 0;
	}
	$s = trim((string) $raw);
	if($s === '' || $s === '-1') {
		return $cached = 0;
	}
	$unit = strtolower(substr($s, -1));
	$num = (float) $s;
	if($num <= 0.0) {
		return $cached = 0;
	}
	if($unit === 'g') {
		$num *= 1024.0 * 1024.0 * 1024.0;
	} elseif($unit === 'm') {
		$num *= 1024.0 * 1024.0;
	} elseif($unit === 'k') {
		$num *= 1024.0;
	}
	return $cached = (int) min((float) PHP_INT_MAX, $num);
}

private static function whole_stream_fzws_has_memory_headroom(int $innerBytes): bool {
	if($innerBytes <= 0) {
		return true;
	}
	$limit = fractal_zip::php_memory_limit_bytes_for_guard();
	if($limit <= 0) {
		return true;
	}
	$used = memory_get_usage(true);
	// FZWS probing can hold base deflate output, transform body, wrapped body, and deflate work buffers at once.
	$needed = ($innerBytes * 6) + (64 * 1024 * 1024);
	return ($used + $needed) < $limit;
}

/**
 * When {@see outer_force_codec_is_zpaq()} and gzip‑1 picked an FZWS wrap, re-check wire size with zpaq (single
 * {@see zpaq_add_method_argv_fragment} trial) for inners ≤ this many bytes and keep the plain inner if zpaq does not shrink
 * the wrap (gzip often mis-ranks vs zpaq). {@code 0} disables the veto. Unset ⇒ 65536.
 */
public static function fzws_zpaq_veto_max_inner_bytes(): int {
	if(!self::outer_force_codec_is_zpaq()) {
		return 0;
	}
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FZWS_ZPAQ_VETO_MAX_INNER_BYTES');
	if($e === false || trim((string) $e) === '') {
		return $cached = 65536;
	}
	return $cached = max(0, (int) trim((string) $e));
}

/** Set a runtime preset name for this process (e.g. fs). */
public static function set_runtime_profile_preset($preset): void {
	if(!is_string($preset)) {
		self::$runtime_profile_preset = null;
		self::$runtime_profile_preset_version++;
		return;
	}
	$p = strtolower(trim($preset));
	self::$runtime_profile_preset = ($p === '') ? null : $p;
	self::$runtime_profile_preset_version++;
}

/** Normalized profile preset from runtime override or env (FRACTAL_ZIP_PROFILE / FRACTAL_ZIP_PRESET). */
public static function active_profile_preset(): ?string {
	static $cached = null;
	static $cachedVersion = -1;
	if($cachedVersion === self::$runtime_profile_preset_version) {
		return $cached;
	}
	$runtime = self::$runtime_profile_preset;
	if(is_string($runtime) && trim($runtime) !== '') {
		$cached = strtolower(trim($runtime));
		$cachedVersion = self::$runtime_profile_preset_version;
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_PROFILE');
	if($e === false || trim((string) $e) === '') {
		$e = getenv('FRACTAL_ZIP_PRESET');
	}
	if($e === false || trim((string) $e) === '') {
		$cached = null;
		$cachedVersion = self::$runtime_profile_preset_version;
		return $cached;
	}
	$p = strtolower(trim((string) $e));
	$cached = $p === '' ? null : $p;
	$cachedVersion = self::$runtime_profile_preset_version;
	return $cached;
}

/** FFS / filesystem throughput preset: speed-first, compute-capped defaults for large-scale usage. */
public static function fs_profile_enabled(): bool {
	$p = self::active_profile_preset();
	if($p === 'ffs' || $p === 'fs' || $p === 'filesystem') {
		return true;
	}
	return getenv('FRACTAL_ZIP_FS_PROFILE') === '1';
}

