			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
		$t = $p + 3;
		if(((ord($cb[$t]) - ord($rb[$t])) & 255) !== $db
			|| ((ord($cb[$t + 1]) - ord($rb[$t + 1])) & 255) !== $dg
			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
		$t = $p + 6;
		if(((ord($cb[$t]) - ord($rb[$t])) & 255) !== $db
			|| ((ord($cb[$t + 1]) - ord($rb[$t + 1])) & 255) !== $dg
			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
		$t = $p + 9;
		if(((ord($cb[$t]) - ord($rb[$t])) & 255) !== $db
			|| ((ord($cb[$t + 1]) - ord($rb[$t + 1])) & 255) !== $dg
			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
		$t = $p + 12;
		if(((ord($cb[$t]) - ord($rb[$t])) & 255) !== $db
			|| ((ord($cb[$t + 1]) - ord($rb[$t + 1])) & 255) !== $dg
			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
		$t = $p + 15;
		if(((ord($cb[$t]) - ord($rb[$t])) & 255) !== $db
			|| ((ord($cb[$t + 1]) - ord($rb[$t + 1])) & 255) !== $dg
			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
		$t = $p + 18;
		if(((ord($cb[$t]) - ord($rb[$t])) & 255) !== $db
			|| ((ord($cb[$t + 1]) - ord($rb[$t + 1])) & 255) !== $dg
			|| ((ord($cb[$t + 2]) - ord($rb[$t + 2])) & 255) !== $dr) {
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
