		$b0 = (ord($c[$q]) - ord($r[$q])) & 255;
		$b1 = (ord($c[$q + 1]) - ord($r[$q + 1])) & 255;
		$b2 = (ord($c[$q + 2]) - ord($r[$q + 2])) & 255;
		if($scalarOk && ($b0 !== $d || $b1 !== $d || $b2 !== $d)) {
			$scalarOk = false;
		}
		if($bgrOk && ($b0 !== $db || $b1 !== $dg || $b2 !== $dr)) {
			$bgrOk = false;
		}
		if(!$scalarOk && !$bgrOk) {
			$outScalar = null;
			$outDb = null;
			$outDg = null;
			$outDr = null;
			return;
		}
