/**
 * Strip one FZWS v1 wrapper (whole-stream transform on FZB4 inner). Magic FZWS + ver1 + tid + BE orig_len + body.
 */
function decode_fzws_v1_layer($wrapped) {
	$wrapped = (string) $wrapped;
	$n = strlen($wrapped);
	if($n < 10) {
		fractal_zip::fatal_error('Corrupt FZWS (truncated).');
	}
	if(substr($wrapped, 0, 4) !== 'FZWS') {
		fractal_zip::fatal_error('Corrupt FZWS (magic).');
	}
	if(ord($wrapped[4]) !== 1) {
		fractal_zip::fatal_error('Corrupt FZWS (unsupported version).');
	}
	$tid = ord($wrapped[5]);
	$u = unpack('NorigLen', substr($wrapped, 6, 4));
	$origLen = (int) ($u['origLen'] ?? 0);
	if($origLen < 0) {
		fractal_zip::fatal_error('Corrupt FZWS (length).');
	}
	$body = substr($wrapped, 10);
	if($tid === 1) {
		$inner = $this->delta_decode_bytes($body);
	} elseif($tid === 2) {
		$inner = $this->xor_adjacent_decode_bytes($body);
	} else {
		fractal_zip::fatal_error('Corrupt FZWS (unknown transform).');
	}
	if(strlen($inner) !== $origLen) {
		fractal_zip::fatal_error('Corrupt FZWS (length mismatch).');
	}
	return $inner;
}

/**
 * True if $inner is FZB4/5/6 or FZBD v1 wrapping one of those (whole-stream FZWS eligibility and outer heuristics).
 * One FZWS v1 layer is peeled first so `finalize_literal_bundle_inner_for_compress` outputs still classify as bundle literals.
 */
function bundle_inner_eligible_for_fzws($inner) {
	$inner = (string) $inner;
	$n = strlen($inner);
	$head4 = $n >= 4 ? substr($inner, 0, 4) : '';
	if($n >= 10 && $head4 === 'FZWS' && ord($inner[4]) === 1) {
		$tid = ord($inner[5]);
		$u = unpack('NorigLen', substr($inner, 6, 4));
		$origLen = (int) ($u['origLen'] ?? -1);
		if($origLen < 0) {
			return false;
		}
		$body = substr($inner, 10);
		if($tid === 1) {
			$unwrapped = $this->delta_decode_bytes($body);
		} elseif($tid === 2) {
			$unwrapped = $this->xor_adjacent_decode_bytes($body);
		} else {
			return false;
		}
		if(strlen($unwrapped) !== $origLen) {
			return false;
		}
		return $this->bundle_inner_eligible_for_fzws($unwrapped);
	}
	if($n < 4) {
		return false;
	}
	$sig = $head4;
	if($sig === 'FZB4' || $sig === 'FZB5' || $sig === 'FZB6') {
		return true;
	}
	if($sig === 'FZBM' && $n >= 5 && ord($inner[4]) === 1) {
		return true;
	}
	if($sig === 'FZBF' && $n >= 5 && ord($inner[4]) === 1) {
		return true;
	}
	if($sig !== 'FZBD' || $n < 10 || ord($inner[4]) !== 1) {
		return false;
	}
	$off = 5;
	$nt = $this->decode_varint_u32($inner, $off, $n, 'FZBD');
	if($nt < 0 || $nt > 65536) {
		return false;
	}
	for($ti = 0; $ti < $nt; $ti++) {
		$bl = $this->decode_varint_u32($inner, $off, $n, 'FZBD');
		if($bl < 0 || $off + $bl > $n) {
			return false;
		}
		$off += $bl;
	}
	if($off + 4 > $n) {
		return false;
	}
	$rest = substr($inner, $off, 4);
	return $rest === 'FZB4' || $rest === 'FZB5' || $rest === 'FZB6';
}

/**
 * Optional FZWS wrap when gzip‑1 probe beats raw inner (bounded by whole_stream_fzws_max_bytes).
 * With {@see outer_force_codec_is_zpaq}, gzip‑1’s winning wrap can be vetoed when zpaq wire size favors the plain inner
 * ({@see fractal_zip::fzws_zpaq_veto_max_inner_bytes}).
 */
function maybe_wrap_fzb_inner_with_fzws($inner) {
	$inner = (string) $inner;
	if(!fractal_zip::whole_stream_fzws_enabled()) {
		return $inner;
	}
	if(!$this->bundle_inner_eligible_for_fzws($inner)) {
		return $inner;
	}
	// FZBM/FZBF merged inners are often multi‑MiB of PCM/FLAC or other incompressible bulk; whole-stream delta/xor builds a second O(n) buffer and rarely wins gzip‑1 probes, but can exhaust RAM (e.g. album-sized FZBM during concat-order scoring).
	$n0 = strlen($inner);
	if($n0 >= 5) {
		$sig0 = substr($inner, 0, 4);
		if(($sig0 === 'FZBM' || $sig0 === 'FZBF') && ord($inner[4]) === 1) {
			return $inner;
		}
	}
	$maxB = fractal_zip::whole_stream_fzws_max_bytes();
	if($maxB > 0 && $n0 > $maxB) {
		return $inner;
	}
	if(!fractal_zip::whole_stream_fzws_has_memory_headroom($n0)) {
		return $inner;
	}
	$base = gzdeflate($inner, 1);
	if($base === false) {
		return $inner;
	}
	$bestScore = strlen($base);
	$bestWrap = '';
	foreach(array(1, 2) as $tid) {
		$body = $tid === 1 ? $this->delta_encode_bytes($inner) : $this->xor_adjacent_encode_bytes($inner);
		$wrapped = 'FZWS' . chr(1) . chr($tid) . pack('N', $n0) . $body;
		$z = gzdeflate($wrapped, 1);
		if($z !== false) {
			$zL = strlen($z);
			if($zL < $bestScore) {
				$bestScore = $zL;
				$bestWrap = $wrapped;
			}
		}
		unset($body, $wrapped, $z);
	}
	if($bestWrap !== '') {
		$vetoMax = fractal_zip::fzws_zpaq_veto_max_inner_bytes();
		if($vetoMax > 0 && $n0 <= $vetoMax) {
			$zpaqExe = fractal_zip::zpaq_executable();
			if($zpaqExe !== null && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ZPAQ')) {
				$mf = fractal_zip::zpaq_add_method_argv_fragment();
				$wIn = $this->outer_zpaq_blob_with_meth_fragment($zpaqExe, $inner, $mf);
				$wWr = $this->outer_zpaq_blob_with_meth_fragment($zpaqExe, $bestWrap, $mf);
				if($wIn !== null && $wIn !== '' && $wWr !== null && $wWr !== ''
					&& strlen($wIn) <= strlen($wWr)) {
					return $inner;
				}
			}
		}
	}
	return $bestWrap !== '' ? $bestWrap : $inner;
}

function finalize_literal_bundle_inner_for_compress($inner) {
	return $this->maybe_wrap_fzb_inner_with_fzws((string) $inner);
}

/**
 * Fork-pool entry: same baseline instance as dual-raw staged comparators (256, false, false, null, false).
 *
 * @return array{blob: string, codec: string|null, zpaq: string|null}
 */
public static function encode_pipeline_literal_outer_trial_full(string $finBlob): array {
	$fz = new fractal_zip(256, false, false, null, false);
	$blob = $fz->adaptive_compress($finBlob);
	return array(
		'blob' => $blob,
		'codec' => fractal_zip::$last_outer_codec,
		'zpaq' => fractal_zip::$last_zpaq_method,
	);
}

/**
 * @return array{blob: string, codec: string|null, zpaq: string|null}
 */
public static function encode_pipeline_literal_outer_trial_fast(string $finBlob): array {
	$fz = new fractal_zip(256, false, false, null, false);
	$blob = $fz->adaptive_compress_outer_fast_codec_tier($finBlob);
	return array(
		'blob' => $blob,
		'codec' => fractal_zip::$last_outer_codec,
		'zpaq' => fractal_zip::$last_zpaq_method,
	);
}

/**
 * Phase 3: smallest adaptive-compressed blob among literal inners (FZCD, FZB*, …) and raw escaped-per-file container.
 * Raw tier: builds disk-escaped and (when unwrap on) unescaped-escaped inners; if FRACTAL_ZIP_BUNDLE_RAW_DUAL_TIER is on (default) and the
 * two inners differ, compresses both and keeps the smaller outer — peel-restore only when the unwrapped variant wins. Literal inners still
 * read disk bytes so choose_best_literal_bundle_transform can record semantic/gzip stacks.
 * When FRACTAL_ZIP_FOLDER_STAGED_LITERAL_OUTER allows (auto: multi-file MPQ-family or mixed extensions), uses a fast
 * gzip+zstd+brotli tier for all candidates, then runs full adaptive_compress only on the best semantic inner if it beats
 * raw on that tier by at least FRACTAL_ZIP_STAGED_LITERAL_DEEP_MIN_FAST_MARGIN_BYTES (unset ⇒ max(48, min(8192,
 * floor(2.5% of raw’s fast-tier size))) — large trees still cap at 8192 B minimum improvement; small mixed-ext folders
 * can deepen after ~48–200 B. Override with the env var (bytes).
 * Below FRACTAL_ZIP_STAGED_LITERAL_FAST_OUTER_MIN_RAW_BYTES total raw (default 16 MiB), the staged fast path is **skipped**
 * and the full adaptive outer contest runs (same as unstaged) so FZB/FZBM/FZCD vs raw is ordered by true `.fz` bytes.
 * At or above that threshold, after the fast tier (and optional deepen pass), raw and the literal winner are re-scored with
 * full adaptive_compress so a semantic inner is never kept when raw is smaller or tied on wire bytes.
 *
 * @param list<array{inner: string, tag: string}> $innerVariants
 * @param array<string,string> $rawFilesByPath
 * @return array{0: string, 1: string}
 */
function choose_smallest_adaptive_literal_inner_or_raw_escaped(array $innerVariants, $rawFilesByPath) {
	$this->fractal_member_gzip_disk_restore = array();
	$innerVariants = fractal_zip_candidate_normalize_list($innerVariants, 'literal', 'literal_bundle');
	$innerVariants = fractal_zip::folder_bundle_apply_schedule_cost_bias_from_census($innerVariants, is_array($this->folder_bundle_census) ? $this->folder_bundle_census : null);
	fractal_zip_metastruct_ensure_folder_census_for_host($this);
	$innerVariants = fractal_zip_metastruct_apply_literal_schedule_bias(
		$innerVariants,
		is_array($this->folder_bundle_census) ? $this->folder_bundle_census : null,
		is_array($this->folder_metastruct_census) ? $this->folder_metastruct_census : null
	);
	// Lifestyle + decisive tiny run-grammar (showing_off): gzip the verified inner only.
	// Racing MiB-scale raw through brotli/zstd in the fast tier costs ~0.4s for a guaranteed loss.
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& $this->fractal_inner_run_grammar_variants_are_decisive($innerVariants, $rawFilesByPath)) {
		$bestBlob = null;
		$bestLen = PHP_INT_MAX;
		$bestTag = 'inner_verified_ops';
		$bestRestore = array();
		foreach($innerVariants as $v) {
			if(!is_array($v) || !isset($v['inner'])) {
				continue;
			}
			$tag = isset($v['tag']) ? (string) $v['tag'] : '';
			if(!str_starts_with($tag, 'inner_verified_ops')) {
				continue;
			}
			$fin = $this->finalize_literal_bundle_inner_for_compress((string) $v['inner']);
			$gz = gzdeflate($fin, 9);
			if($gz === false) {
				continue;
			}
			$restore = (isset($v['restore']) && is_array($v['restore'])) ? $v['restore'] : array();
			$wire = $this->append_restore_trailer_inside_outer_payload($gz, $restore);
			$wlen = strlen($wire);
			if($wlen < $bestLen) {
				$bestLen = $wlen;
				$bestBlob = $gz;
				$bestTag = $tag !== '' ? $tag : 'inner_verified_ops';
				$bestRestore = $restore;
			}
		}
		if($bestBlob !== null && $bestLen <= 2048) {
			fractal_zip::$last_outer_codec = 'gzip';
			fractal_zip::$last_written_container_codec = 'gzip';
			fractal_zip::$last_zpaq_method = null;
			$this->fractal_member_gzip_disk_restore = $bestRestore;
			return array($bestBlob, $bestTag);
		}
	}
	$rawTierPeelRestore = array();
	$rawEscapedDisk = array();
	$rawEscapedUnwrapped = array();
	$rawDirectDisk = array();
	$rawDirectUnwrapped = array();
	foreach($rawFilesByPath as $path => $bytes) {
		$p = (string) $path;
		$disk = (string) $bytes;
		$rawEscapedDisk[$p] = $this->escape_literal_for_storage($disk);
		$rawDirectDisk[$p] = $disk;
		$forUn = $disk;
		if($p !== '' && $disk !== '' && fractal_zip::bundle_raw_tier_deep_unwrap_enabled()) {
			fractal_zip_ensure_literal_pac_stack_loaded();
			list($work) = fractal_zip_literal_deep_unwrap_with_layers($p, $disk, false);
			if($work !== $disk) {
				$rawTierPeelRestore[$p] = $disk;
				$forUn = $work;
			}
		}
		$rawEscapedUnwrapped[$p] = $this->escape_literal_for_storage($forUn);
		$rawDirectUnwrapped[$p] = $forUn;
	}
	$innerVariantSchedule = fractal_zip_encode_pipeline::schedule_inner_variants_for_literal_outer($innerVariants);
	fractal_zip_encode_pipeline::html_trace_checkpoint(
		fractal_zip_encode_pipeline::PHASE_OUTER_CODECS,
		'choose_smallest: outer codec tournament (raw tier + literal inners)'
	);
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
	$rawInnerDisk = $this->encode_container_payload($rawEscapedDisk, '');
	if($rawEscapedDisk === $rawEscapedUnwrapped) {
		$rawInnerUnwrapped = $rawInnerDisk;
	} else {
		$rawInnerUnwrapped = $this->encode_container_payload($rawEscapedUnwrapped, '');
	}
	$singleRawDirectDisk = null;
	$singleRawDirectUnwrapped = null;
	if(count($rawDirectDisk) === 1) {
		if($rawDirectDisk === $rawDirectUnwrapped) {
			foreach($rawDirectDisk as $sp => $sb) {
				$singleRawDirectDisk = $this->encode_single_member_raw_payload((string) $sp, (string) $sb);
				break;
			}
			$singleRawDirectUnwrapped = $singleRawDirectDisk;
		} else {
			foreach($rawDirectDisk as $sp => $sb) {
				$singleRawDirectDisk = $this->encode_single_member_raw_payload((string) $sp, (string) $sb);
				break;
			}
			foreach($rawDirectUnwrapped as $sp => $sb) {
				$singleRawDirectUnwrapped = $this->encode_single_member_raw_payload((string) $sp, (string) $sb);
				break;
			}
		}
	}
	$rawInnerDiffers = ($rawInnerDisk !== $rawInnerUnwrapped);
	$tryDualRaw = fractal_zip::bundle_raw_tier_deep_unwrap_enabled() && fractal_zip::bundle_raw_tier_dual_compress_pick_enabled()
		&& $rawInnerDiffers;
	if($tryDualRaw && (int) $this->zip_folder_member_count === 1 && fractal_zip::lifestyle_speed_profile_enabled()) {
		$tryDualRaw = false;
	}
	$sumRawBytes = 0;
	foreach($rawFilesByPath as $rb) {
		$sumRawBytes += strlen((string) $rb);
	}
	$GLOBALS['fractal_zip_lifestyle_folder_sum_raw'] = $sumRawBytes;
	$GLOBALS['fractal_zip_lifestyle_folder_member_count'] = count($rawFilesByPath);
	$skipAdaptiveSlowOuterForNativeZpaqFolder = fractal_zip::folder_native_zpaq_compare_will_be_available_for_raw_bytes($sumRawBytes);
	$adaptiveSlowOuterSkipEnvNames = array(
		'FRACTAL_ZIP_SKIP_ZPAQ',
		'FRACTAL_ZIP_SKIP_7Z',
		'FRACTAL_ZIP_SKIP_ARC',
		'FRACTAL_ZIP_SKIP_XZ',
	);
	$oldAdaptiveSlowOuterSkipEnv = array();
	foreach($adaptiveSlowOuterSkipEnvNames as $envName) {
		$oldAdaptiveSlowOuterSkipEnv[$envName] = getenv($envName);
	}
	$restoreAdaptiveSlowOuterSkipEnv = function() use ($oldAdaptiveSlowOuterSkipEnv) {
		foreach($oldAdaptiveSlowOuterSkipEnv as $envName => $oldValue) {
			if($oldValue === false) {
				putenv($envName);
			} else {
				putenv($envName . '=' . (string) $oldValue);
			}
		}
	};
	if($skipAdaptiveSlowOuterForNativeZpaqFolder) {
		foreach($adaptiveSlowOuterSkipEnvNames as $envName) {
			putenv($envName . '=1');
		}
	}
	$fastOuterMinRaw = fractal_zip::staged_literal_fast_outer_min_raw_bytes();
	$meetRawFloor = false;
	if($fastOuterMinRaw > 0) {
		if($sumRawBytes >= $fastOuterMinRaw) {
			$meetRawFloor = true;
		} elseif(fractal_zip::folder_staged_literal_outer_homogeneous_many_files_eligible($rawFilesByPath)) {
			$homMin = fractal_zip::staged_literal_homogeneous_fast_outer_min_raw_bytes();
			if($homMin > 0 && $sumRawBytes >= $homMin) {
				$meetRawFloor = true;
			}
		} elseif(sizeof($rawFilesByPath) === 1) {
			$sft = fractal_zip::folder_staged_literal_outer_single_file_min_raw_bytes_threshold();
			if($sft > 0 && $sumRawBytes >= $sft) {
				$meetRawFloor = true;
			}
		} elseif(fractal_zip::folder_staged_literal_outer_enabled($rawFilesByPath)) {
			$sTreeMin = fractal_zip::folder_staged_literal_outer_small_tree_min_raw_bytes();
			if($sTreeMin > 0 && $sumRawBytes >= $sTreeMin) {
				$meetRawFloor = true;
			}
		}
	}
	$useStagedFastOuterPath = fractal_zip::folder_staged_literal_outer_enabled($rawFilesByPath)
		&& $meetRawFloor;
	// Lifestyle tiny: always staged fast outers (never full adaptive_compress storms on micro trees).
	if(!$useStagedFastOuterPath && fractal_zip::lifestyle_should_skip_heavy_startup_for_raw_bytes($sumRawBytes)) {
		$useStagedFastOuterPath = true;
	}
	$literalJobList = array();
	$literalJobListAll = array();
	$literalOverflowJobList = array();
	$literalCapApplied = false;
	$literalRestoreByTie = array();
	$literalTieN = 0;
	foreach($innerVariantSchedule as $vi => $v) {
		if(!is_array($v) || !isset($v['inner'])) {
			continue;
		}
		$inner = (string) $v['inner'];
		if($inner === '') {
			continue;
		}
		$tag = isset($v['tag']) ? (string) $v['tag'] : 'literal';
		$tie = $literalTieN++;
		$innerVariantSchedule[$vi]['__tie'] = $tie;
		$literalRestoreByTie[$tie] = (isset($v['restore']) && is_array($v['restore'])) ? $v['restore'] : array();
		$literalJobList[] = array(
			'fin' => $this->finalize_literal_bundle_inner_for_compress($inner),
			'tag' => $tag,
			'tie' => $tie,
		);
	}
	$literalJobListAll = $literalJobList;
	$profileReciprocalFastPath = fractal_zip::substring_reciprocal_enabled()
		? $this->folder_reciprocal_inner_fast_path_enabled($rawFilesByPath)
		: false;
	$maxLiteralJobs = 0;
	if(fractal_zip::substring_multidiff_recursive_only_enabled() || $profileReciprocalFastPath) {
		$maxLiteralJobs = max($maxLiteralJobs, fractal_zip::substring_multidiff_max_literal_jobs());
	}
	$speedCap = fractal_zip::lifestyle_literal_outer_job_cap($sumRawBytes, count($rawFilesByPath));
	if($speedCap > 0) {
		if($maxLiteralJobs <= 0) {
			$maxLiteralJobs = $speedCap;
		} else {
			$maxLiteralJobs = min($maxLiteralJobs, $speedCap);
		}
	}
	if(count($rawFilesByPath) <= 1 && fractal_zip::lifestyle_speed_profile_enabled()) {
		$singleMemberCap = fractal_zip::lifestyle_single_member_literal_outer_job_cap();
		if($singleMemberCap > 0) {
			if($maxLiteralJobs <= 0) {
				$maxLiteralJobs = $singleMemberCap;
			} else {
				$maxLiteralJobs = min($maxLiteralJobs, $singleMemberCap);
			}
		}
	}
	// Lifestyle tiny: one literal outer trial is enough before the cheap native 7z compare;
	// parallel multi-variant fast outers are the multi-hundred-ms burn on Squash singles.
	// Keep multi-job for small fractal-likely micros (test_files21-class ~4 B win).
	if(fractal_zip::lifestyle_should_use_tiny_outer_shortcuts($sumRawBytes, $rawFilesByPath)) {
		if($maxLiteralJobs <= 0) {
			$maxLiteralJobs = 1;
		} else {
			$maxLiteralJobs = min($maxLiteralJobs, 1);
		}
	}
	if($maxLiteralJobs > 0 && count($literalJobList) > $maxLiteralJobs) {
		$literalCapApplied = true;
		$literalOverflowJobList = array_slice($literalJobList, $maxLiteralJobs);
		$literalJobList = array_slice($literalJobList, 0, $maxLiteralJobs);
		$allowedTies = array();
		foreach($literalJobList as $job) {
			if(isset($job['tie'])) {
				$allowedTies[(int) $job['tie']] = true;
			}
		}
		if($allowedTies !== array()) {
			$innerVariantSchedule = array_values(array_filter($innerVariantSchedule, static function($v) use ($allowedTies): bool {
				return is_array($v) && isset($v['__tie']) && isset($allowedTies[(int) $v['__tie']]);
			}));
		}
	}
	$literalBlobWireLen = function($blob, $tie, $fastTier = false) use (&$literalRestoreByTie) {
		$blob = (string) $blob;
		$restore = $literalRestoreByTie[(int) $tie] ?? array();
		if(!is_array($restore) || $restore === array()) {
			return strlen($blob);
		}
		$withRestore = $fastTier
			? $this->append_restore_trailer_inside_outer_payload_fast($blob, $restore)
			: $this->append_restore_trailer_inside_outer_payload($blob, $restore);
		return strlen($withRestore);
	};
	$adjustLiteralRowsForRestoreWire = function($rows, $fastTier = false) use ($literalBlobWireLen) {
		if(!is_array($rows)) {
			return $rows;
		}
		foreach($rows as $ri => $row) {
			if($row === null || !is_array($row) || !isset($row['blob'], $row['tie'])) {
				continue;
			}
			$rows[$ri]['len'] = $literalBlobWireLen((string) $row['blob'], (int) $row['tie'], $fastTier);
		}
		return $rows;
	};
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment('choose_smallest_phase4_encode_raw_and_literal_jobs');
	if(!$useStagedFastOuterPath) {
		$bestZpaqMeth = null;
		$rawWireLen = null;
		$rawTierRestoreForDirect = array();
		if($tryDualRaw) {
			$fzD = new fractal_zip(256, false, false, null, false);
			$rawDiskBlob = $fzD->adaptive_compress($rawInnerDisk);
			$wireDisk = strlen($fzD->append_restore_trailer_inside_outer_payload($rawDiskBlob, array()));
			$codecDisk = fractal_zip::$last_outer_codec;
			$zDiskM = ($codecDisk === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
			$fzU = new fractal_zip(256, false, false, null, false);
			$rawUnBlob = $fzU->adaptive_compress_inner_payload_with_restore_trailer($rawInnerUnwrapped, $rawTierPeelRestore, false);
			$wireUn = strlen($rawUnBlob);
			$codecUn = fractal_zip::$last_outer_codec;
			$zUnM = ($codecUn === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
			if(fractal_zip::outer_candidate_beats_current((string) $codecUn, $wireUn, (string) $codecDisk, $wireDisk)) {
				$rawContents = $rawUnBlob;
				$codecRaw = $codecUn;
				$rawTierRestoreForPick = array();
				$rawTierRestoreForDirect = $rawTierPeelRestore;
				$rawWireLen = $wireUn;
				$bestZpaqMeth = $zUnM;
			} else {
				$rawContents = $rawDiskBlob;
				$codecRaw = $codecDisk;
				$rawTierRestoreForPick = array();
				$rawWireLen = $wireDisk;
				$bestZpaqMeth = $zDiskM;
			}
		} else {
			$rawPickInner = $rawInnerDiffers && fractal_zip::bundle_raw_tier_deep_unwrap_enabled() ? $rawInnerUnwrapped : $rawInnerDisk;
			$rawContents = $this->adaptive_compress($rawPickInner);
			$codecRaw = fractal_zip::$last_outer_codec;
			$bestZpaqMeth = ($codecRaw === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
			$rawTierRestoreForPick = ($rawPickInner === $rawInnerUnwrapped && $rawInnerDiffers) ? $rawTierPeelRestore : array();
			$rawWireLen = strlen($this->append_restore_trailer_inside_outer_payload($rawContents, $rawTierRestoreForPick));
		}
		if($singleRawDirectDisk !== null && $singleRawDirectUnwrapped !== null) {
			$rawDirectInner = ($rawTierRestoreForDirect !== array()) ? $singleRawDirectUnwrapped : $singleRawDirectDisk;
			$rawDirectContents = $this->adaptive_compress_inner_payload_with_restore_trailer($rawDirectInner, $rawTierRestoreForDirect, false);
			$codecDirect = fractal_zip::$last_outer_codec;
			$zDirM = ($codecDirect === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
			$rawDirectWireLen = strlen($rawDirectContents);
			if(fractal_zip::outer_candidate_beats_current((string) $codecDirect, $rawDirectWireLen, (string) $codecRaw, (int) $rawWireLen)) {
				$rawContents = $rawDirectContents;
				$codecRaw = $codecDirect;
				$bestZpaqMeth = $zDirM;
				$rawWireLen = $rawDirectWireLen;
				$rawTierRestoreForPick = array();
			}
		}
		$bestLen = (int)$rawWireLen;
		$bestBlob = $rawContents;
		$bestTag = 'raw';
		$bestCodec = $codecRaw;
		$bestRestoreForPick = $rawTierRestoreForPick;
		$parFull = null;
		if(sizeof($literalJobList) >= 2) {
			fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
			$parFull = fractal_zip_encode_pipeline::parallel_literal_variant_outer_trials($literalJobList, 'full');
			fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment('choose_smallest_parallel_literal_outer_trials_full');
		}
		if($parFull !== null) {
			$parFull = $adjustLiteralRowsForRestoreWire($parFull);
			list($mergeLen, $litWin) = fractal_zip_encode_pipeline::pick_smallest_literal_outer_vs_raw($bestLen, $parFull, $bestCodec);
			$bestLen = $mergeLen;
			if($litWin !== null) {
				$bestBlob = $litWin['blob'];
				$bestTag = $litWin['tag'];
				$bestCodec = $litWin['codec'];
				$bestZpaqMeth = ($litWin['codec'] === 'zpaq') ? $litWin['zpaq'] : null;
				$bestRestoreForPick = $literalRestoreByTie[(int)$litWin['tie']] ?? array();
			}
		} else {
			foreach($innerVariantSchedule as $v) {
				if(!is_array($v) || !isset($v['inner'])) {
					continue;
				}
				$inner = (string) $v['inner'];
				if($inner === '') {
					continue;
				}
				$tag = isset($v['tag']) ? (string) $v['tag'] : 'literal';
				$bundleContents = $this->adaptive_compress($this->finalize_literal_bundle_inner_for_compress($inner));
				$codecB = fractal_zip::$last_outer_codec;
				$zB = ($codecB === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
				$lb = strlen($this->append_restore_trailer_inside_outer_payload(
					$bundleContents,
					(isset($v['restore']) && is_array($v['restore'])) ? $v['restore'] : array()
				));
			if(fractal_zip::outer_candidate_beats_current((string) $codecB, $lb, (string) $bestCodec, $bestLen)) {
					$bestLen = $lb;
					$bestBlob = $bundleContents;
					$bestTag = $tag;
					$bestCodec = $codecB;
					$bestZpaqMeth = $zB;
					$bestRestoreForPick = (isset($v['restore']) && is_array($v['restore'])) ? $v['restore'] : array();
				}
			}
		}
		if(fractal_zip::fs_profile_enabled()
			&& $sumRawBytes >= fractal_zip::fs_profile_literal_guardrail_min_raw_bytes()
			&& count($rawFilesByPath) > 1
			&& $literalCapApplied
			&& $literalOverflowJobList !== array()) {
			$guardPct = fractal_zip::fs_profile_literal_guardrail_pct();
			if($guardPct > 0.0) {
				$probeLimit = fractal_zip::fs_profile_literal_guardrail_probe_jobs();
				$probeJobs = $literalOverflowJobList;
				if(count($probeJobs) > $probeLimit) {
					$probeJobs = array_slice($probeJobs, 0, $probeLimit);
				}
				$refLen = null;
				$refTie = null;
				$parFastGuard = null;
				if(count($probeJobs) >= 2) {
					$parFastGuard = fractal_zip_encode_pipeline::parallel_literal_variant_outer_trials($probeJobs, 'fast');
				}
				if($parFastGuard !== null) {
					$parFastGuard = $adjustLiteralRowsForRestoreWire($parFastGuard, true);
					foreach($parFastGuard as $row) {
						if(!is_array($row) || !isset($row['len'], $row['tie'])) {
							continue;
						}
						$lenN = (int) $row['len'];
						if($refLen === null || $lenN < $refLen) {
							$refLen = $lenN;
							$refTie = (int) $row['tie'];
						}
					}
				} elseif(isset($probeJobs[0]) && is_array($probeJobs[0])) {
					$one = $probeJobs[0];
					if(isset($one['fin'], $one['tie'])) {
						$fzFast = new fractal_zip(256, false, false, null, false);
						$fastBlob = $fzFast->adaptive_compress_outer_fast_codec_tier((string) $one['fin']);
						$refTie = (int) $one['tie'];
						$refLen = $literalBlobWireLen((string) $fastBlob, $refTie, true);
					}
				}
				if($refLen !== null) {
					$allowedMax = (int) floor((float) $refLen * (1.0 + ($guardPct / 100.0)));
					if($bestLen > $allowedMax && $refTie !== null) {
						foreach($literalOverflowJobList as $job) {
							if(!is_array($job) || !isset($job['tie'], $job['fin'])) {
								continue;
							}
							if((int) $job['tie'] !== (int) $refTie) {
								continue;
							}
							$candBlob = $this->adaptive_compress((string) $job['fin']);
							$candCodec = fractal_zip::$last_outer_codec;
							$candZ = ($candCodec === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
							$candLen = $literalBlobWireLen((string) $candBlob, (int) $refTie, false);
							if(fractal_zip::outer_candidate_beats_current((string) $candCodec, $candLen, (string) $bestCodec, $bestLen)) {
								$bestLen = $candLen;
								$bestBlob = $candBlob;
								$bestTag = isset($job['tag']) ? (string) $job['tag'] : 'literal';
								$bestCodec = (string) $candCodec;
								$bestZpaqMeth = $candZ;
								$bestRestoreForPick = $literalRestoreByTie[(int) $refTie] ?? array();
