			}
		}
		fractal_zip::$last_outer_codec = $bestCodec;
		fractal_zip::$last_written_container_codec = $bestCodec;
		if($bestCodec === 'zpaq' && is_string($bestZpaqMeth) && $bestZpaqMeth !== '' && preg_match('/^[0-9]+$/', (string) $bestZpaqMeth) === 1) {
			fractal_zip::$last_zpaq_method = (string) $bestZpaqMeth;
		} else {
			fractal_zip::$last_zpaq_method = null;
		}
		$this->fractal_member_gzip_disk_restore = $bestRestoreForPick;
		$restoreAdaptiveSlowOuterSkipEnv();
		return array($bestBlob, $bestTag);
	}
	$bestZpaqMeth = null;
	if($tryDualRaw) {
		$fzSd = new fractal_zip(256, false, false, null, false);
		$rpDisk = $fzSd->adaptive_compress_outer_fast_codec_tier($rawInnerDisk);
		$wireFd = strlen($fzSd->append_restore_trailer_inside_outer_payload($rpDisk, array()));
		$codecDiskS = fractal_zip::$last_outer_codec;
		$zDiskS = ($codecDiskS === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
		$fzSu = new fractal_zip(256, false, false, null, false);
			$rpUn = $fzSu->adaptive_compress_inner_payload_with_restore_trailer($rawInnerUnwrapped, $rawTierPeelRestore, true);
			$wireFu = strlen($rpUn);
		$codecUnS = fractal_zip::$last_outer_codec;
		$zUnS = ($codecUnS === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
		if(fractal_zip::outer_candidate_beats_current((string) $codecUnS, $wireFu, (string) $codecDiskS, $wireFd)) {
			$rp = $rpUn;
				$rawTierRestoreForPick = array();
			$bestCodec = $codecUnS;
			$bestZpaqMeth = $zUnS;
		} else {
			$rp = $rpDisk;
			$rawTierRestoreForPick = array();
			$bestCodec = $codecDiskS;
			$bestZpaqMeth = $zDiskS;
		}
	} else {
		$rawPickInner = $rawInnerDiffers && fractal_zip::bundle_raw_tier_deep_unwrap_enabled() ? $rawInnerUnwrapped : $rawInnerDisk;
		$rp = $this->adaptive_compress_outer_fast_codec_tier($rawPickInner);
		$rawTierRestoreForPick = ($rawPickInner === $rawInnerUnwrapped && $rawInnerDiffers) ? $rawTierPeelRestore : array();
		$bestCodec = fractal_zip::$last_outer_codec;
		$bestZpaqMeth = ($bestCodec === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
	}
	$rawFastLen = strlen($this->append_restore_trailer_inside_outer_payload($rp, $rawTierRestoreForPick));
	// Single-member FZS1 (compact path+bytes) often beats FZC5 on micros (test_files21: 38 vs 42).
	// Non-staged path already compares this; lifestyle tiny forces staged and was skipping it.
	if($singleRawDirectDisk !== null && $singleRawDirectUnwrapped !== null) {
		$rawDirectInner = ($rawTierPeelRestore !== array() && $singleRawDirectUnwrapped !== $singleRawDirectDisk)
			? $singleRawDirectUnwrapped
			: $singleRawDirectDisk;
		$rawDirectRestore = ($rawDirectInner === $singleRawDirectUnwrapped && $singleRawDirectUnwrapped !== $singleRawDirectDisk)
			? $rawTierPeelRestore
			: array();
		$rpDirect = $this->adaptive_compress_outer_fast_codec_tier($rawDirectInner);
		$codecDirect = fractal_zip::$last_outer_codec;
		$zDirect = ($codecDirect === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
		$wireDirect = strlen($this->append_restore_trailer_inside_outer_payload($rpDirect, $rawDirectRestore));
		if(fractal_zip::outer_candidate_beats_current((string) $codecDirect, $wireDirect, (string) $bestCodec, $rawFastLen)) {
			$rp = $rpDirect;
			$rawTierRestoreForPick = $rawDirectRestore;
			$bestCodec = $codecDirect;
			$bestZpaqMeth = $zDirect;
			$rawFastLen = $wireDirect;
		}
	}
	// Lifestyle micro singles: FZS1+gzip already matches historical winners. Skip the
	// literal fast-tier storm (and for larger micros like grammar.lsp, skip brotli races).
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& is_string($singleRawDirectDisk)
		&& str_starts_with($singleRawDirectDisk, 'FZS1')
		&& $sumRawBytes <= 8192
		&& $rawFastLen > 0
		&& $rawFastLen <= 2048) {
		$fzs1Gz = gzdeflate($singleRawDirectDisk, 9);
		if($fzs1Gz !== false && strlen($fzs1Gz) <= $rawFastLen && strlen($fzs1Gz) <= 2048) {
			fractal_zip::$last_outer_codec = 'gzip';
			fractal_zip::$last_written_container_codec = 'gzip';
			fractal_zip::$last_zpaq_method = null;
			$this->fractal_member_gzip_disk_restore = array();
			$restoreAdaptiveSlowOuterSkipEnv();
