				$bestLitFin = $fin;
				$bestLitTag = $tag;
				$bestLitTie = isset($v['__tie']) ? (int)$v['__tie'] : null;
				$bestLitCodec = (string) $codecB;
			}
		}
	}
	$deepMinB = fractal_zip::staged_literal_deep_min_bytes();
	$fastMargin = fractal_zip::staged_literal_deep_fast_margin_bytes_or_negative();
