			$bestBlob = $deepBlob;
			$bestTag = $bestLitTag;
			$bestCodec = $deepCodec;
			$bestZpaqMeth = $zDeep;
			$bestChampionFin = $bestLitFin;
			$literalUsesFullAdaptive = true;
			$bestRestoreForPick = $bestLitTie !== null ? ($literalRestoreByTie[$bestLitTie] ?? array()) : $bestRestoreForPick;
		}
	}
