			$zLitF = ($litFullCodec === 'zpaq') ? fractal_zip::$last_zpaq_method : null;
		} else {
			$litFullLen = $bestLen;
			$litFullCodec = $bestCodec;
			$zLitF = $bestZpaqMeth;
		}
		$rawFullBeatsLiteral = fractal_zip::outer_candidate_beats_current((string) $rawFullCodec, $rawFullLen, (string) $litFullCodec, $litFullLen);
		if(!$rawFullBeatsLiteral && $rawFullLen === $litFullLen && (string) $rawFullCodec === (string) $litFullCodec) {
			$rawFullBeatsLiteral = true;
		}
		if($rawFullBeatsLiteral) {
			$bestBlob = (string) $rawFullBlob;
			$bestTag = 'raw';
			$bestCodec = $rawFullCodec;
			$bestZpaqMeth = $rawFullZ;
			$rawTierRestoreForPick = $rawFullRestore;
			$bestRestoreForPick = $rawFullRestore;
		} elseif(!$literalUsesFullAdaptive && $bestChampionFin !== null) {
			$bestBlob = (string) $litFullBlob;
			$bestCodec = $litFullCodec;
			$bestZpaqMeth = $zLitF;
			$bestRestoreForPick = $bestLitTie !== null ? ($literalRestoreByTie[$bestLitTie] ?? array()) : $bestRestoreForPick;
		}
	}
	fractal_zip::$last_outer_codec = $bestCodec;
	fractal_zip::$last_written_container_codec = $bestCodec;
	if($bestCodec === 'zpaq' && is_string($bestZpaqMeth) && $bestZpaqMeth !== '' && preg_match('/^[0-9]+$/', (string) $bestZpaqMeth) === 1) {
		fractal_zip::$last_zpaq_method = (string) $bestZpaqMeth;
	} else {
		fractal_zip::$last_zpaq_method = null;
	}
	$this->fractal_member_gzip_disk_restore = $bestRestoreForPick;
	$restoreAdaptiveSlowOuterSkipEnv();
	return array($bestBlob, $bestTag);
}

/**
 * Peel-restore map after {@see choose_smallest_adaptive_literal_inner_or_raw_escaped} (literal contest fork reads this into JSON).
 *
 * @return array<string, string>
 */
public function fractal_member_gzip_disk_restore_literal_fork_snapshot(): array {
	return $this->fractal_member_gzip_disk_restore;
}

/**
 * @param array<string,string> $rawFilesByPath
 * @return array{0: string, 1: string}
 */
function choose_smaller_adaptive_bundle_or_raw_escaped($bundlePayload, $rawFilesByPath) {
	return $this->choose_smallest_adaptive_literal_inner_or_raw_escaped(
		array(fractal_zip_candidate_from_inner((string) $bundlePayload, 'bundle', 'legacy', 'bundle')),
		$rawFilesByPath
	);
}

/**
 * Phase 2: FZBF (merged + nested fractal) is built in collect_literal_bundle_inner_variants when
 * FRACTAL_ZIP_UNIFIED_LITERAL_MULTIPASS / auto gate. Opaque inners (FZBF, FZCD) are left unchanged here.
 */
function maybe_apply_unified_literal_multipass($inner) {
	$inner = (string) $inner;
	if($inner !== '' && strlen($inner) >= 4) {
		$sig = substr($inner, 0, 4);
		if($sig === 'FZBF' || $sig === 'FZCD') {
			return $inner;
		}
	}
	return $inner;
}

/**
 * Phase 1–2: FZCD merged-PCM transmedia when `FRACTAL_ZIP_FLACPAC=1` and applicable; FZBM merged raw (≥2 files); FZBF merged + nested fractal when multipass synth gate passes (merged blob stats);
 * FZB* from encode_literal_bundle_payload (unwrap + transforms + FZBD auto).
 *
 * @param array<string,string> $rawFilesByPath ksorted rel => disk bytes
 * @return list<array{inner: string, tag: string}>
 */
function collect_literal_bundle_inner_variants_for_folder($root, array $rawFilesByPath) {
	$variants = array();
	$stageTimingEnabled = getenv('FRACTAL_ZIP_DEBUG_STAGE_TIMING') === '1';
	$stageLog = function(string $label, float $startedAt) use ($stageTimingEnabled): void {
		if(!$stageTimingEnabled || PHP_SAPI !== 'cli' || !is_resource(STDERR)) {
			return;
		}
		$ms = (microtime(true) - $startedAt) * 1000.0;
		@fwrite(STDERR, '[fz stage] ' . $label . ' ' . number_format($ms, 1, '.', '') . " ms\n");
	};
	$cacheKey = null;
	if(fractal_zip::substring_reciprocal_enabled() && $rawFilesByPath !== array()) {
		$sigParts = array((string)$root, (string)count($rawFilesByPath));
		foreach($rawFilesByPath as $p => $bytes) {
			$b = (string)$bytes;
			$n = strlen($b);
			$head = substr($b, 0, min(2048, $n));
			$tail = ($n > 2048) ? substr($b, -2048) : '';
			$sampleHash = hash('xxh3', $head . "\0" . $tail, false);
			$sigParts[] = (string)$p . "\0" . (string)$n . "\0" . (string)$sampleHash;
		}
		$cacheKey = hash('sha256', implode("\n", $sigParts), false);
		if(isset($this->reciprocal_literal_bundle_variants_cache[$cacheKey])) {
			$stageLog('collect_literal_variants.cache_hit', microtime(true));
			return $this->reciprocal_literal_bundle_variants_cache[$cacheKey];
		}
	}
	fractal_zip_encode_pipeline::html_trace_checkpoint(
		fractal_zip_encode_pipeline::PHASE_STREAM_BUILD,
		'collect_literal_bundle_inner_variants: FZCD / FZBM / FZBF / FZB chain'
	);
	$paths = array_keys($rawFilesByPath);
	$fzuniKey = fractal_zip::hot_string_digest((string) $root . "\0" . implode("\n", $paths));
	$tmpFzcd = sys_get_temp_dir() . DS . 'fzuni_' . substr(md5($fzuniKey . "\0fzuni\0" . (string) spl_object_id($this)), 0, 16);
	$tStep = microtime(true);
	if($this->write_fzcd_bundle_if_applicable($root, $paths, $tmpFzcd)) {
		$stageLog('collect_literal_variants.write_fzcd_bundle_if_applicable', $tStep);
		$fzcd = file_get_contents($tmpFzcd);
		@unlink($tmpFzcd);
		if($fzcd !== false && $fzcd !== '') {
			$variants[] = fractal_zip_candidate_from_inner((string) $fzcd, 'fzcd', 'literal', 'fzcd');
		}
	} else {
		$stageLog('collect_literal_variants.write_fzcd_bundle_if_applicable', $tStep);
		if(is_file($tmpFzcd)) {
			@unlink($tmpFzcd);
		}
	}
	$fzbmCap = fractal_zip::literal_merged_fzbm_max_raw_bytes_cap();
	$skipLegacyMergedFractalBundle = fractal_zip::substring_multidiff_recursive_only_enabled()
		|| (fractal_zip::substring_reciprocal_enabled() && $this->folder_reciprocal_inner_fast_path_enabled($rawFilesByPath));
	$skipMergedFzbmForReciprocal = $skipLegacyMergedFractalBundle;
	$totalRaw = 0;
	foreach($rawFilesByPath as $b) {
		$totalRaw += strlen((string) $b);
	}
	if(sizeof($rawFilesByPath) >= 2 && !$skipMergedFzbmForReciprocal && fractal_zip::literal_merged_fzbm_inner_enabled() && ($fzbmCap <= 0 || $totalRaw <= $fzbmCap)) {
		$tStep = microtime(true);
		$fzbmInner = $this->encode_fzbm_v1_merged_literal($rawFilesByPath);
		$stageLog('collect_literal_variants.encode_fzbm_v1_merged_literal', $tStep);
		if($fzbmInner !== '') {
			$fzbmInner = $this->maybe_apply_unified_literal_multipass($fzbmInner);
			$variants[] = fractal_zip_candidate_from_inner($fzbmInner, 'fzbm', 'literal', 'fzbm');
		}
	} elseif($skipMergedFzbmForReciprocal) {
		$stageLog('collect_literal_variants.skip_encode_fzbm_v1_merged_literal', microtime(true));
	}
	if(sizeof($rawFilesByPath) >= 1 && !$skipLegacyMergedFractalBundle) {
		$fzbfGate = fractal_zip::unified_literal_multipass_synth_enabled_for_raw_bytes($totalRaw, '');
		if(!$fzbfGate) {
			$tStep = microtime(true);
			$mergedProbe = $this->merged_raw_concat_for_literal_bundle_map($rawFilesByPath);
			$stageLog('collect_literal_variants.merged_raw_concat_for_literal_bundle_map', $tStep);
			$fzbfGate = fractal_zip::unified_literal_multipass_synth_enabled_for_raw_bytes($totalRaw, $mergedProbe);
		}
		if($fzbfGate) {
			$tStep = microtime(true);
			$fzbfInner = $this->encode_fzbf_v1_merged_fractal_bundle($rawFilesByPath);
			$stageLog('collect_literal_variants.encode_fzbf_v1_merged_fractal_bundle', $tStep);
			if($fzbfInner !== null && $fzbfInner !== '') {
				$variants[] = fractal_zip_candidate_from_inner($fzbfInner, 'fzbf', 'legacy', 'merged_fractal_bundle');
			}
		}
	} elseif($skipLegacyMergedFractalBundle) {
		$stageLog('collect_literal_variants.skip_encode_fzbf_v1_merged_fractal_bundle', microtime(true));
	}
	if(fractal_zip::literal_outer_fzta_tar_jpeg_candidate_enabled() && sizeof($rawFilesByPath) === 1) {
		foreach($rawFilesByPath as $relOne => $rawOne) {
			$relOne = (string) $relOne;
			if(strpos($relOne, '/') !== false || strpos($relOne, '\\') !== false) {
				break;
			}
			$tarBlob = fractal_zip::posix_ustar_single_file_archive_bytes($relOne, (string) $rawOne);
			if(is_string($tarBlob) && $tarBlob !== '') {
				// v2: fixed layout FZTA + version + raw tar (no varint) — a few bytes smaller vs v1 for min-ext tar|brotli parity.
				$fztaInner = 'FZTA' . chr(2) . $tarBlob;
				$variants[] = fractal_zip_candidate_from_inner($fztaInner, 'fzta_tar', 'literal', 'tar_literal');
			}
			break;
		}
	}
	$tStep = microtime(true);
	$bundlePayload = $this->encode_literal_bundle_payload($rawFilesByPath);
	$stageLog('collect_literal_variants.encode_literal_bundle_payload', $tStep);
	if($bundlePayload !== null && $bundlePayload !== '') {
		$bundlePayload = $this->maybe_apply_unified_literal_multipass($bundlePayload);
		$variants[] = fractal_zip_candidate_from_inner($bundlePayload, 'fzb', 'literal', 'fzb');
	}
	if($cacheKey !== null) {
		$this->reciprocal_literal_bundle_variants_cache[$cacheKey] = $variants;
	}
	return $variants;
}

/**
 * Image PAC + stream registry only (no semantic ZIP/7z/MPQ, no gzip peel stack). Prefer calling
 * choose_best_literal_bundle_transform on **disk** bytes: it runs fractal_zip_literal_deep_unwrap_with_layers first
 * (same order as zip_folder), which ends with image_pac + stream when applicable — avoid double-passing members.
 */
function literal_bundle_member_preprocess_for_transform($relPath, $rawBytes) {
	fractal_zip_ensure_literal_pac_stack_loaded();
	return fractal_zip_literal_pac_preprocess_literal_for_bundle((string) $relPath, (string) $rawBytes);
}

/**
 * Pick smallest zlib-deflated representation among lossless transforms (probe level from literal_bundle_gzip_probe_level; BMP default 9).
 * zlib level 1 is measured first for ratio gates; the configured probe level (e.g. 9 for BMP) runs only after those gates—skips an extra deflate when gzip-1 early exit or large-text raw-only shortcut applies.
 * Large mostly-text payloads: skip only when a quick gzip-1 probe shows little redundancy (ratio gate); otherwise try
 * delta/xor (tabular/repetitive text). Full nibble/invert/BMP trials stay off for large text unless
 * FRACTAL_ZIP_LITERAL_LARGE_TEXT_LIGHT_PROBE=0 or FRACTAL_ZIP_LITERAL_BUNDLE_ALWAYS_PROBE_TRANSFORMS=1.
 * FRACTAL_ZIP_LITERAL_LARGE_TEXT_SKIP_PROBE_GZIP1_MIN_RATIO (default 0.88): if gzip-1 output length / raw length >= this, use raw only.
 * FRACTAL_ZIP_LITERAL_SKIP_TRANSFORMS_MAX_GZIP1_RATIO (default 0.045): if gzip-1 length / raw length <= this, skip transforms (ratio computed with deflate **level 1** only, independent of literal_bundle_gzip_probe_level so level-9 tournament scoring cannot spuriously trigger this skip). Delta/xor can hurt outer text-detectors on dense prose. Exception: uncompressed BI_RGB BMP
 *   still runs the full transform path so modes 5/13 can beat raw when row/column delta helps.
 * FRACTAL_ZIP_LITERAL_TOURNAMENT_STRICT=1: bytes-first — disable gzip-1 early exit, large-text raw-only shortcut, and the 4 MiB non-text tournament cap (still obeys FRACTAL_ZIP_LITERAL_TRANSFORM_MAX_RAW_BYTES if you set it explicitly). Implies the same large-text / exotic probes as FRACTAL_ZIP_LITERAL_BUNDLE_ALWAYS_PROBE_TRANSFORMS=1; higher CPU and RAM on big literals.
 * Large non-text blobs (default > FRACTAL_ZIP_LITERAL_TRANSFORM_MAX_RAW_BYTES, 4 MiB): skip delta/xor/nibble/invert
 * (each allocates a full copy; FRACTAL_ZIP_LITERAL_BUNDLE_ALWAYS_PROBE_TRANSFORMS=1 or TOURNAMENT_STRICT bypasses this cap) — avoids OOM on e.g. FLAC sidecars.
 * Below that cap, size ≥512 KiB non–large-text payloads use the same full candidate tournament as smaller bodies (BMP row/column, delta, xor, etc.), not BMP-only early exit.
 * Optional $relPath: when set, literals may be preprocessed (fractal_zip_literal_pac.php: rasters + registry stream types: gz/svgz, bz2, xz, zst, lz4, br, lz/lzip, woff2, zip, 7z, pdf, …).
 * @return array [int mode, string stored]
 */
/**
 * Max raw size (bytes) for which non-BMP literals use zlib **level 9** in literal_bundle_gzip_probe_level (bytes-first; was always 1).
 * FRACTAL_ZIP_LITERAL_NONBMP_GZIP9_MAX_BYTES: default 2097152 (2 MiB); 0 = keep legacy level-1 probes for all non-BMP sizes.
 * FRACTAL_ZIP_SPEED=1 clamps the effective cap to 524288 unless the env var is set explicitly (preserves fast iteration when the var is unset).
 */
public static function literal_nonbmp_gzip9_max_probe_bytes(): int {
	static $cap = null;
	if($cap === null) {
		$e = getenv('FRACTAL_ZIP_LITERAL_NONBMP_GZIP9_MAX_BYTES');
		$unset = ($e === false || trim((string) $e) === '');
		if($unset) {
			$cap = 2097152;
		} else {
			$v = (int) trim((string) $e);
			$cap = $v <= 0 ? 0 : min(2147483647, $v);
		}
		if(fractal_zip::speed_mode_enabled() && $unset && $cap > 0) {
			$cap = min($cap, 524288);
		}
	}
	return $cap;
}

/**
 * Whether $relPath looks like a terminal `.flac` member (case-insensitive).
 */
public static function literal_bundle_is_flac_rel(?string $relPath): bool {
	if($relPath === null || (string) $relPath === '') {
		return false;
	}
	return str_ends_with(strtolower((string) $relPath), '.flac');
}

/**
 * Whether <code>$relPath</code> is a Microsoft packaged document we treat like other ZIP‑semantic literals for prescreening:
 * Open XML / OPC (Office 2007+ <code>.docx</code>, <code>.xlsx</code>, …), Store/App packages (<code>.appx</code>, <code>.msix</code>, …),
 * and legacy OLE compound <code>.xls</code>. Gzip‑1 byte ratio is a weak proxy for these; literal tournament and higher probe levels apply.
 */
public static function literal_bundle_rel_is_ms_office_open_container(?string $relPath, ?string $bytes = null): bool {
	if($relPath === null || (string) $relPath === '') {
		return false;
	}
	fractal_zip_ensure_content_format_policy_loaded();
	return fractal_zip_content_format_policy_ms_office_open_container((string) $relPath, $bytes ?? '');
}

/**
 * True when <code>$relPath</code> is semantically “inside” an MS Office–style container path: parent directory ends with
 * an open-container suffix (e.g. mode 19 <code>workbook.xls/Sheet1</code>), or the path is an OLE mode 19 template
 * (<code>…#ole-template</code>) whose base name is such a container. Those paths do not end in <code>.xls</code> / <code>.docx</code>
 * themselves; without this, gzip‑1 ratio gates and zlib‑1 probe scoring treat them like generic binaries.
 */
public static function literal_bundle_rel_is_ms_office_semantic_inner(?string $relPath, ?string $bytes = null): bool {
	if($relPath === null || (string) $relPath === '') {
		return false;
	}
	fractal_zip_ensure_content_format_policy_loaded();
	return fractal_zip_content_format_policy_ms_office_semantic_inner((string) $relPath, $bytes ?? '');
}

/**
 * FRACTAL_ZIP_LITERAL_MERGED_FZBM_MAX_BYTES: max merged raw bytes for FZBM inner when the folder has ≥2 members.
 * Unset, empty, or non-numeric ⇒ 0 (no cap).
 */
public static function literal_merged_fzbm_max_raw_bytes_cap(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LITERAL_MERGED_FZBM_MAX_BYTES');
	if($e === false || trim((string) $e) === '' || !is_numeric($e)) {
		return $cached = 0;
	}
	return $cached = (int) $e;
}

/** False when FRACTAL_ZIP_DISABLE_LITERAL_MERGED_FZBM=1. */
public static function literal_merged_fzbm_inner_enabled(): bool {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	return $cached = getenv('FRACTAL_ZIP_DISABLE_LITERAL_MERGED_FZBM') !== '1';
}

/** FRACTAL_ZIP_LIFESTYLE_SPEED_PROFILE: speed-default profile (unset => on, set 0/off/false/no => off). */
public static function lifestyle_speed_profile_enabled(): bool {
	static $cached = null;
	if(self::$runtime_force_disable_lifestyle_speed_profile) {
		return false;
	}
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_SPEED_PROFILE');
	if($e === false || trim((string) $e) === '') {
		return $cached = true;
	}
	$v = strtolower(trim((string) $e));
	return $cached = !($v === '0' || $v === 'off' || $v === 'false' || $v === 'no');
}

/**
 * Small-folder tryhard under lifestyle: raw-byte ceiling for a deeper encode (~1 s).
 * Unset ⇒ 65536 (covers 50 KiB hybrid soles); {@code =0} disables.
 * Larger trees keep the fast lifestyle / 7z passthrough (100× phone-mix would otherwise stack walls).
 */
public static function lifestyle_small_tryhard_max_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_SMALL_TRYHARD_MAX_RAW_BYTES');
	if($e === false || trim((string) $e) === '') {
		return $cached = 65536;
	}
	return $cached = max(0, (int) trim((string) $e));
}

/** Wall hint for small tryhard ({@code FRACTAL_ZIP_LIFESTYLE_SMALL_TRYHARD_BUDGET_MS}, default 400). */
public static function lifestyle_small_tryhard_budget_ms(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_SMALL_TRYHARD_BUDGET_MS');
	if($e === false || trim((string) $e) === '') {
		return $cached = 400;
	}
	return $cached = max(0, (int) trim((string) $e));
}

/**
 * Lifestyle: skip logical-bundle peel resolve for large singles.
 * Peeling silesia.zip (~65 MiB, test_files78) OOMs / burns minutes before native
 * tar|zstd can sole-win in a few seconds. Same for textlike dumps (webster/nci/
 * dickens): native FreeArc/7z owns the wire — peel is pure wall-clock.
 *
 * @param list<string> $pathKeys
 */
public static function lifestyle_should_skip_peel_resolve_for_native(
	array $pathKeys,
	int $sumRawBytes,
	int $memberCount
): bool {
	if(!self::lifestyle_speed_profile_enabled() || $memberCount <= 0) {
		return false;
	}
	// Single already-compressed / zip-container (any size): peel resolve before
	// native is pure wall — even when expand is a no-op (~0.8 s on tiny 159 .7z
	// <256 KiB; ~0.55 s on OOXML xlsx 153/166/173 just under 256 KiB).
	// Covers silesia.zip / webster / raster_formats.7z / test_files159 / OOXML.
	if($memberCount === 1 && $sumRawBytes > 0) {
		foreach($pathKeys as $path) {
			if(preg_match('/\\.(zip|7z|rar|gz|bz2|xz|zst|br|xlsx|xlsm|docx|pptx)$/i', (string) $path)) {
				return true;
			}
		}
	}
	if($sumRawBytes < 256 * 1024) {
		return false;
	}
	// All already-compressed packs (ROM zip pairs, multi-precomp): lifestyle FZB/native
	// owns the wire; resolving ZIP_MULTI peel expands payloads for nothing (~3 s on 65).
	if($memberCount >= 2 && $memberCount <= 16) {
		$precomp = 0;
		foreach($pathKeys as $path) {
			if(preg_match('/\\.(zip|7z|rar|gz|bz2|xz|zst|br)$/i', (string) $path)) {
				$precomp++;
			}
		}
		if($precomp > 0 && $precomp >= $memberCount) {
			return true;
		}
	}
	// Dense forests (≥64): native Arc/7z/br owns the wire — peel resolve before
	// speed-first was ~3 s of pure wall on nested gzip/raster packs (61).
	if($memberCount >= 64 && $sumRawBytes <= 8 * 1024 * 1024) {
		return true;
	}
	return false;
}

/**
 * Whether peel restore specs should block lifestyle native passthrough so FZHM runs.
 * ZIP_MULTI: bytes-first always reaches FZHM; under lifestyle, multifile ZIP_MULTI still
 * skips native, but single midsize .zip (test_files161/163) keeps native FZS1+br — FZHM
 * peel burns the 45s wall. CLASSIC peel: bytes-first always reaches FZHM; under lifestyle,
 * only sparse classic-heavy packs (≥2 CLASSIC, &lt;32 members) that are not all-precomp
 * skip native. Dense forests (69), classic-minority (77), audio (165), and multi-precomp
 * (175/176) keep native — FZB/native race soles without FZHM+GT.
 *
 * @param list<array<string,mixed>> $restoreSpecs
 * @param list<string>|null $pathKeys optional member paths for shape detection
 */
public static function lifestyle_should_skip_native_for_peel_restore(
	array $restoreSpecs,
	int $memberCount,
	?array $pathKeys = null
): bool {
	$classicKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC')
		? (int) FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC
		: 3;
	$zipMultiKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI')
		? (int) FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI
		: 1;
	$lifestyle = self::lifestyle_speed_profile_enabled();
	$allPrecomp = false;
	$audioMajority = false;
	$singleZip = false;
	if($pathKeys !== null && $pathKeys !== array()) {
		$precomp = 0;
		$audio = 0;
		$zipOnly = ($memberCount === 1);
		foreach($pathKeys as $path) {
			$p = (string) $path;
			if(preg_match('/\\.(zip|7z|rar|gz|bz2|xz|zst|br)$/i', $p)) {
				$precomp++;
			}
			if(preg_match('/\\.(flac|wav|aiff?|m4a|mp3|ogg|opus)$/i', $p)) {
				$audio++;
			}
			if($zipOnly && !preg_match('/\\.zip$/i', $p)) {
				$zipOnly = false;
			}
		}
		$allPrecomp = ($precomp > 0 && $precomp >= $memberCount);
		$audioMajority = ($audio > 0 && $audio * 2 >= max(1, $memberCount));
		$singleZip = $zipOnly;
	}
	// Audio albums (test_files165): CLASSIC RIFF/WAVE peel must not block native.
	if($lifestyle && $audioMajority) {
		foreach($restoreSpecs as $spec) {
			if(!is_array($spec)) {
				continue;
			}
			if((int) ($spec['kind'] ?? -1) === $zipMultiKind && !$singleZip) {
				return true;
			}
		}
		return false;
	}
	$classicCount = 0;
	$zipMultiCount = 0;
	foreach($restoreSpecs as $spec) {
		if(!is_array($spec)) {
			continue;
		}
		$rk = (int) ($spec['kind'] ?? -1);
		if($rk === $zipMultiKind) {
			$zipMultiCount++;
		}
		if($rk === $classicKind) {
			$classicCount++;
		}
	}
	if($zipMultiCount > 0) {
		// Lifestyle single .zip: native FZS1+br / tar|br (161/163); multifile still FZHM.
		if($lifestyle && $singleZip) {
			return false;
		}
		// Dense gz-dupe peel forests (62): FZHM burns ~15 s for a few hundred B;
		// native tar|br soles in <1 s.
		if($lifestyle && $memberCount >= 32 && $zipMultiCount * 2 >= $memberCount) {
			return false;
		}
		return true;
	}
	if($classicCount <= 0) {
		return false;
	}
	if(!$lifestyle) {
		return true;
	}
	// Multi-precomp (175/176): lifestyle FZB+zstd/zpaq soles; FZHM peels burn minutes.
	if($allPrecomp) {
		return false;
	}
	return $memberCount < 32 && $classicCount >= 2;
}

/**
 * Lifestyle default is speed-first; for tiny folders the user can wait ~1 s for better bytes
 * (test_files76: 5807 brotli vs 6220 solid-7z). Size-gated: significant-length trees keep the
 * fast passthrough. Skips single-file specialty paths (PDF/BMP/CM), dense 1-byte forests, and
 * already-tiny fractal micros (test_files/2).
 *
 * Env: {@code FRACTAL_ZIP_LIFESTYLE_SMALL_TRYHARD_MAX_RAW_BYTES} (default 16384, 0=off),
 * {@code FRACTAL_ZIP_LIFESTYLE_SMALL_TRYHARD_BUDGET_MS} (default 400).
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string>|null $allRelPaths
 */
public static function lifestyle_should_small_folder_tryhard(
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $allRelPaths = null
): bool {
	if(!self::lifestyle_speed_profile_enabled() || $sumRawBytes <= 0 || $memberCount <= 0) {
		return false;
	}
	$max = self::lifestyle_small_tryhard_max_raw_bytes();
	if($max <= 0 || $sumRawBytes > $max) {
		return false;
	}
	$pathKeys = $allRelPaths !== null && $allRelPaths !== array()
		? $allRelPaths
		: array_keys($rawFilesByPath);
	// Office/OLE: keep Arc/7z passthrough (kennedy-class).
	if(self::fs_profile_probe_looks_zpaq_native_favorable($rawFilesByPath, $pathKeys)) {
		return false;
	}
	// Dense forests (50–52 1-byte; 62 gz-dupe peels): deep/tryhard is multi-second; keep lifestyle.
	if($memberCount >= 32 && ($sumRawBytes / (float) $memberCount) < 256.0) {
		return false;
	}
	// Tiny flat all-text (190/196): lifestyle tar|br soles soft in <0.1 s; tryhard
	// FZB burns ~3 s for ~150 B. Nested 74/76 still tryhard below; all-web CDN
	// trees (75) prefer native tar|br q11 (tryhard only soft-ties).
	if($memberCount >= 2 && $memberCount <= 4
		&& $sumRawBytes >= 8192 && $sumRawBytes <= 64 * 1024) {
		$allText = true;
		$hasSub = false;
		foreach($pathKeys as $path) {
			$p = str_replace('\\', '/', (string) $path);
			if(strpos($p, '/') !== false) {
				$hasSub = true;
				break;
			}
			if(!preg_match('/\\.(txt|md|csv|html?|xml|json)$/i', $p)) {
				$allText = false;
				break;
			}
		}
		if($allText && !$hasSub) {
			return false;
		}
	}
	// Multifile: under 0.30× skip tryhard on flat packs (native owns). Nested trees
	// (74/76-class) still tryhard — deep sole wires. Pure web/CDN text (75): native.
	if($memberCount >= 4) {
		$hasSub = false;
		$allWebText = true;
		$hasRaster = false;
		foreach($pathKeys as $path) {
			$p = str_replace('\\', '/', (string) $path);
			if(strpos($p, '/') !== false) {
				$hasSub = true;
			}
			if(preg_match('/\\.(png|jpe?g|gif|webp|bmp)$/i', $p)) {
				$hasRaster = true;
			}
			if(!preg_match(
				'/\\.(txt|md|csv|html?|xml|json|css|js|mjs|cjs|map|svg|webmanifest)$/i',
				$p
			)) {
				$allWebText = false;
			}
		}
		if(!$hasSub) {
			return false;
		}
		if($allWebText && $sumRawBytes <= 16 * 1024) {
			return false;
		}
		// Nested ≤64 KiB (74/76): FZB+br (74) or native tar|br (76) soles soft
		// in ≪0.1–0.3 s; tryhard deep was ~0.75–0.8 s for a few dozen bytes.
		if($sumRawBytes <= 64 * 1024) {
			return false;
		}
		if(!self::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount)) {
			return true;
		}
		$avg = $sumRawBytes / (float) $memberCount;
		return $sumRawBytes >= 2048 && $avg >= 128.0;
	}
	// Flat tiny (2–3): keep tryhard for weak-Arc text hybrids (190 sole wire);
	// nested (75/76) also tryhard.
	if($memberCount >= 2
		&& !self::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount)) {
		return true;
	}
	return false;
}

/**
 * Tiny flat packs where FreeArc -m5 clearly beats raw (≤1/6): lifestyle should own
 * the wire instead of small-folder tryhard rediscovering the same Arc result.
 * Weak-Arc flats stay on tryhard / FZB+brotli. Capped at the tryhard raw ceiling
 * so larger fractal-friendly demos keep the deep path.
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string>|null $allRelPaths
 */
function lifestyle_midhybrid_arc_strong_enough_to_own(
	string $dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $allRelPaths = null
): bool {
	$tryhardMax = self::lifestyle_small_tryhard_max_raw_bytes();
	if($tryhardMax <= 0
		|| $sumRawBytes < 8 * 1024 || $sumRawBytes > $tryhardMax
		|| $memberCount < 2 || $memberCount > 8) {
		return false;
	}
	$pathKeys = $allRelPaths !== null && $allRelPaths !== array()
		? $allRelPaths
		: array_keys($rawFilesByPath);
	foreach($pathKeys as $path) {
		$p = (string) $path;
		if(preg_match('/\\.(xlsx|xlsm|docx|pptx)$/i', $p)) {
			return false;
		}
		if(strpos(str_replace('\\', '/', $p), '/') !== false) {
			return false;
		}
	}
	$root = realpath($dir);
	if($root === false || !is_dir($root)) {
		return false;
	}
	$arcBlob = $this->try_build_folder_freearc_native_archive_blob(
		$root,
		$rawFilesByPath,
		$sumRawBytes,
		array(5)
	);
	return is_string($arcBlob) && $arcBlob !== ''
		&& strlen($arcBlob) * 6 < $sumRawBytes;
}

/**
 * Mid printable-ratio payloads (structured binaries: PE/DLL dumps, mixed tables):
 * FreeArc often beats 7z after a cheap -m3 probe. Very sparse binaries and already-
 * textlike payloads skip this lane (textlike uses Arc -m5 directly).
 */
function lifestyle_payload_mid_printable_ratio(string $blob): bool {
	$n = strlen($blob);
	if($n < 4096) {
		return false;
	}
	$sampleTarget = 65536;
	$step = max(1, (int) floor($n / $sampleTarget));
	$sn = 0;
	$printable = 0;
	for($i = 0; $i < $n; $i += $step) {
		$b = ord($blob[$i]);
		if($b === 9 || $b === 10 || $b === 13 || ($b >= 32 && $b <= 126)) {
			$printable++;
		}
		$sn++;
	}
	if($sn < 512) {
		return false;
	}
	$ratio = $printable / (float) $sn;
	// Narrow band: PE/DLL-like structured binaries (~30–40% printable). Wider
	// ratios either go textlike-Arc or stay on 7z without an Arc -m3 tax.
	return $ratio >= 0.28 && $ratio <= 0.40;
}

/**
 * High printable-ratio singles that miss textlike (nulls / binary islands) but
 * where FreeArc still beats mx=9 7z (osdb-class ~81% printable).
 */
function lifestyle_payload_high_printable_ratio(string $blob): bool {
	$n = strlen($blob);
	if($n < 4096) {
		return false;
	}
	$sampleTarget = 65536;
	$step = max(1, (int) floor($n / $sampleTarget));
	$sn = 0;
	$printable = 0;
	for($i = 0; $i < $n; $i += $step) {
		$b = ord($blob[$i]);
		if($b === 9 || $b === 10 || $b === 13 || ($b >= 32 && $b <= 126)) {
			$printable++;
		}
		$sn++;
	}
	if($sn < 512) {
		return false;
	}
	return ($printable / (float) $sn) >= 0.75;
}

/**
 * POSIX ustar / GNU tar singles (samba-class): FreeArc -m5 beats mx=9 7z.
 */
function lifestyle_payload_looks_ustar_tar(string $blob): bool {
	$n = strlen($blob);
	if($n < 512) {
		return false;
	}
	$block = substr($blob, 0, min(1024, $n));
	return strpos($block, 'ustar') !== false;
}

/**
 * Lifestyle bytes-first exceptions: disable the speed profile so full adaptive /
 * binary-cm paths can sole-win without the tiny-outer / native-prefer shortcuts.
 * Small single BMP and all-raster packs stay on the native race under half-time.
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string>|null $allRelPaths
 */
public static function lifestyle_should_bytes_first_folder(
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $allRelPaths = null
): bool {
	if(!self::lifestyle_speed_profile_enabled() || $sumRawBytes <= 0 || $memberCount <= 0) {
		return false;
	}
	$pathKeys = $allRelPaths !== null && $allRelPaths !== array()
		? $allRelPaths
		: array_keys($rawFilesByPath);
	if($memberCount >= 2 && $sumRawBytes <= 2 * 1024 * 1024) {
		$allBmp = true;
		$allRaster = true;
		foreach($pathKeys as $path) {
			$p = (string) $path;
			if(!preg_match('/\\.bmp$/i', $p)) {
				$allBmp = false;
			}
			if(!preg_match('/\\.(png|jpe?g|gif|webp|bmp)$/i', $p)) {
				$allRaster = false;
			}
		}
		// All-BMP packs (155/178): native 7z/brotli sole-wins vs soft in <1 s.
		if($allBmp) {
			return false;
		}
		// PNG/raster grids: native zpaq/brotli (see write_lifestyle PNG escalate).
		// Ultra deep FZHM was tried on 168 (~−15 KiB) but PNG/GIF restores
		// mismatched — keep lifestyle native until that peel is fixed.
		if($allRaster) {
			return false;
		}
	}
	return false;
}

/** FS preset: auto-disable lifestyle speed profile when folder raw bytes are above this limit (0 => never disable). */
public static function fs_profile_disable_lifestyle_above_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FS_DISABLE_LIFESTYLE_ABOVE_RAW_BYTES');
	if($e === false || trim((string) $e) === '') {
		return $cached = 8388608; // 8 MiB: keep lifestyle on medium folders, skip on large trees
	}
	return $cached = max(0, (int) trim((string) $e));
}

