/**
 * Build a bounded sample for {@see fs_profile_cheap_fractal_data_likely}.
 *
 * @param array<string,string> $rawFilesByPath
 */
public static function fs_profile_build_fractal_probe_sample(array $rawFilesByPath): string {
	$maxSample = 131072;
	if($rawFilesByPath === array()) {
		return '';
	}
	if(count($rawFilesByPath) === 1) {
		$only = (string) reset($rawFilesByPath);
		return strlen($only) > $maxSample ? substr($only, 0, $maxSample) : $only;
	}
	$parts = array();
	$n = 0;
	foreach($rawFilesByPath as $blob) {
		$bs = (string) $blob;
		$parts[] = substr($bs, 0, min(8192, strlen($bs)));
		$n++;
		if($n >= 12) {
			break;
		}
	}
	$merged = implode("\n", $parts);
	return strlen($merged) > $maxSample ? substr($merged, 0, $maxSample) : $merged;
}

/**
 * Lightweight zip_folder gate for FS preset: one directory walk (stat + bounded peek), no full file reads.
 *
 * @return array{0:int,1:int,2:array<string,string>,3:array<string,mixed>,4:list<string>}|null
 *         [memberCount, sumRawBytes, probeMap, census, allRelPaths] or null when empty / not fs preset
 */
public static function fs_profile_zip_folder_gate_from_dir(string $dir): ?array {
	if(!fractal_zip::fs_profile_enabled()) {
		return null;
	}
	$iterRoot = realpath($dir);
	if($iterRoot === false || !is_dir($iterRoot)) {
		return null;
	}
	$prefix = rtrim(str_replace('\\', '/', $iterRoot), '/') . '/';
	$extBytes = array();
	$textish = 0;
	$totalBytes = 0;
	$files = 0;
	$probe = array();
	$allRelPaths = array();
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($iterRoot, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		$pathName = $fileInfo->getPathname();
		$pathReal = $fileInfo->getRealPath();
		$pathN = strtr($pathReal !== false ? $pathReal : $pathName, '\\', '/');
		if(!str_starts_with($pathN, $prefix)) {
			continue;
		}
		$rel = substr($pathN, strlen($prefix));
		$sz = (int) $fileInfo->getSize();
		if($sz <= 0) {
			continue;
		}
		$files++;
		$allRelPaths[] = $rel;
		$peekLen = min(65536, $sz);
		$peek = $peekLen > 0 ? (string) @file_get_contents($pathName, false, null, 0, $peekLen) : '';
		fractal_zip::folder_bundle_census_accumulate_raw_file($rel, $peek, $extBytes, $textish, $totalBytes, $sz);
		if(count($probe) < 12) {
			$probe[$rel] = strlen($peek) > 8192 ? substr($peek, 0, 8192) : $peek;
		}
	}
	if($files <= 0) {
		return null;
	}
	ksort($probe, SORT_STRING);
	sort($allRelPaths, SORT_STRING);
	$census = fractal_zip::folder_bundle_census_pack($extBytes, $totalBytes, $textish, $files);

	return array($files, $totalBytes, $probe, $census, $allRelPaths);
}

/**
 * Stat-only directory scan for FS early-gate routing (no file body reads).
 *
 * @return array{0:int,1:int,2:list<string>,3:int}|null [memberCount, sumRawBytes, allRelPaths, gzMembers]
 */
public static function fs_profile_zip_folder_stat_from_dir(string $dir): ?array {
	if(!fractal_zip::fs_profile_enabled()) {
		return null;
	}
	$iterRoot = realpath($dir);
	if($iterRoot === false || !is_dir($iterRoot)) {
		return null;
	}
	$prefix = rtrim(str_replace('\\', '/', $iterRoot), '/') . '/';
	$files = 0;
	$totalBytes = 0;
	$allRelPaths = array();
	$gzMembers = 0;
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($iterRoot, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		$pathReal = $fileInfo->getRealPath();
		$pathN = strtr($pathReal !== false ? $pathReal : $fileInfo->getPathname(), '\\', '/');
		if(!str_starts_with($pathN, $prefix)) {
			continue;
		}
		$rel = substr($pathN, strlen($prefix));
		if(fractal_zip::path_is_inplace_fractal_container_leaf($rel)) {
			continue;
		}
		$sz = (int) $fileInfo->getSize();
		if($sz <= 0) {
			continue;
		}
		$files++;
		$totalBytes += $sz;
		$allRelPaths[] = $rel;
		if(preg_match('/\\.gz$/i', $rel)) {
			$gzMembers++;
		}
	}
	if($files <= 0) {
		return null;
	}
	sort($allRelPaths, SORT_STRING);

	return array($files, $totalBytes, $allRelPaths, $gzMembers);
}

/**
 * Whether FS zip_folder should run an early 7z gate, and how much probing is needed.
 *
 * @param array{0:int,1:int,2:list<string>,3:int} $stat
 * @return null|'stat'|'probe' null = skip gate (small fractal-likely tree)
 */
public static function fs_profile_early_7z_gate_mode_from_stat(array $stat): ?string {
	list($files, $totalBytes, $allRelPaths, $gzMembers) = $stat;
	if($files <= 0) {
		return null;
	}
	if($totalBytes <= fractal_zip::fs_profile_tiny_always_fractal_max_raw_bytes()) {
		return null;
	}
	$largeMin = fractal_zip::fs_profile_large_7z_passthrough_min_raw_bytes();
	if($largeMin > 0 && $totalBytes >= $largeMin) {
		return 'stat';
	}
	if($files >= 8 && $totalBytes <= 262144) {
		return 'probe';
	}
	if($files >= 32 && $totalBytes <= 65536) {
		return 'probe';
	}
	if($files >= 2 && $totalBytes <= 131072) {
		$allHtml = true;
		foreach($allRelPaths as $path) {
			if(!preg_match('/\\.html?$/i', (string) $path)) {
				$allHtml = false;
				break;
			}
		}
		if($allHtml) {
			return 'stat';
		}
	}
	if($files >= 32 && $totalBytes <= 65536 && $gzMembers >= (int) floor($files * 0.6)) {
		return 'stat';
	}
	if($files <= 1 && $totalBytes >= 131072) {
		foreach($allRelPaths as $path) {
			if(preg_match('/\\.(xls|xlsx|xlsm|doc|docx|ppt|pptx|pdf|zip|png|jpe?g|gif|webp|mp3|mp4|mkv|wasm|exe|dll|so|o|flac|wav|ogg|opus|m4a|aac|avi)$/i', (string) $path)) {
				return 'stat';
			}
		}
	}

	return null;
}

/**
 * FS zip_folder early gate: stat screen then optional bounded probe (skips peek on fractal-likely small trees).
 *
 * @return array{0:int,1:int,2:array<string,string>,3:array<string,mixed>|null,4:list<string>}|null
 */
public static function fs_profile_zip_folder_early_gate_from_dir(string $dir): ?array {
	$stat = fractal_zip::fs_profile_zip_folder_stat_from_dir($dir);
	if($stat === null) {
		return null;
	}
	$mode = fractal_zip::fs_profile_early_7z_gate_mode_from_stat($stat);
	if($mode === null) {
		return null;
	}
	list($files, $totalBytes, $allRelPaths,) = $stat;
	if($mode === 'stat') {
		return array($files, $totalBytes, array(), null, $allRelPaths);
	}

	return fractal_zip::fs_profile_zip_folder_gate_from_dir($dir);
}

public static function fs_profile_tiny_always_fractal_max_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FS_TINY_ALWAYS_FRACTAL_MAX_RAW_BYTES');
	if($e === false || trim((string) $e) === '') {
		return $cached = 8192;
	}
	return $cached = max(0, (int) trim((string) $e));
}

/** FS preset: 7z compression level for speed-first native passthrough (1–9). */
public static function fs_profile_seven_zip_passthrough_mx(int $sumRawBytes, array $rawFilesByPath = array(), int $memberCount = 0): int {
	$e = getenv('FRACTAL_ZIP_FS_7Z_PASSTHROUGH_MX');
	if($e !== false && trim((string) $e) !== '') {
		return max(1, min(9, (int) trim((string) $e)));
	}
	if($memberCount >= 32 && $sumRawBytes <= 65536) {
		$gzMembers = 0;
		foreach(array_keys($rawFilesByPath) as $path) {
			if(preg_match('/\\.gz$/i', (string) $path)) {
				$gzMembers++;
			}
		}
		if($gzMembers >= (int) floor(max(1, $memberCount) * 0.6)) {
			return 1;
		}
	}
	if($memberCount >= 2 && $sumRawBytes <= 131072) {
		$allHtml = true;
		foreach(array_keys($rawFilesByPath) as $path) {
			if(!preg_match('/\\.html?$/i', (string) $path)) {
				$allHtml = false;
				break;
			}
		}
		if($allHtml) {
			return 3;
		}
	}
	return 9;
}

