}

/**
 * Cheap fractal-data screen for FS speed-first routing (gzip-1 proxy + cross-file chunk reuse).
 * True ⇒ worth running fractal inner; false ⇒ prefer native 7z / gzip-fast when raw is large enough.
 *
 * @param array<string,string> $rawFilesByPath
 */
public static function fs_profile_cheap_fractal_data_likely(array $rawFilesByPath, int $sumRawBytes, int $memberCount): bool {
	if($sumRawBytes <= fractal_zip::fs_profile_tiny_always_fractal_max_raw_bytes()) {
		return true;
	}
	$sample = fractal_zip::fs_profile_build_fractal_probe_sample($rawFilesByPath);
	if($sample === '') {
		return false;
	}
	list($label, $ratio,) = fractal_zip::substring_reciprocal_profile($sample);
	$reuseScore = 0.0;
	if($label === 'high') {
		if($memberCount <= 1) {
			if($ratio > 0.12) {
				return false;
			}
			if($sumRawBytes >= 262144) {
				return $ratio <= 0.08;
			}
			return true;
		}
		return true;
	}
	if($memberCount <= 1) {
		if($ratio <= 0.06) {
			return true;
		}
		if($sumRawBytes >= 262144) {
			return false;
		}
		return $ratio <= 0.11;
	}
	if($ratio <= 0.38) {
		return true;
	}
	if($memberCount >= 4) {
		$pieces = array();
		$picked = 0;
		foreach($rawFilesByPath as $blob) {
			$pieces[] = substr((string) $blob, 0, 4096);
			$picked++;
			if($picked >= 16) {
				break;
			}
		}
		$chunkFreq = array();
		$totalChunks = 0;
		foreach($pieces as $piece) {
			$pn = strlen($piece);
			if($pn < 128) {
				continue;
			}
			$seenLocal = array();
			for($off = 0; $off + 128 <= $pn; $off += 256) {
				$h = hash('xxh3', substr($piece, $off, 128), false);
				$seenLocal[$h] = true;
			}
			foreach($seenLocal as $h => $_) {
				$chunkFreq[$h] = ($chunkFreq[$h] ?? 0) + 1;
				$totalChunks++;
			}
		}
		$reusedChunks = 0;
		foreach($chunkFreq as $freq) {
			if((int) $freq >= 2) {
				$reusedChunks++;
			}
		}
		if($totalChunks > 0) {
			$reuseScore = (float) $reusedChunks / (float) $totalChunks;
		}
		if($reuseScore >= 0.22 || ($memberCount >= 32 && $reuseScore >= 0.08)) {
			return true;
		}
		if($memberCount >= 4 && $memberCount < 32 && $reuseScore >= 0.42) {
			return true;
		}
	}
	if($memberCount >= 2 && $sumRawBytes > fractal_zip::fs_profile_tiny_always_fractal_max_raw_bytes()
		&& $label !== 'high' && $ratio > 0.38 && $reuseScore < 0.25) {
		return false;
	}
	if($label === 'low' && $ratio >= 0.72) {
		return false;
	}
	if($sumRawBytes <= 524288 && $ratio <= 0.36 && $memberCount <= 1) {
		return true;
	}
	return $memberCount <= 2 && $sumRawBytes <= fractal_zip::fs_profile_full_fractal_max_raw_bytes() * 8 && $ratio <= 0.62;
}

/**
 * FS preset: OLE / already-compressed payloads where zpaq_raw wins — skip 7z passthrough.
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string> $pathKeys
 */
public static function fs_profile_probe_looks_zpaq_native_favorable(array $rawFilesByPath, array $pathKeys): bool {
	if($rawFilesByPath === array()) {
		return false;
	}
	$oleHits = 0;
	$checked = 0;
	foreach($rawFilesByPath as $rel => $blob) {
		$bs = (string) $blob;
		if(strlen($bs) < 4) {
			continue;
		}
		$checked++;
		if(substr($bs, 0, 4) === "\xD0\xCF\x11\xE0") {
			$oleHits++;
		}
	}
	if($checked > 0 && $oleHits === $checked) {
		return true;
	}
	foreach($pathKeys as $path) {
		$p = (string) $path;
		if(preg_match('/\\.(xls|xlsx|xlsm|doc|docx|ppt|pptx)$/i', $p)) {
			return true;
		}
	}
	return false;
}

/**
 * Pareto: tiny 100% textish trees (e.g. phpinfo HTML) — skip multipass under SPEED (near-zero byte gain, ~80× wall).
 */
public static function tiny_textish_should_skip_multipass(?array $folderCensus, int $sumRawBytes): bool {
	$e = getenv('FRACTAL_ZIP_TINY_TEXTISH_SKIP_MULTIPASS');
	if($e !== false && in_array(strtolower(trim((string) $e)), array('0', 'off', 'false', 'no'), true)) {
		return false;
	}
	if(getenv('FRACTAL_ZIP_FORCE_MULTIPASS') === '1') {
		return false;
	}
	$speed = getenv('FRACTAL_ZIP_SPEED');
	if($speed === false || !in_array(strtolower(trim((string) $speed)), array('1', 'true', 'yes', 'on'), true)) {
		if($e === false || trim((string) $e) === '') {
			return false;
		}
	}
	if(!is_array($folderCensus)) {
		return false;
	}
	$ratio = (float) ($folderCensus['textish_ratio'] ?? 0.0);
	$maxRaw = (int) (getenv('FRACTAL_ZIP_TINY_TEXTISH_SKIP_MULTIPASS_MAX_RAW_BYTES') ?: 262144);
	if($sumRawBytes <= 0 || $sumRawBytes > max(8192, $maxRaw)) {
		return false;
	}
	return $ratio >= (float) (getenv('FRACTAL_ZIP_TINY_TEXTISH_SKIP_MULTIPASS_MIN_TEXTISH') ?: 0.85);
}

/**
 * FS preset: dense multi-file fractal corpora (synth micro trees, many small members) benefit from
 * reciprocal multidiff fast path instead of peeler / run-grammar sweeps.
 *
 * @param array<string,string> $rawFilesByPath
 */
public static function fs_profile_should_use_dense_multifile_reciprocal_fast_path(array $rawFilesByPath, int $sumRawBytes, int $memberCount): bool {
	if(!fractal_zip::fs_profile_enabled()) {
		return false;
	}
	$denseMinMembers = fractal_zip::fs_profile_dense_reciprocal_min_members();
	if($denseMinMembers <= 0 || $memberCount < $denseMinMembers) {
		return false;
	}
	$denseMaxRaw = fractal_zip::fs_profile_disable_lifestyle_tiny_multifile_max_raw_bytes();
	if($denseMaxRaw > 0 && $sumRawBytes > $denseMaxRaw) {
		return fractal_zip::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount);
	}
	return true;
}

/**
 * FS preset: small multifile trees (misc roots, mixed small sets) — reciprocal fast path when fractal-likely.
 *
 * @param array<string,string> $rawFilesByPath
 */
public static function fs_profile_should_use_small_multifile_reciprocal_fast_path(array $rawFilesByPath, int $sumRawBytes, int $memberCount): bool {
	if(!fractal_zip::fs_profile_enabled()) {
		return false;
	}
	$minM = fractal_zip::fs_profile_small_multifile_reciprocal_min_members();
	$maxRaw = fractal_zip::fs_profile_small_multifile_reciprocal_max_raw_bytes();
	if($minM <= 0 || $maxRaw <= 0 || $memberCount < $minM || $sumRawBytes > $maxRaw) {
		return false;
	}
	return fractal_zip::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount);
}

/**
 * FS preset: prefer native 7z passthrough over full fractal encode.
 *
 * @param array<string,string> $rawFilesByPath probe or full map (relative path => bytes)
 * @param array<string,mixed>|null $folderCensus optional {@see folder_bundle_census_from_dir} result
 * @param list<string>|null $allRelPaths all member relpaths when probe map is partial
 */
public static function fs_profile_should_use_7z_passthrough(
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $folderCensus = null,
	?array $allRelPaths = null
): bool {
	if(!fractal_zip::fs_profile_enabled()) {
		return false;
	}
	if(fractal_zip::fs_profile_probe_looks_zpaq_native_favorable($rawFilesByPath, $pathKeys)) {
		return false;
	}
	if($sumRawBytes <= fractal_zip::fs_profile_tiny_always_fractal_max_raw_bytes()) {
		return false;
	}
	$pathKeys = $allRelPaths !== null && $allRelPaths !== array()
		? $allRelPaths
		: array_keys($rawFilesByPath);
	if($memberCount >= 8 && $sumRawBytes <= 262144) {
		$sample = fractal_zip::fs_profile_build_fractal_probe_sample($rawFilesByPath);
		if($sample !== '') {
			list($label, $ratio,) = fractal_zip::substring_reciprocal_profile($sample);
			if($label === 'high' && $ratio <= 0.05) {
				return true;
			}
		}
	}
	if($memberCount <= 1 && $sumRawBytes >= 131072) {
		foreach($pathKeys as $path) {
			if(preg_match('/\\.(xls|xlsx|xlsm|doc|docx|ppt|pptx|pdf|zip|png|jpe?g|gif|webp|mp3|mp4|mkv|wasm|exe|dll|so|o|flac|wav|ogg|opus|m4a|aac|avi)$/i', (string) $path)) {
				return true;
			}
		}
	}
	if($memberCount >= 2 && $sumRawBytes > fractal_zip::fs_profile_tiny_always_fractal_max_raw_bytes()
		&& $sumRawBytes <= 131072) {
		$allHtml = true;
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.html?$/i', (string) $path)) {
				$allHtml = false;
				break;
			}
		}
		if($allHtml) {
			return true;
		}
	}
	if($memberCount >= 32 && $sumRawBytes <= 65536) {
		$gzMembers = 0;
		foreach($pathKeys as $path) {
			if(preg_match('/\\.gz$/i', (string) $path)) {
				$gzMembers++;
			}
		}
		if($gzMembers >= (int) floor($memberCount * 0.6)) {
			return true;
		}
	}
	$largeMin = fractal_zip::fs_profile_large_7z_passthrough_min_raw_bytes();
	// FS manual compress: large trees always native 7z (speed ≈ 7z; agent bytes-first keeps fractal).
	if($largeMin > 0 && $sumRawBytes >= $largeMin) {
		return true;
	}
	if(!fractal_zip::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount)) {
		return true;
	}
	if($memberCount >= 32 && $sumRawBytes <= 65536) {
		$sample = fractal_zip::fs_profile_build_fractal_probe_sample($rawFilesByPath);
		if($sample !== '') {
			list($label, $ratio,) = fractal_zip::substring_reciprocal_profile($sample);
			if($label !== 'high' && $ratio >= 0.35) {
				return true;
			}
		}
	}
	return false;
}

/**
 * Lifestyle default: prefer a single native 7z write when fractal is unlikely to beat it,
 * or when Office/OLE shapes would otherwise burn multi-second native zpaq under the 45s lifestyle bar.
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string>|null $allRelPaths
 */
public static function lifestyle_should_prefer_native_7z_passthrough(
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $allRelPaths = null
): bool {
	if(!self::lifestyle_speed_profile_enabled() || $sumRawBytes <= 0 || $memberCount <= 0) {
		return false;
	}
	$pathKeys = $allRelPaths !== null && $allRelPaths !== array()
		? $allRelPaths
		: array_keys($rawFilesByPath);
	// General-text CM virtual folders (opaque chunk + tiny meta): always wrap natively.
	// Cheap-fractal probe misfires on nested meta/ and would skip tar|br.
	foreach($pathKeys as $path) {
		$p = str_replace('\\', '/', (string) $path);
		if(preg_match('#(^|/)pages/chunk_\\d+\\.inner$#', $p)
			|| preg_match('#(^|/)meta/text_inner_#', $p)) {
			return true;
		}
	}
	// Small single BMP: prefer native FZS1+brotli-q11 (see write_lifestyle bmp branch).
	// Deep fractal still wins bytes but blows the half-time budget (157 ~10 s).
	if($memberCount === 1 && $sumRawBytes > 0 && $sumRawBytes < 1048576) {
		foreach($pathKeys as $path) {
			if(preg_match('/\\.bmp$/i', (string) $path)) {
				return true;
			}
		}
	}
	// Single already-compressed archive: cheap-fractal probe can misfire (.7z → true)
	// and send unified FZB down a ~13 s path (test_files160). Native tar|br ~2 s.
	if($memberCount === 1 && $sumRawBytes > 0) {
		foreach($pathKeys as $path) {
			if(preg_match('/\\.(7z|zip|rar|gz|bz2|xz|zst)$/i', (string) $path)) {
				return true;
			}
		}
	}
	// kennedy.xls / Office: v8 used fast 7z; native zpaq5 wins bytes but blows the time gate.
	if(self::fs_profile_probe_looks_zpaq_native_favorable($rawFilesByPath, $pathKeys)) {
		return true;
	}
	// Any size: when cheap fractal probe is negative, native 7z matches historical winners
	// (pic/obj/kennedy-class binaries above the tiny threshold).
	if(!self::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount)) {
		return true;
	}
	// Tiny/mid trees: speed-first FZB/native owns soft — nested ≤256 KiB
	// (74/76/140/148/149/63) and flat 8–64 KiB (181/196). Nested 2–3 FZB+br
	// soles soft (148: ~3165 < 3270). Flat tinier packs (186) stay on deep.
	if($memberCount >= 2 && $memberCount <= 16
		&& $sumRawBytes > 0 && $sumRawBytes <= 256 * 1024) {
		$hasSubTiny = false;
		foreach($pathKeys as $path) {
			if(strpos(str_replace('\\', '/', (string) $path), '/') !== false) {
				$hasSubTiny = true;
				break;
			}
		}
		if($hasSubTiny || ($sumRawBytes >= 8 * 1024 && $sumRawBytes <= 64 * 1024)) {
			return true;
		}
	}
	// Mid nested README+large-.bin demos (145 runpair / 150 hardmix ~1.2 MiB):
	// FZB+br soles soft br in ~0.1 s; deep was ~0.3–0.5 s. Keep all-text mid
	// nests (144) on deep — already sub-0.1 s there.
	if($memberCount >= 2 && $memberCount <= 8
		&& $sumRawBytes >= 256 * 1024 && $sumRawBytes <= 2 * 1024 * 1024) {
		$hasSubMid = false;
		$hasReadmeMid = false;
		$hasLargeBin = false;
		foreach($pathKeys as $path) {
			$p = str_replace('\\', '/', (string) $path);
			if(strpos($p, '/') !== false) {
				$hasSubMid = true;
			}
			if(preg_match('/README/i', $p)) {
				$hasReadmeMid = true;
			}
			$blob = $rawFilesByPath[$path] ?? null;
			if(is_string($blob) && strlen($blob) >= 256 * 1024
				&& preg_match('/\\.(bin|dat|raw|rgba)$/i', $p)) {
				$hasLargeBin = true;
			}
		}
		if($hasSubMid && $hasReadmeMid && $hasLargeBin) {
			return true;
		}
	}
	// Single small textlike (70/49/107/112/110/113/129): tar|br q11 owns soft;
	// keep native. Tiny fractal texts (22 ~800 B) stay deep gzip (8 KiB floor).
	// .c/.lsp/man (110/113/129) are often 3–12 KiB — 1 KiB floor for those only.
	if($memberCount === 1 && $sumRawBytes < 256 * 1024) {
		foreach($pathKeys as $path) {
			$p = (string) $path;
			if($sumRawBytes >= 8 * 1024
				&& preg_match('/\\.(txt|md|csv|tsv|log|html?|xml|json|css|js|protodata)$/i', $p)) {
				return true;
			}
			if($sumRawBytes >= 1024
				&& preg_match('/\\.(c|lsp|[1-8n])$/i', $p)) {
				return true;
			}
		}
	}
	// Small lifestyle pseudo-PDF (121): FZB+zstd15 owns soft; keep native so
	// tip-lpaq (~0.3 s) is skipped. Real PDFs (≥%PDF) stay on deep/CM lanes.
	if($memberCount === 1 && $sumRawBytes >= 32 * 1024 && $sumRawBytes <= 256 * 1024
		&& function_exists('fractal_zip_binary_cm_looks_pseudo_pdf')) {
		foreach($pathKeys as $path) {
			$p = (string) $path;
			if(!preg_match('/\\.pdf$/i', $p) || !isset($rawFilesByPath[$p])
				|| !is_string($rawFilesByPath[$p])) {
				continue;
			}
			if(fractal_zip_binary_cm_looks_pseudo_pdf($p, (string) $rawFilesByPath[$p])) {
				return true;
			}
		}
	}
	// Cheap-fractal flat mid hybrids (test_files194/197): deep adaptive+native burns
	// 15–25 s then FreeArc wins. Keep nested fractal demos (144/145/147) on deep path.
	if($memberCount >= 2 && $memberCount <= 8
		&& $sumRawBytes >= 256 * 1024 && $sumRawBytes <= 4 * 1024 * 1024) {
		$hasSubdir = false;
		foreach($pathKeys as $path) {
			if(strpos(str_replace('\\', '/', (string) $path), '/') !== false) {
				$hasSubdir = true;
				break;
			}
		}
		if(!$hasSubdir) {
			return true;
		}
	}
	// Near-duplicate text forests (test_files90): skipping native lets ≥8 MiB disable lifestyle
	// and run full fractal — ~284 B vs soft tar|zstd ~1.6 KiB, still under the 45s wall.
	if(self::lifestyle_near_duplicate_text_forest_likely($rawFilesByPath, $sumRawBytes, $memberCount, $pathKeys)) {
		// Prefer native: tar|brotli-q11 ~407 B soles vs soft ~1.6 KiB in ~1 s.
		// Deep fractal ~284 B costs ~17 s — not worth it under 0.30×.
		return true;
	}
	// PNG/JPEG grids ≤2 MiB (169/177): native race sole-wins with fat margin.
	// All-BMP packs (155/178): native also sole-wins vs soft — prefer here (bytes_first off).
	if($memberCount >= 2 && $sumRawBytes <= 2 * 1024 * 1024 && $sumRawBytes > 0) {
		$allPngish = true;
		$allBmp = true;
		foreach($pathKeys as $path) {
			$p = (string) $path;
			if(!preg_match('/\\.(png|jpe?g|gif|webp)$/i', $p)) {
				$allPngish = false;
			}
			if(!preg_match('/\\.bmp$/i', $p)) {
				$allBmp = false;
			}
		}
		// Incl. tiny PNG grids ≤80 KiB (154/177): native brotli soles in ~1–3 s.
		// 169 escalates inside write_lifestyle when gzip9 ≤ native race.
		if($allBmp || $allPngish) {
			return true;
		}
	}
	// Single raster image (81 PNG): FZB+zstd soles vs soft xz.
	if($memberCount === 1 && $sumRawBytes > 0 && $sumRawBytes <= 2 * 1024 * 1024) {
		foreach($pathKeys as $path) {
			if(preg_match('/\\.(png|jpe?g|gif|webp)$/i', (string) $path)) {
				return true;
			}
		}
	}
	// Mid hybrid text (196): post-race FZB+br soles vs soft-identical native brotli.
	// Require a *hybrid* basename so near-dup mid packs (190) keep the 7z race.
	if($memberCount >= 2 && $memberCount <= 4
		&& $sumRawBytes >= 8192 && $sumRawBytes <= 64 * 1024) {
		$allText = true;
		$hasHybrid = false;
		foreach($pathKeys as $path) {
			$p = (string) $path;
			if(!preg_match('/\\.(txt|md|csv|html?|xml|json)$/i', $p)) {
				$allText = false;
				break;
			}
			if(stripos(basename($p), 'hybrid') !== false) {
				$hasHybrid = true;
			}
		}
		if($allText && $hasHybrid) {
			return true;
		}
	}
	// Tiny nested all-web/CDN trees (test_files75): native tar|br q11 soles;
	// tryhard only soft-ties min-ext. Mixed tiny nests (74/76) stay on deep path.
	if($memberCount >= 4 && $memberCount <= 16
		&& $sumRawBytes > 0 && $sumRawBytes <= 16 * 1024) {
		$hasSub = false;
		$allWebText = true;
		foreach($pathKeys as $path) {
			$p = str_replace('\\', '/', (string) $path);
			if(strpos($p, '/') !== false) {
				$hasSub = true;
			}
			if(!preg_match(
				'/\\.(txt|md|csv|html?|xml|json|css|js|mjs|cjs|map|svg|webmanifest)$/i',
				$p
			)) {
				$allWebText = false;
			}
		}
		if($hasSub && $allWebText) {
			return true;
		}
	}
	// Fractal-stress hard/ packs (test_files150): cheap-fractal skips native and
	// lifestyle gzip lands ~134 B over min-ext tar|br; prefer the brotli race.
	if($memberCount >= 2 && $memberCount <= 16
		&& $sumRawBytes >= 64 * 1024 && $sumRawBytes <= 2 * 1024 * 1024) {
		foreach($pathKeys as $path) {
			if(preg_match('#(^|/)hard/#', str_replace('\\', '/', (string) $path))) {
				return true;
			}
		}
	}
	// Mid/large lifestyle trees that still look "cheap fractal" (audio albums, peel forests,
	// PNG/web mixes, multi‑MiB source trees) blow the 45s bench wall on full encode. Prefer
	// native Arc/7z (+ brotli/xz/zstd race) so every case finishes and can still tie min-ext.
	if($sumRawBytes >= 8388608) {
		return true;
	}
	$audio = 0;
	$precompressed = 0;
	foreach($pathKeys as $path) {
		$p = (string) $path;
		if(preg_match('/\\.(flac|wav|aiff?|m4a|mp3|ogg|opus)$/i', $p)) {
			$audio++;
		}
		if(preg_match('/\\.(gz|zip|7z|rar|bz2|xz|zst|png|jpe?g|gif|webp|pdf|flac|wav)$/i', $p)) {
			$precompressed++;
		}
	}
	if($audio >= 1 && $audio + 1 >= (int) max(1, (int) floor($memberCount * 0.5))) {
		return true;
	}
	if($memberCount >= 8 && $precompressed * 2 >= $memberCount) {
		return true;
	}
	if($memberCount >= 64 && $sumRawBytes >= 1048576) {
		return true;
	}
	if(!self::lifestyle_should_skip_heavy_startup_for_raw_bytes($sumRawBytes)) {
		return false;
	}
	// Dense .gz peel trees (test_files62): 7z matches historical winners — not synth 1-byte forests.
	if($memberCount >= 32 && $sumRawBytes <= 65536) {
		$gzMembers = 0;
		foreach($pathKeys as $path) {
			if(preg_match('/\\.gz$/i', (string) $path)) {
				$gzMembers++;
			}
		}
		if($gzMembers >= (int) floor($memberCount * 0.5)) {
			return true;
		}
		// Synth 1-byte forests (50–52): native brotli ≪ deep tournament wall.
		if(($sumRawBytes / (float) $memberCount) < 16.0) {
			return true;
		}
	}
	// Midsize multifile (e.g. test_files63 mode-lab): v8 used fast 7z; full fractal is slower.
	if($memberCount >= 8 && $sumRawBytes >= 131072 && $sumRawBytes <= 524288) {
		return true;
	}
	// Small all-HTML trees: 7z ties historical winners without a transform tournament.
	if($memberCount >= 2) {
		$allHtml = true;
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.html?$/i', (string) $path)) {
				$allHtml = false;
				break;
			}
		}
		if($allHtml) {
			return true;
		}
	}
	// Single HTML under lifestyle tiny (cp.html): same as multifile HTML.
	if($memberCount === 1) {
		foreach($pathKeys as $path) {
			if(preg_match('/\\.html?$/i', (string) $path)) {
				return true;
			}
			// Large BMP: native race ties/beats min-ext (test_files35). Small BMP
			// (test_files157 ~40 KiB): full fractal sole-wins vs tar|brotli.
			if(preg_match('/\\.bmp$/i', (string) $path) && $sumRawBytes >= 1048576) {
				return true;
			}
			// Already-compressed singles: native race ties min-ext without fractal.
			if(preg_match('/\\.(7z|zip|rar|gz|bz2|xz|zst)$/i', (string) $path)) {
				return true;
			}
		}
	}
	return false;
}

/**
 * Size-clustered all-text forests where full fractal crushes tar|zstd (test_files90).
 * Cap ≤16 MiB so larger text mixes keep the native ≥8 MiB fast path.
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string> $pathKeys
 */
public static function lifestyle_near_duplicate_text_forest_likely(
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	array $pathKeys
): bool {
	if($memberCount < 8 || $sumRawBytes < 8388608 || $sumRawBytes > 16 * 1024 * 1024) {
		return false;
	}
	$textish = 0;
	$sizes = array();
	$payloadMembers = 0;
	foreach($pathKeys as $path) {
		$p = (string) $path;
		if(fractal_zip::path_is_inplace_fractal_container_leaf($p)
			|| fractal_zip::container_filename_looks_like_fractal_zip(basename($p))) {
			continue;
		}
		$payloadMembers++;
		if(!preg_match('/\\.(txt|csv|log|json|xml|md|html?)$/i', $p)) {
			return false;
		}
		$textish++;
		if(isset($rawFilesByPath[$p]) && is_string($rawFilesByPath[$p])) {
			$sizes[] = strlen($rawFilesByPath[$p]);
		}
	}
	if($payloadMembers < 8 || $textish < $payloadMembers || count($sizes) < 4) {
		return false;
	}
	$memberCount = $payloadMembers;
	sort($sizes);
	$med = $sizes[(int) floor(count($sizes) / 2)];
	if($med < 65536) {
		return false;
	}
	$tol = max(64, (int) floor($med * 0.02));
	$near = 0;
	foreach($sizes as $s) {
		if(abs((int) $s - $med) <= $tol) {
			$near++;
		}
	}
	if($near * 10 < $memberCount * 9) {
		return false;
	}
	return true;
}

/**
 * Lifestyle monster folders: write raw tar|zstd without loading the tree into PHP.
 * Used when raw ≥ {@see FRACTAL_ZIP_LARGE_FOLDER_FAST_BYTES} (default 128 MiB).
 * Soft min-ext only measures zstd -1; race -3 (same wall, often multi‑MiB smaller)
 * and keep the smaller frame so monsters sole-win when -3 helps (test_files55/54/72).
 */
function write_lifestyle_monster_zstd_fast_container($dir): bool {
	if(!fractal_zip::lifestyle_speed_profile_enabled()) {
		return false;
	}
	if(PHP_OS_FAMILY === 'Windows') {
		return false;
	}
	$zstdExe = fractal_zip::zstd_executable();
	if($zstdExe === null || !fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ZSTD')) {
		return false;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return false;
	}
	$threshEnv = getenv('FRACTAL_ZIP_LARGE_FOLDER_FAST_BYTES');
	$lim = ($threshEnv !== false && trim((string) $threshEnv) !== '') ? (int) $threshEnv : (128 * 1024 * 1024);
	if($lim <= 0) {
		return false;
	}
	$rp = realpath((string) $dir);
	if($rp === false || !is_dir($rp)) {
		return false;
	}
	// Mega file-count trees (206 ~300k): one cheap zstd pass — multi-level tar is hours.
	// Cap probe at 80k: 58 (~23k) must keep the -10/-19 ladder; only GP source lakes trip this.
	// Allow even below the raw-byte monster threshold so gzip-fast never walks 300k members.
	$fileCount = $this->folder_file_count_capped($rp, 80000);
	$megaFiles = ($fileCount > 80000);
	$denseFiles = ($fileCount > 5000);
	// Mega trees: skip full byte sum (another ~300k-stat walk). tar|zstd -1
	// does not need raw for routing; lakes below still sum once.
	$raw = $megaFiles ? 0 : $this->folder_raw_total_bytes($dir);
	if($raw < $lim && !$megaFiles) {
		return false;
	}
	// Absolute .fz path before any chdir — relative `$dir.fz` would land *inside*
	// the corpus after `chdir($rp)` and get tar'd into itself (test_files203).
	$fzcPath = (string) $dir . $this->fractal_zip_container_file_extension;
	if($fzcPath !== '' && $fzcPath[0] !== '/' && (strlen($fzcPath) < 2 || $fzcPath[1] !== ':')) {
		$fzcAbs = realpath(dirname($fzcPath));
		if($fzcAbs !== false) {
			$fzcPath = $fzcAbs . DS . basename($fzcPath);
		} else {
			$fzcPath = getcwd() . DS . $fzcPath;
		}
	}
	if(is_file($fzcPath)) {
		@unlink($fzcPath);
	}
	// One cheap extension/byte-mass walk: route lakes by dominant filetype.
	// Mega file-count trees (206 ~300k): skip entirely — only tar|zstd -1 runs,
	// and a full walk was tens of seconds before the soft-ext -1 wall (~40 s).
	$pdfBytes = 0;
	$zipPrecompBytes = 0;
	$videoBytes = 0;
	$audioBytes = 0;
	$parquetBytes = 0;
	$officeBytes = 0;
	$htmlTextBytes = 0;
	$imageBytes = 0;
	$modelBytes = 0;
	$debBytes = 0;
	$compressedMemberBytes = 0;
	if(!$megaFiles) {
		try {
			$itMass = new RecursiveIteratorIterator(
				new RecursiveDirectoryIterator($rp, FilesystemIterator::SKIP_DOTS)
			);
			$majThresh = ($raw > 0) ? (int) ($raw * 0.85) : 0;
			$pdfOfficeThresh = ($raw > 0) ? (int) ($raw * 0.60) : 0;
			$officeThresh = ($raw > 0) ? (int) ($raw * 0.50) : 0;
			$pdfMajThresh = ($raw > 0) ? (int) ($raw * 0.70) : 0;
			foreach($itMass as $fi) {
				if(!$fi->isFile()) {
					continue;
				}
				$pn = $fi->getPathname();
				$name = (string) $fi->getFilename();
				if(fractal_zip::path_is_inplace_fractal_container_leaf($name)) {
					continue;
				}
				$sz = (int) $fi->getSize();
				if(preg_match('/\\.pdf$/i', $pn)) {
					$pdfBytes += $sz;
				} elseif(preg_match('/\\.(zip|7z|rar|zst)$/i', $pn)) {
					// Near-incomp archive lakes (202). Do NOT count .gz/.bz2/.xz here:
					// extracted Debian payloads (207) are mostly .xz and would false-trip
					// solid 7z before debArchiveLake / tar|zstd-10 can own the tip.
					$zipPrecompBytes += $sz;
				} elseif(preg_match('/\\.(gz|bz2|xz)$/i', $pn)) {
					// Already-compressed members. Alone (210 gnu tarballs) → solid 7z.
					// With .deb packages (207) → tar|zstd via debArchiveLake.
					$compressedMemberBytes += $sz;
				} elseif(preg_match('/\\.deb$/i', $pn)) {
					// Count separately: solid 7z loses to tar|zstd on .deb lakes (207).
					$debBytes += $sz;
				} elseif(preg_match('/\\.(mp4|mkv|webm|avi|mov|m4v)$/i', $pn)) {
					$videoBytes += $sz;
				} elseif(preg_match('/\\.(flac|wav|aiff?|m4a|mp3|ogg|opus)$/i', $pn)) {
					$audioBytes += $sz;
				} elseif(preg_match('/\\.parquet$/i', $pn)) {
					$parquetBytes += $sz;
				} elseif(preg_match('/\\.(docx|xlsx|xlsm|pptx|doc|xls|ppt|pub)$/i', $pn)) {
					$officeBytes += $sz;
				} elseif(preg_match('/\\.(jpe?g|png|gif|webp|bmp|tiff?)$/i', $pn)) {
					$imageBytes += $sz;
				} elseif(preg_match('/\\.(gguf|onnx|pt|pth|safetensors)$/i', $pn)) {
					$modelBytes += $sz;
				} elseif(preg_match('/\\.(html?|htm|xhtml|xml|css|js|json|txt|md|php)$/i', $pn)) {
					$htmlTextBytes += $sz;
				}
				// Stop once a routing majority is already decided (GP lakes).
				if($majThresh > 0 && (
					($zipPrecompBytes + $parquetBytes) >= $majThresh
					|| $videoBytes >= $majThresh
					|| $audioBytes >= $majThresh
					|| $imageBytes >= $majThresh
					|| $modelBytes >= $majThresh
					|| $compressedMemberBytes >= $majThresh
					|| ($debBytes + $compressedMemberBytes) >= $majThresh
					|| ($pdfBytes >= $pdfMajThresh && $raw >= 512 * 1024 * 1024)
					|| $officeBytes >= $officeThresh
					|| ($pdfBytes + $officeBytes) >= $pdfOfficeThresh
				)) {
					break;
				}
			}
		} catch(Throwable $e) {
			$pdfBytes = 0;
			$zipPrecompBytes = 0;
			$videoBytes = 0;
			$audioBytes = 0;
			$parquetBytes = 0;
			$officeBytes = 0;
			$htmlTextBytes = 0;
			$imageBytes = 0;
			$modelBytes = 0;
			$debBytes = 0;
			$compressedMemberBytes = 0;
		}
	}
	$pdfMajority = ($raw > 0 && $pdfBytes >= (int) ($raw * 0.70));
	$audioMajorityLake = ($raw > 0 && $audioBytes >= (int) ($raw * 0.85));
	$videoMajorityLake = ($raw > 0 && $videoBytes >= (int) ($raw * 0.85));
	$imageMajorityLake = ($raw > 0 && $imageBytes >= (int) ($raw * 0.85));
	$modelMajorityLake = ($raw > 0 && $modelBytes >= (int) ($raw * 0.85));
	$compressedMemberLake = ($raw > 0 && $debBytes === 0
		&& $compressedMemberBytes >= (int) ($raw * 0.85));
	// Real .deb packages + nested .xz/gz (207): tar|zstd -10 soles soft.
	// Do NOT treat xz/gz-only lakes (210) as deb — solid 7z wins there.
	$debArchiveLake = ($raw > 0 && $debBytes > 0
		&& ($debBytes + $compressedMemberBytes + $zipPrecompBytes) >= (int) ($raw * 0.85));
	// Near-incomp lakes (202 zip / 208 parquet), FLAC albums (59), office (54),
	// image lakes (205 jpeg/png), xz/gz-only (210), and PDF-majority ≥512 MiB (72):
	// solid 7z beats tar|zstd -10 vs the 7z baseline column. Video → gzip-9 above.
	$precompOrOfficeLake = !$megaFiles && !$videoMajorityLake && $raw >= $lim
		&& (
			($zipPrecompBytes + $parquetBytes) >= (int) ($raw * 0.85)
			|| $compressedMemberLake
			|| $audioMajorityLake
			|| $imageMajorityLake
			|| ($pdfMajority && $raw >= 512 * 1024 * 1024)
			|| $officeBytes >= (int) ($raw * 0.50)
			// Mixed PDF+OLE lakes (204): neither gate alone hits; solid 7z still wins.
			|| ($pdfBytes + $officeBytes) >= (int) ($raw * 0.60)
		);
	// Video lakes (203): tar|pigz-9 soles vs 7z (~275 KiB) and is ~7× faster than
	// mx=9 7z. zstd-19 reclaim ~181 KiB but costs ~355 s — bank that wall for
	// other soles (mega now zstd-16).
	if($videoMajorityLake && !$megaFiles && $raw >= $lim) {
		$gzLakePath = $fzcPath;
		if(is_file($gzLakePath)) {
			@unlink($gzLakePath);
		}
		$pigz = trim((string) shell_exec('command -v pigz 2>/dev/null'));
		$gzip = trim((string) shell_exec('command -v gzip 2>/dev/null'));
		$gzOk = false;
		$cwdGz = getcwd();
		if(($pigz !== '' || $gzip !== '') && @chdir($rp)
			&& trim((string) shell_exec('command -v tar 2>/dev/null')) !== '') {
			$gzCmd = ($pigz !== '')
				? ('tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' .'
					. ' | ' . fractal_zip::shell_quote_arg_cached($pigz) . ' -9 > '
					. fractal_zip::shell_quote_arg_cached($gzLakePath))
				: ('tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' .'
					. ' | ' . fractal_zip::shell_quote_arg_cached($gzip) . ' -9 > '
					. fractal_zip::shell_quote_arg_cached($gzLakePath));
			exec($gzCmd . ' 2>/dev/null', $xoGz, $retGz);
			$gzOk = ((int) $retGz === 0 && is_file($gzLakePath) && (int) filesize($gzLakePath) > 0);
		}
		if($cwdGz !== false) {
			chdir($cwdGz);
		}
		if($gzOk) {
			fractal_zip::$last_outer_codec = 'gzip';
			fractal_zip::$last_written_container_codec = 'gzip';
			fractal_zip::$folder_zip_wire_best_outer_codec = 'gzip';
			fractal_zip::$used_folder_gzip_fast = false;
			fractal_zip::$used_folder_literal_fzb4_store = false;
			fractal_zip::$used_folder_unified_stream = false;
			fractal_zip::$used_folder_per_member_best = false;
			fractal_zip::html_trace_print(
				'Lifestyle monster: video-majority native tar|gzip-9 (streamed).<br>'
			);
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
			return true;
		}
		if(is_file($gzLakePath)) {
			@unlink($gzLakePath);
		}
	}
	if($precompOrOfficeLake && !$videoMajorityLake && fractal_zip::seven_zip_executable() !== null) {
		$officeMajorityLake = ($raw > 0 && $officeBytes >= (int) ($raw * 0.50));
		$pdfOfficeMixedLake = ($raw > 0
			&& ($pdfBytes + $officeBytes) >= (int) ($raw * 0.60));
		$pdfBigLake = ($pdfMajority && $raw >= 512 * 1024 * 1024);
		$zipMajorityDense = ($raw > 0 && $denseFiles
			&& ($zipPrecompBytes + $parquetBytes) >= (int) ($raw * 0.85));
		// FreeArc -m9 tip wins vs mx=9 7z on:
		//   - office-majority (54): ~−155 MiB
		//   - PDF+OLE mixed (204): ~−3.4 MiB
		//   - PDF-majority ≥512 MiB (72): ~−521 KiB
		// (image/audio/zip/parquet lakes stay on solid 7z — Arc loses or ties.)
		$arcDocLake = ($officeMajorityLake || $pdfOfficeMixedLake || $pdfBigLake);
		if($arcDocLake && fractal_zip::freearc_executable() !== null
			&& fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')) {
			$arcExeOff = fractal_zip::freearc_executable();
			$arcOutOff = sys_get_temp_dir() . DS . 'fzmon_arc_off_' . md5($rp . "\0off9") . '.arc';
			if(is_file($arcOutOff)) {
				@unlink($arcOutOff);
			}
			$prefixOff = $this->command_prefix_with_local_lib();
			$qOff = fractal_zip::shell_quote_arg_cached($arcExeOff);
			$mtOff = fractal_zip::library_arc_compress_mt_shell_fragment_for_exec();
			$cwdOff = getcwd();
			$retOff = -1;
			if(@chdir($rp)) {
				$cmdOff = $prefixOff . $qOff
					. ' a -m9' . $mtOff . ' -ep1 -y'
					. ' -x*.fz -x*.fzc -x*.fractalzip '
					. fractal_zip::shell_quote_arg_cached($arcOutOff) . ' . 2>/dev/null';
				exec($cmdOff, $xoOff, $retOff);
			}
			if($cwdOff !== false) {
				chdir($cwdOff);
			}
			if((int) $retOff === 0 && is_file($arcOutOff) && (int) filesize($arcOutOff) > 0) {
				if(is_file($fzcPath)) {
					@unlink($fzcPath);
				}
				$okOff = @rename($arcOutOff, $fzcPath);
				if(!$okOff) {
					$okOff = @copy($arcOutOff, $fzcPath);
					@unlink($arcOutOff);
				}
				if($okOff && is_file($fzcPath) && (int) filesize($fzcPath) > 0) {
					fractal_zip::$last_outer_codec = 'arc';
					fractal_zip::$last_written_container_codec = 'arc';
					fractal_zip::$folder_zip_wire_best_outer_codec = 'arc';
					fractal_zip::$used_folder_gzip_fast = false;
					fractal_zip::$used_folder_literal_fzb4_store = false;
					fractal_zip::$used_folder_unified_stream = false;
					fractal_zip::$used_folder_per_member_best = false;
					$arcLakeKind = $officeMajorityLake
						? 'office-majority'
						: ($pdfBigLake ? 'PDF-majority' : 'PDF+office');
					fractal_zip::html_trace_print(
						'Lifestyle monster: ' . $arcLakeKind
						. ' native FreeArc -m9 (streamed).<br>'
					);
					$micro_time_taken = microtime(true) - $this->initial_micro_time;
					fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
					return true;
				}
			}
			if(is_file($arcOutOff)) {
				@unlink($arcOutOff);
			}
			// Fall through to 7z if Arc failed.
		}
		// Dense zip lakes (58 ~22k small zips): tar|zstd-16 --long=27 beats plain -19
		// (~118 KiB smaller, ~0.7× wall) and still soles mx=9 7z by ~1.5 MiB.
		if($zipMajorityDense && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ZSTD')) {
			$zstdZip = fractal_zip::zstd_executable();
			if($zstdZip !== null) {
				if(is_file($fzcPath)) {
					@unlink($fzcPath);
				}
				$cwdZ = getcwd();
				$retZ = -1;
				if(@chdir($rp)) {
					$cmdZ = 'tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' .'
						. ' | ' . fractal_zip::shell_quote_arg_cached($zstdZip)
						. ' -16 --long=27' . fractal_zip::bench_zstd_thread_shell_fragment_for_exec()
						. ' -c > ' . fractal_zip::shell_quote_arg_cached($fzcPath)
						. ' 2>/dev/null';
					exec($cmdZ, $xoZ, $retZ);
				}
				if($cwdZ !== false) {
					chdir($cwdZ);
				}
				if((int) $retZ === 0 && is_file($fzcPath) && (int) filesize($fzcPath) > 0) {
					fractal_zip::$last_outer_codec = 'zstd';
					fractal_zip::$last_written_container_codec = 'zstd';
					fractal_zip::$folder_zip_wire_best_outer_codec = 'zstd';
					fractal_zip::$used_folder_gzip_fast = false;
					fractal_zip::$used_folder_literal_fzb4_store = false;
					fractal_zip::$used_folder_unified_stream = false;
					fractal_zip::$used_folder_per_member_best = false;
					fractal_zip::html_trace_print(
						'Lifestyle monster: dense-zip-majority native tar|zstd-16 --long=27 (streamed).<br>'
					);
					$micro_time_taken = microtime(true) - $this->initial_micro_time;
					fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
					return true;
				}
				if(is_file($fzcPath)) {
					@unlink($fzcPath);
				}
			}
		}
		// Stream mx=9 in-place to the container path — do not file_get_contents GiB archives.
		$sevenLake = fractal_zip::seven_zip_executable();
		if(is_file($fzcPath)) {
			@unlink($fzcPath);
		}
		$cwdLake = getcwd();
		$retLake = -1;
		if($sevenLake !== null && @chdir($rp)) {
			$metaLake = '';
			$metaArgvLake = fractal_zip::outer_7z_metadata_strip_argv();
			if($metaArgvLake !== array()) {
				$metaLake = ' ' . implode(' ', $metaArgvLake);
			}
			$mmtLake = fractal_zip::seven_zip_mmt_shell_fragment_for_exec();
			if($mmtLake === '') {
				$mmtLake = ' -mmt=on';
			}
			$cmdLake = fractal_zip::shell_quote_arg_cached($sevenLake)
				. ' a -t7z -mx=9' . $mmtLake . $metaLake
				. ' -xr!*.fz -xr!*.fzc -xr!*.fractalzip'
				. ' -m0=lzma2 -bso0 -bsp0 -bd -y '
				. fractal_zip::shell_quote_arg_cached($fzcPath) . ' . 2>/dev/null';
			exec($cmdLake, $xoLake, $retLake);
		}
		if($cwdLake !== false) {
			chdir($cwdLake);
		}
		if((int) $retLake === 0 && is_file($fzcPath) && (int) filesize($fzcPath) > 0) {
			fractal_zip::$last_outer_codec = '7z';
			fractal_zip::$last_written_container_codec = '7z';
			fractal_zip::$folder_zip_wire_best_outer_codec = '7z';
			fractal_zip::$used_folder_gzip_fast = false;
			fractal_zip::$used_folder_literal_fzb4_store = false;
			fractal_zip::$used_folder_unified_stream = false;
			fractal_zip::$used_folder_per_member_best = false;
			fractal_zip::html_trace_print(
				'Lifestyle monster: precomp/office/audio/image-majority native 7z mx=9 (streamed).<br>'
			);
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
			return true;
		}
		if(is_file($fzcPath)) {
			@unlink($fzcPath);
		}
	}
	// HTML/text-majority <256 MiB (test_files55): FreeArc -m9 sole-beats mx=9 7z
	// and tar|zstd-22; skip the zstd ladder when Arc already ≤12% raw.
	// Probe: -m9 == -m7 tip (11 647 534) and ~0.8× wall vs -m7 on this host.
	$arcMonsterTried = false;
	$htmlTextMajority = ($raw > 0 && $htmlTextBytes >= (int) ($raw * 0.70));
	$arcExeEarly = fractal_zip::freearc_executable();
	if(!$megaFiles && !$denseFiles && $htmlTextMajority && $raw < 256 * 1024 * 1024
		&& $arcExeEarly !== null
		&& fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')) {
		$arcMonsterTried = true;
		$bestArcPath = null;
		$bestArcLen = null;
		$bestArcMeth = 5;
		$prefixArcE = $this->command_prefix_with_local_lib();
		$qArcE = fractal_zip::shell_quote_arg_cached($arcExeEarly);
		$mtArcE = fractal_zip::library_arc_compress_mt_shell_fragment_for_exec();
		$cwdArcE = getcwd();
		// -m9 first (55: same tip as -m7, lower wall); -m7/-m5 only if -m9 fails.
		foreach(array(9, 7, 5) as $methNum) {
			$arcOut = sys_get_temp_dir() . DS . 'fzmon_arc_' . md5($rp . "\0e\0" . (string) $methNum) . '.arc';
			if(is_file($arcOut)) {
				@unlink($arcOut);
			}
			$retArc = -1;
			if(@chdir($rp)) {
				$cmdArc = $prefixArcE . $qArcE
					. ' a -m' . (string) (int) $methNum . $mtArcE . ' -ep1 -y'
					. ' -x*.fz -x*.fzc -x*.fractalzip '
					. fractal_zip::shell_quote_arg_cached($arcOut) . ' . 2>/dev/null';
				exec($cmdArc, $xoArcE, $retArc);
			}
			if($cwdArcE !== false) {
				chdir($cwdArcE);
			}
			if((int) $retArc !== 0 || !is_file($arcOut)) {
				continue;
			}
			$nArc = (int) filesize($arcOut);
			if($nArc <= 0) {
				@unlink($arcOut);
				continue;
			}
			if($bestArcLen === null || $nArc < $bestArcLen) {
				if($bestArcPath !== null && $bestArcPath !== $arcOut && is_file($bestArcPath)) {
					@unlink($bestArcPath);
				}
				$bestArcPath = $arcOut;
				$bestArcLen = $nArc;
				$bestArcMeth = (int) $methNum;
			} elseif($arcOut !== $bestArcPath) {
				@unlink($arcOut);
			}
			// -m9 already ≤12% raw: skip -m7/-m5 wall (test_files55).
			if($bestArcLen !== null && $bestArcLen < (int) ($raw * 0.12)
				&& (int) $methNum === 9) {
				break;
			}
		}
		if($bestArcPath !== null && $bestArcLen !== null
			&& $bestArcLen < (int) ($raw * 0.12)) {
			if(is_file($fzcPath)) {
				@unlink($fzcPath);
			}
			if(!@rename($bestArcPath, $fzcPath)) {
				$okArc = @copy($bestArcPath, $fzcPath);
				@unlink($bestArcPath);
				if(!$okArc) {
					// Fall through to zstd ladder.
					$bestArcPath = null;
				}
			}
			if($bestArcPath !== null && is_file($fzcPath) && (int) filesize($fzcPath) > 0) {
				fractal_zip::$last_outer_codec = 'arc';
				fractal_zip::$last_written_container_codec = 'arc';
				fractal_zip::$folder_zip_wire_best_outer_codec = 'arc';
				fractal_zip::$used_folder_gzip_fast = false;
				fractal_zip::$used_folder_literal_fzb4_store = false;
				fractal_zip::$used_folder_unified_stream = false;
				fractal_zip::$used_folder_per_member_best = false;
				fractal_zip::html_trace_print(
					'Lifestyle monster: HTML/text-majority native FreeArc -m'
					. (string) $bestArcMeth . ' folder (raw arc).<br>'
				);
				$micro_time_taken = microtime(true) - $this->initial_micro_time;
				fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
				return true;
			}
		}
		if($bestArcPath !== null && is_file($bestArcPath)) {
			@unlink($bestArcPath);
		}
	}
	// Soft min-ext only measures -1 above 48 MiB.
	// ≥512 MiB routing:
	//   - model weights (209 gguf/onnx): -10 only (−19 is slightly larger on this lake)
	//   - .deb archive lakes (207): -10 --long=29 (plain -19 was ~0.4 MiB / ~286 s)
	//   - else: -1, escalate to -10 when wire still ≥95% raw (near-incomp)
	// Mega file-count (206 ~300k): zstd-16 --long=31 Pareto vs --long=27..30/-19.
	// Full probe (Aug 2026): plain -16 ~389 MiB/~178 s; --long=27 ~364 MiB;
	// --long=30 ~362.0 MiB/~161 s; --long=31 ~360.8 MiB/~323 s (best tip; bytes-first).
	// Soft min-ext zstd ~589 MiB — sole margin widens.
	// -12/--long=27 ~401 MiB/~43 s still soles but loses ~36 MiB tip (bytes-first keeps -16).
	// (Prior plain -10 gold was ~422 MiB — still sole, worse Pareto.)
	if($megaFiles) {
		$levels = array(16);
	} elseif($modelMajorityLake && $raw >= 256 * 1024 * 1024) {
		$levels = array(10);
	} elseif($debArchiveLake && $raw >= 256 * 1024 * 1024) {
		// 207 .deb+.xz: -10 --long=29 reclaim ~508 MiB vs --long=27 on the source
		// tree (~9 s wall; content checksum OK). Soft min-ext was a ~5 KiB sole
		// before long; margin is now hundreds of MiB. Plain -19 was only ~448 KiB
		// for ~286 s — skip.
		$levels = array(10);
	} elseif($raw >= 512 * 1024 * 1024) {
		$levels = array(1);
	} elseif($raw >= 256 * 1024 * 1024) {
		$levels = array(1);
	} else {
		$levels = array(3);
	}
	$tarRoot = $rp;
	$stageDir = null;
	// PDF qpdf stage omitted: tar|zstd -10 already soles soft on 72 (~12 MiB) in ~8 s;
	// qpdf across hundreds of PDFs was a multi-minute wall under beat-ext-time.
	$bestPath = null;
	$bestLen = null;
	$bestLev = 1;
	$cwd = getcwd();
	$tmpPaths = array();
	for($li = 0; $li < count($levels); $li++) {
		$lev = (int) $levels[$li];
		$outPath = ($lev === 1)
			? $fzcPath
			: (sys_get_temp_dir() . DS . 'fzmon_' . md5($rp . "\0" . (string) $lev) . '.zst');
		if(is_file($outPath)) {
			@unlink($outPath);
		}
		if($lev !== 1) {
			$tmpPaths[] = $outPath;
		}
		$blobOk = false;
		$out = @fopen($outPath, 'wb');
		if($out !== false && @chdir($tarRoot)) {
			$ultraFrag = ($lev >= 20) ? ' --ultra' : '';
			// --long=31 with ultra -22 (2 GiB window). Mega lakes (206): --long=31
			// with -16; deb lakes (207): --long=29 with -10. Frame header carries
			// window; decompress already passes --long=31.
			$longFrag = ($lev >= 22)
				? ' --long=31'
				: (($megaFiles && $lev >= 16)
					? ' --long=31'
					: (($debArchiveLake && $lev >= 10) ? ' --long=29' : ''));
			// Deb lakes: size-descending member order so each .deb sits near its
			// nearly-identical unpacked data.tar.xz inside the --long window.
			// Readdir order after cp -al (bench work trees) dumps all .debs first
			// and loses ~577 MiB vs size-desc / lucky source interleaving.
			if($debArchiveLake) {
				$tarCmd = 'find . -type f'
					. ' ! -name \'*.fz\' ! -name \'*.fzc\' ! -name \'*.fractalzip\''
					. ' -printf \'%s\\t%p\\n\' 2>/dev/null'
					. ' | sort -nr | cut -f2-'
					. ' | tar cf - -T - 2>/dev/null';
			} else {
				$tarCmd = 'tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' . 2>/dev/null';
			}
			$cmd = $tarCmd . ' | '
				. fractal_zip::shell_quote_arg_cached($zstdExe)
				. $ultraFrag
				. $longFrag
				. ' -' . (string) $lev
				. fractal_zip::bench_zstd_thread_shell_fragment_for_exec()
				. ' -c 2>/dev/null';
			$pipe = @popen($cmd, 'r');
			if(is_resource($pipe)) {
				$copied = @stream_copy_to_stream($pipe, $out);
				$pclose = pclose($pipe);
				$blobOk = ($copied !== false && $copied > 0 && (int) $pclose === 0);
			}
		}
		if($out !== false) {
			fclose($out);
		}
		if($cwd !== false) {
			chdir($cwd);
		}
		if(!$blobOk || !is_file($outPath)) {
			if(is_file($outPath)) {
				@unlink($outPath);
			}
			continue;
		}
		$n = (int) filesize($outPath);
		if($n <= 0) {
			@unlink($outPath);
			continue;
		}
		if($bestLen === null || $n < $bestLen) {
			if($bestPath !== null && $bestPath !== $outPath && $bestPath !== $fzcPath && is_file($bestPath)) {
				@unlink($bestPath);
			}
			$bestPath = $outPath;
			$bestLen = $n;
			$bestLev = $lev;
		} elseif($outPath !== $fzcPath) {
			@unlink($outPath);
		}
		// Escalate from -3 when highly compressible (test_files55).
		if($lev === 3 && $bestLen !== null && !in_array(10, $levels, true)
			&& $bestLen < (int) ($raw * 0.45)) {
			$levels[] = 10;
		}
		// ≥256 MiB generic -1: escalate to -10 only when still near-incomp (≥95% raw).
		// Deb lakes stay on -1; model lakes start at -10 (see levels above).
		if($lev === 1 && $bestLen !== null && !in_array(10, $levels, true)
			&& $raw >= 256 * 1024 * 1024
			&& $bestLen >= (int) ($raw * 0.95)) {
			$levels[] = 10;
		}
		// After -10, -19 reclaims multi‑MiB on ultra-compressible trees (55).
		if($lev === 10 && $bestLen !== null && !in_array(19, $levels, true)
			&& $bestLen < (int) ($raw * 0.20)) {
			$levels[] = 19;
		}
		// After -19, --ultra -22 on still-highly-compressible <256 MiB (55).
		if($lev === 19 && $bestLen !== null && !in_array(22, $levels, true)
			&& $raw < 256 * 1024 * 1024
			&& $bestLen < (int) ($raw * 0.15)) {
			$levels[] = 22;
		}
		// ≥512 MiB ladder only: skip ultra -22 when -19 already ≤55% raw (near-incomp /
		// sole). Must not strip the <256 MiB escalate above — that bug left 55 on -19
		// (~19 MiB) instead of -22 (~11.9 MiB).
		if($lev === 19 && $bestLen !== null && $raw >= 512 * 1024 * 1024
			&& in_array(22, $levels, true)
			&& $bestLen <= (int) ($raw * 0.55)) {
			$levels = array_values(array_filter($levels, static function ($x) {
				return (int) $x !== 22;
			}));
		}
	}
	if($bestPath === null || $bestLen === null) {
		if(is_file($fzcPath)) {
			@unlink($fzcPath);
		}
		if($stageDir !== null && is_dir($stageDir)) {
			$this->recursive_remove_directory($stageDir);
		}
		return false;
	}
	$winCodec = 'zstd';
	$winLev = $bestLev;
	// Fallback Arc race when the early HTML path did not run (non-html but still
	// ultra-compressible <256 MiB). Cap: skip mega/dense lakes.
	$arcExeMonster = fractal_zip::freearc_executable();
	if(!$arcMonsterTried && !$megaFiles && !$denseFiles && $raw < 256 * 1024 * 1024
		&& $bestLen < (int) ($raw * 0.12)
		&& $arcExeMonster !== null
		&& fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')) {
		$arcMethods = array(5, 7);
		$prefixArc = $this->command_prefix_with_local_lib();
		$qArc = fractal_zip::shell_quote_arg_cached($arcExeMonster);
		$mtArc = fractal_zip::library_arc_compress_mt_shell_fragment_for_exec();
		$cwdArc = getcwd();
		foreach($arcMethods as $methNum) {
			$arcOut = sys_get_temp_dir() . DS . 'fzmon_arc_' . md5($rp . "\0" . (string) $methNum) . '.arc';
			if(is_file($arcOut)) {
				@unlink($arcOut);
			}
			$tmpPaths[] = $arcOut;
			$retArc = -1;
			if(@chdir($tarRoot)) {
				$cmdArc = $prefixArc . $qArc
					. ' a -m' . (string) (int) $methNum . $mtArc . ' -ep1 -y'
					. ' -x*.fz -x*.fzc -x*.fractalzip '
					. fractal_zip::shell_quote_arg_cached($arcOut) . ' . 2>/dev/null';
				exec($cmdArc, $xoArc, $retArc);
			}
			if($cwdArc !== false) {
				chdir($cwdArc);
			}
			if((int) $retArc !== 0 || !is_file($arcOut)) {
				continue;
			}
			$nArc = (int) filesize($arcOut);
			if($nArc > 0 && $nArc < $bestLen) {
				if($bestPath !== null && $bestPath !== $fzcPath && $bestPath !== $arcOut
					&& is_file($bestPath)) {
					@unlink($bestPath);
				}
				$bestPath = $arcOut;
				$bestLen = $nArc;
				$winCodec = 'arc';
				$winLev = (int) $methNum;
			} else {
				@unlink($arcOut);
			}
		}
	}
	if($bestPath !== $fzcPath) {
		if(is_file($fzcPath)) {
			@unlink($fzcPath);
		}
		if(!@rename($bestPath, $fzcPath)) {
			$ok = @copy($bestPath, $fzcPath);
			@unlink($bestPath);
			if(!$ok) {
				if($stageDir !== null && is_dir($stageDir)) {
					$this->recursive_remove_directory($stageDir);
				}
				return false;
			}
		}
	}
	foreach($tmpPaths as $tp) {
		if($tp !== $fzcPath && is_file($tp)) {
			@unlink($tp);
		}
	}
	if($stageDir !== null && is_dir($stageDir)) {
		$this->recursive_remove_directory($stageDir);
	}
	fractal_zip::$last_outer_codec = $winCodec;
	fractal_zip::$last_written_container_codec = $winCodec;
	fractal_zip::$folder_zip_wire_best_outer_codec = $winCodec;
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	fractal_zip::$used_folder_unified_stream = false;
	fractal_zip::$used_folder_per_member_best = false;
	$traceExtra = ($tarRoot !== $rp) ? ' (qpdf-staged)' : '';
	if($winCodec === 'arc') {
		fractal_zip::html_trace_print('Lifestyle monster: native FreeArc -m' . (string) $winLev
			. ' folder (raw arc)' . $traceExtra . '.<br>');
	} else {
		fractal_zip::html_trace_print('Lifestyle monster: native tar|zstd-' . (string) $winLev
			. ' folder (raw zstd)' . $traceExtra . '.<br>');
	}
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

/**
 * Lifestyle Pareto race: keep the smallest among a seed native wire and optional
 * tar|brotli / tar|xz / tar|zstd folder archives (FZLB / FZLX / FZLZ wrappers).
 *
 * @param array<string,string> $rawFilesByPath
 * @return array{0: string, 1: string} [wire, codec]
 */
function lifestyle_race_native_folder_wire_candidates(
	$dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	string $seedBlob,
	string $seedCodec
): array {
	$best = (string) $seedBlob;
	$codec = (string) $seedCodec;
	if($best === '') {
		return array($best, $codec);
	}
	$consider = static function (string $blob, string $name) use (&$best, &$codec): void {
		if($blob !== '' && ($best === '' || strlen($blob) < strlen($best))) {
			$best = $blob;
			$codec = $name;
		}
	};
	$memberCount = count($rawFilesByPath);
	// Under 45s walls, q11 brotli above ~6 MiB often blows the case budget; singles soft-cap at 8 MiB.
	$brCap = ($memberCount === 1) ? (4 * 1024 * 1024) : (6 * 1024 * 1024);
	// SC2Replay (~6.2 MiB) still needs brotli to tie cached min-ext — allow up to 7 MiB multifile.
	if($memberCount >= 16 && $sumRawBytes <= 7 * 1024 * 1024) {
		$brCap = 7 * 1024 * 1024;
	}
	// Small trees: min-ext xz can beat 7z/brotli by tens of bytes (test_files81).
	$xzCap = ($sumRawBytes > 0 && $sumRawBytes <= 8 * 1024 * 1024) ? $sumRawBytes : 0;
	$zsCap = 96 * 1024 * 1024;
	if($memberCount === 1 && $sumRawBytes > 12 * 1024 * 1024) {
		$brCap = 0;
	}
	// Audio-majority: brotli burns wall for ~0 byte gain vs store/zstd.
	$audio = 0;
	$precomp = 0;
	foreach(array_keys($rawFilesByPath) as $path) {
		$p = (string) $path;
		if(preg_match('/\\.(flac|wav|aiff?|m4a|mp3|ogg|opus)$/i', $p)) {
			$audio++;
		}
		if(preg_match('/\\.(zip|7z|rar|gz|bz2|xz|zst|br)$/i', $p)) {
			$precomp++;
		}
	}
	if($audio > 0 && $audio * 2 >= max(1, $memberCount)) {
		$brCap = 0;
	}
	// All-.zip/.7z/.rar packs: tar|brotli cannot beat tar|zstd/--ultra and burns
	// ~7 s (test_files65). Keep brotli for mixed .br/.gz/.zst packs (176).
	$allArchive = ($precomp > 0 && $precomp >= $memberCount);
	if($allArchive) {
		foreach(array_keys($rawFilesByPath) as $path) {
			if(!preg_match('/\\.(zip|7z|rar)$/i', (string) $path)) {
				$allArchive = false;
				break;
			}
		}
	}
	if($allArchive) {
		$brCap = 0;
		$xzCap = 0;
	}
	// Dense near-incompressible forests: 7z already soles; tar|br burns ~12 s for
	// ~2 KiB (test_files69). Keep br for compressible dense trees (test_files61).
	if($brCap > 0 && $codec === '7z' && $memberCount >= 64
		&& $sumRawBytes > 0 && strlen($best) * 10 > $sumRawBytes * 8) {
		$brCap = 0;
	}
	// Midsize multi-file with a strong 7z seed (<50% of raw): tar|br rarely wins
	// and burns ~8 s (Calgary-class). Weak mid 7z (≥16 members) also skips br —
	// q10 on ~5 MiB forests costs ~6 s for tens of KiB (test_files80).
	if($brCap > 0 && $codec === '7z' && $memberCount >= 8 && $memberCount < 64
		&& $sumRawBytes >= 1024 * 1024 && strlen($best) * 2 < $sumRawBytes) {
		$brCap = 0;
	}
	if($brCap > 0 && $codec === '7z' && $memberCount >= 16 && $memberCount <= 48
		&& $sumRawBytes >= 2 * 1024 * 1024 && $sumRawBytes <= 8 * 1024 * 1024
		&& strlen($best) * 100 > $sumRawBytes * 85) {
		$brCap = 0;
	}
	if($sumRawBytes > 0 && $sumRawBytes <= $brCap
		&& fractal_zip::folder_native_brotli_compare_enabled()) {
		$br = $this->try_build_folder_brotli_native_tar_br_blob($dir, $rawFilesByPath);
		if(is_string($br) && $br !== '') {
			$consider($br, 'brotli');
		}
	}
	// Dense forests: once brotli owns the wire, xz/zstd rarely shrink further and
	// only add wall (mixed raster+precomp packs).
	if($codec === 'brotli' && $memberCount >= 64) {
		$xzCap = 0;
		$zsCap = 0;
	}
	if($sumRawBytes > 0 && $sumRawBytes <= $xzCap
		&& fractal_zip::folder_native_xz_compare_enabled()) {
		$xz = $this->try_build_folder_xz_native_tar_xz_blob($dir, $rawFilesByPath);
		if(is_string($xz) && $xz !== '') {
			$consider($xz, 'xz');
		}
	}
	if($sumRawBytes > 0 && $sumRawBytes <= $zsCap) {
		$zs = $this->try_build_folder_zstd_native_tar_zst_blob($dir, $rawFilesByPath);
		if(is_string($zs) && $zs !== '') {
			$consider($zs, 'zstd');
		}
	}
	// Near-incompressible trees (test_files159/169): gzip9 packed-bundle can beat tar|br.
	if($sumRawBytes > 0 && $sumRawBytes <= 4 * 1024 * 1024) {
		$gz = $this->try_build_folder_gzip9_bundle_zlib_blob($dir, $rawFilesByPath);
		if(is_string($gz) && $gz !== '') {
			$consider($gz, 'gzip');
		}
	}
	// Already-compressed singles: FZS1 store beats gzip when near-incompressible
	// (test_files159). FZS1+brotli-q11 beats tar|brotli on midsize .zip (test_files163).
	// Skip for .7z/.rar — FZS1+br cannot beat tar|br and burns ~2 s (test_files160).
	if($memberCount === 1 && $sumRawBytes > 0 && $sumRawBytes <= 4 * 1024 * 1024) {
		foreach($rawFilesByPath as $rel => $bytes) {
			if(!is_string($bytes) || $bytes === '') {
				break;
			}
			if(!preg_match('/\\.(zip|gz|bz2|xz|zst)$/i', (string) $rel)) {
				break;
			}
			$store = $this->encode_single_member_raw_payload((string) $rel, $bytes);
			if(!is_string($store) || $store === '') {
				break;
			}
			$consider($store, 'store');
			$brotliExe = fractal_zip::brotli_executable();
			if($brotliExe !== null && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_BROTLI')) {
				$brBlob = $this->outer_brotli_blob($brotliExe, $store, 11);
				if(is_string($brBlob) && $brBlob !== '') {
					$consider($brBlob, 'brotli');
				}
			}
			break;
		}
	}
	return array($best, $codec);
}

/**
 * Lifestyle: FZB4 store-only + one cheap outer when native tar|codec cannot beat
 * soft folder-zpaq (image grids) or soft zpaq on multi-precomp packs.
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string> $pathKeys
 * @return array{0:string,1:string}|null [wire,codec] when strictly smaller than $nativeBlob
 *         (or any successful build when $nativeBlob is '')
 */
function lifestyle_try_fzb_store_outer_beat_native(
	string $rootDir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	array $pathKeys,
	string $nativeBlob
): ?array {
	if($sumRawBytes <= 0 || $memberCount < 1) {
		return null;
	}
	$allPrecomp = true;
	$allZip = true;
	$img = 0;
	$bmp = 0;
	$audio = 0;
	foreach($pathKeys as $path) {
		$p = (string) $path;
		if(!preg_match('/\\.(zip|7z|rar|gz|bz2|xz|zst|br)$/i', $p)) {
			$allPrecomp = false;
		}
		if(!preg_match('/\\.zip$/i', $p)) {
			$allZip = false;
		}
		if(preg_match('/\\.(png|jpe?g|gif|webp|bmp)$/i', $p)) {
			$img++;
		}
		if(preg_match('/\\.bmp$/i', $p)) {
			$bmp++;
		}
		if(preg_match('/\\.(flac|wav|aiff?|m4a|mp3|ogg|opus)$/i', $p)) {
			$audio++;
		}
	}
	// Small FLAC/album mixes (test_files60): FZB+zstd-19 widens the sole vs soft
	// tar|zstd (~80 B). Same 8 MiB cap as all-.zip ROM pairs (65).
	$audioMajority = ($audio > 0 && $audio * 2 >= max(1, $memberCount)
		&& $memberCount >= 2 && $memberCount <= 8);
	// All-.zip ROM pairs (test_files65): FZB+zstd-19 soles vs soft tar|zstd with
	// ~200 B margin; the generic 4 MiB cap blocked the 5.4 MiB pack. Keep other
	// FZB shapes at 4 MiB so image/precomp storms stay under the half-time bar.
	// Audio albums up to ~12 MiB (test_files165) need the raised cap; ROM zip pairs stay at 8 MiB.
	$maxRaw = ($audioMajority && $memberCount >= 2 && $memberCount <= 8)
		? (12 * 1024 * 1024)
		: ((($allZip) && $memberCount >= 2 && $memberCount <= 8)
			? (8 * 1024 * 1024)
			: (4 * 1024 * 1024));
	if($sumRawBytes > $maxRaw) {
		return null;
	}
	$imageMajority = ($img >= 2 && $img === $memberCount);
	$singleImage = ($memberCount === 1 && $img === 1);
	// Post-race only: tiny all-text packs — FZB+outer can beat soft-tied native.
	// Skip on early empty-native lane so tiny fractal demos stay on deep encode.
	$tinyText = false;
	if($nativeBlob !== '' && !$allPrecomp && !$imageMajority && !$singleImage && !$audioMajority
		&& $memberCount >= 2 && $memberCount <= 4
		&& $sumRawBytes >= 8192 && $sumRawBytes <= 64 * 1024) {
		$tinyText = true;
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.(txt|md|csv|html?|xml|json)$/i', (string) $path)) {
				$tinyText = false;
				break;
			}
		}
	}
	// Tiny/mid nested mixed trees (74/140/148/149/63): raw FZB+br q11 soles soft
	// in <0.05 s; tryhard unified was slower for a few-byte tip. Cap 256 KiB so
	// literal-stress (63 ~179 KiB) joins the early lane.
	$tinyNested = false;
	if(!$allPrecomp && !$imageMajority && !$singleImage && !$audioMajority
		&& $memberCount >= 2 && $memberCount <= 16
		&& $sumRawBytes > 0 && $sumRawBytes <= 256 * 1024) {
		foreach($pathKeys as $path) {
			if(strpos(str_replace('\\', '/', (string) $path), '/') !== false) {
				$tinyNested = true;
				break;
			}
		}
	}
	// Mid nested README+large-.bin (145/150): FZB+br soles soft br; deep ~0.3–0.5 s.
	$midNestedBin = false;
	if(!$tinyNested && !$allPrecomp && !$imageMajority && !$singleImage && !$audioMajority
		&& $memberCount >= 2 && $memberCount <= 8
		&& $sumRawBytes >= 256 * 1024 && $sumRawBytes <= 2 * 1024 * 1024) {
		$hasSubMid = false;
		$hasReadmeMid = false;
		$hasLargeBin = false;
		foreach($pathKeys as $path) {
			$p = str_replace('\\', '/', (string) $path);
			if(strpos($p, '/') !== false) {
				$hasSubMid = true;
			}
			if(preg_match('/README/i', $p)) {
				$hasReadmeMid = true;
			}
			$blob = $rawFilesByPath[$path] ?? null;
			if(is_string($blob) && strlen($blob) >= 256 * 1024
				&& preg_match('/\\.(bin|dat|raw|rgba)$/i', $p)) {
				$hasLargeBin = true;
			}
		}
		$midNestedBin = ($hasSubMid && $hasReadmeMid && $hasLargeBin);
	}
	// Dense tiny .gz forests (62): native 7z is <1 s; peeled FZB burns ~20 s.
	if($allPrecomp && !$allZip && $memberCount >= 16 && $sumRawBytes < 1536 * 1024) {
		return null;
	}
	// Single archives (158/160/163): keep tar|br / FZS1 race — FZB+zpaq loses to soft brotli.
	if($allPrecomp && $memberCount === 1) {
		return null;
	}
	if(!$allPrecomp && !$imageMajority && !$singleImage && !$tinyText && !$tinyNested
		&& !$midNestedBin && !$audioMajority) {
		return null;
	}
	// Audio: only post-race beat vs a real native seed. Empty-native early lane would
	// skip the 7z race and regress test_files165 (FZB+zstd ≫ lifestyle 7z).
	if($audioMajority && $nativeBlob === '') {
		return null;
	}
	// Solid 7z on compressible audio (165 ~70% raw): FZB+zstd cannot win and burns
	// several seconds. Near-incompressible albums (60 ~99% raw) still try FZB.
	if($audioMajority && $nativeBlob !== ''
		&& strlen($nativeBlob) * 100 < $sumRawBytes * 85) {
		return null;
	}
	// Large single BMP/raster: FZB+br burns ~12–18 s and loses to native 7z
	// (~2 s, ~976 KiB; test_files35). Skip early and post-race FZB.
	if($singleImage && $sumRawBytes >= 1048576) {
		return null;
	}
	// Mid mixed-image grids (168 ~1.1 MiB photo+raster mix): FZB+zstd loses ~1.5 KiB
	// to tar|br11 — skip FZB so native brotli can seed. All-BMP grids (155/178) keep
	// FZB+br — tar|br11 loses the soft sole.
	if($imageMajority && $bmp < $memberCount
		&& $sumRawBytes >= 512 * 1024 && $sumRawBytes <= 1536 * 1024) {
		return null;
	}
	$rp = realpath($rootDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	$tmpFzb = sys_get_temp_dir() . DS . 'fzfzb_life_'
		. md5($rp . "\0fzb_life") . '.fzb';
	if(is_file($tmpFzb)) {
		@unlink($tmpFzb);
	}
	// Image / multi-precomp (175/176): preprocess for ratio.
	// All-zip (82) / audio (60) / tiny all-text (196): skip peel — raw FZB+outer
	// already soles soft; peel was ~1.7 s for zero byte gain on 196.
	// Large multi-precomp: peel1+zstd soles vs soft tar|br; pin gzip -9 (not pigz -11)
	// so raster_formats.tar.gz does not burn ~8 s (175/176 still sole by several KiB).
	// Tiny PNG grids (154/169/177): skip image_pac — raw FZB+br still soles soft
	// gzip (~130 B) without the ~0.2–0.5 s GD recompress tax.
	// Mid nested bin demos (145): peel adds wall with no sole gain vs raw FZB+br.
	$skipPre = $allZip || $audioMajority || $tinyText || $tinyNested || $midNestedBin
		|| ($imageMajority && $sumRawBytes > 0 && $sumRawBytes <= 80 * 1024);
	$savedPeel = false;
	$prevPeel = null;
	$prevGzEng = null;
	$prevZop = null;
	$savedGz = false;
	// One peel pass is enough for 176 (same FZB as 24-pass) and cuts ~17 s→~6 s.
	if(!$skipPre && $allPrecomp) {
		$prevPeel = getenv('FRACTAL_ZIP_LITERALPAC_STREAM_PEEL_MAX_PASSES');
		putenv('FRACTAL_ZIP_LITERALPAC_STREAM_PEEL_MAX_PASSES=1');
		$savedPeel = true;
		$prevGzEng = getenv('FRACTAL_ZIP_LITERALPAC_GZIP_ENGINE');
		$prevZop = getenv('FRACTAL_ZIP_LITERALPAC_ZOPFLI');
		putenv('FRACTAL_ZIP_LITERALPAC_GZIP_ENGINE=gzip');
		putenv('FRACTAL_ZIP_LITERALPAC_ZOPFLI=0');
		$savedGz = true;
	}
	$fzbOk = $this->stream_literal_bundle_fzb4_to_file($rp, $tmpFzb, true, $skipPre);
	if($savedPeel) {
		if($prevPeel === false) {
			putenv('FRACTAL_ZIP_LITERALPAC_STREAM_PEEL_MAX_PASSES');
		} else {
			putenv('FRACTAL_ZIP_LITERALPAC_STREAM_PEEL_MAX_PASSES=' . $prevPeel);
		}
	}
	if($savedGz) {
		if($prevGzEng === false) {
			putenv('FRACTAL_ZIP_LITERALPAC_GZIP_ENGINE');
		} else {
			putenv('FRACTAL_ZIP_LITERALPAC_GZIP_ENGINE=' . $prevGzEng);
		}
		if($prevZop === false) {
			putenv('FRACTAL_ZIP_LITERALPAC_ZOPFLI');
		} else {
			putenv('FRACTAL_ZIP_LITERALPAC_ZOPFLI=' . $prevZop);
		}
	}
	if(!$fzbOk || !is_file($tmpFzb)) {
		return null;
	}
	$inner = file_get_contents($tmpFzb);
	@unlink($tmpFzb);
	if(!is_string($inner) || $inner === '') {
		return null;
	}
	$best = null;
	$bestCodec = null;
	$consider = static function (string $blob, string $name) use (&$best, &$bestCodec): void {
		if($blob === '') {
			return;
		}
		if($best === null || strlen($blob) < strlen($best)) {
			$best = $blob;
			$bestCodec = $name;
		}
	};
	// Prefer br/zstd on FZB for all-zip / images / tiny-text / peeled precomp.
	// All-zip (82): FZB+zstd soles vs soft folder-zstd in <1 s; zpaq wastes ~12 s.
	// Large multi-precomp skipPre (175): skip br/zstd here — they lose to soft brotli;
	// zpaq block below is the sole path.
	$wantBrZstd = $imageMajority || $singleImage || $tinyText || $tinyNested
		|| $midNestedBin || $audioMajority
		|| ($allPrecomp && !$skipPre) || $allZip;
	if($wantBrZstd) {
		// All-zip (82) / audio (60) / multi-precomp (175/176): zstd soles vs soft; skip br11 tax.
		// Mid/large single image (≥256 KiB, 81): br11 loses to zstd-19 and burns ~2 s.
		// Tiny single BMP (64 ~166 KiB): FZB+br soles soft (~80 B); zstd-only loses sole.
		// Mixed photo grids (≥256 KiB, 168): FZB skipped entirely (native tar|br11).
		// All-BMP mid grids (155/178): keep FZB+br — zstd-only loses soft sole.
		// Tiny PNG grids (154/169/177): q10 soles soft gzip (~130 B) in ~0.1 s;
		// q11 adds ~0.2 s for ≤10 B. Other shapes keep q11.
		$skipBrotli = $allZip || $allPrecomp || $audioMajority
			|| ($singleImage && $sumRawBytes >= 256 * 1024)
			|| ($imageMajority && $sumRawBytes >= 256 * 1024 && $bmp < $memberCount);
		if(!$skipBrotli) {
			$brotliExe = fractal_zip::brotli_executable();
			if($brotliExe !== null && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_BROTLI')) {
				$brQ = ($imageMajority && $sumRawBytes > 0 && $sumRawBytes <= 80 * 1024)
					? 10 : 11;
				$br = $this->outer_brotli_blob($brotliExe, $inner, $brQ);
				if(is_string($br) && $br !== '') {
					$consider($br, 'brotli');
				}
			}
		}
		$zstdExe = fractal_zip::zstd_executable();
		if($zstdExe !== null && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ZSTD')) {
			// Mid/large single image (81): zstd-6 already soles soft xz by tens of KiB;
			// zstd-19 adds ~60 ms for ~11 KiB. Keep -19 for grids / all-zip / audio.
			$zstdLevel = ($singleImage && $sumRawBytes >= 256 * 1024) ? 6 : 19;
			$zs = $this->outer_zstd_blob($zstdExe, $inner, $zstdLevel);
			if(is_string($zs) && $zs !== '') {
				$consider($zs, 'zstd');
			}
		}
	}
	// zpaq m5 only on large multi-precomp raw FZB (175): skipPre br/zstd lose to soft
	// brotli; image grids / all-zip already sole via br/zstd above.
	$zpaqExe = fractal_zip::zpaq_executable();
	if($zpaqExe !== null && $skipPre && $allPrecomp && !$allZip) {
		$work = sys_get_temp_dir() . DS . 'fzfzb_zq_'
			. md5($rp . "\0fzb_zq") . '_w';
		if(is_dir($work)) {
			$this->recursive_remove_directory($work);
		}
		@mkdir($work, 0755, true);
		$innerPath = $work . DS . 'i';
		$arcPath = $work . DS . 'inner.zpaq';
		if(@file_put_contents($innerPath, $inner) !== false) {
			$cwd = getcwd();
			$ret = -1;
			if(@chdir($work)) {
				$cmd = fractal_zip::shell_quote_arg_cached($zpaqExe)
					. ' -threads 1 add inner.zpaq i -method 5 -force';
				exec($cmd . ' 2>/dev/null', $xo, $ret);
			}
			if($cwd !== false) {
				chdir($cwd);
			}
			if($ret === 0 && is_file($arcPath)) {
				$r = file_get_contents($arcPath);
				if(is_string($r) && $r !== '') {
					$consider(fractal_zip::OUTER_ZPAQ_MAGIC . $r, 'zpaq');
				}
			}
		}
		if(is_dir($work)) {
			$this->recursive_remove_directory($work);
		}
	}
	// Multi-precomp: zpaq5 is the soft-zpaq beater; skip tar|brotli here (adds ~5 s).
	if(!is_string($best) || $best === '' || !is_string($bestCodec)) {
		return null;
	}
	// Empty $nativeBlob ⇒ take any successful FZB+outer (early lifestyle lane).
	if($nativeBlob !== '' && strlen($best) >= strlen($nativeBlob)) {
		return null;
	}
	return array($best, $bestCodec);
}

/**
 * Lifestyle: small all-WAV albums → FLAC -8 with {@code --keep-foreign-metadata}
 * packed as FZWF v1 (bit-exact WAV restore). test_files165: ~6.69 MiB wire vs
 * zpaq-of-WAV ~6.93 MiB, encode ≪1 s vs ~35 s.
 *
 * Layout: magic "FZWF" + u8 ver=1 + varint n + n×(varint pathLen, path, varint flacLen, flac).
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string> $pathKeys
 */
function write_lifestyle_wav_flac_fzwf_container(
	$dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	array $pathKeys
): bool {
	if(!fractal_zip::lifestyle_speed_profile_enabled()
		|| $memberCount < 2
		|| $memberCount > 16
		|| $sumRawBytes <= 0
		|| $sumRawBytes > 32 * 1024 * 1024
		|| PHP_OS_FAMILY === 'Windows') {
		return false;
	}
	$flacExe = fractal_zip::flac_cli_executable();
	if($flacExe === null) {
		return false;
	}
	foreach($pathKeys as $path) {
		if(!preg_match('/\\.wav$/i', (string) $path)) {
			return false;
		}
	}
	$root = realpath((string) $dir);
	if($root === false || !is_dir($root)) {
		return false;
	}
	$tmp = sys_get_temp_dir() . DS . 'fzwf_' . md5($root . "\0" . (string) $sumRawBytes);
	if(is_dir($tmp)) {
		$this->recursive_remove_directory($tmp);
	}
	if(!@mkdir($tmp, 0700, true)) {
		return false;
	}
	$ordered = $pathKeys;
	sort($ordered, SORT_STRING);
	$parts = array('FZWF' . chr(1) . $this->encode_varint_u32(count($ordered)));
	$wireBody = 0;
	$qFlac = fractal_zip::shell_quote_arg_cached($flacExe);
	foreach($ordered as $rel) {
		$rel = str_replace('\\', '/', (string) $rel);
		if($rel === '' || str_contains($rel, '..')) {
			$this->recursive_remove_directory($tmp);
			return false;
		}
		$abs = $root . DS . str_replace('/', DS, $rel);
		if(!is_file($abs)) {
			$this->recursive_remove_directory($tmp);
			return false;
		}
		$flacTmp = $tmp . DS . 'm' . md5($rel) . '.flac';
		$ret = -1;
		// -e (exhaustive model search): ~2 KiB reclaim on 165 vs plain -8 at
		// similar wall (~2 s). Keep --keep-foreign-metadata for bit-exact WAV.
		$cmd = $qFlac . ' -s -8 -e -f --keep-foreign-metadata -o '
			. fractal_zip::shell_quote_arg_cached($flacTmp) . ' '
			. fractal_zip::shell_quote_arg_cached($abs) . ' 2>/dev/null';
		exec($cmd, $xo, $ret);
		if((int) $ret !== 0 || !is_file($flacTmp) || (int) filesize($flacTmp) <= 0) {
			$this->recursive_remove_directory($tmp);
			return false;
		}
		$flacBytes = @file_get_contents($flacTmp);
		@unlink($flacTmp);
		if(!is_string($flacBytes) || $flacBytes === '') {
			$this->recursive_remove_directory($tmp);
			return false;
		}
		$wireBody += strlen($flacBytes);
		$parts[] = $this->encode_varint_u32(strlen($rel)) . $rel
			. $this->encode_varint_u32(strlen($flacBytes)) . $flacBytes;
	}
	$this->recursive_remove_directory($tmp);
	// Must clearly beat raw (and typical zpaq-of-WAV ~65% raw) before owning the tip.
	if($wireBody <= 0 || $wireBody * 100 >= $sumRawBytes * 85) {
		return false;
	}
	$blob = implode('', $parts);
	$fzcPath = $this->zip_folder_fzc_output_path($dir);
	if(file_put_contents($fzcPath, $blob) === false) {
		return false;
	}
	fractal_zip::$last_outer_codec = 'fzwf';
	fractal_zip::$last_written_container_codec = 'fzwf';
	fractal_zip::$folder_zip_wire_best_outer_codec = 'fzwf';
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	fractal_zip::$used_folder_unified_stream = false;
	fractal_zip::$used_folder_per_member_best = false;
	fractal_zip::html_trace_print(
		'Lifestyle speed-first: WAV→FLAC -8 --keep-foreign-metadata (FZWF).<br>'
	);
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

/**
 * Lifestyle/ultra: small all-.zip packs (ROM pairs, test_files82) —
 * opaque zpaq-of-zips ≈ raw. Disk-unzip every outer zip → FreeArc -m5 of the
 * inners → FZCL+FZHR ZIP_MULTI (~−119 KiB vs zpaq, ≪1 s) with semantic PKZIP
 * verify. Single-file inners are supported (literal pac rebuild n≥1).
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string> $pathKeys
 */
function write_lifestyle_small_allzip_unpack_arc_fzcl_container(
	$dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	array $pathKeys
): bool {
	if((!fractal_zip::lifestyle_speed_profile_enabled()
			&& !fractal_zip::ultra_compression_enabled())
		|| $memberCount < 2
		|| $memberCount > 4
		|| $sumRawBytes < 512 * 1024
		|| $sumRawBytes > 8 * 1024 * 1024
		|| PHP_OS_FAMILY === 'Windows') {
		return false;
	}
	if(fractal_zip::freearc_executable() === null
		|| !fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')) {
		return false;
	}
	foreach($pathKeys as $path) {
		if(!preg_match('/\\.zip$/i', (string) $path)) {
			return false;
		}
	}
	$root = realpath((string) $dir);
	if($root === false || !is_dir($root) || !class_exists(ZipArchive::class)) {
		return false;
	}
	fractal_zip_ensure_folder_logical_bundle_loaded();
	$classicPeel = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_classic_peel.php';
	if(is_readable($classicPeel)) {
		require_once $classicPeel;
	}
	if(!function_exists('fractal_zip_classic_encode_fzcl_v1')
		|| !defined('FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI')) {
		return false;
	}
	$unzip = trim((string) shell_exec('command -v unzip 2>/dev/null'));
	if($unzip === '') {
		return false;
	}
	$restore = array();
	$seenNames = array();
	$totalInner = 0;
	$nInner = 0;
	foreach($pathKeys as $path) {
		$zipRel = str_replace('\\', '/', (string) $path);
		$zipAbs = $root . DS . str_replace('/', DS, $zipRel);
		if(!is_file($zipAbs)) {
			return false;
		}
		$za = new ZipArchive();
		if($za->open($zipAbs) !== true) {
			return false;
		}
		$names = array();
		for($i = 0; $i < $za->numFiles; $i++) {
			$st = $za->statIndex($i);
			if($st === false) {
				continue;
			}
			$n = str_replace('\\', '/', (string) ($st['name'] ?? ''));
			if($n === '' || str_ends_with($n, '/')) {
				continue;
			}
			$n = ltrim($n, '/');
			if($n === '' || str_contains($n, '..') || isset($seenNames[$n])) {
				$za->close();
				return false;
			}
			$seenNames[$n] = true;
			$names[] = $n;
			$totalInner += (int) ($st['size'] ?? 0);
			$nInner++;
		}
		$za->close();
		// ROM dumps: 1–4 files per outer zip; reject empty / huge peels.
		if($names === array() || count($names) > 4) {
			return false;
		}
		$restore[$zipRel] = array(
			'kind' => (int) FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI,
			'member_names' => $names,
		);
	}
	if($nInner < 2 || $totalInner < $sumRawBytes) {
		return false;
	}
	$tmp = sys_get_temp_dir() . DS . 'fz_allzip_arc_' . getmypid() . '_' . bin2hex(random_bytes(3));
	$arcOut = $tmp . '.arc';
	if(is_dir($tmp)) {
		$this->recursive_remove_directory($tmp);
	}
	if(!@mkdir($tmp, 0700, true)) {
		return false;
	}
	foreach($pathKeys as $path) {
		$zipRel = str_replace('\\', '/', (string) $path);
		$zipAbs = $root . DS . str_replace('/', DS, $zipRel);
		$retUn = -1;
		exec(
			fractal_zip::shell_quote_arg_cached($unzip) . ' -q -o '
				. fractal_zip::shell_quote_arg_cached($zipAbs) . ' -d '
				. fractal_zip::shell_quote_arg_cached($tmp) . ' 2>/dev/null',
			$xoUn,
			$retUn
		);
		if((int) $retUn !== 0) {
			$this->recursive_remove_directory($tmp);
			return false;
		}
	}
	// Ultra: peeleed Genesis ROMs (.bin/.smd) → per-member paq8 FZpq → FZHM+FZHR
	// ZIP_MULTI (~−172 KiB vs opaque Arc-of-zips on 82, ~22 min). Lifestyle
	// keeps FreeArc -m5 below (≪1 s).
	$allRomInners = ($seenNames !== array());
	foreach(array_keys($seenNames) as $innerName) {
		if(!preg_match('/\\.(bin|smd)$/i', (string) $innerName)) {
			$allRomInners = false;
			break;
		}
	}
	if(fractal_zip::ultra_compression_enabled()
		&& $allRomInners
		&& function_exists('fractal_zip_encode_fzhm_v1_with_restore')) {
		if(!function_exists('fractal_zip_encode_fzhm_v1')) {
			$pmb = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_folder_per_member_best.php';
			if(is_readable($pmb)) {
				require_once $pmb;
			}
		}
		if(!function_exists('fractal_zip_encode_fzhm_v1')) {
			// Fall through to FreeArc path.
		} else {
		$wires = array();
		$romIt = new RecursiveIteratorIterator(
			new RecursiveDirectoryIterator($tmp, FilesystemIterator::SKIP_DOTS)
		);
		$tmpLen = strlen($tmp) + 1;
		foreach($romIt as $fi) {
			if(!$fi->isFile()) {
				continue;
			}
			$abs = $fi->getPathname();
			$rel = str_replace('\\', '/', substr($abs, $tmpLen));
			if($rel === '' || strpos($rel, '..') !== false) {
				continue;
			}
			$plain = @file_get_contents($abs);
			if(!is_string($plain) || $plain === '') {
				continue;
			}
			$w = $this->try_build_single_member_mcm_fzpq_wire($rel, $plain);
			if(!is_string($w) || $w === '' || strlen($w) < 256) {
				$wires = array();
				break;
			}
			$wires[$rel] = $w;
		}
		if($wires !== array() && count($wires) === count($seenNames)) {
			ksort($wires, SORT_STRING);
			$fzhm = fractal_zip_encode_fzhm_v1_with_restore($wires, $restore);
			unset($wires);
			if(is_string($fzhm) && $fzhm !== ''
				&& strlen($fzhm) + 4096 < $sumRawBytes) {
				$fzcPath = $this->zip_folder_fzc_output_path($dir);
				if(@file_put_contents($fzcPath, $fzhm) !== false) {
					unset($fzhm);
					$this->recursive_remove_directory($tmp);
					if(is_file($arcOut)) {
						@unlink($arcOut);
					}
					fractal_zip::$last_outer_codec = 'paq';
					fractal_zip::$last_written_container_codec = 'paq';
					fractal_zip::$folder_zip_wire_best_outer_codec = 'paq';
					fractal_zip::$used_folder_gzip_fast = false;
					fractal_zip::$used_folder_literal_fzb4_store = false;
					fractal_zip::$used_folder_unified_stream = false;
					fractal_zip::$used_folder_per_member_best = true;
					fractal_zip::html_trace_print(
						'Ultra: small all-zip unpack+paq8 FZHM ZIP_MULTI.<br>'
					);
					$micro_time_taken = microtime(true) - $this->initial_micro_time;
					fractal_zip::html_trace_print(
						'Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>'
					);
					$this->zip_folder_root_for_members = '';
					return true;
				}
			}
			unset($fzhm);
		}
		} // encode_fzhm_v1 available
	}
	$arcExe = fractal_zip::freearc_executable();
	$prefix = $this->command_prefix_with_local_lib();
	$qArc = fractal_zip::shell_quote_arg_cached($arcExe);
	$mt = fractal_zip::library_arc_compress_mt_shell_fragment_for_exec();
	$cwd = getcwd();
	$retArc = -1;
	if(@chdir($tmp)) {
		$cmd = $prefix . $qArc
			. ' a -m5' . $mt . ' -ep1 -y '
			. fractal_zip::shell_quote_arg_cached($arcOut) . ' . 2>/dev/null';
		exec($cmd, $xoArc, $retArc);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	$this->recursive_remove_directory($tmp);
	if((int) $retArc !== 0 || !is_file($arcOut) || (int) filesize($arcOut) <= 0) {
		if(is_file($arcOut)) {
			@unlink($arcOut);
		}
		return false;
	}
	$arcBytes = @file_get_contents($arcOut);
	@unlink($arcOut);
	if(!is_string($arcBytes) || $arcBytes === '') {
		return false;
	}
	$fzcl = fractal_zip_classic_encode_fzcl_v1($arcBytes, $restore);
	unset($arcBytes);
	// Must reclaim ≥4 KiB vs opaque zip-of-zips raw (82: ~119 KiB).
	if($fzcl === '' || strlen($fzcl) + 4096 >= $sumRawBytes) {
		return false;
	}
	$fzcPath = $this->zip_folder_fzc_output_path($dir);
	if(@file_put_contents($fzcPath, $fzcl) === false) {
		return false;
	}
	unset($fzcl);
	fractal_zip::$last_outer_codec = 'arc';
	fractal_zip::$last_written_container_codec = 'arc';
	fractal_zip::$folder_zip_wire_best_outer_codec = 'arc';
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	fractal_zip::$used_folder_unified_stream = false;
	fractal_zip::$used_folder_per_member_best = true;
	fractal_zip::html_trace_print(
		'Lifestyle speed-first: small all-zip unpack+FreeArc -m5 (FZCL).<br>'
	);
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

/**
 * Lifestyle: midsize single multi-member .zip (silesia / test_files78) —
 * opaque 7z-of-zip ≈ raw (~67 MiB). Disk-unzip → FreeArc -m9 of the inners →
 * FZCL+FZHR ZIP_MULTI (~45.7 MiB, ~90 s) soles soft while keeping semantic
 * PKZIP verify (FRACTAL_ZIP_FOLDER_CONTAINER_SEMANTIC_VERIFY default on).
 * Avoids in-PHP peel resolve (OOMs at 1 GiB on silesia rebuild-matching).
 *
 * @param array<string,string> $rawFilesByPath
 * @param list<string> $pathKeys
 */
function write_lifestyle_midsize_zip_multi_arc_fzcl_container(
	$dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	array $pathKeys
): bool {
	if(!fractal_zip::lifestyle_speed_profile_enabled()
		|| $memberCount !== 1
		|| $sumRawBytes < 32 * 1024 * 1024
		|| $sumRawBytes > 96 * 1024 * 1024
		|| PHP_OS_FAMILY === 'Windows') {
		return false;
	}
	if(fractal_zip::freearc_executable() === null
		|| !fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')) {
		return false;
	}
	$zipRel = null;
	foreach($pathKeys as $path) {
		$zipRel = str_replace('\\', '/', (string) $path);
		break;
	}
	if($zipRel === null || !preg_match('/\\.zip$/i', $zipRel)) {
		return false;
	}
	$root = realpath((string) $dir);
	if($root === false || !is_dir($root)) {
		return false;
	}
	$zipAbs = $root . DS . str_replace('/', DS, $zipRel);
	if(!is_file($zipAbs) || !class_exists(ZipArchive::class)) {
		return false;
	}
	$za = new ZipArchive();
	if($za->open($zipAbs) !== true) {
		return false;
	}
	$names = array();
	$payloadBytes = 0;
	$nFiles = 0;
	for($i = 0; $i < $za->numFiles; $i++) {
		$st = $za->statIndex($i);
		if($st === false) {
			continue;
		}
		$n = str_replace('\\', '/', (string) ($st['name'] ?? ''));
		if($n === '' || str_ends_with($n, '/')) {
			continue;
		}
		$n = ltrim($n, '/');
		if($n === '' || str_contains($n, '..')) {
			$za->close();
			return false;
		}
		$names[] = $n;
		$payloadBytes += (int) ($st['size'] ?? 0);
		$nFiles++;
	}
	$za->close();
	// Silesia-class: ≥8 members, expanded payload clearly larger than the zip.
	if($nFiles < 8 || $nFiles > 64 || $payloadBytes < $sumRawBytes * 2) {
		return false;
	}
	fractal_zip_ensure_folder_logical_bundle_loaded();
	$classicPeel = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_classic_peel.php';
	if(is_readable($classicPeel)) {
		require_once $classicPeel;
	}
	$pmb = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_folder_per_member_best.php';
	if(is_readable($pmb)) {
		require_once $pmb;
	}
	if(!function_exists('fractal_zip_classic_encode_fzcl_v1')
		|| !defined('FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI')) {
		return false;
	}
	$unzip = trim((string) shell_exec('command -v unzip 2>/dev/null'));
	if($unzip === '') {
		return false;
	}
	$tmp = sys_get_temp_dir() . DS . 'fz_zip_arc_' . getmypid() . '_' . bin2hex(random_bytes(3));
	$arcOut = $tmp . '.arc';
	if(is_dir($tmp)) {
		$this->recursive_remove_directory($tmp);
	}
	if(!@mkdir($tmp, 0700, true)) {
		return false;
	}
	$retUn = -1;
	exec(
		fractal_zip::shell_quote_arg_cached($unzip) . ' -q -o '
			. fractal_zip::shell_quote_arg_cached($zipAbs) . ' -d '
			. fractal_zip::shell_quote_arg_cached($tmp) . ' 2>/dev/null',
		$xoUn,
		$retUn
	);
	if((int) $retUn !== 0) {
		$this->recursive_remove_directory($tmp);
		return false;
	}
	$arcExe = fractal_zip::freearc_executable();
	$prefix = $this->command_prefix_with_local_lib();
	$qArc = fractal_zip::shell_quote_arg_cached($arcExe);
	$mt = fractal_zip::library_arc_compress_mt_shell_fragment_for_exec();
	$cwd = getcwd();
	$retArc = -1;
	if(@chdir($tmp)) {
		$cmd = $prefix . $qArc
			. ' a -m9' . $mt . ' -ep1 -y '
			. fractal_zip::shell_quote_arg_cached($arcOut) . ' . 2>/dev/null';
		exec($cmd, $xoArc, $retArc);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	$this->recursive_remove_directory($tmp);
	if((int) $retArc !== 0 || !is_file($arcOut) || (int) filesize($arcOut) <= 0) {
		if(is_file($arcOut)) {
			@unlink($arcOut);
		}
		return false;
	}
	$arcBytes = @file_get_contents($arcOut);
	@unlink($arcOut);
	if(!is_string($arcBytes) || $arcBytes === '') {
		return false;
	}
	// Beat opaque 7z-of-zip by a clear margin; otherwise keep the fast path.
	if(strlen($arcBytes) * 10 > $sumRawBytes * 9) {
		return false;
	}
	$restore = array(
		$zipRel => array(
			'kind' => (int) FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI,
			'member_names' => $names,
		),
	);
	$fzcl = fractal_zip_classic_encode_fzcl_v1($arcBytes, $restore);
	unset($arcBytes);
	if($fzcl === '' || strlen($fzcl) >= $sumRawBytes) {
		return false;
	}
	$fzcPath = $this->zip_folder_fzc_output_path($dir);
	if(@file_put_contents($fzcPath, $fzcl) === false) {
		return false;
	}
	unset($fzcl);
	fractal_zip::$last_outer_codec = 'arc';
	fractal_zip::$last_written_container_codec = 'arc';
	fractal_zip::$folder_zip_wire_best_outer_codec = 'arc';
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	fractal_zip::$used_folder_unified_stream = false;
	fractal_zip::$used_folder_per_member_best = true;
	fractal_zip::html_trace_print(
		'Lifestyle speed-first: midsize ZIP_MULTI unpack+FreeArc -m9 (FZCL).<br>'
	);
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

function write_lifestyle_speed_first_7z_folder_container(
	$dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $allRelPaths = null
): bool {
	if(!fractal_zip::lifestyle_should_prefer_native_7z_passthrough($rawFilesByPath, $sumRawBytes, $memberCount, $allRelPaths)) {
		return false;
	}
	$resolvedRoot = realpath((string) $dir);
	$this->zip_folder_root_for_members = $resolvedRoot !== false ? $resolvedRoot : (string) $dir;
	$pathKeys = $allRelPaths !== null && $allRelPaths !== array()
		? $allRelPaths
		: array_keys($rawFilesByPath);
	// WAV albums (test_files165): flac -8 --keep-foreign-metadata → FZWF (~−230 KiB
	// vs zpaq of WAV, ≪1 s encode) with bit-exact restore.
	if($this->write_lifestyle_wav_flac_fzwf_container(
		$dir,
		$rawFilesByPath,
		$sumRawBytes,
		$memberCount,
		$pathKeys
	)) {
		return true;
	}
	// ROM zip pairs (82): unpack+Arc FZCL before silesia-scale single-zip path.
	if($this->write_lifestyle_small_allzip_unpack_arc_fzcl_container(
		$dir,
		$rawFilesByPath,
		$sumRawBytes,
		$memberCount,
		$pathKeys
	)) {
		return true;
	}
	if($this->write_lifestyle_midsize_zip_multi_arc_fzcl_container(
		$dir,
		$rawFilesByPath,
		$sumRawBytes,
		$memberCount,
		$pathKeys
	)) {
		return true;
	}
	// Large single textlike (enwik8): FreeArc -m7 reclaim ~3.5 MiB vs mx=9 7z and
	// is faster (~55 s vs ~103 s). Prefer-native routes here before the midsize
	// tournament (cheap-fractal probe is negative on extensionless dumps).
	if($memberCount === 1 && $sumRawBytes >= 48 * 1024 * 1024
		&& $sumRawBytes <= 128 * 1024 * 1024
		&& fractal_zip::freearc_executable() !== null
		&& fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')) {
		$singleEarly = null;
		foreach($pathKeys as $path) {
			$singleEarly = (string) $path;
			break;
		}
		if($singleEarly !== null
			&& !preg_match('/\\.(7z|zip|rar|gz|bz2|xz|zst)$/i', $singleEarly)) {
			$blobEarly = $rawFilesByPath[$singleEarly] ?? null;
			$textEarly = false;
			if(is_string($blobEarly) && $blobEarly !== '') {
				$textEarly = $this->outer_likely_textlike(
					strlen($blobEarly) > 65536 ? substr($blobEarly, 0, 65536) : $blobEarly
				);
			} else {
				$textEarly = (bool) preg_match(
					'/^(enwik\\d*|.*\\.(txt|xml|html?|csv|json|md))$/i',
					basename(str_replace('\\', '/', $singleEarly))
				);
			}
			if($textEarly) {
				// Arc -m9: enwik8 ~20.75 MiB in ~70–75 s (−398 KiB vs -m7, still ≪ soft).
				// zpaq -m5: enwik8 ~19.63 MiB in ~285 s (−1.1 MiB vs Arc; still ≪ fair).
				// Prefer zpaq first; skip Arc when zpaq is already ≤1/5 raw.
				$bestEarly = null;
				$bestEarlyCodec = null;
				if(fractal_zip::zpaq_executable() !== null) {
					$zpEarly = $this->try_build_folder_zpaq_squash_noattr_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath,
						$sumRawBytes,
						5
					);
					if(is_string($zpEarly) && $zpEarly !== '') {
						$bestEarly = $zpEarly;
						$bestEarlyCodec = 'zpaq';
					}
				}
				$skipArcAfterZpaq = is_string($bestEarly) && $bestEarly !== ''
					&& strlen($bestEarly) * 5 < $sumRawBytes;
				if(!$skipArcAfterZpaq) {
					$arcEarly = $this->try_build_folder_freearc_native_archive_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath,
						$sumRawBytes,
						array(9)
					);
					if(is_string($arcEarly) && $arcEarly !== ''
						&& ($bestEarly === null || strlen($arcEarly) < strlen($bestEarly))) {
						$bestEarly = $arcEarly;
						$bestEarlyCodec = 'arc';
					}
				}
				if(is_string($bestEarly) && $bestEarly !== ''
					&& strlen($bestEarly) * 10 < $sumRawBytes * 3) {
					$fzcEarly = $this->zip_folder_fzc_output_path($dir);
					if(file_put_contents($fzcEarly, $bestEarly) !== false) {
						fractal_zip::$last_outer_codec = $bestEarlyCodec;
						fractal_zip::$last_written_container_codec = $bestEarlyCodec;
						fractal_zip::$folder_zip_wire_best_outer_codec = $bestEarlyCodec;
						fractal_zip::$used_folder_gzip_fast = false;
						fractal_zip::$used_folder_literal_fzb4_store = false;
						fractal_zip::$used_folder_unified_stream = false;
						fractal_zip::$used_folder_per_member_best = false;
						fractal_zip::html_trace_print(
							'Lifestyle speed-first: large textlike native '
							. ($bestEarlyCodec === 'zpaq' ? 'zpaq -m5' : 'FreeArc -m9')
							. '.<br>'
						);
						$micro_time_taken = microtime(true) - $this->initial_micro_time;
						fractal_zip::html_trace_print(
							'Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>'
						);
						$this->zip_folder_root_for_members = '';
						return true;
					}
				}
			}
		}
	}
	// Near-dup text forests (90 ~11 MiB): tar|br q9 soles soft in ~0.04 s —
	// write immediately; later race used q11 (~0.4 s) for a larger wire.
	if(fractal_zip::lifestyle_near_duplicate_text_forest_likely(
			$rawFilesByPath,
			$sumRawBytes,
			$memberCount,
			$pathKeys
		)
		&& fractal_zip::folder_native_brotli_compare_enabled()) {
		$savedBqNd = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=9');
		$brNd = $this->try_build_folder_brotli_native_tar_br_blob(
			$this->zip_folder_root_for_members,
			$rawFilesByPath
		);
		if($savedBqNd === false) {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		} else {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . $savedBqNd);
		}
		if(is_string($brNd) && $brNd !== '') {
			$fzcNd = $this->zip_folder_fzc_output_path($dir);
			if(file_put_contents($fzcNd, $brNd) !== false) {
				fractal_zip::$last_outer_codec = 'brotli';
				fractal_zip::$last_written_container_codec = 'brotli';
				fractal_zip::$folder_zip_wire_best_outer_codec = 'brotli';
				fractal_zip::$used_folder_gzip_fast = false;
				fractal_zip::$used_folder_literal_fzb4_store = false;
				fractal_zip::$used_folder_unified_stream = false;
				fractal_zip::$used_folder_per_member_best = false;
				fractal_zip::html_trace_print(
					'Lifestyle speed-first: near-dup text forest tar|brotli-q9.<br>'
				);
				$micro_time_taken = microtime(true) - $this->initial_micro_time;
				fractal_zip::html_trace_print(
					'Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>'
				);
				$this->zip_folder_root_for_members = '';
				return true;
			}
		}
	}
	// Dense micro 1-byte forests (50/51): mx=9 7z soles soft; early-return skips
	// the br/xz race (~0.15 s tax on <1 KiB raw).
	if($memberCount >= 64 && $sumRawBytes > 0 && $sumRawBytes <= 4 * 1024) {
		$z7micro = $this->try_build_folder_7z_native_archive_blob(
			$this->zip_folder_root_for_members,
			$rawFilesByPath,
			true
		);
		if(is_string($z7micro) && $z7micro !== '') {
			$fzcMicro = $this->zip_folder_fzc_output_path($dir);
			if(file_put_contents($fzcMicro, $z7micro) !== false) {
				fractal_zip::$last_outer_codec = '7z';
				fractal_zip::$last_written_container_codec = '7z';
				fractal_zip::$folder_zip_wire_best_outer_codec = '7z';
				fractal_zip::$used_folder_gzip_fast = false;
				fractal_zip::$used_folder_literal_fzb4_store = false;
				fractal_zip::$used_folder_unified_stream = false;
				fractal_zip::$used_folder_per_member_best = false;
				fractal_zip::html_trace_print(
					'Lifestyle speed-first: dense micro forest 7z.<br>'
				);
				$micro_time_taken = microtime(true) - $this->initial_micro_time;
				fractal_zip::html_trace_print(
					'Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>'
				);
				$this->zip_folder_root_for_members = '';
				return true;
			}
		}
	}
	// Tiny single .7z/.rar (159): FZS1 store soles soft gzip — write and return
	// before any brotli/gzip/tournament probes.
	if($memberCount === 1 && $sumRawBytes > 0 && $sumRawBytes <= 512 * 1024) {
		$tiny7zRel = null;
		$tiny7zBlob = null;
		foreach($rawFilesByPath as $rk => $rb) {
			if(preg_match('/\\.(7z|rar)$/i', (string) $rk) && is_string($rb) && $rb !== '') {
				$tiny7zRel = str_replace('\\', '/', (string) $rk);
				$tiny7zBlob = $rb;
			}
			break;
		}
		if($tiny7zRel !== null && $tiny7zBlob !== null) {
			$storeTiny = $this->encode_single_member_raw_payload($tiny7zRel, $tiny7zBlob);
			if(is_string($storeTiny) && $storeTiny !== '') {
				$fzcTiny7z = $this->zip_folder_fzc_output_path($dir);
				if(file_put_contents($fzcTiny7z, $storeTiny) !== false) {
					fractal_zip::$last_outer_codec = 'store';
					fractal_zip::$last_written_container_codec = 'store';
					fractal_zip::$folder_zip_wire_best_outer_codec = 'store';
					fractal_zip::$used_folder_gzip_fast = false;
					fractal_zip::$used_folder_literal_fzb4_store = false;
					fractal_zip::$used_folder_unified_stream = false;
					fractal_zip::$used_folder_per_member_best = false;
					fractal_zip::html_trace_print(
						'Lifestyle speed-first: tiny .7z/.rar FZS1 store.<br>'
					);
					$micro_time_taken = microtime(true) - $this->initial_micro_time;
