				&& fractal_zip::folder_native_xz_compare_enabled()) {
				$considerSingle(
					$this->try_build_folder_xz_native_tar_xz_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath
					),
					'xz'
				);
			}
			if(is_string($bestSingle) && $bestSingle !== '' && is_string($bestSingleCodec)) {
				$native = $bestSingle;
				$codec = $bestSingleCodec;
			}
		} else {
			// 256 KiB–4 MiB singles: textlike CSV/plain → FreeArc -m5 (skip FZS1+br11 storm).
			// Non-textlike below 1 MiB: leave native empty for the 7z seed below.
			$singleBlob = $rawFilesByPath[$singleRel];
			$textlikeMid = is_string($singleBlob) && $singleBlob !== ''
				&& $this->outer_likely_textlike($singleBlob);
			$bestSingle = null;
			$bestSingleCodec = null;
			$considerSingle = static function (?string $blob, string $name) use (&$bestSingle, &$bestSingleCodec): void {
				if(!is_string($blob) || $blob === '') {
					return;
				}
				if($bestSingle === null || strlen($blob) < strlen($bestSingle)) {
					$bestSingle = $blob;
					$bestSingleCodec = $name;
				}
			};
			// OLE office (kennedy.xls / 114 ~1006 KiB): FreeArc -m3 below owns the
			// sole wire in ~0.08 s. xz/FZS1 storms here were ~1.2 s then discarded.
			$oleOfficeSingle = fractal_zip::lifestyle_speed_profile_enabled()
				&& preg_match('/\\.(xls|doc|ppt)$/i', (string) $singleRel);
			if($oleOfficeSingle) {
				// leave native empty for Office/OLE Arc -m3 seed below
			} elseif($textlikeMid) {
				// CSV/plain mid singles (53/151): -m7 reclaims ~244 B vs -m5 at
				// similar wall; keep both and take the smaller.
				$considerSingle(
					$this->try_build_folder_freearc_native_archive_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath,
						$sumRawBytes,
						array(5, 7)
					),
					'arc'
				);
			} elseif($sumRawBytes >= 1048576) {
				$inner = $this->encode_single_member_raw_payload($singleRel, $rawFilesByPath[$singleRel]);
				$zstdExe = fractal_zip::zstd_executable();
				if($zstdExe !== null && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ZSTD')) {
					$zBlob = $this->outer_zstd_blob($zstdExe, $inner, 6);
					if(is_string($zBlob) && $zBlob !== '') {
						$considerSingle($zBlob, 'zstd');
					}
				}
				$brotliExe = fractal_zip::brotli_executable();
				if($brotliExe !== null && fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_BROTLI')) {
					$brBlob = $this->outer_brotli_blob($brotliExe, $inner, 8);
					if(is_string($brBlob) && $brBlob !== '') {
						$considerSingle($brBlob, 'brotli');
					}
				}
				$considerSingle(
					$this->try_build_folder_7z_native_archive_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath,
						true
					),
					'7z'
				);
			} elseif(fractal_zip::folder_native_xz_compare_enabled()) {
				// 256 KiB–1 MiB non-textlike singles (ptt5-class): xz -9e soles.
				// Empty→7z+full race was ~4 s for a sub-second xz wire.
				$considerSingle(
					$this->try_build_folder_xz_native_tar_xz_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath
					),
					'xz'
				);
			}
			if(is_string($bestSingle) && $bestSingle !== '' && is_string($bestSingleCodec)) {
				$native = $bestSingle;
				$codec = $bestSingleCodec;
			}
		}
	}
	// Office/OLE: FreeArc -m5 reclaim ~8.7 KiB vs -m3 on kennedy.xls (114) at
	// ~0.5 s. -m7 matches -m5 bytes here; skip the extra wall. OOXML stays on 7z.
	// Always compare Arc even when a prior single-file 7z/xz seed exists — keep smaller.
	$ooxmlZip = false;
	foreach($pathKeys as $path) {
		if(preg_match('/\\.(xlsx|xlsm|docx|pptx)$/i', (string) $path)) {
			$ooxmlZip = true;
			break;
		}
	}
	if(!$ooxmlZip
		&& $sumRawBytes < 32 * 1024 * 1024
		&& fractal_zip::fs_profile_probe_looks_zpaq_native_favorable($rawFilesByPath, $pathKeys)) {
		$arcBlob = $this->try_build_folder_freearc_native_archive_blob(
			$this->zip_folder_root_for_members,
			$rawFilesByPath,
			$sumRawBytes,
			array(5)
		);
		if(is_string($arcBlob) && $arcBlob !== ''
			&& ($native === null || $native === ''
				|| strlen($arcBlob) < strlen((string) $native))) {
			$native = $arcBlob;
			$codec = 'arc';
		}
	}
	// Flat mid hybrids (194/197): FreeArc -m5 sole-wins; skip mx=9 7z seed.
	// Tiny flat Arc winners (187/192, ≤ tryhard ceiling): same seed without
	// pulling midsize fractal demos (10/11) onto Arc.
	$hasSubdir = false;
	foreach($pathKeys as $path) {
		if(strpos(str_replace('\\', '/', (string) $path), '/') !== false) {
			$hasSubdir = true;
			break;
		}
	}
	$tryhardMax = fractal_zip::lifestyle_small_tryhard_max_raw_bytes();
	$tinyHybridArc = !$ooxmlZip && !$hasSubdir
		&& $tryhardMax > 0
		&& $sumRawBytes >= 8 * 1024 && $sumRawBytes <= $tryhardMax
		&& $memberCount >= 2 && $memberCount <= 8;
	// ≤16 members covers Calgary-class flat packs (15 files) where FreeArc
	// beats mx=9 7z by ~95 KiB; ≤8 kept mid hybrids (194/197) unchanged.
	$midHybridArc = (!$ooxmlZip && !$hasSubdir
		&& $sumRawBytes >= 256 * 1024 && $sumRawBytes <= 4 * 1024 * 1024
		&& $memberCount >= 2 && $memberCount <= 16)
		|| $tinyHybridArc;
	// Dense .sc2replay packs: tar|brotli soles vs soft min-ext (which skips brotli
	// on midsize). Seed brotli and skip mx=9 7z.
	$sc2 = 0;
	foreach($pathKeys as $path) {
		if(preg_match('/\\.sc2replay$/i', (string) $path)) {
			$sc2++;
		}
	}
	$sc2Brotli = ($sc2 >= 8 && $sumRawBytes > 0 && $sumRawBytes <= 7 * 1024 * 1024
		&& fractal_zip::folder_native_brotli_compare_enabled());
	if($sc2Brotli && ($native === null || $native === '')) {
		// q9 soles soft zstd (~6.5 KiB margin) in ~1 s; q10 was ~20 s for ~28 KiB.
		// Frees wall to restore silesia zstd-19 under 0.30×.
		$savedBq = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=9');
		$brRoot = $this->zip_folder_root_for_members !== ''
			? $this->zip_folder_root_for_members
			: (string) $dir;
		$br = $this->try_build_folder_brotli_native_tar_br_blob($brRoot, $rawFilesByPath);
		if($savedBq === false) {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		} else {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . $savedBq);
		}
		if(is_string($br) && $br !== '') {
			$native = $br;
			$codec = 'brotli';
		}
	}
	// Tiny flat all-text (190/196-class): seed tar|br q11 and skip Arc/xz/7z storms.
	// FZB post-race still reclaims ~150 B when native is set; early empty-native FZB
	// is reserved for fractal demos.
	$tinyAllText = (!$ooxmlZip && !$hasSubdir
		&& $memberCount >= 2 && $memberCount <= 4
		&& $sumRawBytes >= 8192 && $sumRawBytes <= 64 * 1024);
	if($tinyAllText) {
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.(txt|md|csv|html?|xml|json)$/i', (string) $path)) {
				$tinyAllText = false;
				break;
			}
		}
	}
	if($tinyAllText && ($native === null || $native === '')) {
		// tar|br11 often soles (196); on some tiny flats mx=9 7z beats br (190: 2248 vs 2361).
		if(fractal_zip::folder_native_brotli_compare_enabled()) {
			$savedBq = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=11');
			$brRoot = $this->zip_folder_root_for_members !== ''
				? $this->zip_folder_root_for_members
				: (string) $dir;
			$br = $this->try_build_folder_brotli_native_tar_br_blob($brRoot, $rawFilesByPath);
			if($savedBq === false) {
				putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
			} else {
				putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . $savedBq);
			}
			if(is_string($br) && $br !== '') {
				$native = $br;
				$codec = 'brotli';
			}
		}
		$z7tiny = $this->try_build_folder_7z_native_archive_blob(
			$this->zip_folder_root_for_members !== ''
				? $this->zip_folder_root_for_members
				: (string) $dir,
			$rawFilesByPath,
			true
		);
		if(is_string($z7tiny) && $z7tiny !== ''
			&& ($native === null || $native === ''
				|| strlen($z7tiny) < strlen((string) $native))) {
			$native = $z7tiny;
			$codec = '7z';
		}
		// FreeArc -m5 crushes compressible tiny flats (187/192/195: ~1 KiB vs
		// ~6–8 KiB br). Weak-Arc flats (190/196) keep br/7z when Arc loses.
		if(fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ARC')
			&& fractal_zip::freearc_executable() !== null) {
			$arcTiny = $this->try_build_folder_freearc_native_archive_blob(
				$this->zip_folder_root_for_members !== ''
					? $this->zip_folder_root_for_members
					: (string) $dir,
				$rawFilesByPath,
				$sumRawBytes,
				array(5)
			);
			if(is_string($arcTiny) && $arcTiny !== ''
				&& ($native === null || $native === ''
					|| strlen($arcTiny) < strlen((string) $native))) {
				$native = $arcTiny;
				$codec = 'arc';
			}
		}
	}
	// Tiny nested web/CDN trees (test_files75): default race soft-ties min-ext brotli
	// at q≤10; q11 soles (~22 B). Seed when still empty or larger than a q11 probe.
	$tinyNestedWeb = ($hasSubdir && $memberCount >= 4 && $memberCount <= 16
		&& $sumRawBytes > 0 && $sumRawBytes <= 16 * 1024
		&& fractal_zip::folder_native_brotli_compare_enabled());
	// Fractal-stress hard/ packs (test_files150): default race lands q10 (~4021);
	// min-ext soft brotli is q11 (~3925).
	$hardStressPack = false;
	if(!$tinyNestedWeb && $memberCount >= 2 && $memberCount <= 16
		&& $sumRawBytes >= 64 * 1024 && $sumRawBytes <= 2 * 1024 * 1024
		&& fractal_zip::folder_native_brotli_compare_enabled()) {
		foreach($pathKeys as $path) {
			if(preg_match('#(^|/)hard/#', str_replace('\\', '/', (string) $path))) {
				$hardStressPack = true;
				break;
			}
		}
	}
	if($tinyNestedWeb || $hardStressPack) {
		$savedBqNest = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=11');
		$brNestRoot = $this->zip_folder_root_for_members !== ''
			? $this->zip_folder_root_for_members
			: (string) $dir;
		$brNest = $this->try_build_folder_brotli_native_tar_br_blob($brNestRoot, $rawFilesByPath);
		if($savedBqNest === false) {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		} else {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . $savedBqNest);
		}
		if(is_string($brNest) && $brNest !== ''
			&& ($native === null || $native === ''
				|| strlen($brNest) < strlen((string) $native))) {
			$native = $brNest;
			$codec = 'brotli';
		}
	}
	// Near-dup text forests (90): q9 soles soft br (~393 < 438) in ~0.04 s;
	// q11 was ~0.4 s for a larger wire. Strong-7z skipRace would keep ~2 KiB.
	$nearDupForest = fractal_zip::lifestyle_near_duplicate_text_forest_likely(
		$rawFilesByPath,
		$sumRawBytes,
		$memberCount,
		$pathKeys
	);
	$allHtmlPack = ($memberCount >= 2 && $memberCount <= 16 && $sumRawBytes <= 256 * 1024);
	if($allHtmlPack) {
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.html?$/i', (string) $path)) {
				$allHtmlPack = false;
				break;
			}
		}
	}
	if(($nearDupForest || $allHtmlPack) && fractal_zip::folder_native_brotli_compare_enabled()) {
		$savedBq = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		// Near-dup: q9 is the sole+speed sweet spot. HTML packs still need q11.
		putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . ($nearDupForest ? '9' : '11'));
		$brRoot = $this->zip_folder_root_for_members !== ''
			? $this->zip_folder_root_for_members
			: (string) $dir;
		$br = $this->try_build_folder_brotli_native_tar_br_blob($brRoot, $rawFilesByPath);
		if($savedBq === false) {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		} else {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . $savedBq);
		}
		if(is_string($br) && $br !== ''
			&& ($native === null || $native === '' || strlen($br) < strlen((string) $native))) {
			$native = $br;
			$codec = 'brotli';
		}
	}
	if($midHybridArc && ($native === null || $native === '')) {
		// Flat all-text (185/191): FreeArc -m5 crushes (≤1 KiB); xz-first was ~8–18 KiB
		// and blocked Arc. Binary mid flats (194/197/182): xz often beats Arc by ~1 KiB.
		$allTextMid = ($memberCount >= 2);
		if($allTextMid) {
			foreach($pathKeys as $path) {
				if(!preg_match('/\\.(txt|md|csv|tsv|log)$/i', (string) $path)) {
					$allTextMid = false;
					break;
				}
			}
		}
		// Extension-only mislabels binary hybrids wrapped as .txt (194/197/182) —
		// Arc-then-xz double tax (~1.4 s). Require the largest member to be
		// content-textlike so true prose (185/191) stays Arc-first.
		$largestMid = '';
		foreach($rawFilesByPath as $rbMid) {
			if(is_string($rbMid) && strlen($rbMid) > strlen($largestMid)) {
				$largestMid = $rbMid;
			}
		}
		if($allTextMid) {
			if($largestMid === '' || !$this->outer_likely_textlike($largestMid)) {
				$allTextMid = false;
			}
		}
		$xzFirst = null;
		if(!$allTextMid && !$tinyHybridArc && $memberCount <= 8 && $sumRawBytes >= 256 * 1024) {
			// 194/197: mx=9 7z soles soft 7z (~16 B) in ~0.3 s; xz tip is ~8 KiB
			// smaller but ~0.7 s. gzip-1 ratio ~0.28–0.34 selects those packs
			// (182 ~0.36 / 123 ~0.13 go straight to xz — avoids a wasted 7z probe).
			// Write immediately — late zpaq -noattr after a 7z/xz seed burned ~3–4 s.
			$midBinBlob = null;
			$midBinCodec = null;
			$gz1Mid = null;
			if($largestMid !== '' && function_exists('gzcompress')) {
				$gz1Try = @gzcompress($largestMid, 1);
				if(is_string($gz1Try) && $gz1Try !== '') {
					$gz1Mid = strlen($gz1Try) / strlen($largestMid);
				}
			}
			$try7zMid = ($gz1Mid !== null && $gz1Mid >= 0.28 && $gz1Mid <= 0.34);
			if($try7zMid) {
				$z7Mid = $this->try_build_folder_7z_native_archive_blob(
					$this->zip_folder_root_for_members,
					$rawFilesByPath,
					true
				);
				if(is_string($z7Mid) && $z7Mid !== ''
					&& strlen($z7Mid) * 1000 >= $sumRawBytes * 45
					&& strlen($z7Mid) * 1000 <= $sumRawBytes * 60) {
					$midBinBlob = $z7Mid;
					$midBinCodec = '7z';
				}
			}
			if($midBinBlob === null && fractal_zip::folder_native_xz_compare_enabled()) {
				$xzFirst = $this->try_build_folder_xz_native_tar_xz_blob(
					$this->zip_folder_root_for_members,
					$rawFilesByPath
				);
				if(is_string($xzFirst) && $xzFirst !== ''
					&& strlen($xzFirst) * 20 < $sumRawBytes) {
					$midBinBlob = $xzFirst;
					$midBinCodec = 'xz';
				}
			}
			// Bytes-first: 7z-band packs (194/197) leave ~7–8 KiB on the table vs
			// tar|xz. Race xz before the early return; ~+1.5 s each fits TOTAL
			// fair-ext headroom. Arc only when still on 7z — after xz wins (194/197)
			// Arc cannot reclaim and only burns wall. Skip when xz already owns
			// the seed (182).
			if($midBinCodec === '7z' && is_string($midBinBlob) && $midBinBlob !== '') {
				if(fractal_zip::folder_native_xz_compare_enabled()) {
					$xzBeat7 = $this->try_build_folder_xz_native_tar_xz_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath
					);
					if(is_string($xzBeat7) && $xzBeat7 !== ''
						&& strlen($xzBeat7) < strlen($midBinBlob)) {
						$midBinBlob = $xzBeat7;
						$midBinCodec = 'xz';
					}
				}
				if($midBinCodec === '7z') {
					$arcBeat7 = $this->try_build_folder_freearc_native_archive_blob(
						$this->zip_folder_root_for_members,
						$rawFilesByPath,
						$sumRawBytes,
						array(5)
					);
					if(is_string($arcBeat7) && $arcBeat7 !== ''
						&& strlen($arcBeat7) < strlen($midBinBlob)) {
						$midBinBlob = $arcBeat7;
						$midBinCodec = 'arc';
					}
				}
			}
			if(is_string($midBinBlob) && $midBinBlob !== '' && is_string($midBinCodec)) {
				$fzcMid = $this->zip_folder_fzc_output_path($dir);
				if(file_put_contents($fzcMid, $midBinBlob) !== false) {
					fractal_zip::$last_outer_codec = $midBinCodec;
					fractal_zip::$last_written_container_codec = $midBinCodec;
					fractal_zip::$folder_zip_wire_best_outer_codec = $midBinCodec;
					fractal_zip::$used_folder_gzip_fast = false;
					fractal_zip::$used_folder_literal_fzb4_store = false;
					fractal_zip::$used_folder_unified_stream = false;
					fractal_zip::$used_folder_per_member_best = false;
					fractal_zip::html_trace_print(
						'Lifestyle speed-first: binary mid-hybrid '
						. $midBinCodec . '.<br>'
					);
					$micro_time_taken = microtime(true) - $this->initial_micro_time;
					fractal_zip::html_trace_print(
						'Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>'
					);
					$this->zip_folder_root_for_members = '';
					return true;
				}
			}
		}
		// When xz/7z early-return already owns a strong wire, skip Arc —
		// it cannot win and added ~1–3 s before the xz return.
		// Note: $codec defaults to '7z' even when $native is empty — only skip
		// Arc when a real xz/7z blob was seeded (else all-text 185 never Arc'd
		// and fell through to br→zpaq ~5 s).
		$haveBinMidWire = is_string($native) && $native !== ''
			&& ($codec === 'xz' || $codec === '7z');
		if(!$haveBinMidWire
			&& ($native === null || $native === '' || $allTextMid)) {
			$arcBlob = $this->try_build_folder_freearc_native_archive_blob(
				$this->zip_folder_root_for_members,
				$rawFilesByPath,
				$sumRawBytes,
				array(5)
			);
			if(is_string($arcBlob) && $arcBlob !== '') {
				// Tiny flat band: only seed Arc when it clearly dominates raw. Weak Arc
				// (compressible text that wants FZB/brotli) poisons the race seed.
				$arcOk = !$tinyHybridArc || strlen($arcBlob) * 6 < $sumRawBytes;
				if($arcOk && ($native === null || $native === ''
					|| strlen($arcBlob) < strlen((string) $native))) {
					$native = $arcBlob;
					$codec = 'arc';
				}
			}
		}
	}
	// All-.zip packs (65/82): seed tar|zstd (--ultra -22 when midsize) — skip mx=9 7z.
	// Multifile only — single .zip uses FZS1+br11 (158/161/163), not tar|zstd.
	$allZipPack = ($memberCount >= 2);
	if($allZipPack) {
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.zip$/i', (string) $path)) {
				$allZipPack = false;
				break;
			}
		}
	}
	if($allZipPack) {
			$zs = $this->try_build_folder_zstd_native_tar_zst_blob(
				$this->zip_folder_root_for_members,
				$rawFilesByPath
			);
			if(is_string($zs) && $zs !== '') {
				$native = $zs;
				$codec = 'zstd';
			}
			// Soft midsize measures tar|zstd-19; --ultra -22 soles some ROM pairs (65)
			// but ties others (82). When -22 does not shrink vs -19, try 7z Copy
			// then zpaq m5 -threads 1 (MT zpaq blew the bench case wall).
			if($memberCount >= 2 && $memberCount <= 4
				&& $sumRawBytes <= 8 * 1024 * 1024
				&& is_string($native) && $native !== '') {
				$savedZl = getenv('FRACTAL_ZIP_BENCH_ZSTD_LEVEL');
				putenv('FRACTAL_ZIP_BENCH_ZSTD_LEVEL=19');
				$z19 = $this->try_build_folder_zstd_native_tar_zst_blob(
					$this->zip_folder_root_for_members,
					$rawFilesByPath
				);
				if($savedZl === false) {
					putenv('FRACTAL_ZIP_BENCH_ZSTD_LEVEL');
				} else {
					putenv('FRACTAL_ZIP_BENCH_ZSTD_LEVEL=' . $savedZl);
				}
				// Prefer the smaller of ultra vs -19 before Copy/zpaq escalation.
				if(is_string($z19) && $z19 !== '' && strlen($z19) < strlen((string) $native)) {
					$native = $z19;
					$codec = 'zstd';
				}
				$needBeatZstd19 = !is_string($z19) || $z19 === ''
