		// Multi-.zip only: single .zip already seeded FZS1 above.
		|| (!empty($allZipPack) && ($codec === 'zstd' || $codec === 'zpaq' || $codec === '7z') && $memberCount >= 2)
		// Dense near-incompressible (69) / midsize strong-7z (77): race is pure wall.
		// Dense compressible 7z (61): lifestyle skips br race (~7 s for ~5 KiB).
		|| ($codec === '7z' && is_string($native) && $native !== '' && $sumRawBytes > 0
			&& (($memberCount >= 64 && strlen($native) * 10 > $sumRawBytes * 8)
				|| ($memberCount >= 64 && fractal_zip::lifestyle_speed_profile_enabled()
					&& $sumRawBytes <= 8 * 1024 * 1024 && strlen($native) * 2 < $sumRawBytes)
				|| ($memberCount >= 8 && $memberCount < 64 && $sumRawBytes >= 8 * 1024 * 1024
					&& strlen($native) * 2 < $sumRawBytes)))
		// Near-incompressible multifile (HTML+JPEG forests): full race burns wall, but
		// brotli q10 often reclaims tens of KiB vs 7z alone — one targeted try.
		|| ($codec === '7z' && is_string($native) && $native !== '' && $sumRawBytes > 0
			&& $memberCount >= 16 && strlen($native) * 100 > $sumRawBytes * 85)
		// Strong xz singles (ptt5): xz already ≪ raw — skip br/zstd/gzip re-race.
		|| ($codec === 'xz' && $memberCount === 1 && is_string($native) && $native !== ''
			&& $sumRawBytes >= 256 * 1024 && strlen($native) * 5 < $sumRawBytes)
		// Midhybrid xz seed (182/123): already the sole wire — skip Arc/br re-race.
		|| ($codec === 'xz' && !empty($midHybridArc) && is_string($native) && $native !== ''
			&& strlen($native) * 20 < $sumRawBytes)
		// Midhybrid 7z seed (194/197 ~5% raw): soles soft 7z — skip xz/br storm.
		|| ($codec === '7z' && !empty($midHybridArc) && is_string($native) && $native !== ''
			&& strlen($native) * 1000 >= $sumRawBytes * 45
			&& strlen($native) * 1000 <= $sumRawBytes * 60);
	if(!$skipRace) {
		list($native, $codec) = $this->lifestyle_race_native_folder_wire_candidates(
			$this->zip_folder_root_for_members,
			$rawFilesByPath,
			$sumRawBytes,
			(string) $native,
			(string) $codec
		);
	} elseif($codec === '7z' && is_string($native) && $native !== '' && $sumRawBytes > 0
		&& $memberCount >= 64 && strlen($native) * 100 > $sumRawBytes * 85
		&& fractal_zip::folder_native_brotli_compare_enabled()) {
		// Dense near-incompressible: q9 soles soft zstd (~180 B vs q8); q10 was
		// ~9 s for ~2.5 KiB (test_files69). q9 is nearly free.
		$savedBq = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=9');
		$brRoot = $this->zip_folder_root_for_members !== ''
			? $this->zip_folder_root_for_members
			: (string) $dir;
		$br = $this->try_build_folder_brotli_native_tar_br_blob($brRoot, $rawFilesByPath);
		if($savedBq === false) {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
		} else {
			putenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY=' . $savedBq);
		}
		if(is_string($br) && $br !== '' && strlen($br) < strlen((string) $native)) {
			$native = $br;
			$codec = 'brotli';
		}
	} elseif($midHybridArc && $codec === 'arc'
		&& is_string($native) && $native !== ''
		&& strlen($native) * 100 >= $sumRawBytes
		&& fractal_zip::folder_native_xz_compare_enabled()
		&& $sumRawBytes <= 4 * 1024 * 1024) {
		// Flat mid hybrids: Arc -m5 often soles, but xz can still reclaim 1–2 KiB
		// when Arc is only moderately small (194/197/182). Skip xz when Arc already
		// crushed raw (≤1%) — xz cannot win and burns 0.2–0.8 s (185/188/191).
		$xz = $this->try_build_folder_xz_native_tar_xz_blob(
			$this->zip_folder_root_for_members,
			$rawFilesByPath
		);
		if(is_string($xz) && $xz !== '' && strlen($xz) < strlen((string) $native)) {
			$native = $xz;
			$codec = 'xz';
		}
	}
	if($native === '') {
		return false;
	}
	// FZB4 store + cheap outer: soles vs soft folder-zpaq on image grids (168)
	// and vs soft zpaq/brotli on multi-precomp packs (175/176) without the native
	// tar|brotli double race. Skip when native already dominates.
	// Strong mid-hybrid Arc already owns the sole wire — FZB tiny-text burns ~2 s
	// then loses (187/192). Tiny all-text (196): tar|br ties min-ext at 3022;
	// FZB+br reclaim (~170 B) is required for untied sole.
	if(!$midHybridArcStrong && empty($pdfBrotliCrushed)
		&& empty($strongArcSingleWire) && empty($denseArcStrong)
		&& empty($denseBrotliStrong) && empty($nearIncompArcMid)
		&& empty($midImageBrotli) && empty($midMediaBrotli)
		&& empty($nestedCensusArc) && empty($oleArcStrong)) {
		$fzbOuter = $this->lifestyle_try_fzb_store_outer_beat_native(
			$this->zip_folder_root_for_members !== ''
				? $this->zip_folder_root_for_members
				: (string) $dir,
			$rawFilesByPath,
			$sumRawBytes,
			$memberCount,
			$pathKeys,
			(string) $native
		);
		if(is_array($fzbOuter) && isset($fzbOuter[0], $fzbOuter[1])
			&& is_string($fzbOuter[0]) && $fzbOuter[0] !== '') {
			$native = $fzbOuter[0];
			$codec = (string) $fzbOuter[1];
		}
	}
	// Tiny all-PNG grids (154/169/177): soft gzip9 packed-bundle can beat tar|brotli
	// (169: 60615 vs br 60622). Native brotli soles when it beats gzip (154/177);
	// otherwise disable lifestyle and fall through to deep FZS1 (~10 s, still under half).
	if($memberCount >= 2 && $sumRawBytes > 0 && $sumRawBytes <= 80 * 1024) {
		$allPngEsc = true;
		foreach($pathKeys as $path) {
			if(!preg_match('/\\.(png|jpe?g|gif|webp)$/i', (string) $path)) {
				$allPngEsc = false;
				break;
			}
		}
		if($allPngEsc) {
			$gzEsc = $this->try_build_folder_gzip9_bundle_zlib_blob(
				$this->zip_folder_root_for_members,
				$rawFilesByPath
			);
			if(is_string($gzEsc) && $gzEsc !== ''
				&& strlen((string) $native) >= strlen($gzEsc)) {
				self::$runtime_force_disable_lifestyle_speed_profile = true;
				fractal_zip::html_trace_print(
					'Lifestyle PNG-grid escalate: native ≤ gzip9 bundle; deeper encode.<br>'
				);
				$this->zip_folder_root_for_members = '';
				return false;
			}
		}
	}
	// Midsize packs (1–256 files): min-ext zpaq wins without -noattributes.
	// Race zpaq -noattributes (typically −1–45 B; 165 WAVs / 80 HTML / 56 SC2 /
	// 57 php-langref / 61 rasters / 201 samples) then, for singles only, mcm FZpq.
	$zpaqNaMinRaw = ($memberCount === 1) ? (1024 * 1024) : (512 * 1024);
	// Skip zpaq -noattr when a tiny Arc tip already owns the wire (150/185:
	// Arc ≪4 KiB — zpaq loses and burns ~7–9 s). Larger Arc mid tips (188/191
	// text flats, and all-BMP via early path) still race — zpaq reclaim KiB.
	// Keep the race for multifile packs where zpaq soles.
	$skipZpaqNaPrecomp = false;
	if($memberCount === 1 && ($codec === 'brotli' || $codec === 'store')
		&& is_string($native) && $native !== '') {
		foreach($rawFilesByPath as $rk => $_rb) {
			if(preg_match('/\\.(7z|rar)$/i', (string) $rk)) {
				$skipZpaqNaPrecomp = true;
			}
			break;
		}
	}
	$skipZpaqNaStrong = is_string($native) && $native !== '' && $sumRawBytes > 0
		&& (
			!empty($skipZpaqNaPrecomp)
			|| !empty($oleArcStrong)
			|| ($codec === 'xz' && strlen($native) * 20 < $sumRawBytes)
			|| ($codec === '7z' && !empty($midHybridArc)
				&& strlen($native) * 1000 >= $sumRawBytes * 45
				&& strlen($native) * 1000 <= $sumRawBytes * 60)
			// Tiny multifile Arc (150 hardmix / 185 flat): zpaq cannot beat ≪4 KiB.
			|| ($codec === 'arc' && $memberCount >= 2 && strlen($native) < 4096)
			// OLE/CFB Arc (114): skip zpaq -noattr wall; mcm still races below.
			|| ($codec === 'arc' && $memberCount === 1 && !$ooxmlZip
				&& strlen($native) * 10 < $sumRawBytes
				&& fractal_zip::fs_profile_probe_looks_zpaq_native_favorable($rawFilesByPath, $pathKeys))
			// Single CSV ≤4 MiB (167/174): zpaq -noattr (~6 s) loses to the
			// following mcm/DRT FZpq tip — pure wall.
			|| ($memberCount === 1 && $sumRawBytes <= 4 * 1024 * 1024
				&& $pathKeys !== array()
				&& (bool) preg_match('/\\.csv$/i', (string) $pathKeys[0]))
			// Already have FZpq CM tip (dickens/reymont prose path): zpaq cannot
			// reclaim and burns 20–30 s.
			|| ($codec === 'paq' && $memberCount === 1)
		);
	if(!$skipZpaqNaStrong && $memberCount >= 1 && $memberCount <= 256
		&& is_string($native) && $native !== ''
		&& $sumRawBytes >= $zpaqNaMinRaw && $sumRawBytes <= 48 * 1024 * 1024
		&& fractal_zip::lifestyle_speed_profile_enabled()) {
		// Already seeded zpaq -noattr above (textlike prose path) — do not re-run.
		if($codec !== 'zpaq' && fractal_zip::zpaq_executable() !== null) {
			$zpNa = $this->try_build_folder_zpaq_squash_noattr_blob(
				$this->zip_folder_root_for_members !== ''
					? $this->zip_folder_root_for_members
					: (string) $dir,
				$rawFilesByPath,
				$sumRawBytes
			);
			if(is_string($zpNa) && $zpNa !== '' && strlen($zpNa) < strlen($native)) {
				$native = $zpNa;
				$codec = 'zpaq';
			}
		}
	}
	// Single-member mcm FZpq: race even when zpaq -noattr was skipped (OLE Arc
	// 114 / CSV Arc 53/151 / PNG 7z early-return is separate).
	// Non-zpaq tips stay ≤4 MiB (~1–2 s). Zpaq prose tips (nci/webster) go to
	// 48 MiB so mcm can untie / widen soles after the textlike CM-first raise.
	$mcmFinalCap = ($codec === 'zpaq') ? (48 * 1024 * 1024) : (4 * 1024 * 1024);
	if($memberCount === 1 && is_string($native) && $native !== ''
		&& $codec !== 'paq'
		&& $sumRawBytes >= 3 * 1024 && $sumRawBytes <= $mcmFinalCap
		&& fractal_zip::lifestyle_speed_profile_enabled()) {
		$singleRelMcm = null;
		$singlePlainMcm = null;
		foreach($rawFilesByPath as $rk => $rb) {
			$singleRelMcm = str_replace('\\', '/', (string) $rk);
			$singlePlainMcm = (string) $rb;
			break;
		}
		// Zpaq tip≥10% raw: skip mcm on prose (nci/webster) — same tip, pure wall.
		// Binary dumps (.bin / BMP / PDF / extensionless) still race CM/paq8 under ultra.
		$binLikeMcm = is_string($singleRelMcm) && (
			(bool) preg_match('/\\.(bmp|bin|pdf)$/i', $singleRelMcm)
			|| (strpos(basename($singleRelMcm), '.') === false
				&& fractal_zip::ultra_compression_enabled())
		);
		$skipMcmProseFinal = ($codec === 'zpaq' && $sumRawBytes > 0
			&& strlen($native) * 10 >= $sumRawBytes
			&& !$binLikeMcm);
		if(fractal_zip::ultra_compression_enabled() && $binLikeMcm) {
			$skipMcmProseFinal = false;
		}
		if(!$skipMcmProseFinal
			&& is_string($singleRelMcm) && is_string($singlePlainMcm) && $singlePlainMcm !== '') {
			$mcmWire = $this->try_build_single_member_mcm_fzpq_wire($singleRelMcm, $singlePlainMcm);
			if(is_string($mcmWire) && $mcmWire !== '' && strlen($mcmWire) < strlen($native)) {
				$native = $mcmWire;
				$codec = 'paq';
			}
		}
	}
	$fzcPath = $this->zip_folder_fzc_output_path($dir);
	if(file_put_contents($fzcPath, $native) === false) {
		return false;
	}
	fractal_zip::$last_outer_codec = $codec;
	fractal_zip::$last_written_container_codec = $codec;
	fractal_zip::$folder_zip_wire_best_outer_codec = $codec;
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	fractal_zip::$used_folder_unified_stream = false;
	fractal_zip::$used_folder_per_member_best = false;
	fractal_zip::html_trace_print('Lifestyle speed-first: native folder ' . $codec . ' passthrough.<br>');
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

/**
 * FS speed-first: write native folder 7z as .fz when fractal encode is unlikely to beat 7z.
 *
 * @param array<string,string> $rawFilesByPath probe or full map
 * @param array<string,mixed>|null $folderCensus
 * @param list<string>|null $allRelPaths
 */
function write_fs_profile_speed_first_folder_container(
	$dir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount,
	?array $folderCensus = null,
	?array $allRelPaths = null
): bool {
	if(!fractal_zip::fs_profile_should_use_7z_passthrough($rawFilesByPath, $sumRawBytes, $memberCount, $folderCensus, $allRelPaths)) {
		return false;
	}
	$resolvedRoot = realpath((string) $dir);
	$this->zip_folder_root_for_members = $resolvedRoot !== false ? $resolvedRoot : (string) $dir;
	// Disk copy only — avoid read-all-then-materialize when routing decided passthrough from lightweight probe.
	$native = $this->try_build_folder_7z_native_archive_blob($this->zip_folder_root_for_members, null, true);
	if($native === null || $native === '') {
		return false;
	}
	$fzcPath = (string) $dir . $this->fractal_zip_container_file_extension;
	if(file_put_contents($fzcPath, $native) === false) {
		return false;
	}
	fractal_zip::$last_outer_codec = '7z';
	fractal_zip::$last_written_container_codec = '7z';
	fractal_zip::$folder_zip_wire_best_outer_codec = '7z';
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	fractal_zip::$used_folder_unified_stream = false;
	fractal_zip::$used_folder_per_member_best = false;
	fractal_zip::html_trace_print('FS speed-first: native folder 7z passthrough (cheap fractal probe negative).<br>');
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

/** In lifestyle speed profile, very small merged literals may still do full FZBM order search for bytes. */
public static function lifestyle_fzbm_order_tryhard_max_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_FZBM_ORDER_TRYHARD_MAX_RAW_BYTES');
	return $cached = ($e === false || trim((string) $e) === '') ? 0 : max(0, (int) trim((string) $e));
}

/** In speed profile, prefilter FZBM path-order candidates with cheap gzip-1 score and keep top-K for exact scoring. */
public static function lifestyle_fzbm_path_order_prefilter_top_k(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_FZBM_PATH_ORDER_PREFILTER_TOP_K');
	return $cached = ($e === false || trim((string) $e) === '') ? 6 : max(0, (int) trim((string) $e));
}

/** In speed profile, prefilter FZB4 path-order candidates with cheap gzip-1 score and keep top-K for exact scoring. */
public static function lifestyle_fzb4_path_order_prefilter_top_k(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_FZB4_PATH_ORDER_PREFILTER_TOP_K');
	// Default 2 under lifestyle: enough for test_files75 ≤1624, cheaper than 6.
	return $cached = ($e === false || trim((string) $e) === '') ? 2 : max(0, (int) trim((string) $e));
}

/** Global tiny-input shortcut: skip FZBM order search when merged literal payload is very small. */
public static function literal_bundle_fzbm_order_tiny_skip_max_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LITERAL_BUNDLE_FZBM_ORDER_TINY_SKIP_MAX_RAW_BYTES');
	return $cached = ($e === false || trim((string) $e) === '') ? 1024 : max(0, (int) trim((string) $e));
}

/**
 * Under the lifestyle (default) speed profile, folders at/below this merged raw size skip
 * heavy startup work: per-member literal transform tournaments + raster-dedup pass, and
 * native Arc/brotli/xz/zpaq folder compares. A single cheap native 7z compare is still
 * allowed (Squash literature singles win on 7z wire bytes in ~0.1s). Specialized/bytes-first
 * runs leave lifestyle off (e.g. --ultra) and keep the full probes. 0 disables the shortcut.
 * Env: FRACTAL_ZIP_LIFESTYLE_TINY_SKIP_HEAVY_STARTUP_MAX_RAW_BYTES (default 262144 = 256 KiB).
 */
public static function lifestyle_tiny_skip_heavy_startup_max_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_LIFESTYLE_TINY_SKIP_HEAVY_STARTUP_MAX_RAW_BYTES');
	// 512 KiB covers Squash literature singles (alice ~152 KiB, lcet10 ~427 KiB)
	// without full adaptive outer / FZB4 path-order tournaments that explode wall vs v8.
	return $cached = ($e === false || trim((string) $e) === '') ? 524288 : max(0, (int) trim((string) $e));
}

/** @see lifestyle_tiny_skip_heavy_startup_max_raw_bytes */
public static function lifestyle_should_skip_heavy_startup_for_raw_bytes(int $sumRawBytes): bool {
	if($sumRawBytes <= 0 || !self::lifestyle_speed_profile_enabled()) {
		return false;
	}
	$max = self::lifestyle_tiny_skip_heavy_startup_max_raw_bytes();
	return $max > 0 && $sumRawBytes <= $max;
}

/**
 * Whether phase-4 may force staged-only / 1-job / no-deepen lifestyle tiny shortcuts.
 * Small fractal-likely trees (test_files21-class micros) lose ~4 B under those shortcuts;
 * keep the full adaptive outer contest there. Literature / !fractal_likely still use tiny.
 *
 * @param array<string,string> $rawFilesByPath
 */
public static function lifestyle_should_use_tiny_outer_shortcuts(int $sumRawBytes, array $rawFilesByPath = array()): bool {
	if(!self::lifestyle_should_skip_heavy_startup_for_raw_bytes($sumRawBytes)) {
		return false;
	}
	$n = count($rawFilesByPath);
	if($n > 0
		&& $sumRawBytes <= 8192
		&& self::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $n)) {
		return false;
	}
	// Small single BMP: 1-job tiny outer loses ~180 B vs full contest (test_files157).
	if($n === 1 && $sumRawBytes > 0 && $sumRawBytes < 1048576) {
		foreach($rawFilesByPath as $path => $_bytes) {
			if(preg_match('/\\.bmp$/i', (string) $path)) {
				return false;
			}
		}
	}
	return true;
}

/** FRACTAL_ZIP_LITERAL_BUNDLE_FZBM_ORDER unset ⇒ probe; explicit 0/off/false/no ⇒ off. */
public static function literal_bundle_fzbm_concat_order_probe_enabled(): bool {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$offEnv = getenv('FRACTAL_ZIP_LITERAL_BUNDLE_FZBM_ORDER');
	if($offEnv === false || trim((string) $offEnv) === '') {
		return $cached = true;
	}
	$ov = strtolower(trim((string) $offEnv));
	return $cached = !($ov === '0' || $ov === 'off' || $ov === 'false' || $ov === 'no');
}

public static function literal_bundle_fzbm_order_exhaustive_max_n(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$exhMaxEnv = getenv('FRACTAL_ZIP_LITERAL_BUNDLE_FZBM_ORDER_EXHAUSTIVE_MAX_N');
	if($exhMaxEnv === false || trim((string) $exhMaxEnv) === '') {
		return $cached = fractal_zip::ultra_compression_enabled() ? 8 : 5;
	}
	return $cached = max(2, min(8, (int) trim((string) $exhMaxEnv)));
}

public static function literal_bundle_fzbm_order_random_tries(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$randTriesEnv = getenv('FRACTAL_ZIP_LITERAL_BUNDLE_FZBM_ORDER_RANDOM_TRIES');
	if($randTriesEnv === false || trim((string) $randTriesEnv) === '') {
		return $cached = fractal_zip::ultra_compression_enabled() ? 512 : 24;
	}
	return $cached = max(0, min(2048, (int) trim((string) $randTriesEnv)));
}

/** Fork pool over FZBM path-order proxy trials (brotli/gzip); bytes unchanged (min-score merge). */
public static function fzbm_path_order_parallel_enabled(): bool {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	fractal_zip_encode_pipeline::bootstrap_cli_parallel_defaults_if_cli();
	$e = getenv('FRACTAL_ZIP_FZBM_PATH_ORDER_PARALLEL');
	if($e === false || trim((string) $e) === '') {
		if(fractal_zip_parallel_runtime_disabled() || fractal_zip_parallel_runtime_probe_mode()) {
			return $cached = false;
		}
		return $cached = fractal_zip_encode_pipeline::parallel_fork_allowed();
	}
	$v = strtolower(trim((string) $e));
	if($v === '0' || $v === 'false' || $v === 'no' || $v === 'off') {
		return $cached = false;
	}
	return $cached = ($v === '1' || $v === 'true' || $v === 'on' || $v === 'yes');
}

public static function fzbm_path_order_parallel_min_candidates(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FZBM_PATH_ORDER_PARALLEL_MIN');
	if($e === false || trim((string) $e) === '' || !ctype_digit(trim((string) $e))) {
		return $cached = 8;
	}
	return $cached = max(2, (int) trim((string) $e));
}

/** True when FRACTAL_ZIP_BROTLI_LGWIN is unset or empty (FZB* path-order / outer Q11: default + w=16, optional w=20/22/24 for textlike when few order candidates). */
public static function literal_bundle_brotli_lgwin_env_unset_or_empty(): bool {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_BROTLI_LGWIN');
	return $cached = ($e === false || trim((string) $e) === '');
}

/**
 * FZBM/FZB4 path-order: try Brotli w=20/22/24 in the Brotli proxy when there are at most this many order candidates
