	$e = getenv('FRACTAL_ZIP_PATH_ORDER_LGWIN_SWEEP_MAX_CAND');
	return $cached = ($e === false || trim((string) $e) === '') ? 1 : max(1, min(10000, (int) trim((string) $e)));
}

