		$bss2 = $this->encode_bmp_block_core_scalar_shift_payload($rawBytes, $bmpRgbOnce);
	} else {
		$bss = $this->encode_bmp_block_scalar_shift_payload($rawBytes);
		$bss2 = $this->encode_bmp_block_core_scalar_shift_payload($rawBytes);
	}
