			}
			if($chainPick !== null) {
				$lch = $this->literal_bundle_gzip_deflate_len($chainPick['blob'], $gzipProbeLevel);
				if($lch === false) {
					$lch = $chainPick['len'];
				}
				if($this->literal_bundle_transform_beats_current($lch, 17, $bestLen, $bestMode)) {
