	$this->literal_bundle_consider_convert_png_to_bmp($rawBytes, $relPath, $gzipProbeLevel, $bestLen, $bestMode, $bestStore, $verbatimDiskBytes);
	$this->literal_bundle_consider_ole_mode19($rawBytes, $relPath, $gzipProbeLevel, $bestLen, $bestMode, $bestStore);
	list($cm, $cst) = $wrapOut($bestMode, $bestStore);
