function encode_literal_bundle_payload($array_raw_files_by_path, $encode_opts = null) {
	$ordered = $array_raw_files_by_path;
	if (class_exists('fractal_zip_encode_pipeline', false) && fractal_zip_encode_pipeline::reorder_members_enabled()) {
		$ordered = fractal_zip_encode_pipeline::reorder_raw_members_for_locality($ordered);
		fractal_zip_encode_pipeline::html_trace_checkpoint(
			fractal_zip_encode_pipeline::PHASE_STREAM_REORDER,
			'encode_literal_bundle_payload: locality reorder hook (v1 stable path sort)'
		);
	} else {
		ksort($ordered, SORT_STRING);
	}
	$count = sizeof($ordered);
	if($count === 0) {
		return 'FZB4';
	}
	$sharedExt = null;
	$fzb5LayoutOk = true;
	$fzb6PatternOk = false;
	$fzb6Prefix = null;
	$fzb6DigitsLen = 0;
	$fzb6Nums = array();
	if($fzb5LayoutOk) {
		foreach($ordered as $path => $rawBytes) {
			$path = (string)$path;
			if(strpos($path, '/') !== false || strpos($path, '\\') !== false) {
				$fzb5LayoutOk = false;
				break;
			}
			$dot = strrpos($path, '.');
			if($dot === false || $dot < 1 || $dot === strlen($path) - 1) {
				$fzb5LayoutOk = false;
				break;
			}
			$ext = substr($path, $dot);
			$name = substr($path, 0, $dot);
			if(strlen($name) > 255 || strlen($ext) > 32) {
				$fzb5LayoutOk = false;
				break;
			}
			if($sharedExt === null) {
				$sharedExt = $ext;
			} elseif($sharedExt !== $ext) {
				$fzb5LayoutOk = false;
				break;
			}
		}
		if($fzb5LayoutOk && $sharedExt !== null) {
			$fzb6PatternOk = true;
			foreach($ordered as $path => $rawBytes) {
				$path = (string)$path;
				$dot = strrpos($path, '.');
				$name = substr($path, 0, $dot);
				if(!preg_match('/^(.+?)([0-9]+)$/', $name, $m)) {
					$fzb6PatternOk = false;
					break;
				}
				$prefix = (string)$m[1];
				$digits = (string)$m[2];
				if($fzb6Prefix === null) {
					$fzb6Prefix = $prefix;
					$fzb6DigitsLen = strlen($digits);
					if(strlen($fzb6Prefix) > 255 || $fzb6DigitsLen < 1 || $fzb6DigitsLen > 9) {
						$fzb6PatternOk = false;
						break;
					}
				} elseif($fzb6Prefix !== $prefix || $fzb6DigitsLen !== strlen($digits)) {
					$fzb6PatternOk = false;
					break;
				}
				$num = (int)$digits;
				$reconstructed = str_pad((string)$num, $fzb6DigitsLen, '0', STR_PAD_LEFT);
				if($reconstructed !== $digits) {
					$fzb6PatternOk = false;
					break;
				}
				$fzb6Nums[$path] = $num;
			}
		}
	} else {
		$fzb5LayoutOk = false;
	}
	$rasterDedupPolicy = 'auto';
	if(is_array($encode_opts) && isset($encode_opts['raster_dedup_policy'])) {
		$rp = $encode_opts['raster_dedup_policy'];
		if($rp === 'always' || $rp === 'never' || $rp === 'auto') {
			$rasterDedupPolicy = $rp;
		}
	}
	$envRasterDedupPolicy = getenv('FRACTAL_ZIP_LITERAL_RASTER_DEDUP_POLICY');
	if(is_string($envRasterDedupPolicy) && $envRasterDedupPolicy !== '') {
		$rpEnv = strtolower(trim($envRasterDedupPolicy));
		if($rpEnv === 'always' || $rpEnv === 'never' || $rpEnv === 'auto') {
			$rasterDedupPolicy = $rpEnv;
		}
	}
	// Lifestyle small multifile: skip raster-dedup second pass (wall without byte wins on 74/75).
	if($rasterDedupPolicy === 'auto'
		&& fractal_zip::lifestyle_should_skip_heavy_startup_for_raw_bytes(
			array_sum(array_map('strlen', $ordered))
		)
		&& count($ordered) >= 2
		&& count($ordered) <= 32) {
		$rasterDedupPolicy = 'never';
	}
	$sumRawEarly = 0;
	$nOrderedEarly = count($ordered);
	$allPlainText = ($nOrderedEarly >= 2);
	if($allPlainText) {
		fractal_zip_ensure_literal_pac_stack_loaded();
	}
