			$plen = strlen($pl);
			$sc = PHP_INT_MAX;
			if($brotliExePick !== null && !$skipBrotliPick && $fzbLitMaxPick > 0 && $plen <= $fzbLitMaxPick) {
				$blob = $this->outer_brotli_blob($brotliExePick, $pl, 11, null);
				if($blob !== null && $blob !== '') {
					$sc = strlen($blob);
				}
			}
