		&& $rasterDedupPolicy !== 'always'
		&& (!fractal_zip::fs_profile_cheap_fractal_data_likely($ordered, $sumRawOrdered, $nOrdered)
			|| ($nOrdered >= 4 && $nOrdered <= 32 && $avgMember >= 256.0));
