		$prevLayoutProxy = getenv('FRACTAL_ZIP_LITERAL_BUNDLE_LAYOUT_USE_PROXY_SCORE');
		putenv('FRACTAL_ZIP_LITERAL_BUNDLE_FZB4_PATH_ORDER=0');
		putenv('FRACTAL_ZIP_LITERAL_BUNDLE_LAYOUT_USE_PROXY_SCORE=0');
