function logical_path_for_zip_member($absolutePath) {
	$root = $this->zip_folder_root_for_members;
	if($root === null || $root === '') {
		return $absolutePath;
	}
	// Per-root cache: zip_folder() keeps one member root for a whole tree walk; skip rtrim+slash norm on every file.
	static $cKey = null;
	static $cRootN = null;
	static $cPrefix = null;
	static $cPrefixLen = 0;
	$r = (string) $root;
	if($cKey !== $r) {
		$cKey = $r;
		$cRootN = rtrim(strtr($r, '\\', '/'), '/');
		$cPrefix = $cRootN . '/';
		$cPrefixLen = strlen($cPrefix);
	}
	$abs = realpath($absolutePath);
	if($abs === false) {
		$abs = $absolutePath;
	}
	$absN = strtr($abs, '\\', '/');
	if(str_starts_with($absN, $cPrefix)) {
		return (string) substr($absN, $cPrefixLen);
	}
	if($absN === $cRootN) {
		return basename($absolutePath);
	}
	fractal_zip::warning_once('logical_path_for_zip_member: file not under zip folder root; using basename.');
	return basename($absolutePath);
}

function recursive_zip_folder($dir, $debug = false) {
	// One ensure per directory visit; inner static makes subsequent calls free (avoids N× per-file dispatch after first load).
	fractal_zip_ensure_literal_pac_stack_loaded();
	$handle = opendir($dir);
	if($handle === false) {
		fractal_zip::warning_once('recursive_zip_folder: unable to open directory, skipping');
		return;
	}
	while(($entry = readdir($handle)) !== false) {
		if($entry === '.' || $entry === '..') {
			continue;
		}
		$sub = $dir . DS . $entry;
		if(is_dir($sub)) {
			$this->recursive_zip_folder($sub, $debug);
		} else {
			$entry_filename = $sub;
			$contents = file_get_contents($entry_filename);
			$memberKey = $this->logical_path_for_zip_member($entry_filename);
			$diskBytes = (string)$contents;
			$zipBytes = $diskBytes;
			$equivOriginal = null;
			$this->zip_pending_raster_canonical_hash = null;
			$this->zip_raster_canonical_lazy_only = false;
			$this->raster_canonical_reuse_lazy_range = null;
			if(fractal_zip::member_deep_unwrap_enabled()) {
				$mk = (string)$memberKey;
				if($mk !== '') {
					list($unwrapped) = fractal_zip_literal_deep_unwrap_with_layers($mk, $diskBytes, false);
					if($unwrapped !== $diskBytes) {
						$zipBytes = $unwrapped;
						$this->fractal_member_gzip_disk_restore[$mk] = $diskBytes;
						$equivOriginal = $diskBytes;
					}
				}
			} elseif(fractal_zip_literal_expand_gzip_inner_enabled()) {
				$mkLower = strtolower((string)$memberKey);
				$mkLen = strlen($mkLower);
				if(($mkLen >= 3 && substr($mkLower, -3) === '.gz')
					|| ($mkLen >= 5 && substr($mkLower, -5) === '.svgz')
					|| ($mkLen >= 4 && substr($mkLower, -4) === '.vgz')) {
					$ex = fractal_zip_literal_expand_outer_gzip_once($diskBytes);
					if($ex !== null) {
						$zipBytes = $ex['inner'];
						$this->fractal_member_gzip_disk_restore[(string)$memberKey] = $diskBytes;
						$equivOriginal = $diskBytes;
					}
				}
			}
			$mk = (string)$memberKey;
			if($mk !== '') {
				$canonTry = fractal_zip_raster_canonical_try($mk, $zipBytes);
				if($canonTry !== null && $canonTry !== $zipBytes) {
					$h = sha1($canonTry, true);
					if(isset($this->raster_canonical_hash_to_lazy_range[$h])) {
						$this->raster_canonical_reuse_lazy_range = $this->raster_canonical_hash_to_lazy_range[$h];
					} else {
						$this->zip_pending_raster_canonical_hash = $h;
						$this->zip_raster_canonical_lazy_only = true;
					}
					$zipBytes = $canonTry;
					$this->fractal_member_gzip_disk_restore[$mk] = $diskBytes;
					$equivOriginal = $diskBytes;
				}
			}
			$this->zip($zipBytes, $memberKey, $debug, $equivOriginal);
			if($debug) {
				$this->validate_fractal_zip($memberKey);
			}
			$this->files_counter++;
		}
	}
	closedir($handle);
}

function recursive_get_strings_for_fractal_zip_markers($dir) {
	$handle = opendir($dir);
	if($handle === false) {
		return;
	}
	while(($entry = readdir($handle)) !== false) {
		if($entry === '.' || $entry === '..') {
			continue;
		}
		$sub = $dir . DS . $entry;
		if(is_dir($sub)) {
			fractal_zip::recursive_get_strings_for_fractal_zip_markers($sub);
		} else {
			$contents = file_get_contents($sub);
			$this->strings_for_fractal_zip_markers[] = $contents;
		}
	}
	closedir($handle);
}

/**
 * Legacy digit-only floor from **fractal_string** length: multipass shrink, recursive_fractal_substring savings gate,
 * and default sliding-window start in `all_substrings_count` when no override is passed.
 *
 * Inner append **slice spans** use **`fz_inner_append_min_corpus_slice_bytes`** (next append step = parent `append_depth + 1`),
 * not this helper. **`all_substrings_count`** keeps its own window floor here; short literals also arrive via inner merges
 * (`fz_inner_merge_fractal_ref_*`).
 */
function substr_scan_minimum_length(): int {
	$digits = strlen((string) strlen($this->fractal_string));
	return max(6, 5 + (2 * $digits));
}

/**
 * If $s is an exact concatenation of k≥2 copies of some shortest unit u, return u; otherwise null.
 * Helps tuple-style expansions (e.g. case 27) retain the primitive period in substring candidates.
 */
public static function pure_repetition_primitive_unit(string $s): ?string {
	$n = strlen($s);
	if ($n < 4) {
		return null;
	}
	$half = intdiv($n, 2);
	for ($p = 1; $p <= $half; $p++) {
		if ($n % $p !== 0) {
			continue;
		}
		$u = substr($s, 0, $p);
		if ($u === '') {
			continue;
		}
		$k = intdiv($n, $p);
		if ($k < 2) {
			continue;
		}
		if (str_repeat($u, $k) === $s) {
			return $u;
		}
	}
	return null;
}

/**
 * Marker bytes for first append+replace from an empty dictionary (match offset 0), `<0"{pieceLen}>`.
 */
function estimate_inner_pass1_marker_strlen(int $pieceLen): int {
	return strlen($this->left_fractal_zip_marker) + strlen('0') + strlen($this->mid_fractal_zip_marker) + strlen((string) $pieceLen) + strlen($this->right_fractal_zip_marker);
}

/**
 * Upper bound driving substring sliding-window caps (all_substrings_count hard caps scale off this). Much larger than substr_scan_minimum_length() so long repeats are visible.
 * Env FRACTAL_ZIP_MAX_SUBSTR_EXPRESSION_LENGTH: positive bytes, clamped to segment_length (and never below substr_scan_minimum_length()). Unset = scaled default from fractal_string length.
 */
function maximum_substr_expression_length(): int {
	$seg = max(8, min(500000, (int) $this->segment_length));
	$floor = $this->substr_scan_minimum_length();
	static $envCap = null;
	if($envCap === null) {
		$e = getenv('FRACTAL_ZIP_MAX_SUBSTR_EXPRESSION_LENGTH');
		if($e !== false && trim((string) $e) !== '') {
			$v = (int) trim((string) $e);
			$envCap = $v > 0 ? $v : 0;
		} else {
			$envCap = 0;
		}
	}
	if($envCap > 0) {
		return max($floor, min($seg, $envCap));
	}
	$fsLen = strlen($this->fractal_string);
	$scaled = max($floor * 8, min($seg, max(256, (int) ceil($fsLen / 64))));
	return max($floor, min($seg, $scaled));
}

/**
 * Max input length (bytes) for heavy substring / fractal analysis. Above this, zip uses lazy range markers only.
 * Env FRACTAL_ZIP_MAX_FRACTAL_BYTES: unset = **0** (unlimited; can use huge RAM); positive = cap.
 */
public static function max_fractal_analysis_bytes(): int {
	if(getenv('FRACTAL_ZIP_FZCD_MERGED_ZIP_PASS') === '1' || getenv('FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS') === '1') {
		return 0;
	}
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$env = getenv('FRACTAL_ZIP_MAX_FRACTAL_BYTES');
	if($env === false || trim((string) $env) === '') {
		$cached = 0;
		return $cached;
	}
	$v = (int) trim((string) $env);
	if($v < 0) {
		$cached = 0;
		return $cached;
	}
	$cached = $v;
	return $cached;
}

/**
 * Per-member cap for entering expensive true-fractal analysis in zip().
