	$env = getenv('FRACTAL_ZIP_MAX_SUBSTRING_TUPLE_EXPAND_BYTES');
	if($env === false || trim((string) $env) === '') {
		$cached = 16777216;
		return $cached;
	}
	$v = (int) trim((string) $env);
	if($v <= 0) {
		$cached = 0;
		return $cached;
	}
	$cached = min($v, 2147483647);
	return $cached;
}

