/**
 * RECURSIVE_ONLY skips peelers/slide for heavy text — but fractal-likely corpora
 * (showing_off / dehacking / grid recipes) still need run-grammar (FZC5 → tens of B gzip).
 * Lifestyle micro singles (≤8 KiB) skip run-grammar: FZS1+gzip already matches the v8 bar
 * and collect_fractal_inner_run_grammar alone costs ~0.3 s on test_files21-class inputs.
 *
 * @param array<string,string> $rawFilesByPath
 */
public static function substring_multidiff_recursive_only_skips_run_grammar(
	array $rawFilesByPath,
	int $sumRawBytes,
	int $memberCount
): bool {
	if(!self::substring_multidiff_recursive_only_enabled()) {
		return false;
	}
	if($sumRawBytes <= 0 || !self::fs_profile_cheap_fractal_data_likely($rawFilesByPath, $sumRawBytes, $memberCount)) {
		return true;
	}
	// Lifestyle micro singles: FZS1 wins; skip the ~0.3s run-grammar collect.
	if($memberCount <= 1
		&& $sumRawBytes <= 8192
		&& self::lifestyle_speed_profile_enabled()) {
		return true;
	}
	// Singles: always keep run-grammar when fractal-likely (showing_off ~1 MiB+).
	if($memberCount <= 1) {
		return false;
	}
	// Multi-member showing_off-class trees (high reciprocal, midsize+).
	if($sumRawBytes >= 65536) {
		$sample = self::fs_profile_build_fractal_probe_sample($rawFilesByPath);
		if($sample !== '') {
			list($label, $ratio,) = self::substring_reciprocal_profile($sample);
			if($label === 'high' && $ratio <= 0.32) {
				return false;
			}
		}
	}
	return true;
}

