/**
 * Classify input into high/mixed/low reciprocal profiles using a cheap compression proxy.
 * Returns: [label, proxy_ratio, depth_adjust, seconds_scale].
 *
 * @return array{0:string,1:float,2:int,3:float}
 */
public static function substring_reciprocal_profile(string $string): array {
	$n = strlen($string);
	if($n <= 0) {
		return array('mixed', 1.0, 0, 1.0);
	}
	$sampleMax = 131072;
	$sample = ($n > $sampleMax) ? substr($string, 0, $sampleMax) : $string;
	$sampleLen = strlen($sample);
	if($sampleLen <= 0) {
		return array('mixed', 1.0, 0, 1.0);
	}
	$def = @gzdeflate($sample, 1);
	if(!is_string($def) || $def === '') {
		return array('mixed', 1.0, 0, 1.0);
	}
	$ratio = (float) strlen($def) / (float) $sampleLen;
	if($ratio <= 0.32) {
		return array('high', $ratio, 2, 1.25);
	}
	if($ratio <= 0.68) {
		return array('mixed', $ratio, 0, 1.0);
	}
	return array('low', $ratio, -1, 0.75);
}

/**
 * Corpus-adaptive reciprocal knobs derived from {@see substring_reciprocal_profile()} label on this instance.
 *
 * @return array{min_bytes:int,segment_bytes:int,max_pair_probes:int,min_seed_bytes:int,max_skip_seeds:int,legacy_skip_reuse_ratio:float,chunk_bytes:int,chunk_stride:int,chunk_hash_pairs:int,seed_score_scale:float}
 */
public function substring_reciprocal_effective_config(): array {
	$label = (string) $this->recursive_reciprocal_profile_label;
	$segmentBytes = fractal_zip::substring_reciprocal_segment_bytes();
	$chunkBytes = max(256, min(8192, (int) floor($segmentBytes / 6)));
	$cfg = array(
		'min_bytes' => fractal_zip::substring_reciprocal_min_bytes(),
		'segment_bytes' => $segmentBytes,
		'max_pair_probes' => fractal_zip::substring_reciprocal_max_pair_probes(),
		'min_seed_bytes' => fractal_zip::substring_reciprocal_min_seed_bytes(),
		'max_skip_seeds' => fractal_zip::substring_reciprocal_max_skip_seeds(),
		'legacy_skip_reuse_ratio' => 0.0,
		'chunk_bytes' => $chunkBytes,
		'chunk_stride' => max(64, (int) floor($chunkBytes / 2)),
		'chunk_hash_pairs' => 120,
		'seed_score_scale' => 0.97,
	);
	if($label === 'high') {
		$cfg['max_pair_probes'] = min(512, (int) round($cfg['max_pair_probes'] * 2.0));
		$cfg['max_skip_seeds'] = min(256, (int) round($cfg['max_skip_seeds'] * 2.0));
		$cfg['min_seed_bytes'] = max(8, (int) round($cfg['min_seed_bytes'] * 0.75));
		$cfg['legacy_skip_reuse_ratio'] = 0.42;
		$cfg['chunk_hash_pairs'] = 320;
		$cfg['chunk_stride'] = max(64, (int) floor($cfg['chunk_bytes'] / 3));
		$cfg['seed_score_scale'] = 0.95;
	} elseif($label === 'low') {
		$cfg['max_pair_probes'] = max(2, (int) round($cfg['max_pair_probes'] * 0.5));
		$cfg['max_skip_seeds'] = max(4, (int) round($cfg['max_skip_seeds'] * 0.5));
		$cfg['min_bytes'] = max($cfg['min_bytes'], 131072);
		$cfg['chunk_hash_pairs'] = 64;
		$cfg['chunk_stride'] = max(128, (int) floor($cfg['chunk_bytes'] * 0.8));
		$cfg['seed_score_scale'] = 1.0;
	} else {
		$cfg['legacy_skip_reuse_ratio'] = 0.28;
		$cfg['chunk_hash_pairs'] = 180;
		$cfg['seed_score_scale'] = 0.96;
	}
	return $cfg;
}

/**
 * For highly similar multi-file folders, keep inner flow centered on reciprocal multidiff instead of
 * additional run-grammar/peeler variant sweeps.
 *
 * @param array<string,string> $rawFilesByPath
 * @return array{0:string,1:float,2:int,3:float}
 */
private function folder_reciprocal_inner_profile(array $rawFilesByPath): array {
	$files = count($rawFilesByPath);
	if($files < 2) {
		return array('low', 1.0, $files, 0.0);
	}
	$sigParts = array((string) $files);
	$sampled = 0;
	foreach($rawFilesByPath as $path => $bytes) {
		$bs = (string) $bytes;
		$n = strlen($bs);
		$head = substr($bs, 0, min(256, $n));
		$tail = ($n > 256) ? substr($bs, -256) : '';
		$sigParts[] = (string) $path . ':' . $n . ':' . hash('xxh3', $head . "\0" . $tail, false);
		$sampled++;
		if($sampled >= 16) {
			break;
		}
	}
	$sig = hash('sha256', implode("\n", $sigParts), false);
	if(isset($this->folder_reciprocal_profile_cache[$sig])) {
		return $this->folder_reciprocal_profile_cache[$sig];
	}
	$pieces = array();
	$picked = 0;
	foreach($rawFilesByPath as $bytes) {
		$pieces[] = substr((string) $bytes, 0, 16384);
		$picked++;
		if($picked >= 16) {
			break;
		}
	}
	if($pieces === array()) {
		return array('low', 1.0, $files, 0.0);
	}
	$chunkFreq = array();
	$totalChunks = 0;
	foreach($pieces as $piece) {
		$pn = strlen($piece);
		if($pn < 256) {
			continue;
		}
		$seenLocal = array();
		for($off = 0; $off + 256 <= $pn; $off += 512) {
			$h = hash('xxh3', substr($piece, $off, 256), false);
			$seenLocal[$h] = true;
		}
		foreach($seenLocal as $h => $_) {
			$chunkFreq[$h] = ($chunkFreq[$h] ?? 0) + 1;
			$totalChunks++;
		}
	}
	$reusedChunks = 0;
	foreach($chunkFreq as $freq) {
		if((int) $freq >= 2) {
			$reusedChunks++;
		}
	}
	$reuseScore = ($totalChunks > 0) ? ((float) $reusedChunks / (float) $totalChunks) : 0.0;
	$sample = implode("\n", $pieces);
	$profile = fractal_zip::substring_reciprocal_profile($sample);
	$out = array((string) $profile[0], (float) $profile[1], $files, $reuseScore);
	$this->folder_reciprocal_profile_cache[$sig] = $out;
	if(count($this->folder_reciprocal_profile_cache) > 32) {
		array_shift($this->folder_reciprocal_profile_cache);
	}
	return $out;
}

/**
 * For highly similar multi-file folders, keep inner flow centered on reciprocal multidiff instead of
 * additional run-grammar/peeler variant sweeps.
 *
 * @param array<string,string> $rawFilesByPath
 */
private function folder_reciprocal_inner_fast_path_enabled(array $rawFilesByPath): bool {
	if(!fractal_zip::substring_reciprocal_enabled()) {
		return false;
	}
	list($label, $ratio, $files, $reuseScore) = $this->folder_reciprocal_inner_profile($rawFilesByPath);
	return $files >= 8
		&& $label === 'high'
		&& ($ratio <= 0.08 || ($ratio <= 0.20 && $reuseScore >= 0.35));
}

/**
 * When recursive_fractal_substring starts on a very large root string, clamp depth below max_recursive_fractal_depth().
 * FRACTAL_ZIP_FRACTAL_LARGE_ENTRY_DEPTH_MIN_BYTES: default 512 KiB (262144 when FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS=1); 0 = disable.
 * FRACTAL_ZIP_FRACTAL_LARGE_ENTRY_MAX_RECURSION_DEPTH: 1–64, default 9.
 */
public static function fractal_large_entry_effective_max_depth(int $rootStrlen, int $configuredMaxDepth): int {
	if($rootStrlen <= 0) {
		return $configuredMaxDepth;
	}
	static $snap = null;
	if($snap === null) {
		$synthOn = getenv('FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS') === '1';
		$e = getenv('FRACTAL_ZIP_FRACTAL_LARGE_ENTRY_DEPTH_MIN_BYTES');
		if($e !== false && trim((string) $e) !== '') {
			$thr = max(0, (int) $e);
		} elseif($synthOn) {
			$thr = 262144;
		} else {
			$thr = 524288;
		}
		$ed = getenv('FRACTAL_ZIP_FRACTAL_LARGE_ENTRY_MAX_RECURSION_DEPTH');
		$capD = ($ed !== false && trim((string) $ed) !== '') ? max(1, min(64, (int) $ed)) : 9;
		$snap = array('thr' => $thr, 'capD' => $capD);
	}
	if($snap['thr'] <= 0 || $rootStrlen < $snap['thr']) {
		return $configuredMaxDepth;
	}
	return min($configuredMaxDepth, $snap['capD']);
}

/**
 * Max recursion depth for recursive_fractal_substring() exploration.
 * Env FRACTAL_ZIP_MAX_RECURSIVE_FRACTAL_DEPTH: 1-64, default 12.
 * During FZBF nested zip (FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS=1), optional
 * FRACTAL_ZIP_LITERAL_SYNTH_MAX_RECURSIVE_FRACTAL_DEPTH (1-64); otherwise same default as normal (12).
 */
public static function max_recursive_fractal_depth(): int {
	$synthOn = getenv('FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS') === '1';
	$sKey = $synthOn ? 's' : 'n';
	static $cached = array();
	if(isset($cached[$sKey])) {
		return $cached[$sKey];
	}
	if($synthOn) {
		$eSyn = getenv('FRACTAL_ZIP_LITERAL_SYNTH_MAX_RECURSIVE_FRACTAL_DEPTH');
		if($eSyn !== false && trim((string) $eSyn) !== '') {
			$v = (int) trim((string) $eSyn);
			$cached[$sKey] = max(1, min(64, $v));
			return $cached[$sKey];
		}
	}
	$env = getenv('FRACTAL_ZIP_MAX_RECURSIVE_FRACTAL_DEPTH');
	if($env === false || trim((string) $env) === '') {
		$cached[$sKey] = 12;
		return $cached[$sKey];
	}
	$v = (int) trim((string) $env);
	$cached[$sKey] = max(1, min(64, $v));
	return $cached[$sKey];
}

/**
 * Wall-clock budget (seconds) for recursive_fractal_substring() exploration per zip instance.
 * Env FRACTAL_ZIP_MAX_RECURSIVE_FRACTAL_SECONDS: 1-120, default 10.
 * FZBF nested zip sets FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS=1; default wall budget matches the normal 10s unless
 * FRACTAL_ZIP_LITERAL_SYNTH_MAX_RECURSIVE_FRACTAL_SECONDS is set (1-600) for deeper searches (e.g. README 102-byte demos).
 * Cached separately from the normal path so a parent zip cannot pin the nested synth to the wrong budget.
 */
public static function max_recursive_fractal_seconds(): int {
	$synthOn = getenv('FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS') === '1';
	// Include FRACTAL_ZIP_TIME_BUDGET_MS in the cache key so per-request changes (e.g. perf_test
	// shrinking the remaining wall between corpora) are not pinned to the first value seen.
	$ms = getenv('FRACTAL_ZIP_TIME_BUDGET_MS');
	$msKey = 'noms';
	if($ms !== false && trim((string) $ms) !== '' && is_numeric($ms)) {
		$msKey = 'ms' . (string) (int) (float) trim((string) $ms);
	}
	$sKey = ($synthOn ? 's' : 'n') . '|' . $msKey;
	static $cached = array();
	if(isset($cached[$sKey])) {
		return $cached[$sKey];
	}
	// Global speed budget (milliseconds) overrides recursive search budget.
	if($ms !== false && trim((string)$ms) !== '' && is_numeric($ms)) {
		$vms = (float) trim((string)$ms);
		if($vms > 0) {
			$sec = (int) ceil($vms / 1000.0);
			$cap = $synthOn ? 600 : 120;
			$cached[$sKey] = max(1, min($cap, $sec));
			return $cached[$sKey];
		}
	}
	if($synthOn) {
		$envS = getenv('FRACTAL_ZIP_LITERAL_SYNTH_MAX_RECURSIVE_FRACTAL_SECONDS');
		if($envS !== false && trim((string) $envS) !== '') {
			$v = (int) trim((string) $envS);
			$cached[$sKey] = max(1, min(600, $v));
			return $cached[$sKey];
		}
		$cached[$sKey] = 10;
		return $cached[$sKey];
	}
	$env = getenv('FRACTAL_ZIP_MAX_RECURSIVE_FRACTAL_SECONDS');
	if($env === false || trim((string) $env) === '') {
		$cached[$sKey] = 10;
		return $cached[$sKey];
	}
	$v = (int) trim((string) $env);
	$cached[$sKey] = max(1, min(120, $v));
	return $cached[$sKey];
}

/**
 * Wall-clock budget for the zip_folder / literal-synth **multipass equivalence** loop (range substitution passes).
 * Normal folders: same as FRACTAL_ZIP_MAX_RECURSIVE_FRACTAL_SECONDS (via max_recursive_fractal_seconds()), except
 * FRACTAL_ZIP_ULTRA=1 defaults to **0 = unlimited** while passes still improve (override with FRACTAL_ZIP_MAX_FRACTAL_MULTIPASS_WALL_SECONDS>0).
 * FZBF nested synth: default **0 = unlimited** while passes still improve; set FRACTAL_ZIP_LITERAL_SYNTH_MULTIPASS_MAX_SECONDS>0 to cap.
 */
public static function max_fractal_multipass_wall_seconds(): int {
	if(getenv('FRACTAL_ZIP_LITERAL_SYNTH_ZIP_PASS') !== '1') {
		$capEnv = getenv('FRACTAL_ZIP_MAX_FRACTAL_MULTIPASS_WALL_SECONDS');
		if($capEnv !== false && trim((string) $capEnv) !== '') {
			$cv = (int) trim((string) $capEnv);
			if($cv <= 0) {
				return 0;
			}
			return max(1, min(86400, $cv));
		}
		if(fractal_zip::ultra_compression_enabled()) {
			return 0;
		}
		return fractal_zip::max_recursive_fractal_seconds();
	}
	$e = getenv('FRACTAL_ZIP_LITERAL_SYNTH_MULTIPASS_MAX_SECONDS');
	if($e === false || trim((string) $e) === '') {
		return 0;
	}
	$v = (int) trim((string) $e);
	if($v <= 0) {
		return 0;
	}
	return max(1, min(86400, $v));
}

/**
 * Multipass keeps a candidate when matches×len(piece)/len(range_marker) > this × improvement_factor_threshold.
 * Env FRACTAL_ZIP_MULTIPASS_GATE_MULT: 1.0–4.0, default 1.28 (fewer marginal multipass candidates vs 1.18).
 */
public static function multipass_ratio_gate_multiplier(): float {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$env = getenv('FRACTAL_ZIP_MULTIPASS_GATE_MULT');
	if($env === false || trim((string) $env) === '') {
		$cached = 1.28;
		return $cached;
	}
	$v = (float) trim((string) $env);
	$cached = max(1.0, min(4.0, $v));
	return $cached;
}

/** @uses static env default when instance override unset */
function effective_substring_top_k(): int {
	if($this->tuning_substring_top_k !== null) {
		return max(1, min(48, (int) $this->tuning_substring_top_k));
	}
	return fractal_zip::substring_top_candidate_count();
}

function effective_multipass_gate_mult(): float {
	if($this->tuning_multipass_gate_mult !== null) {
		return max(1.0, min(4.0, (float) $this->tuning_multipass_gate_mult));
	}
	return fractal_zip::multipass_ratio_gate_multiplier();
}

/**
 * $minimum_overhead_length drives multipass substring windows; keep consistent with marker widths.
 */
function prepare_minimum_overhead_for_multipass() {
	if($this->multipass) {
		$this->minimum_overhead_length = strlen($this->left_fractal_zip_marker) + 1 + strlen($this->mid_fractal_zip_marker) + 3 + strlen($this->mid_fractal_zip_marker) + 1 + strlen($this->right_fractal_zip_marker);
	} else {
		$this->minimum_overhead_length = strlen($this->left_fractal_zip_marker) + 3 + strlen($this->right_fractal_zip_marker);
	}
}

/**
 * Multipass range substitution on $this->equivalences (same logic as zip_folder tail). Continues while each pass finds improvements
 * or until max additional passes / wall seconds (see max_fractal_multipass_wall_seconds).
 */
function run_fractal_multipass_equivalence_passes($debug = false) {
	if(!$this->multipass) {
		return;
	}
	$maxAdditional = $this->multipass_max_additional_passes;
	$additionalDone = 0;
	$last_pass_made_an_improvement = true;
	while($last_pass_made_an_improvement) {
		if($maxAdditional !== null && $additionalDone >= (int) $maxAdditional) {
			break;
		}
		$maxSeconds = fractal_zip::max_fractal_multipass_wall_seconds();
		if($maxSeconds > 0 && microtime(true) - $this->initial_micro_time > $maxSeconds) {
			fractal_zip::warning_once('multipass time budget reached; stopping additional passes');
			break;
		}
		$last_pass_made_an_improvement = false;
		$improving_replaces = array();
		$this->fractal_zipping_pass++;
		if($debug) {
			print('$this->fractal_zipping_pass: ');
			var_dump($this->fractal_zipping_pass);
		}
		$strings = array();
		foreach($this->equivalences as $equivalence_index => $equivalence) {
			$string = $equivalence[2];
			$strings[] = $string;
		}
		foreach($this->equivalences as $equivalence_index => $equivalence) {
			$string = $equivalence[2];
			$stringLen = strlen($string);
			$maxSubstrExprLen = $this->substr_scan_minimum_length();
			$counter = 0;
			$last_start_matches = 0;
			while($counter < $stringLen) {
				$length_counter = $stringLen - $counter;
				if($length_counter > $this->segment_length) {
					$length_counter = $this->segment_length;
				}
				$last_end_matches = 0;
				while($length_counter > $maxSubstrExprLen) {
					$piece = substr($string, $counter, $length_counter);
					$matches = 0;
					foreach($strings as $string2) {
						$matches += substr_count($string2, $piece);
					}
					if($matches > 1 && $matches > $last_start_matches && $matches > $last_end_matches) {
						$position_in_fractal_string = strpos($this->fractal_string, $piece);
						if($position_in_fractal_string !== false) {
							$start_offset = $position_in_fractal_string;
						} else {
							$start_offset = strlen($this->fractal_string);
						}
						$end_offset = strlen($piece) + $start_offset - 1;
						$range_string = $this->left_fractal_zip_marker . $this->fractal_zipping_pass . $this->mid_fractal_zip_marker . $start_offset . '-' . $end_offset . $this->mid_fractal_zip_marker . $this->fractal_zipping_pass . $this->right_fractal_zip_marker;
						if($matches * strlen($piece) / strlen($range_string) > $this->effective_multipass_gate_mult() * $this->improvement_factor_threshold) {
							$score = $matches * (strlen($piece) - strlen($range_string));
							$improving_replaces[$piece] = $score;
							$last_pass_made_an_improvement = true;
						}
					}
					$last_end_matches = $matches;
					$length_counter--;
				}
				$last_start_matches = $matches;
				$counter++;
			}
		}
		arsort($improving_replaces);
		foreach($improving_replaces as $search => $score) {
			$would_need_to_add_to_fractal_string = false;
			$position_in_fractal_string = strpos($this->fractal_string, $search);
			if($position_in_fractal_string !== false) {
				$start_offset = $position_in_fractal_string;
			} else {
				$start_offset = strlen($this->fractal_string);
				$would_need_to_add_to_fractal_string = true;
			}
			$end_offset = strlen($search) + $start_offset - 1;
			$range_string = $this->left_fractal_zip_marker . $this->fractal_zipping_pass . $this->mid_fractal_zip_marker . $start_offset . '-' . $end_offset . $this->mid_fractal_zip_marker . $this->fractal_zipping_pass . $this->right_fractal_zip_marker;
			if($would_need_to_add_to_fractal_string) {
				$this->fractal_string .= $search;
			}
			foreach($this->equivalences as $equivalence_index => $equivalence) {
				$this->equivalences[$equivalence_index][2] = str_replace($search, $range_string, $this->equivalences[$equivalence_index][2]);
			}
		}
		$additionalDone++;
	}
}

function maximum_scale_expression_length() {
	// assumptions: recursion_counter < 10
	return (4 + (2 * strlen((string)strlen($this->fractal_string))) + strlen((string)round((1 / 3), 6))); // limiting infinitely expressed fractions (0.3333..., etc.) that arise in decimal due to incompatibilities between the expressed value nature and the limited number of factors in the base (10) choice
}

function fractal_marker_ctx_publish(): void {
	fractal_zip::$fractal_marker_ctx_left = (string) $this->left_fractal_zip_marker;
	fractal_zip::$fractal_marker_ctx_mid = (string) $this->mid_fractal_zip_marker;
	fractal_zip::$fractal_marker_ctx_right = (string) $this->right_fractal_zip_marker;
	fractal_zip::$fractal_marker_ctx_range = (string) $this->range_shorthand_marker;
}

function create_fractal_zip_markers($dir, $debug = false) {
	$this->minimum_overhead_length = 5; // <#"#>
	fractal_zip::warning_once('need the ability to have a recursive fractal zip such that the structure of what is compressed (such as a file structure or data structure) could be selectively decompressed according to what in the fractal zip we are interested in. self-extracting file could also thus be self-navigating');
	fractal_zip_maybe_apply_adaptive_markers($this, $dir);
	if($this->multipass) {
		$this->minimum_overhead_length = strlen($this->left_fractal_zip_marker) + 1 + strlen($this->mid_fractal_zip_marker) + 3 + strlen($this->mid_fractal_zip_marker) + 1 + strlen($this->right_fractal_zip_marker);
	} else {
		$this->minimum_overhead_length = strlen($this->left_fractal_zip_marker) + 3 + strlen($this->right_fractal_zip_marker);
	}
	$this->fractal_marker_ctx_publish();
	return true;
}

/** Sum of file sizes under $dir (bytes); directories only, regular files. */
function folder_raw_total_bytes($dir) {
	if(!is_dir($dir)) {
		return 0;
	}
	$total = 0;
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		// Ignore leftover in-tree .fz/.fzc (test_files59 after a prior encode doubled
		// the monster-path raw hint past the -10 race gate).
		$name = (string) $fileInfo->getFilename();
		if(fractal_zip::path_is_inplace_fractal_container_leaf($name)) {
			continue;
		}
		$total += (int) $fileInfo->getSize();
	}
	return $total;
}

/**
 * Count files under $dir, stopping at $cap+1 (for mega-tree short-circuits).
 * Ignores leftover in-tree fractal containers like {@see folder_raw_total_bytes}.
 */
function folder_file_count_capped($dir, int $cap = 20000): int {
	if(!is_dir($dir) || $cap <= 0) {
		return 0;
	}
	$n = 0;
	try {
		$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
		foreach($it as $fileInfo) {
			if(!$fileInfo->isFile()) {
				continue;
			}
			$name = (string) $fileInfo->getFilename();
			if(fractal_zip::path_is_inplace_fractal_container_leaf($name)) {
				continue;
			}
			$n++;
			if($n > $cap) {
				return $n;
			}
		}
	} catch(Throwable $e) {
		return $n;
	}
	return $n;
}

/**
 * Use streaming FZB4 + raw deflate outer for very large folders when enabled.
 * FRACTAL_ZIP_FOLDER_GZIP_FAST: unset = auto if raw bytes ≥ FRACTAL_ZIP_LARGE_FOLDER_FAST_BYTES (default 128 MiB; was 48 MiB — 48–120 MiB trees often FLAC/literal-unified and lose badly to deflate-only); 1 = on; 0 = off.
 */
function should_use_large_folder_gzip_fast_path($dir) {
	if(is_array($this->enwik_zip_ctx)) {
		return false;
	}
	$explicitOn = false;
	$v = getenv('FRACTAL_ZIP_FOLDER_GZIP_FAST');
	if($v !== false && trim((string) $v) !== '') {
		$v = strtolower(trim((string) $v));
		if($v === '0' || $v === 'off' || $v === 'false' || $v === 'no') {
			return false;
		}
		if($v === '1' || $v === 'on' || $v === 'true' || $v === 'yes') {
			$explicitOn = true;
			if(!fractal_zip::folder_census_gzip_fast_gate_forced_path()) {
				return true;
			}
		}
	}
	$threshEnv = getenv('FRACTAL_ZIP_LARGE_FOLDER_FAST_BYTES');
	$lim = ($threshEnv !== false && trim((string) $threshEnv) !== '') ? (int) $threshEnv : (128 * 1024 * 1024);
	if($lim <= 0) {
		return false;
	}
	$raw = $this->folder_raw_total_bytes($dir);
	if($raw < $lim) {
		return false;
	}
	if($explicitOn || fractal_zip::folder_census_gzip_fast_auto_gate_enabled()) {
		$census = fractal_zip::folder_bundle_census_from_dir($dir);
		$ratio = isset($census['textish_ratio']) ? (float) $census['textish_ratio'] : 0.0;
		if($ratio >= fractal_zip::folder_census_gzip_fast_max_textish_ratio()) {
			// Lifestyle: still take gzip-fast on huge textish trees (test_files55) — full
			// fractal / q11 brotli cannot finish under the 90s monster wall.
			if(fractal_zip::lifestyle_speed_profile_enabled() && $raw >= $lim) {
				// keep gzip-fast
			} elseif(!fractal_zip::fs_profile_enabled()) {
				return false;
			} elseif(fractal_zip::fs_profile_fs_gzip_fast_should_defer_to_7z($dir)) {
				return false;
			}
		}
	}
	if(fractal_zip::fs_profile_enabled() && fractal_zip::fs_profile_fs_gzip_fast_should_defer_to_7z($dir)) {
		return false;
	}
	return true;
}

/** FS preset: gzip-fast would lose to early native 7z passthrough — skip streaming literal path. */
public static function fs_profile_fs_gzip_fast_should_defer_to_7z(string $dir): bool {
	if(!fractal_zip::fs_profile_enabled()) {
		return false;
	}
	$stat = fractal_zip::fs_profile_zip_folder_stat_from_dir($dir);
	if($stat === null) {
		return false;
	}
	list($memberCount, $sumRawBytes, $allRelPaths,) = $stat;

	return fractal_zip::fs_profile_should_use_7z_passthrough(array(), $sumRawBytes, $memberCount, null, $allRelPaths);
}

/**
 * Write FZB4 literal bundle to a temp file (one file loaded at a time). Matches encode_literal_bundle_payload FZB4 layout.
 * @param bool $rawLiteralsOnly If true, skip choose_best_literal_bundle_transform (mode 0, raw bytes only) for speed on huge trees.
 * @return bool false on I/O or path-length failure
 */
function fzcd_cleanup_pcm_rows(array $rows) {
	foreach($rows as $r) {
		if(isset($r['pcm']) && is_string($r['pcm']) && $r['pcm'] !== '' && is_file($r['pcm'])) {
			@unlink($r['pcm']);
		}
	}
}

/**
 * Inner bundle FZCD v1: merged raw PCM for one or more compatible .flac (same rate/channels/bps/pcm_fmt). Payload is either
 * one FLAC stream (FRACTAL_ZIP_FZCD_FLAG_MERGED_FLAC), chunked fractal FZC* (FRACTAL_ZIP_FZCD_FLAG_MERGED_FRACTAL_CHUNKED),
 * legacy single-blob fractal (FRACTAL_ZIP_FZCD_FLAG_MERGED_FRACTAL_PCM),
 * legacy gzip on PCM (bit 2), or raw inline PCM. Manifest keeps per-track byte lengths. Non-FLAC members use FZB4-style
 * records after. Outer raw deflate compresses the whole inner.
 * @param list<string> $paths sorted relative paths
 */
function write_fzcd_bundle_if_applicable($root, array $paths, $outPath) {
	fractal_zip_ensure_flac_pac_loaded();
	if(!fractal_zip_flac_pac_enabled() || !fractal_zip_flac_pac_tools_ok()) {
		return false;
	}
	$flacPaths = array();
	$otherPaths = array();
	foreach($paths as $p) {
		if(preg_match('/\\.flac$/i', (string) $p)) {
			$flacPaths[] = (string) $p;
		} else {
			$otherPaths[] = (string) $p;
		}
	}
	if(count($flacPaths) < 1) {
		return false;
	}
	$fzcdWBase = fractal_zip::hot_string_digest((string) $root . "\0" . implode("\n", $paths) . "\0fzcdw\0" . (string) spl_object_id($this));
	$rows = array();
	$ref = null;
	foreach($flacPaths as $pi => $p) {
		$full = $root . DS . str_replace('/', DS, $p);
		if(!is_file($full)) {
			$this->fzcd_cleanup_pcm_rows($rows);
			return false;
		}
		$meta = fractal_zip_flac_pac_probe($full);
		if($meta === null) {
			$this->fzcd_cleanup_pcm_rows($rows);
			return false;
		}
		if($ref === null) {
			$ref = $meta;
		} elseif($ref['sample_rate'] !== $meta['sample_rate'] || $ref['channels'] !== $meta['channels']
			|| $ref['source_bps'] !== $meta['source_bps'] || $ref['pcm_fmt'] !== $meta['pcm_fmt']) {
			$this->fzcd_cleanup_pcm_rows($rows);
			return false;
		}
		$pcmTmp = sys_get_temp_dir() . DS . 'fzcdpcm_' . substr(md5($fzcdWBase . "\0row\0" . (string) $pi), 0, 16) . '.raw';
		if(!fractal_zip_flac_pac_decode_file_to_pcm_path($full, $meta['pcm_fmt'], $pcmTmp)) {
			@unlink($pcmTmp);
			$this->fzcd_cleanup_pcm_rows($rows);
			return false;
		}
		$sz = filesize($pcmTmp);
		if(!is_int($sz) || $sz < 1) {
			@unlink($pcmTmp);
			$this->fzcd_cleanup_pcm_rows($rows);
			return false;
		}
		$rows[] = array(
			'path' => $p,
			'pcm' => $pcmTmp,
			'len' => $sz,
			'sample_rate' => $meta['sample_rate'],
			'channels' => $meta['channels'],
			'source_bps' => $meta['source_bps'],
			'pcm_fmt' => $meta['pcm_fmt'],
		);
	}
	$plannedRaw = 0;
	foreach($rows as $r) {
		$plannedRaw += (int) $r['len'];
	}
	// Chunked merged-fractal streams PCM from mergePath; no all-in-RAM size cap here (see fractal_zip_flac_pac_merged_fractal_requested).
	$wantMergedFractal = fractal_zip_flac_pac_merged_fractal_requested($plannedRaw);
	$manifestParts = array($this->encode_varint_u32(count($rows)));
	$prevPath = '';
	foreach($rows as $r) {
		$p = $r['path'];
		$cpl = 0;
		$max = min(strlen($prevPath), strlen($p));
		while($cpl < $max && $prevPath[$cpl] === $p[$cpl]) {
			$cpl++;
		}
		$suf = substr($p, $cpl);
		$chunk = $this->encode_varint_u32($cpl) . $this->encode_varint_u32(strlen($suf)) . $suf
			. pack('V', $r['sample_rate'])
			. chr(min(255, $r['channels'])) . chr(min(255, $r['source_bps'])) . chr($r['pcm_fmt'])
			. pack('P', $r['len']);
		$manifestParts[] = $chunk;
		$prevPath = $p;
	}
	$manifestBin = implode('', $manifestParts);
	$mergePath = sys_get_temp_dir() . DS . 'fzcdmrg_' . substr(md5($fzcdWBase . "\0merge"), 0, 16) . '.raw';
	$mergeOut = @fopen($mergePath, 'wb');
	if($mergeOut === false) {
		$this->fzcd_cleanup_pcm_rows($rows);
		return false;
	}
	$ok = true;
	$rawTotal = 0;
	foreach($rows as $r) {
		$pin = @fopen($r['pcm'], 'rb');
		if($pin === false) {
			$ok = false;
			break;
		}
		$copied = stream_copy_to_stream($pin, $mergeOut);
		fclose($pin);
		@unlink($r['pcm']);
		if($copied !== $r['len']) {
			$ok = false;
			break;
		}
		$rawTotal += $r['len'];
	}
	fclose($mergeOut);
	if(!$ok) {
		@unlink($mergePath);
		$this->fzcd_cleanup_pcm_rows($rows);
		return false;
	}
	$fractalInner = null;
	$fzcdReuseMergedFlacPath = null;
	if($wantMergedFractal) {
		$bpf = fractal_zip_flac_pac_pcm_bytes_per_frame_from_ref($ref);
		$chunkSz = fractal_zip_flac_pac_align_chunk_bytes(fractal_zip_flac_pac_merged_fractal_chunk_bytes(), $bpf);
		$mpFr = fractal_zip_flac_pac_merged_fractal_use_multipass();
		$useMp = $mpFr ? (bool) $this->multipass : false;
		$seg = fractal_zip_fzcd_merged_fractal_segment_length((int) $this->segment_length);
		$imp = fractal_zip_fzcd_merged_fractal_improvement_threshold((float) $this->improvement_factor_threshold);
		$topK = $this->tuning_substring_top_k;
		$gate = $this->tuning_multipass_gate_mult;
		$mergeIn = @fopen($mergePath, 'rb');
		if($mergeIn !== false) {
			$pcmPreWire = fractal_zip_pcm_pretransform_enabled();
			$chunkPartList = array();
			$nChunks = 0;
			$sumPcm = 0;
			$allChunksOk = true;
			while($sumPcm < $rawTotal && $allChunksOk) {
				$need = min($chunkSz, $rawTotal - $sumPcm);
				$pcmChunk = stream_get_contents($mergeIn, $need);
				if($pcmChunk === false) {
					$pcmChunk = '';
				}
				$got = strlen($pcmChunk);
				if($got !== $need) {
					$allChunksOk = false;
					break;
				}
				$enc = fractal_zip_fzcd_encode_merged_pcm_chunk_with_pre($pcmChunk, $seg, $useMp, $imp, $topK, $gate, (int) $ref['pcm_fmt'], (int) $ref['channels']);
				if($enc === null || strlen($enc['inner']) >= $got) {
					$allChunksOk = false;
					break;
				}
				$innerBlob = $enc['inner'];
				$segBase = pack('P', $got) . pack('P', strlen($innerBlob));
				$preByte = $pcmPreWire ? chr(max(0, min(255, (int) $enc['pre']))) : '';
				$chunkPartList[] = $segBase . $preByte . $innerBlob;
				$nChunks++;
				$sumPcm += $got;
			}
			fclose($mergeIn);
			if($allChunksOk && $sumPcm === $rawTotal && $nChunks > 0) {
				$fractalInner = pack('P', $rawTotal) . pack('V', $nChunks) . implode('', $chunkPartList);
			} else {
				fractal_zip::warning_once('FZCD merged fractal: chunk encode failed or size mismatch; using merged FLAC.');
			}
		}
	}
	if($fractalInner !== null && is_file($mergePath)) {
		$flacCmp = $mergePath . '.fzcdsz.flac';
		if(fractal_zip_flac_pac_pcm_file_to_flac_file($mergePath, $ref['sample_rate'], $ref['channels'], $ref['pcm_fmt'], $flacCmp)) {
			$cmpLen = @filesize($flacCmp);
			$frPay = strlen($fractalInner);
			if(is_int($cmpLen) && $cmpLen > 0 && $frPay >= $cmpLen) {
				$fractalInner = null;
				$fzcdReuseMergedFlacPath = $flacCmp;
			} elseif(is_file($flacCmp)) {
				@unlink($flacCmp);
			}
		}
	}
	$fh = fopen($outPath, 'wb');
	if($fh === false) {
		@unlink($mergePath);
		return false;
	}
	$fzcdFlags = 1 | (($fractalInner !== null) ? FRACTAL_ZIP_FZCD_FLAG_MERGED_FRACTAL_CHUNKED : FRACTAL_ZIP_FZCD_FLAG_MERGED_FLAC);
	if($fractalInner !== null && fractal_zip_pcm_pretransform_enabled()) {
		$fzcdFlags |= FRACTAL_ZIP_FZCD_FLAG_CHUNK_PCM_PRETRANSFORM;
	}
	$ok = fwrite($fh, 'FZCD' . chr(1) . chr($fzcdFlags)) !== false;
	if($ok) {
		$ok = fwrite($fh, $manifestBin) !== false;
	}
	if($ok && $fractalInner !== null) {
		$frLen = strlen($fractalInner);
		$w3 = fwrite($fh, $fractalInner);
		if($w3 === false || $w3 !== $frLen) {
			$ok = false;
		}
		@unlink($mergePath);
	} elseif($ok) {
		if($fzcdReuseMergedFlacPath !== null && is_file($fzcdReuseMergedFlacPath)) {
			$flacPath = $fzcdReuseMergedFlacPath;
			if(is_file($mergePath)) {
				@unlink($mergePath);
			}
		} else {
			$flacPath = $mergePath . '.flac';
			if(!fractal_zip_flac_pac_pcm_file_to_flac_file($mergePath, $ref['sample_rate'], $ref['channels'], $ref['pcm_fmt'], $flacPath)) {
				@unlink($mergePath);
				@unlink($flacPath);
				$ok = false;
			} else {
				@unlink($mergePath);
			}
		}
		if($ok) {
			$flLen = filesize($flacPath);
			if(!is_int($flLen) || $flLen < 1) {
				@unlink($flacPath);
				$ok = false;
			} elseif(fwrite($fh, pack('P', $rawTotal)) === false || fwrite($fh, pack('P', $flLen)) === false) {
				@unlink($flacPath);
				$ok = false;
			} else {
				$flIn = @fopen($flacPath, 'rb');
				if($flIn === false) {
					@unlink($flacPath);
					$ok = false;
				} else {
					if(stream_copy_to_stream($flIn, $fh) !== $flLen) {
						$ok = false;
					}
					fclose($flIn);
					@unlink($flacPath);
				}
			}
		}
	}
	if($ok && fwrite($fh, $this->encode_varint_u32(count($otherPaths))) === false) {
		$ok = false;
	}
	$prevPath = '';
	if($ok) {
		foreach($otherPaths as $p) {
			$full = $root . DS . str_replace('/', DS, $p);
			$rawBytes = file_get_contents($full);
			if($rawBytes === false) {
				$rawBytes = '';
			}
			list($mode, $storeBytes) = $this->choose_best_literal_bundle_transform($rawBytes, $p);
			$cpl = 0;
			$max = min(strlen($prevPath), strlen($p));
			while($cpl < $max && $prevPath[$cpl] === $p[$cpl]) {
				$cpl++;
			}
			$suf = substr($p, $cpl);
			$rec = $this->encode_varint_u32($cpl) . $this->encode_varint_u32(strlen($suf)) . $suf
				. chr($mode) . $this->encode_varint_u32(strlen($storeBytes)) . $storeBytes;
			if(fwrite($fh, $rec) === false) {
				$ok = false;
				break;
			}
			$prevPath = $p;
		}
	}
	fclose($fh);
	if(!$ok) {
		@unlink($outPath);
		$this->fzcd_cleanup_pcm_rows($rows);
		return false;
	}
	return true;
}

/**
 * Stream-read FZCD inner from disk; write members under $rootDir (FLACs re-encoded; others literal modes).
 * @return bool false if not FZCD
 */
function extract_fzcd_bundle_streaming_from_path($bundlePath, $rootDir, $debug) {
	fractal_zip_ensure_flac_pac_loaded();
	$fh = @fopen($bundlePath, 'rb');
	if($fh === false) {
		return false;
	}
	$sig = fread($fh, 4);
	if($sig !== 'FZCD') {
		fclose($fh);
		return false;
	}
	$verCh = fread($fh, 1);
	if($verCh === false || strlen($verCh) !== 1 || ord($verCh) !== 1) {
		fclose($fh);
		fractal_zip::fatal_error('Unsupported or corrupt FZCD version.');
	}
	$flCh = fread($fh, 1);
	if($flCh === false || strlen($flCh) !== 1) {
		fclose($fh);
		fractal_zip::fatal_error('Corrupt FZCD (flags).');
	}
	if((ord($flCh) & 1) === 0) {
		fclose($fh);
		return false;
	}
	$this->fractal_string = '';
	$this->array_fractal_zipped_strings_of_files = array();
	fractal_zip::$open_container_streaming_extract_used = true;
	$nFl = $this->read_varint_u32_from_stream($fh, 'FZCD');
	$prevPath = '';
	$entries = array();
	for($fi = 0; $fi < $nFl; $fi++) {
		$prefixLen = $this->read_varint_u32_from_stream($fh, 'FZCD');
		$suffixLen = $this->read_varint_u32_from_stream($fh, 'FZCD');
		if($prefixLen > strlen($prevPath)) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD path prefix.');
		}
		$suf = $suffixLen > 0 ? fread($fh, $suffixLen) : '';
		if(strlen($suf) !== $suffixLen) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD path suffix.');
		}
		$path = substr($prevPath, 0, $prefixLen) . $suf;
		$metaB = fread($fh, 15);
		if(strlen($metaB) !== 15) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD FLAC meta.');
		}
		$um = unpack('Vsr/Cch/Cbps/Cfmt/Pplen', $metaB);
		if(!is_array($um) || !isset($um['plen'])) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD FLAC meta unpack.');
		}
		$entries[] = array(
			'path' => $path,
			'sr' => (int) $um['sr'],
			'ch' => (int) $um['ch'],
			'fmt' => (int) $um['fmt'],
			'pcmLen' => (int) $um['plen'],
		);
		$prevPath = $path;
	}
	$fzcdFlags = ord($flCh);
	$fzcdExBase = fractal_zip::hot_string_digest((string) $bundlePath . "\0fzcdex\0" . (string) spl_object_id($this));
	if(($fzcdFlags & FRACTAL_ZIP_FZCD_FLAG_MERGED_FRACTAL_CHUNKED) !== 0) {
		if($entries === []) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: empty FLAC table.');
		}
		$hb = fread($fh, 12);
		if(strlen($hb) !== 12) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal chunked header.');
		}
		$ur = unpack('Praw', substr($hb, 0, 8));
		$unc = unpack('Vnch', substr($hb, 8, 4));
		if(!is_array($ur) || !is_array($unc) || !isset($ur['raw'], $unc['nch'])) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal chunked header unpack.');
		}
		$rawTotal = (int) $ur['raw'];
		$nChunks = (int) $unc['nch'];
		if($rawTotal < 1 || $nChunks < 1) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal chunked counts.');
		}
		$chunkPre = ($fzcdFlags & FRACTAL_ZIP_FZCD_FLAG_CHUNK_PCM_PRETRANSFORM) !== 0;
		$pcmFmt0 = (int) $entries[0]['fmt'];
		$ch0 = (int) $entries[0]['ch'];
		$pcmPieces = array();
		$sumChunk = 0;
		for($ci = 0; $ci < $nChunks; $ci++) {
			$szb = fread($fh, 16);
			if(strlen($szb) !== 16) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: merged fractal chunk sizes.');
			}
			$ucp = unpack('Pclen', substr($szb, 0, 8));
			$uil = unpack('Pilen', substr($szb, 8, 8));
			if(!is_array($ucp) || !is_array($uil) || !isset($ucp['clen'], $uil['ilen'])) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: merged fractal chunk size unpack.');
			}
			$cLen = (int) $ucp['clen'];
			$iLen = (int) $uil['ilen'];
			$preId = FRACTAL_ZIP_PCM_PRE_NONE;
			if($chunkPre) {
				$pb = fread($fh, 1);
				if($pb === false || strlen($pb) !== 1) {
					fclose($fh);
					fractal_zip::fatal_error('FZCD extract: merged fractal chunk pre id.');
				}
				$preId = ord($pb);
			}
			if($cLen < 1 || $iLen < 1) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: merged fractal chunk lengths.');
			}
			$frTmp = sys_get_temp_dir() . DS . 'fzcdexfr_' . substr(md5($fzcdExBase . "\0ch_inner\0" . (string) $ci), 0, 16) . '.fzcinner';
			$fout = @fopen($frTmp, 'wb');
			if($fout === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: temp merged fractal chunk.');
			}
			$remain = $iLen;
			while($remain > 0) {
				$take = $remain > 1048576 ? 1048576 : $remain;
				$b = fread($fh, $take);
				if($b === false || strlen($b) !== $take) {
					fclose($fout);
					fclose($fh);
					@unlink($frTmp);
					fractal_zip::fatal_error('Corrupt FZCD merged fractal chunk body.');
				}
				fwrite($fout, $b);
				$remain -= $take;
			}
			fclose($fout);
			$frBody = file_get_contents($frTmp);
			@unlink($frTmp);
			if($frBody === false || strlen($frBody) !== $iLen) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: read merged fractal chunk inner.');
			}
			$innerDec = $this->decode_container_payload($frBody);
			if(!is_array($innerDec) || !isset($innerDec[0], $innerDec[1]) || !is_array($innerDec[0])) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: merged fractal chunk inner decode.');
			}
			$innerMap = $innerDec[0];
			$innerFr = (string) $innerDec[1];
			if(!isset($innerMap[FRACTAL_ZIP_FZCD_MERGED_PCM_MEMBER])) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: merged fractal chunk member missing.');
			}
			$pcmPiece = $this->unzip($innerMap[FRACTAL_ZIP_FZCD_MERGED_PCM_MEMBER], $innerFr, true);
			if(strlen($pcmPiece) !== $cLen) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: merged fractal chunk PCM length.');
			}
			if($chunkPre) {
				$pcmInv = fractal_zip_fzcd_merge_pcm_piece_maybe_invert($pcmPiece, $preId, $cLen, $pcmFmt0, $ch0);
				if($pcmInv === null) {
					fclose($fh);
					fractal_zip::fatal_error('FZCD extract: merged fractal chunk PCM pre-transform inverse.');
				}
				$pcmPiece = $pcmInv;
			}
			$pcmPieces[] = $pcmPiece;
			$sumChunk += $cLen;
		}
		$pcmAll = implode('', $pcmPieces);
		if(strlen($pcmAll) !== $rawTotal || $sumChunk !== $rawTotal) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal chunked PCM total.');
		}
		$at = 0;
		foreach($entries as $ti => $e) {
			$pcm = substr($pcmAll, $at, $e['pcmLen']);
			if(strlen($pcm) !== $e['pcmLen']) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM slice.');
			}
			$at += $e['pcmLen'];
			$sfxT = substr(md5($fzcdExBase . "\0ex_trkch\0" . (string) $ti), 0, 16);
			$pcmTmp = sys_get_temp_dir() . DS . 'fzcdex_' . $sfxT . '_p.raw';
			if(file_put_contents($pcmTmp, $pcm) === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: temp PCM.');
			}
			$outFlac = sys_get_temp_dir() . DS . 'fzcdexf_' . $sfxT . '.flac';
			if(!fractal_zip_flac_pac_pcm_file_to_flac_file($pcmTmp, $e['sr'], $e['ch'], $e['fmt'], $outFlac)) {
				@unlink($pcmTmp);
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM→FLAC failed.');
			}
			@unlink($pcmTmp);
			$flacData = file_get_contents($outFlac);
			@unlink($outFlac);
			if($flacData === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: read FLAC.');
			}
			$escaped = $this->escape_literal_for_storage($flacData);
			$unzipped = $this->unzip($escaped);
			$outPath = $this->safe_container_member_output_path($rootDir, $e['path']);
			$this->build_directory_structure_for($outPath);
			file_put_contents($outPath, $unzipped);
			if($debug) {
				fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
			}
			$this->files_counter++;
			$this->array_fractal_zipped_strings_of_files[$e['path']] = '';
		}
	} elseif(($fzcdFlags & FRACTAL_ZIP_FZCD_FLAG_MERGED_FRACTAL_PCM) !== 0) {
		if($entries === []) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: empty FLAC table.');
		}
		$nb = fread($fh, 16);
		if(strlen($nb) !== 16) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal sizes.');
		}
		$ur = unpack('Praw', substr($nb, 0, 8));
		$ufr = unpack('Pfrl', substr($nb, 8, 8));
		if(!is_array($ur) || !is_array($ufr) || !isset($ur['raw'], $ufr['frl'])) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal size unpack.');
		}
		$rawTotal = (int) $ur['raw'];
		$frLen = (int) $ufr['frl'];
		$frTmp = sys_get_temp_dir() . DS . 'fzcdexfr_' . substr(md5($fzcdExBase . "\0ex_mf_inner"), 0, 16) . '.fzcinner';
		$fout = @fopen($frTmp, 'wb');
		if($fout === false) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: temp merged fractal.');
		}
		$remain = $frLen;
		while($remain > 0) {
			$take = $remain > 1048576 ? 1048576 : $remain;
			$b = fread($fh, $take);
			if($b === false || strlen($b) !== $take) {
				fclose($fout);
				fclose($fh);
				@unlink($frTmp);
				fractal_zip::fatal_error('Corrupt FZCD merged fractal body.');
			}
			fwrite($fout, $b);
			$remain -= $take;
		}
		fclose($fout);
		$frBody = file_get_contents($frTmp);
		@unlink($frTmp);
		if($frBody === false || strlen($frBody) !== $frLen) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: read merged fractal inner.');
		}
		$innerDec = $this->decode_container_payload($frBody);
		if(!is_array($innerDec) || !isset($innerDec[0], $innerDec[1]) || !is_array($innerDec[0])) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal inner decode.');
		}
		$innerMap = $innerDec[0];
		$innerFr = (string) $innerDec[1];
		if(!isset($innerMap[FRACTAL_ZIP_FZCD_MERGED_PCM_MEMBER])) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged fractal member missing.');
		}
		$pcmAll = $this->unzip($innerMap[FRACTAL_ZIP_FZCD_MERGED_PCM_MEMBER], $innerFr, true);
		if(strlen($pcmAll) !== $rawTotal) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: PCM length after merged fractal.');
		}
		$at = 0;
		foreach($entries as $ti => $e) {
			$pcm = substr($pcmAll, $at, $e['pcmLen']);
			if(strlen($pcm) !== $e['pcmLen']) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM slice.');
			}
			$at += $e['pcmLen'];
			$sfxM = substr(md5($fzcdExBase . "\0ex_trkmf\0" . (string) $ti), 0, 16);
			$pcmTmp = sys_get_temp_dir() . DS . 'fzcdex_' . $sfxM . '_p.raw';
			if(file_put_contents($pcmTmp, $pcm) === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: temp PCM.');
			}
			$outFlac = sys_get_temp_dir() . DS . 'fzcdexf_' . $sfxM . '.flac';
			if(!fractal_zip_flac_pac_pcm_file_to_flac_file($pcmTmp, $e['sr'], $e['ch'], $e['fmt'], $outFlac)) {
				@unlink($pcmTmp);
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM→FLAC failed.');
			}
			@unlink($pcmTmp);
			$flacData = file_get_contents($outFlac);
			@unlink($outFlac);
			if($flacData === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: read FLAC.');
			}
			$escaped = $this->escape_literal_for_storage($flacData);
			$unzipped = $this->unzip($escaped);
			$outPath = $this->safe_container_member_output_path($rootDir, $e['path']);
			$this->build_directory_structure_for($outPath);
			file_put_contents($outPath, $unzipped);
			if($debug) {
				fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
			}
			$this->files_counter++;
			$this->array_fractal_zipped_strings_of_files[$e['path']] = '';
		}
	} elseif(($fzcdFlags & FRACTAL_ZIP_FZCD_FLAG_MERGED_FLAC) !== 0) {
		if($entries === []) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: empty FLAC table.');
		}
		$nb = fread($fh, 16);
		if(strlen($nb) !== 16) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged FLAC sizes.');
		}
		$ur = unpack('Praw', substr($nb, 0, 8));
		$uf = unpack('Pfll', substr($nb, 8, 8));
		if(!is_array($ur) || !is_array($uf) || !isset($ur['raw'], $uf['fll'])) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged FLAC size unpack.');
		}
		$rawTotal = (int) $ur['raw'];
		$flLen = (int) $uf['fll'];
		$sfxExMfl = substr(md5($fzcdExBase . "\0ex_mfl_in"), 0, 16);
		$flacTmp = sys_get_temp_dir() . DS . 'fzcdexm_' . $sfxExMfl . '.flac';
		$fout = @fopen($flacTmp, 'wb');
		if($fout === false) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: temp merged FLAC.');
		}
		$remain = $flLen;
		while($remain > 0) {
			$take = $remain > 1048576 ? 1048576 : $remain;
			$b = fread($fh, $take);
			if($b === false || strlen($b) !== $take) {
				fclose($fout);
				fclose($fh);
				@unlink($flacTmp);
				fractal_zip::fatal_error('Corrupt FZCD merged FLAC body.');
			}
			fwrite($fout, $b);
			$remain -= $take;
		}
		fclose($fout);
		$pcmAllPath = sys_get_temp_dir() . DS . 'fzcdexpcm_' . substr(md5($fzcdExBase . "\0ex_mpcm_all"), 0, 16) . '.raw';
		if(!fractal_zip_flac_pac_decode_file_to_pcm_path($flacTmp, $entries[0]['fmt'], $pcmAllPath)) {
			@unlink($flacTmp);
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: merged FLAC→PCM.');
		}
		@unlink($flacTmp);
		$pcmAll = file_get_contents($pcmAllPath);
		@unlink($pcmAllPath);
		if($pcmAll === false) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: read merged PCM.');
		}
		if(strlen($pcmAll) !== $rawTotal) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: PCM length after merged FLAC.');
		}
		$at = 0;
		foreach($entries as $ti => $e) {
			$pcm = substr($pcmAll, $at, $e['pcmLen']);
			if(strlen($pcm) !== $e['pcmLen']) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM slice.');
			}
			$at += $e['pcmLen'];
			$sfxTr = substr(md5($fzcdExBase . "\0ex_trkmfl\0" . (string) $ti), 0, 16);
			$pcmTmp = sys_get_temp_dir() . DS . 'fzcdex_' . $sfxTr . '_p.raw';
			if(file_put_contents($pcmTmp, $pcm) === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: temp PCM.');
			}
			$outFlac = sys_get_temp_dir() . DS . 'fzcdexf_' . $sfxTr . '.flac';
			if(!fractal_zip_flac_pac_pcm_file_to_flac_file($pcmTmp, $e['sr'], $e['ch'], $e['fmt'], $outFlac)) {
				@unlink($pcmTmp);
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM→FLAC failed.');
			}
			@unlink($pcmTmp);
			$flacData = file_get_contents($outFlac);
			@unlink($outFlac);
			if($flacData === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: read FLAC.');
			}
			$escaped = $this->escape_literal_for_storage($flacData);
			$unzipped = $this->unzip($escaped);
			$outPath = $this->safe_container_member_output_path($rootDir, $e['path']);
			$this->build_directory_structure_for($outPath);
			file_put_contents($outPath, $unzipped);
			if($debug) {
				fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
			}
			$this->files_counter++;
			$this->array_fractal_zipped_strings_of_files[$e['path']] = '';
		}
	} elseif(($fzcdFlags & FRACTAL_ZIP_FZCD_FLAG_MERGED_GZIP) !== 0) {
		$nb = fread($fh, 16);
		if(strlen($nb) !== 16) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: gzip PCM sizes.');
		}
		$ur = unpack('Praw', substr($nb, 0, 8));
		$ug = unpack('Pgzl', substr($nb, 8, 8));
		if(!is_array($ur) || !is_array($ug) || !isset($ur['raw'], $ug['gzl'])) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: size unpack.');
		}
		$rawTotal = (int) $ur['raw'];
		$gzLen = (int) $ug['gzl'];
		$gzBody = $gzLen > 0 ? fread($fh, $gzLen) : '';
		if(strlen($gzBody) !== $gzLen) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD gzip body.');
		}
		$pcmAll = gzdecode($gzBody);
		if($pcmAll === false) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: gzdecode PCM.');
		}
		if(strlen($pcmAll) !== $rawTotal) {
			fclose($fh);
			fractal_zip::fatal_error('FZCD extract: PCM length mismatch.');
		}
		$at = 0;
		foreach($entries as $ti => $e) {
			$pcm = substr($pcmAll, $at, $e['pcmLen']);
			if(strlen($pcm) !== $e['pcmLen']) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM slice.');
			}
			$at += $e['pcmLen'];
			$sfxGz = substr(md5($fzcdExBase . "\0ex_trkgz\0" . (string) $ti), 0, 16);
			$pcmTmp = sys_get_temp_dir() . DS . 'fzcdex_' . $sfxGz . '_p.raw';
			if(file_put_contents($pcmTmp, $pcm) === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: temp PCM.');
			}
			$outFlac = sys_get_temp_dir() . DS . 'fzcdexf_' . $sfxGz . '.flac';
			if(!fractal_zip_flac_pac_pcm_file_to_flac_file($pcmTmp, $e['sr'], $e['ch'], $e['fmt'], $outFlac)) {
				@unlink($pcmTmp);
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM→FLAC failed.');
			}
			@unlink($pcmTmp);
			$flacData = file_get_contents($outFlac);
			@unlink($outFlac);
			if($flacData === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: read FLAC.');
			}
			$escaped = $this->escape_literal_for_storage($flacData);
			$unzipped = $this->unzip($escaped);
			$outPath = $this->safe_container_member_output_path($rootDir, $e['path']);
			$this->build_directory_structure_for($outPath);
			file_put_contents($outPath, $unzipped);
			if($debug) {
				fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
			}
			$this->files_counter++;
			$this->array_fractal_zipped_strings_of_files[$e['path']] = '';
		}
	} else {
		foreach($entries as $ti => $e) {
			$sfxRaw = substr(md5($fzcdExBase . "\0ex_trkraw\0" . (string) $ti), 0, 16);
			$pcmTmp = sys_get_temp_dir() . DS . 'fzcdex_' . $sfxRaw . '_p.raw';
			$pout = @fopen($pcmTmp, 'wb');
			if($pout === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: temp PCM.');
			}
			$remain = $e['pcmLen'];
			while($remain > 0) {
				$take = $remain > 1048576 ? 1048576 : $remain;
				$b = fread($fh, $take);
				if($b === false || strlen($b) !== $take) {
					fclose($pout);
					fclose($fh);
					@unlink($pcmTmp);
					fractal_zip::fatal_error('Corrupt FZCD PCM.');
				}
				fwrite($pout, $b);
				$remain -= $take;
			}
			fclose($pout);
			$outFlac = sys_get_temp_dir() . DS . 'fzcdexf_' . $sfxRaw . '.flac';
			if(!fractal_zip_flac_pac_pcm_file_to_flac_file($pcmTmp, $e['sr'], $e['ch'], $e['fmt'], $outFlac)) {
				@unlink($pcmTmp);
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: PCM→FLAC failed.');
			}
			@unlink($pcmTmp);
			$flacData = file_get_contents($outFlac);
			@unlink($outFlac);
			if($flacData === false) {
				fclose($fh);
				fractal_zip::fatal_error('FZCD extract: read FLAC.');
			}
			$escaped = $this->escape_literal_for_storage($flacData);
			$unzipped = $this->unzip($escaped);
			$outPath = $this->safe_container_member_output_path($rootDir, $e['path']);
			$this->build_directory_structure_for($outPath);
			file_put_contents($outPath, $unzipped);
			if($debug) {
				fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
			}
			$this->files_counter++;
			$this->array_fractal_zipped_strings_of_files[$e['path']] = '';
		}
	}
	$nOth = $this->read_varint_u32_from_stream($fh, 'FZCD');
	$prevPath = '';
	for($oi = 0; $oi < $nOth; $oi++) {
		$prefixLen = $this->read_varint_u32_from_stream($fh, 'FZCD');
		$suffixLen = $this->read_varint_u32_from_stream($fh, 'FZCD');
		if($prefixLen > strlen($prevPath)) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD other path prefix.');
		}
		$pathSuffix = $suffixLen > 0 ? fread($fh, $suffixLen) : '';
		if(strlen($pathSuffix) !== $suffixLen) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD other path suffix.');
		}
		$path = substr($prevPath, 0, $prefixLen) . $pathSuffix;
		$modeCh = fread($fh, 1);
		if($modeCh === false || strlen($modeCh) !== 1) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD other mode.');
		}
		$mode = ord($modeCh);
		$dataLen = $this->read_varint_u32_from_stream($fh, 'FZCD');
		$rawStored = $dataLen > 0 ? fread($fh, $dataLen) : '';
		if(strlen($rawStored) !== $dataLen) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZCD other data.');
		}
		$raw = $this->decode_bundle_literal_member($mode, $rawStored);
		$escaped = $this->escape_literal_for_storage($raw);
		$unzipped = $this->unzip($escaped);
		$outPath = $this->safe_container_member_output_path($rootDir, $path);
		$this->build_directory_structure_for($outPath);
		file_put_contents($outPath, $unzipped);
		if($debug) {
			fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
		}
		$this->files_counter++;
		$this->array_fractal_zipped_strings_of_files[$path] = '';
		$prevPath = $path;
	}
	$at = ftell($fh);
	fseek($fh, 0, SEEK_END);
	$sz = ftell($fh);
	if($at !== $sz) {
		fclose($fh);
		fractal_zip::fatal_error('Corrupt FZCD (trailing bytes).');
	}
	fclose($fh);
	if($debug) {
		$micro_time_taken = microtime(true) - $this->initial_micro_time;
		fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
	}
	return true;
}

function stream_literal_bundle_fzb4_to_file($dir, $outPath, $rawLiteralsOnly = false, $skipLiteralPreprocess = false) {
	$root = realpath($dir);
	if($root === false) {
		$root = $dir;
	}
	$prefixLen = strlen($root);
	$paths = array();
	// Iterate $root (realpath), not the possibly-relative $dir: otherwise
	// substr(pathname, strlen(realpath)+1) mangles names with "[" (e.g. ROM "[!].zip").
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		$path = $fileInfo->getPathname();
		$rel = substr($path, $prefixLen + 1);
		$rel = strtr((string) $rel, '\\', '/');
		if(strlen($rel) > 65535) {
			return false;
		}
		$paths[] = $rel;
	}
	sort($paths, SORT_STRING);
	if(!$rawLiteralsOnly && $this->write_fzcd_bundle_if_applicable($root, $paths, $outPath)) {
		return true;
	}
	$fh = fopen($outPath, 'wb');
	if($fh === false) {
		return false;
	}
	if(fwrite($fh, 'FZB4') === false) {
		fclose($fh);
		return false;
	}
	if(!$skipLiteralPreprocess) {
		fractal_zip_ensure_literal_pac_stack_loaded();
	}
	$prevPath = '';
	$videoPac = false;
	if(!$rawLiteralsOnly || !$skipLiteralPreprocess) {
		fractal_zip_ensure_video_lossless_pac_loaded();
		$videoPac = function_exists('fractal_zip_video_lossless_pac_enabled')
			&& fractal_zip_video_lossless_pac_enabled()
			&& fractal_zip_video_lossless_pac_tools_ok();
	}
	foreach($paths as $path) {
		$path = (string) $path;
		$full = $root . DS . str_replace('/', DS, $path);
		$rawBytes = file_get_contents($full);
		if($rawBytes === false) {
			$rawBytes = '';
		}
		// Opt-in lossless-video PAC (Lagarith/HuffYUV/UT/FFV1): semantic rewrap to FZVL when smaller.
		if($videoPac && $rawBytes !== '') {
			$low = strtolower($path);
			if(str_ends_with($low, '.avi') || str_ends_with($low, '.mkv') || str_ends_with($low, '.mov')) {
				$shrunk = fractal_zip_video_lossless_pac_try_shrink_member($full, $rawBytes);
				if(is_array($shrunk) && isset($shrunk['bytes']) && is_string($shrunk['bytes']) && $shrunk['bytes'] !== '') {
					$rawBytes = $shrunk['bytes'];
				}
			}
		}
		if($rawLiteralsOnly) {
			$mode = 0;
			// Lifestyle FZB+outer lane: skip peel/tokenize preprocess (18 s on
			// already-compressed multi-precomp packs); mode-0 raw is enough.
			$storeBytes = $skipLiteralPreprocess
				? $rawBytes
				: fractal_zip_literal_pac_preprocess_literal_for_bundle($path, $rawBytes);
		} else {
			list($mode, $storeBytes) = $this->choose_best_literal_bundle_transform($rawBytes, $path);
		}
		$commonPrefixLen = 0;
		$maxPrefix = min(strlen($prevPath), strlen($path), 65535);
		while($commonPrefixLen < $maxPrefix && $prevPath[$commonPrefixLen] === $path[$commonPrefixLen]) {
			$commonPrefixLen++;
		}
		$pathSuffix = (string) substr($path, $commonPrefixLen);
		if(strlen($pathSuffix) > 65535) {
			fclose($fh);
			return false;
		}
		$chunk = $this->encode_varint_u32($commonPrefixLen) . $this->encode_varint_u32(strlen($pathSuffix)) . $pathSuffix
			. chr($mode) . $this->encode_varint_u32(strlen($storeBytes)) . $storeBytes;
		if(fwrite($fh, $chunk) === false) {
			fclose($fh);
			return false;
		}
		$prevPath = $path;
	}
	fclose($fh);
	return true;
}

/**
 * Raw deflate level for large-folder gzip-fast .fz (streaming FZB4 inner). FRACTAL_ZIP_FOLDER_GZIP_FAST_DEFLATE_LEVEL 1–9 (default 6: faster roundtrip on huge trees; 9 = smallest).
 */
public static function folder_gzip_fast_deflate_level(): int {
	$e = getenv('FRACTAL_ZIP_FOLDER_GZIP_FAST_DEFLATE_LEVEL');
	if($e === false || trim((string) $e) === '' || !is_numeric($e)) {
		// Lifestyle huge trees: level 1 keeps monster corpora under the 90s wall.
		if(fractal_zip::lifestyle_speed_profile_enabled()) {
			return 1;
		}
		return 6;
	}
	return max(1, min(9, (int) $e));
}

/**
 * When > 0 and streamed FZB4 inner is ≤ this size, gzip-fast uses adaptive_compress (+ raw contest) instead of deflate-only.
 * 0 = always deflate-only. FRACTAL_ZIP_FOLDER_GZIP_FAST_ADAPTIVE_OUTER_MAX_BYTES (default 64 MiB).
 */
public static function folder_gzip_fast_adaptive_outer_max_bytes(): int {
	$e = getenv('FRACTAL_ZIP_FOLDER_GZIP_FAST_ADAPTIVE_OUTER_MAX_BYTES');
	if($e === false || trim((string) $e) === '') {
		return 64 * 1024 * 1024;
	}
	return max(0, (int) $e);
}

/**
 * fread chunk size for streaming deflate/inflate (gzip-fast folder path). FRACTAL_ZIP_STREAM_CHUNK_BYTES (default 1048576; min 65536, max 67108864).
 */
public static function stream_chunk_bytes(): int {
	$e = getenv('FRACTAL_ZIP_STREAM_CHUNK_BYTES');
	if($e === false || trim((string) $e) === '' || !is_numeric($e)) {
		return 1048576;
	}
	return max(65536, min(67108864, (int) $e));
}

/** Stream raw deflate (ZLIB_ENCODING_RAW) from file to path — level 1–9 or default 9 when $level null (non–folder-fast callers). */
function gzip_deflate_file_to_path($innerPath, $outPath, $level = null) {
	$lev = $level !== null ? max(1, min(9, (int) $level)) : 9;
	if(!function_exists('deflate_init')) {
		$data = file_get_contents($innerPath);
		if($data === false) {
			return false;
		}
		$c = gzdeflate($data, $lev);
		if($c === false) {
			return false;
		}
		return file_put_contents($outPath, $c) !== false;
	}
	$in = fopen($innerPath, 'rb');
	if($in === false) {
		return false;
	}
	$out = fopen($outPath, 'wb');
	if($out === false) {
		fclose($in);
		return false;
	}
	$ctx = deflate_init(ZLIB_ENCODING_RAW, array('level' => $lev));
	if($ctx === false) {
		fclose($in);
		fclose($out);
		return false;
	}
	$readChunk = fractal_zip::stream_chunk_bytes();
	while(true) {
		$chunk = fread($in, $readChunk);
		if($chunk === false) {
			fclose($in);
			fclose($out);
			return false;
		}
		$last = feof($in);
		$fl = $last ? ZLIB_FINISH : ZLIB_NO_FLUSH;
		$enc = deflate_add($ctx, $chunk, $fl);
		if($enc === false) {
			fclose($in);
			fclose($out);
			return false;
		}
		if($enc !== '' && fwrite($out, $enc) === false) {
			fclose($in);
			fclose($out);
			return false;
		}
		if($last) {
			break;
		}
	}
	fclose($in);
	fclose($out);
	return true;
}

/**
 * Same pipeline as benchmarks min-ext xz: {@code tar cf - . | xz -9 -c} in a temp dir (Unix).
 *
 * @param array<string,string>|null $rawFilesByPathOrNull
 * @return string|null raw .xz bytes or null
 */
function try_build_folder_xz_native_tar_xz_blob($sourceDir, $rawFilesByPathOrNull = null) {
	if(PHP_OS_FAMILY === 'Windows') {
		return null;
	}
	$xzExe = fractal_zip::xz_executable();
	if($xzExe === null || !fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_XZ')) {
		return null;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return null;
	}
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	// Soft min-ext uses xz -9. Under lifestyle on small trees, use -9e only
	// (extreme): -9 never wins the sole wire on these packs (123/182/194/197)
	// and the dual pass was pure wall.
	$sumHint = 0;
	if(is_array($rawFilesByPathOrNull)) {
		foreach($rawFilesByPathOrNull as $b) {
			$sumHint += strlen((string) $b);
		}
	} else {
		$sumHint = $this->folder_raw_total_bytes($rp);
	}
	$suffixes = array('9');
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& $sumHint > 0
		&& $sumHint <= 2 * 1024 * 1024) {
		$suffixes = array('9e');
	}
	$bestBlob = null;
	$cwd = getcwd();
	// Prefer in-place tar|xz from the live tree (same bytes as min-ext; avoid copy drift).
	foreach($suffixes as $suf) {
		$tryOut = sys_get_temp_dir() . DS . 'fzxzbench_' . md5($rp . "\0xz" . $suf) . '.xz';
		if(is_file($tryOut)) {
			@unlink($tryOut);
		}
		$compressorArgv = fractal_zip::shell_quote_arg_cached($xzExe)
			. ' -' . $suf
			. fractal_zip::bench_xz_thread_shell_fragment_for_exec()
			. ' -c';
		$ret = -1;
		if(@chdir($rp)) {
			$cmd = 'tar cf - --exclude=\'.fz\' --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' . 2>/dev/null | '
				. $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($tryOut) . ' 2>/dev/null';
			exec($cmd, $xo, $ret);
		}
		if($cwd !== false) {
			chdir($cwd);
		}
		if($ret === 0 && is_file($tryOut)) {
			$r = @file_get_contents($tryOut);
			if($r !== false && $r !== ''
				&& ($bestBlob === null || strlen($r) < strlen($bestBlob))) {
				$bestBlob = $r;
			}
		}
		if(is_file($tryOut)) {
			@unlink($tryOut);
		}
	}
	if($bestBlob !== null) {
		return $bestBlob;
	}
	// Fallback: materialize/copy into a sandbox when in-place tar fails.
	$box = sys_get_temp_dir() . DS . 'fzxzbench_' . substr(md5((string) $rp . "\0fzxz_native"), 0, 16);
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	mkdir($box, 0755, true);
	$useMemMap = $rawFilesByPathOrNull !== null && is_array($rawFilesByPathOrNull)
		&& $this->folder_structure_was_made
		&& $this->folder_structure_scan_root === $rp;
	if($useMemMap) {
		$this->materialize_raw_files_map_to_directory_for_native_arc_box($rawFilesByPathOrNull, $box);
	} else {
		$this->recursive_copy_directory_for_native_arc_box($rp, $box);
	}
	foreach($suffixes as $suf) {
		$tryOut = sys_get_temp_dir() . DS . 'fzxzbench_' . md5($box . "\0xz" . $suf) . '.xz';
		if(is_file($tryOut)) {
			@unlink($tryOut);
		}
		$compressorArgv = fractal_zip::shell_quote_arg_cached($xzExe)
			. ' -' . $suf
			. fractal_zip::bench_xz_thread_shell_fragment_for_exec()
			. ' -c';
		$ret = -1;
		if(@chdir($box)) {
			$cmd = 'tar cf - . 2>/dev/null | ' . $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($tryOut) . ' 2>/dev/null';
			exec($cmd, $xo, $ret);
		}
		if($cwd !== false) {
			chdir($cwd);
		}
		if($ret === 0 && is_file($tryOut)) {
			$r = @file_get_contents($tryOut);
			if($r !== false && $r !== ''
				&& ($bestBlob === null || strlen($r) < strlen($bestBlob))) {
				$bestBlob = $r;
			}
		}
		if(is_file($tryOut)) {
			@unlink($tryOut);
		}
	}
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}

	return $bestBlob;
}

public static function folder_native_xz_compare_enabled(): bool {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	return $cached = getenv('FRACTAL_ZIP_FOLDER_NATIVE_XZ_COMPARE') !== '0';
}

/**
 * Max merged raw bytes for {@see maybe_folder_xz_native_smaller_than_fzc}. Unset ⇒ 256 MiB; {@code 0} = no cap.
 */
public static function folder_native_xz_compare_max_raw_bytes(): int {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FOLDER_NATIVE_XZ_MAX_RAW_BYTES');
	if($e !== false && trim((string) $e) !== '') {
		$v = (int) trim((string) $e);
		return $cached = max(0, min(2147483647, $v));
	}
	return $cached = 256 * 1024 * 1024;
}

/**
 * Effective Arc cap: baseline tie can lift the default 100 MiB cap for large heterogeneous folders.
 */
public static function folder_native_freearc_compare_max_raw_bytes_effective(int $sumRawBytes): int {
	fractal_zip_ensure_folder_per_member_best_loaded();
	return fractal_zip_folder_native_compare_cap_effective(
		fractal_zip::folder_native_freearc_compare_max_raw_bytes(),
		$sumRawBytes
	);
}

/**
 * @param array<string,string>|null $rawFilesByPath
 * @return string|null
 */
function maybe_folder_xz_native_smaller_than_fzc($dir, $fzcBody, $sumRawBytes, $rawFilesByPath = null) {
	$fzcBody = (string) $fzcBody;
	if($fzcBody === '' || !fractal_zip::folder_native_xz_compare_enabled()) {
		return null;
	}
	if(fractal_zip::outer_force_codec_is_gzip() || fractal_zip::outer_force_codec_is_zpaq()) {
		return null;
	}
	fractal_zip_ensure_folder_per_member_best_loaded();
	$cap = fractal_zip_folder_native_compare_cap_effective(
		fractal_zip::folder_native_xz_compare_max_raw_bytes(),
		(int) $sumRawBytes
	);
	if($cap > 0 && (int) $sumRawBytes > $cap) {
		return null;
	}
	$native = $this->try_build_folder_xz_native_tar_xz_blob($dir, $rawFilesByPath);
	if($native === null || $native === '') {
		return null;
	}
	$wrapped = "FZLX\x01" . $native;
	$currentCodec = is_string(fractal_zip::$last_written_container_codec) ? fractal_zip::$last_written_container_codec : 'store';
	if(!fractal_zip::outer_candidate_beats_current('xz', strlen($wrapped), $currentCodec, strlen($fzcBody))) {
		return null;
	}
	fractal_zip::$last_outer_codec = 'xz';
	fractal_zip::$last_written_container_codec = 'xz';

	return $wrapped;
}

/**
 * Run unified-stream folder encode in-process; return wire body or null.
 *
 * @param array<string,string> $rawFilesByPath
 * @return array{0: string, 1: string}|null [fzcBody, pickTag]
 */
function encode_folder_unified_stream_wire_in_memory($rootDir, array $rawFilesByPath) {
	$this->zip_folder_root_for_members = (string) $rootDir;
	$innerRunGrammarVariants = $this->collect_fractal_inner_run_grammar_variants_for_folder($rawFilesByPath);
	if($this->fractal_inner_run_grammar_variants_are_decisive($innerRunGrammarVariants, $rawFilesByPath)) {
		$variants = $innerRunGrammarVariants;
	} else {
		$innerPeelerVariants = $this->collect_fractal_inner_peeler_variants_for_folder($rawFilesByPath);
		$variants = fractal_zip::folder_literal_variants_for_unified_stream(
			$this->collect_literal_bundle_inner_variants_for_folder($rootDir, $rawFilesByPath)
		);
		if($innerPeelerVariants !== array()) {
			$variants = array_merge($innerPeelerVariants, $variants);
		}
		if($innerRunGrammarVariants !== array()) {
			$variants = array_merge($innerRunGrammarVariants, $variants);
		}
	}
	if($variants === array()) {
		$this->zip_folder_root_for_members = '';
		return null;
	}
	list($bestContents, $pick) = $this->choose_smallest_adaptive_literal_inner_or_raw_escaped($variants, $rawFilesByPath);
	$fzcBody = $this->append_restore_trailer_inside_outer_payload($bestContents, $this->fractal_member_gzip_disk_restore);
	$nativePick = null;
	if(!$this->fractal_inner_skip_native_compare_for_verified_tiny_payload((string) $pick, $fzcBody, $rawFilesByPath)) {
		list($fzcBody, $nativePick) = $this->folder_wire_after_literal_outer_try_native_folder_archives(
			$rootDir,
			$fzcBody,
			$rawFilesByPath,
			'encode_unified_stream_wire'
		);
	}
	if($nativePick !== null) {
		$pick = $nativePick;
	}
	$this->zip_folder_root_for_members = '';
	return array($fzcBody, (string) $pick);
}

/**
 * Isolated single-file folder encode (same path as Mahoney per-file bench).
 */
function encode_isolated_single_file_fzc_wire(string $memberPath, string $rawBytes) {
	$memberPath = str_replace('\\', '/', (string) $memberPath);
	if($memberPath === '' || strpos($memberPath, "\0") !== false
		|| strpos($memberPath, '..') !== false || $memberPath[0] === '/') {
		return null;
	}
	// Flat basename leaf: jpeg-cm / FZpq / FZCJ store this name; FZHM extract expects
	// caseDir/basename. Nested logical paths (classic peel lumps) must not leak into the
	// isolated wire — each call has its own tmpRoot so basename collisions are fine.
	$leaf = basename($memberPath);
	if($leaf === '' || $leaf === '.' || $leaf === '..') {
		return null;
	}
	$tmpRoot = sys_get_temp_dir() . DS . 'fzpmb1_' . getmypid() . '_' . bin2hex(random_bytes(4));
	if(!@mkdir($tmpRoot, 0700, true)) {
		return null;
	}
	$memberFile = $tmpRoot . DS . $leaf;
	if(@file_put_contents($memberFile, (string) $rawBytes) === false) {
		$this->recursive_remove_directory($tmpRoot);
		return null;
	}
	$trial = new fractal_zip(
		$this->segment_length,
		$this->multipass,
		false,
		null,
		false
	);
	$trial->multipass_max_additional_passes = $this->multipass_max_additional_passes;
	$oldPm = getenv('FRACTAL_ZIP_FOLDER_PER_MEMBER_BEST');
	putenv('FRACTAL_ZIP_FOLDER_PER_MEMBER_BEST=0');
	ob_start();
	try {
		$trial->zip_folder($tmpRoot, false);
	} catch(Throwable $e) {
		ob_end_clean();
		if($oldPm === false) {
			putenv('FRACTAL_ZIP_FOLDER_PER_MEMBER_BEST');
		} else {
			putenv('FRACTAL_ZIP_FOLDER_PER_MEMBER_BEST=' . (string) $oldPm);
		}
		$this->recursive_remove_directory($tmpRoot);
		return null;
	}
	ob_end_clean();
	if($oldPm === false) {
		putenv('FRACTAL_ZIP_FOLDER_PER_MEMBER_BEST');
	} else {
		putenv('FRACTAL_ZIP_FOLDER_PER_MEMBER_BEST=' . (string) $oldPm);
	}
	$fzcPath = $tmpRoot . $this->fractal_zip_container_file_extension;
	$wire = is_file($fzcPath) ? @file_get_contents($fzcPath) : false;
	$this->recursive_remove_directory($tmpRoot);
	if($wire === false || $wire === '') {
		return null;
	}
	return $wire;
}

/**
 * Per-member best wires → FZHM store outer; ratchet vs monolithic unified + native xz/arc when smaller.
 *
 * @return bool false on failure
 */
function write_folder_heterogeneous_bundle($dir, ?array $logicalBundle = null) {
	fractal_zip_ensure_folder_per_member_best_loaded();
	fractal_zip_ensure_folder_logical_bundle_loaded();
	fractal_zip::$used_folder_per_member_best = false;
	$resolvedRoot = realpath($dir);
	$this->zip_folder_root_for_members = $resolvedRoot !== false ? $resolvedRoot : $dir;
	$rawFilesByPath = $this->collect_raw_files_for_bundle($dir);
	if($rawFilesByPath === array()) {
		$this->zip_folder_root_for_members = '';
		return false;
	}
	if($logicalBundle === null) {
		$logicalBundle = fractal_zip_resolve_folder_logical_bundle($rawFilesByPath);
	}
	$membersForEncode = $logicalBundle['members'] ?? array();
	if($membersForEncode === array()) {
		$this->zip_folder_root_for_members = '';
		return false;
	}
	if(function_exists('fractal_zip_folder_jpeg_fzhm_prepare_members')) {
		$jpegShare = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_folder_jpeg_marker_share.php';
		if(is_readable($jpegShare)) {
			require_once $jpegShare;
		}
		$membersForEncode = fractal_zip_folder_jpeg_fzhm_prepare_members(
			$membersForEncode,
			$logicalBundle['members'] ?? array()
		);
	}
	$restoreSpecs = $logicalBundle['restore'] ?? array();
	$hasClassicRestore = false;
	if(is_array($restoreSpecs)) {
		$classicKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC')
			? (int) FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC
			: 3;
		foreach($restoreSpecs as $spec) {
			if(is_array($spec) && (int) ($spec['kind'] ?? -1) === $classicKind) {
				$hasClassicRestore = true;
				break;
			}
		}
	}
	// Skip encoding VERBATIM orphan peels (container is restored from FZHR blob alone).
	if(!$hasClassicRestore && is_array($restoreSpecs)
		&& function_exists('fractal_zip_folder_wires_without_verbatim_orphans')) {
		$membersForEncode = fractal_zip_folder_wires_without_verbatim_orphans(
			$membersForEncode,
			$restoreSpecs
		);
	}
	$ordered = $membersForEncode;
	ksort($ordered, SORT_STRING);
	$wires = array();
	foreach($ordered as $path => $bytes) {
		$wire = $this->encode_isolated_single_file_fzc_wire((string) $path, (string) $bytes);
		if($wire === null || $wire === '') {
			$this->zip_folder_root_for_members = '';
			return false;
		}
		$wires[(string) $path] = $wire;
	}
	$restoreForTournament = is_array($restoreSpecs)
		? fractal_zip_folder_restore_specs_for_tournament($restoreSpecs)
		: array();
	$fzhmBody = fractal_zip_encode_fzhm_v1_with_restore($wires, $restoreForTournament);
	$fzhmBodyFull = fractal_zip_encode_fzhm_v1_with_restore(
		$wires,
		is_array($restoreSpecs) ? $restoreSpecs : array()
	);
	// Honest size: include FZHR payloads (verbatim/patch); do not pick on stripped tournament body.
	$bestBody = $fzhmBodyFull;
	$bestPick = 'fzhm_per_member';
	$sumRaw = 0;
	foreach($rawFilesByPath as $rb) {
		$sumRaw += strlen((string) $rb);
	}
	$rootForNative = $this->zip_folder_root_for_members;
	$preferFzhm = function_exists('fractal_zip_folder_prefer_fzhm_enabled')
		&& fractal_zip_folder_prefer_fzhm_enabled();
	if($hasClassicRestore) {
		// Classic peel FZHM includes CLASSIC rebuild trailer (no verbatim tax).
		$bestBody = $fzhmBodyFull;
		$bestPick = 'fzhm_per_member';
		// Peeled unified (cross-lump dedupe) + FZCL wrapper often beats isolated FZHM.
		$classicPeel = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_classic_peel.php';
		if(is_readable($classicPeel)) {
			require_once $classicPeel;
		}
		if(function_exists('fractal_zip_classic_encode_fzcl_v1')) {
			$tmpPeel = sys_get_temp_dir() . DS . 'fzcl_' . getmypid() . '_' . bin2hex(random_bytes(3));
			if(@mkdir($tmpPeel, 0700, true)) {
				$flat = array();
				$okMat = true;
				foreach($ordered as $path => $bytes) {
					$rel = str_replace('\\', '/', (string) $path);
					$dest = $tmpPeel . DS . str_replace('/', DS, $rel);
					$dirn = dirname($dest);
					if($dirn !== $tmpPeel && !is_dir($dirn) && !@mkdir($dirn, 0700, true)) {
						$okMat = false;
						break;
					}
					if(@file_put_contents($dest, (string) $bytes) === false) {
						$okMat = false;
						break;
					}
					$flat[$rel] = (string) $bytes;
				}
				// FZCL v3: embed FZHR as a normal member so outer codec compresses it.
				$sidecarName = function_exists('fractal_zip_classic_fzcl_restore_sidecar_name')
					? fractal_zip_classic_fzcl_restore_sidecar_name()
					: '.fzcl_restore';
				$fzhrSide = '';
				if($okMat && function_exists('fractal_zip_encode_fzhr_v1')) {
					$fzhrSide = fractal_zip_encode_fzhr_v1(
						is_array($restoreSpecs) ? $restoreSpecs : array()
					);
				}
				if($okMat && $fzhrSide !== '') {
					$sidePath = $tmpPeel . DS . $sidecarName;
					if(@file_put_contents($sidePath, $fzhrSide) === false) {
						$okMat = false;
					} else {
						$flat[$sidecarName] = $fzhrSide;
					}
				}
				if($okMat && $flat !== array()) {
					$peeled = $this->encode_folder_unified_stream_wire_in_memory($tmpPeel, $flat);
					if(is_array($peeled) && isset($peeled[0]) && is_string($peeled[0]) && $peeled[0] !== '') {
						$fzcl = '';
						if(function_exists('fractal_zip_classic_encode_fzcl_v3') && $fzhrSide !== '') {
							$fzcl = fractal_zip_classic_encode_fzcl_v3((string) $peeled[0]);
						}
						if($fzcl === '') {
							$fzcl = fractal_zip_classic_encode_fzcl_v1(
								(string) $peeled[0],
								is_array($restoreSpecs) ? $restoreSpecs : array()
							);
						}
						// Prefer FZCL on ≤ as well as < so peel restore wins ties vs FZHM/opaque.
						if($fzcl !== '' && strlen($fzcl) <= strlen($bestBody)) {
							$bestBody = $fzcl;
							$bestPick = 'fzcl_classic_peeled';
						}
					}
				}
				$this->recursive_remove_directory($tmpPeel);
			}
		}
	}
	if(!$preferFzhm && fractal_zip::folder_unified_stream_enabled()) {
		$mono = $this->encode_folder_unified_stream_wire_in_memory($rootForNative, $rawFilesByPath);
		if($mono !== null) {
			list($monoBody,) = $mono;
			if(strlen((string) $monoBody) < strlen($bestBody)) {
				$bestBody = (string) $monoBody;
				$bestPick = 'unified_stream';
			}
		}
		// Debug peel tournament (FRACTAL_ZIP_DEBUG_PEEL_TOURNAMENT=1).
		$dbgPeel = getenv('FRACTAL_ZIP_DEBUG_PEEL_TOURNAMENT');
		if($dbgPeel !== false && trim((string) $dbgPeel) !== '' && trim((string) $dbgPeel) !== '0') {
			$monoLen = ($mono !== null && isset($monoBody)) ? strlen((string) $monoBody) : -1;
			fwrite(STDERR, '[peel-tournament] bestPick=' . $bestPick
				. ' best=' . strlen($bestBody)
				. ' mono=' . $monoLen
				. ' preferFzhm=' . ($preferFzhm ? '1' : '0')
				. ' root=' . (string) $rootForNative
				. ' rawN=' . count($rawFilesByPath)
				. "\n");
		}
	}
	// Always ratchet FZHM/unified vs native folder archives (zpaq/7z/…) when baseline
	// tie is on — previously this lived only inside the unified-stream branch, so
	// FZHM-only paths (Calgary) could keep a losing heterogeneous wire.
	if(!$preferFzhm) {
		list($ratchetBody, $ratchetPick) = $this->folder_wire_baseline_tie_ratchet(
			$rootForNative,
			$bestBody,
			$rawFilesByPath,
			$sumRaw
		);
		$bestBody = $ratchetBody;
		if($ratchetPick !== null) {
			$bestPick = $ratchetPick;
		}
	}
	if($bestPick === 'fzhm_per_member' && !$hasClassicRestore) {
		// Keep FZHM store body when native/unified did not win (no-op if already FZHM).
		$bestBody = $fzhmBodyFull;
	}
	$fzcPath = $dir . $this->fractal_zip_container_file_extension;
	if(@file_put_contents($fzcPath, $bestBody) === false) {
		$this->zip_folder_root_for_members = '';
		return false;
	}
	fractal_zip::$used_folder_per_member_best = ($bestPick === 'fzhm_per_member' || $bestPick === 'fzcl_classic_peeled');
	fractal_zip::$used_folder_unified_stream = ($bestPick === 'unified_stream' || str_contains((string) $bestPick, 'native'));
	fractal_zip::$last_outer_codec = ($bestPick === 'fzhm_per_member' || $bestPick === 'fzcl_classic_peeled')
		? 'store'
		: (is_string(fractal_zip::$last_outer_codec) ? fractal_zip::$last_outer_codec : 'store');
	fractal_zip::$last_written_container_codec = fractal_zip::$last_outer_codec;
	fractal_zip::$folder_zip_wire_best_outer_codec = fractal_zip::$last_outer_codec;
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('per-member best path: pick=' . htmlspecialchars($bestPick) . ' wire=' . strlen($bestBody) . ' B.<br>');
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

/** @deprecated alias — use write_folder_heterogeneous_bundle */
function write_folder_per_member_best_container($dir) {
	return $this->write_folder_heterogeneous_bundle($dir);
}

/**
 * When baseline tie is enabled, try native folder archives (arc / 7z / brotli / xz / zpaq) if smaller than $fzcBody.
 *
 * @param array<string,string> $rawFilesByPath
 * @return array{0: string, 1: string|null}
 */
function folder_wire_baseline_tie_ratchet($rootDir, $fzcBody, array $rawFilesByPath, int $sumRawBytes) {
	fractal_zip_ensure_folder_per_member_best_loaded();
	$fzcBody = (string) $fzcBody;
	if(!fractal_zip_folder_baseline_tie_enabled()) {
		return array($fzcBody, null);
	}
	return $this->folder_wire_after_literal_outer_try_native_folder_archives($rootDir, $fzcBody, $rawFilesByPath, 'fzhm_baseline_tie');
}

/**
 * Write .fz as raw FZB4 (no outer compression). Fast for huge directories when ratio is secondary.
 * @return bool false on I/O failure
 */
function write_folder_literal_fzb4_store_only_container($dir) {
	fractal_zip::$used_folder_gzip_fast = false;
	fractal_zip::$used_folder_literal_fzb4_store = false;
	$resolvedRoot = realpath($dir);
	$this->zip_folder_root_for_members = $resolvedRoot !== false ? $resolvedRoot : $dir;
	$fzcPath = $dir . $this->fractal_zip_container_file_extension;
	if(!$this->stream_literal_bundle_fzb4_to_file($dir, $fzcPath, true)) {
		$this->zip_folder_root_for_members = '';
		return false;
	}
	fractal_zip::$last_outer_codec = 'store';
	fractal_zip::$last_written_container_codec = 'store';
	fractal_zip::$folder_zip_wire_best_outer_codec = 'store';
	fractal_zip::$used_folder_literal_fzb4_store = true;
	$micro_time_taken = microtime(true) - $this->initial_micro_time;
	fractal_zip::html_trace_print('literal FZB4 store-only .fz (no outer compression).<br>');
	fractal_zip::html_trace_print('Time taken zipping folder: ' . $micro_time_taken . ' seconds.<br>');
	$this->zip_folder_root_for_members = '';
	return true;
}

function zip_folder_fzc_output_path($memberDir) {
	$base = is_string($this->zip_folder_fzc_write_dir) && $this->zip_folder_fzc_write_dir !== ''
		? $this->zip_folder_fzc_write_dir
		: (string) $memberDir;
	return $base . $this->fractal_zip_container_file_extension;
}

function zip_folder($dir, $debug = false) {
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_begin();
	fractal_zip_encode_pipeline::pipeline_wall_timer_zip_folder_begin();
	fractal_zip_encode_pipeline::bootstrap_cli_parallel_defaults_if_cli();
	// Clear cross-call poison before any lifestyle gate (monster / native). A prior
	// zip_folder that set runtime_force_disable_lifestyle and exited without the
	// mid-function finally would otherwise skip tar|zstd lakes (207/209) and
	// mega trees (206) for the rest of the process — solid 7z / store fallbacks.
	self::$runtime_force_disable_lifestyle_speed_profile = false;
	if(function_exists('fractal_zip_inner_include_loaded')) {
		$fj = getenv('FZ_INNER_FRONTIER_JOBS');
		if($fj !== false && trim((string) $fj) !== '' && (int) trim((string) $fj) > 1) {
			fractal_zip_inner_include_loaded($this);
		}
	}
	$this->zip_folder_fzc_write_dir = (string) $dir;
	$this->enwik_zip_ctx = null;
	$enwikPrep = fractal_zip_enwik_try_prepare_virtual_folder((string) $dir);
	// Binary / URL-list / small-source CM before general-text: bare FZpq beats the
	// phda9_xml wrapper on fields.c / xargs.1 / grammar.lsp, and opaque binaries
	// never belong on the text-inner path.
	if ($enwikPrep === null && function_exists('fractal_zip_binary_cm_try_write')
		&& fractal_zip_binary_cm_try_write($this, (string) $dir)) {
		fractal_zip::html_trace_print('binary-cm: FZpq native passthrough.<br>');
		return;
	}
	// Single-file JPEG: lepton/brunsli bit-exact deep recompression (~20% typical).
	if ($enwikPrep === null && function_exists('fractal_zip_jpeg_cm_try_write')
		&& fractal_zip_jpeg_cm_try_write($this, (string) $dir)) {
		fractal_zip::html_trace_print('jpeg-cm: lepton FZpq passthrough.<br>');
		return;
	}
	// Lifestyle monsters (≥128 MiB): tar|zstd before general-text. GT must not scan
	// huge HTML forests (isisunveiled) — and must not run after a prior case leaked
	// runtime_force_disable_lifestyle (static) which would skip this path entirely.
	if($enwikPrep === null && $this->write_lifestyle_monster_zstd_fast_container($dir)) {
		return;
	}
	if ($enwikPrep === null) {
		// Lifestyle: skip general-text/phda9 except mid/large single CSV/plain
		// (≥768 KiB: 53/151/167/174) where phda9+gzip soles soft. Nested forests
		// (61) must not pay GT prepare — it was ~5 s before native Arc.
		$skipGt = false;
		if(fractal_zip::lifestyle_speed_profile_enabled()) {
			$gtN = 0;
			$gtRaw = 0;
			$gtNested = false;
			$gtAllCsvPlain = true;
			try {
				$gtIt = new RecursiveIteratorIterator(
					new RecursiveDirectoryIterator((string) $dir, FilesystemIterator::SKIP_DOTS)
				);
				foreach($gtIt as $gtFi) {
					if(!$gtFi->isFile()) {
						continue;
					}
					$gtN++;
					$gtRaw += (int) $gtFi->getSize();
					$rel = str_replace('\\', '/', (string) $gtIt->getSubPathname());
					if(strpos($rel, '/') !== false) {
						$gtNested = true;
					}
					if(!preg_match('/\\.(csv|txt|tsv|log)$/i', $rel)) {
						$gtAllCsvPlain = false;
					}
					if($gtN > 3) {
						break;
					}
				}
			} catch(Throwable $e) {
				$gtN = 0;
			}
			$skipGt = true;
			// ≥1 MiB single CSV/plain (167/174): lifestyle FreeArc then mcm FZpq
			// soles soft in ~2 s. GT phda9+virtual folder was ~12–14 s then
			// lifestyle_maybe_upgrade replaced the wire with the same mcm tip —
			// pure wall. 768 KiB–1 MiB (53/151) already skip GT for Arc/mcm.
			// 8–12 MiB prose (dickens): do NOT enable GT — phda9/mcm ~21 s then
