		$dir = (string) $enwikPrep['virtualDir'];
		$prepLabel = !empty($enwikPrep['generalTextInner']) ? 'general text-inner' : 'enwik entry sort';
		fractal_zip::html_trace_print($prepLabel . ': virtual multi-member folder (' . count($enwikPrep['memberRelPaths']) . ' members).<br>');
	}
