		if(is_array($webRefRaw)) {
			$webRefRawSaved = (int)($webRefRaw['saved'] ?? 0);
			if(!empty($webRefRaw['entries']) && is_array($webRefRaw['entries'])) {
				if(!is_array($this->fzwr_entries)) {
					$this->fzwr_entries = array();
				}
				$this->fzwr_entries = array_merge($this->fzwr_entries, $webRefRaw['entries']);
			}
		}
	}
