		$webRefFolder = fractal_zip_web_ref_apply_before_folder_zip($this, $dir);
		if(is_array($webRefFolder)) {
			$webRefRawSaved = (int)($webRefFolder['saved'] ?? 0);
			if(!empty($webRefFolder['entries']) && is_array($webRefFolder['entries'])) {
				if(!is_array($this->fzwr_entries)) {
					$this->fzwr_entries = array();
				}
