	$savedForceEnableMultidiff = self::$runtime_force_enable_substring_multidiff;
	$savedForceDisableReciprocal = self::$runtime_force_disable_substring_reciprocal;
	$savedForceEnableReciprocal = self::$runtime_force_enable_substring_reciprocal;
	$savedForceEnableMultidiffRecursiveOnly = self::$runtime_force_enable_substring_multidiff_recursive_only;
	$savedForceMultidiffMinBytes = self::$runtime_force_substring_multidiff_min_bytes;
	$savedForceDisableLifestyle = self::$runtime_force_disable_lifestyle_speed_profile;
