		$skipHeterogeneousForReciprocal = false;
	}
	if(!$skipHeterogeneousForReciprocal && fractal_zip_heterogeneous_folder_encode_enabled($logicalBundle)) {
		fractal_zip_encode_pipeline::html_trace_checkpoint(
			fractal_zip_encode_pipeline::PHASE_STREAM_BUILD,
			'heterogeneous: per logical member isolated encode → FZHM (+FZHR restore when peeled)'
		);
		if($this->write_folder_heterogeneous_bundle($dir, $logicalBundle)) {
			return;
		}
		fractal_zip::warning_once('heterogeneous folder encode failed; falling back to unified stream');
	} elseif($skipHeterogeneousForReciprocal) {
		$stageLog('skip_heterogeneous_per_member_best.reciprocal', microtime(true));
	}
	// Unified stream: phase 1–2 literal inners (FZCD when applicable, else FZB* from encode_literal_bundle_payload); phase 3 smallest vs raw.
	if(!$fsTinyDenseBundleOnly && (fractal_zip::folder_unified_stream_enabled() || fractal_zip::substring_multidiff_recursive_only_enabled())) {
		fractal_zip_encode_pipeline::html_trace_checkpoint(
			fractal_zip_encode_pipeline::PHASE_STREAM_BUILD,
			'unified stream: literal variants + byte stream'
		);
		$resolvedRoot = realpath($dir);
		$this->zip_folder_root_for_members = $resolvedRoot !== false ? $resolvedRoot : $dir;
		$rootForCollect = $resolvedRoot !== false ? $resolvedRoot : $dir;
		$rawFilesByPath = $this->collect_raw_files_for_bundle($dir);
		$stageLog('collect_raw_files_for_bundle.unified', $stageStart);
		$stageStart = microtime(true);
		// Lifestyle tiny multifile: raw FZC5+gzip already matches historical micros when the
		// gzip wire is tiny (test_files2=122). Also short-circuit when raw gzip is clearly the
		// winner vs raw size (test_files74=1594) — skip the transform tournament that loses.
		$memberN = count($rawFilesByPath);
		if(fractal_zip::lifestyle_speed_profile_enabled()
			&& $rawForBundleBytes > 0
			&& $rawForBundleBytes <= 8192
			&& $memberN >= 8
			&& $memberN <= 32) {
			$rawEscapedProbe = array();
			foreach($rawFilesByPath as $p => $b) {
				$rawEscapedProbe[(string) $p] = $this->escape_literal_for_storage((string) $b);
			}
			$rawInnerProbe = $this->encode_container_payload($rawEscapedProbe, '');
			$gzProbe = gzdeflate($rawInnerProbe, 9);
			if($gzProbe !== false) {
				$gzLen = strlen($gzProbe);
				$avgMember = (int) floor($rawForBundleBytes / max(1, $memberN));
				// Tight raw wins (test_files2) or midsize dir-shells where raw gzip is the
				// historical winner (test_files74). Skip test_files75-class (larger avg members
				// where FZB still beats raw by tens of bytes).
				$takeRawGz = ($gzLen <= 256)
					|| ($gzLen <= 2048 && $gzLen <= $rawForBundleBytes && $avgMember <= 400);
				if($takeRawGz) {
					$fzcPath = $this->zip_folder_fzc_output_path($dir);
					if(file_put_contents($fzcPath, $gzProbe) !== false) {
						fractal_zip::$last_outer_codec = 'gzip';
						fractal_zip::$last_written_container_codec = 'gzip';
						fractal_zip::$last_zpaq_method = null;
						fractal_zip::$used_folder_unified_stream = true;
						fractal_zip::$folder_zip_wire_best_outer_codec = 'gzip';
						$this->zip_folder_root_for_members = '';
						return;
					}
				}
			}
		}
		$profileReciprocalFastPath = $this->folder_reciprocal_inner_fast_path_enabled($rawFilesByPath);
		$fsDenseReciprocalFastPath = fractal_zip::fs_profile_should_use_dense_multifile_reciprocal_fast_path(
			$rawFilesByPath,
			$rawForBundleBytes,
			$this->zip_folder_member_count
		) || fractal_zip::fs_profile_should_use_small_multifile_reciprocal_fast_path(
			$rawFilesByPath,
			$rawForBundleBytes,
			$this->zip_folder_member_count
		);
		$skipRunGrammar = fractal_zip::substring_multidiff_recursive_only_skips_run_grammar(
			$rawFilesByPath,
			$rawForBundleBytes,
			$this->zip_folder_member_count
		);
		$integratedMultidiffOnly = $skipRunGrammar || $profileReciprocalFastPath || $fsDenseReciprocalFastPath;
		$preferReciprocalInnerFastPath = $integratedMultidiffOnly || $profileReciprocalFastPath || $fsDenseReciprocalFastPath;
		if(!$skipRunGrammar) {
			// Showing_off-class: keep run-grammar even when reciprocal fast-path is on.
			$integratedMultidiffOnly = false;
			$preferReciprocalInnerFastPath = false;
		}
		$stageLog('folder_reciprocal_inner_fast_path_enabled.unified', $stageStart);
		$stageStart = microtime(true);
		$innerRunGrammarVariants = $integratedMultidiffOnly ? array() : $this->collect_fractal_inner_run_grammar_variants_for_folder($rawFilesByPath);
		$stageLog('collect_run_grammar_variants.unified', $stageStart);
		$stageStart = microtime(true);
		if($preferReciprocalInnerFastPath) {
			$variants = fractal_zip::folder_literal_variants_for_unified_stream(
				$this->collect_literal_bundle_inner_variants_for_folder($rootForCollect, $rawFilesByPath)
			);
			$stageLog('collect_literal_variants.unified.fast_path', $stageStart);
		} elseif($this->fractal_inner_run_grammar_variants_are_decisive($innerRunGrammarVariants, $rawFilesByPath)) {
