				putenv('FRACTAL_ZIP_TIME_BUDGET_MS=' . $savedTimeBudgetMs);
			}
			if($savedDisableBrotliLgwin === false) {
				putenv('FRACTAL_ZIP_DISABLE_BROTLI_FZB_Q11_LGWIN16');
			} else {
				putenv('FRACTAL_ZIP_DISABLE_BROTLI_FZB_Q11_LGWIN16=' . $savedDisableBrotliLgwin);
			}
		}
		fractal_zip_encode_pipeline::pipeline_wall_timer_zip_folder_end();
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_end();
	}
}

function should_use_bundle_only_for_folder($dir) {
	$maxFilesEnv = getenv('FRACTAL_ZIP_BUNDLE_ONLY_MIN_FILES');
	$minFilesForBundleOnly = ($maxFilesEnv === false || trim((string)$maxFilesEnv) === '') ? 256 : max(16, (int)$maxFilesEnv);
	$singleFileMinBytesEnv = getenv('FRACTAL_ZIP_BUNDLE_ONLY_SINGLE_FILE_MIN_BYTES');
	// Default 5 MiB (FRACTAL_ZIP_BUNDLE_ONLY_SINGLE_FILE_MIN_BYTES): smaller single-file trees use full fractal_zip; larger ones use literal bundle only.
	$singleFileMinBytes = ($singleFileMinBytesEnv === false || trim((string)$singleFileMinBytesEnv) === '') ? 5242880 : max(0, (int)$singleFileMinBytesEnv);
	$fileCount = 0;
	$totalBytes = 0;
	$largestFileBytes = 0;
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		$fileCount++;
		$sz = $fileInfo->getSize();
		if($sz !== false && $sz > 0) {
			$sz = (int)$sz;
			$totalBytes += $sz;
			if($sz > $largestFileBytes) {
				$largestFileBytes = $sz;
			}
		}
		if($fileCount >= $minFilesForBundleOnly) {
			return true;
		}
	}
	if($fileCount === 1 && $largestFileBytes >= $singleFileMinBytes) {
		return true;
	}
	return false;
}

/**
 * Lowercase file extension from a bundle-relative path (POSIX basename rules; empty when none).
 */
public static function folder_bundle_rel_path_extension(string $rel): string {
	$rel = strtr($rel, '\\', '/');
	$slash = strrpos($rel, '/');
	$b = $slash === false ? $rel : substr($rel, $slash + 1);
	if($b === '') {
		return '';
	}
	$p = strrpos($b, '.');
	if($p === false || $p >= strlen($b) - 1) {
		return '';
	}

	return strtolower(substr($b, $p + 1));
}

/**
 * Add one raw member to running folder-bundle census counters (used by collect_raw_files_for_bundle and {@see folder_bundle_census_from_raw_map}).
 *
 * @param array<string,int> $extBytes
 */
public static function folder_bundle_census_accumulate_raw_file(string $rel, string $raw, array &$extBytes, int &$textish, int &$totalBytes, ?int $byteLenOverride = null): void {
	$s = $byteLenOverride !== null ? max(0, (int) $byteLenOverride) : strlen($raw);
	fractal_zip_ensure_content_format_policy_loaded();
	$totalBytes += $s;
	$peek = strlen($raw) > 65536 ? substr($raw, 0, 65536) : $raw;
	$bucket = fractal_zip_content_format_policy_content_profile_bucket($rel, $peek);
	if(!isset($extBytes[$bucket])) {
		$extBytes[$bucket] = 0;
	}
	$extBytes[$bucket] += $s;
	if(fractal_zip_content_format_policy_member_is_textish($rel, $peek, $s)) {
		$textish += $s;
	} elseif($bucket === 'unknown' && fractal_zip::folder_bundle_rel_path_extension($rel) === ''
		&& fractal_zip::folder_census_extless_bytes_count_as_textish()) {
		$textish += $s;
	}
}

/** Extensionless members (e.g. Mahoney Silesia basenames) count toward textish mass for census gates (default on). */
public static function folder_census_extless_bytes_count_as_textish(): bool {
	$v = getenv('FRACTAL_ZIP_FOLDER_CENSUS_EXTLESS_AS_TEXTISH');
	if($v === false || trim((string) $v) === '') {
		return true;
	}
	$v = strtolower(trim((string) $v));
	return !($v === '0' || $v === 'off' || $v === 'false' || $v === 'no');
}

/**
 * Build the census return value from per-extension byte totals (top 12 by mass; full arsort only when ≤12 distinct extensions).
 *
 * @param array<string,int> $extBytes
 * @return array{files:int,bytes:int,textish_bytes:int,textish_ratio:float,top_ext_bytes:array<string,int>}
 */
public static function folder_bundle_census_pack(array $extBytes, int $totalBytes, int $textish, int $files): array {
	$uniqExt = count($extBytes);
	if($uniqExt <= 12) {
		$top = $extBytes;
		arsort($top, SORT_NUMERIC);
	} else {
		$work = $extBytes;
		$top = array();
		for($ti = 0; $ti < 12 && $work !== array(); $ti++) {
			$bestK = null;
			$bestV = -1;
			foreach($work as $k => $v) {
				if($v > $bestV) {
					$bestV = $v;
					$bestK = $k;
				}
			}
			if($bestK === null) {
				break;
			}
			$top[$bestK] = $bestV;
			unset($work[$bestK]);
		}
		arsort($top, SORT_NUMERIC);
	}
	$ratio = $totalBytes > 0 ? ($textish / $totalBytes) : 0.0;

	return array(
		'files' => $files,
		'bytes' => $totalBytes,
		'textish_bytes' => $textish,
		'textish_ratio' => $ratio,
		'top_ext_bytes' => $top,
	);
}

/**
 * Census over an in-memory raw map: file count, total bytes, web-text-ish bytes by extension bucket,
 * and the top 12 extensions by raw byte mass (for large-corpus scheduling / diagnostics only; does not affect wire bytes).
 * Per-file work is strlen + a lightweight relative-path extension parse; top-12 avoids full arsort when there are many distinct extensions.
 *
 * @param array<string,string> $out relative_path => raw_bytes
 * @return array{files:int,bytes:int,textish_bytes:int,textish_ratio:float,top_ext_bytes:array<string,int>}
 */
public static function folder_bundle_census_from_raw_map(array $out): array {
	$extBytes = array();
	$textish = 0;
	$totalBytes = 0;
	foreach($out as $rel => $bytes) {
		fractal_zip::folder_bundle_census_accumulate_raw_file((string) $rel, (string) $bytes, $extBytes, $textish, $totalBytes);
	}

	return fractal_zip::folder_bundle_census_pack($extBytes, $totalBytes, $textish, count($out));
}

/**
 * Directory census without reading file bodies (filesize + extension only).
 *
 * @return array{files:int,bytes:int,textish_bytes:int,textish_ratio:float,top_ext_bytes:array<string,int>}
 */
public static function folder_bundle_census_from_dir(string $dir): array {
	$extBytes = array();
	$textish = 0;
	$totalBytes = 0;
	$files = 0;
	$root = realpath($dir);
	if($root === false || !is_dir($root)) {
		return fractal_zip::folder_bundle_census_pack($extBytes, 0, 0, 0);
	}
	$prefix = rtrim(str_replace('\\', '/', $root), '/') . '/';
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		$full = str_replace('\\', '/', $fileInfo->getPathname());
		if(strncmp($full, $prefix, strlen($prefix)) !== 0) {
			continue;
		}
		$rel = substr($full, strlen($prefix));
		if(fractal_zip::path_is_inplace_fractal_container_leaf($rel)) {
			continue;
		}
		$sz = (int) $fileInfo->getSize();
		if($sz <= 0) {
			continue;
		}
		$files++;
		$peek = '';
		if($sz > 0) {
			$peek = (string) @file_get_contents($full, false, null, 0, min(65536, $sz));
		}
		fractal_zip::folder_bundle_census_accumulate_raw_file($rel, $peek, $extBytes, $textish, $totalBytes, $sz);
	}

	return fractal_zip::folder_bundle_census_pack($extBytes, $totalBytes, $textish, $files);
}

/** Auto large-folder gzip-fast: apply textish census gate (default on). */
public static function folder_census_gzip_fast_auto_gate_enabled(): bool {
	$v = getenv('FRACTAL_ZIP_FOLDER_CENSUS_GZIP_FAST_AUTO');
	if($v === false || trim((string) $v) === '') {
		return true;
	}
	$v = strtolower(trim((string) $v));
	return !($v === '0' || $v === 'off' || $v === 'false' || $v === 'no');
}

/** When census `textish_ratio` is at or above this, auto gzip-fast is skipped (default 0.35). */
public static function folder_census_gzip_fast_max_textish_ratio(): float {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FOLDER_CENSUS_GZIP_FAST_MAX_TEXTISH');
	if($e === false || trim((string) $e) === '') {
		return $cached = 0.35;
	}
	return $cached = max(0.0, min(1.0, (float) trim((string) $e)));
}

/** Apply census gate even when {@code FRACTAL_ZIP_FOLDER_GZIP_FAST=1} is explicitly set. */
public static function folder_census_gzip_fast_gate_forced_path(): bool {
	$v = getenv('FRACTAL_ZIP_FOLDER_CENSUS_GZIP_FAST_GATE_FORCE');
	if($v === false || trim((string) $v) === '') {
		return false;
	}
	$v = strtolower(trim((string) $v));
	return $v === '1' || $v === 'on' || $v === 'true' || $v === 'yes';
}

/** {@code FRACTAL_ZIP_SPEED=1}: skip run-grammar collection below this textish ratio (default 0.12). */
public static function folder_low_textish_skip_run_grammar_enabled(): bool {
	if(getenv('FRACTAL_ZIP_FOLDER_LOW_TEXTISH_SKIP_RUN_GRAMMAR') !== '1') {
		return false;
	}
	return fractal_zip::speed_profile_enabled();
}

public static function folder_census_low_textish_threshold(): float {
	static $cached = null;
	if($cached !== null) {
		return $cached;
	}
	$e = getenv('FRACTAL_ZIP_FOLDER_LOW_TEXTISH_THRESHOLD');
	if($e === false || trim((string) $e) === '') {
		return $cached = 0.12;
	}
	return $cached = max(0.0, min(1.0, (float) trim((string) $e)));
}

/**
 * Optional schedule-only tweak from {@see fractal_zip::folder_bundle_census_from_raw_map}: nudge `cost_hint` so
 * `schedule_inner_variants_for_literal_outer` tries **literal** lane candidates slightly earlier on text-heavy trees
 * and **fractal_inner** slightly later (within lane / length ties only). {@code FRACTAL_ZIP_FOLDER_BUNDLE_SCHED_COST_BIAS=1}
 * enables; default off. Does not skip codec trials.
 *
 * @param list<array<string,mixed>> $innerVariants
 * @param array<string,mixed>|null $census
 * @return list<array<string,mixed>>
 */
public static function folder_bundle_apply_schedule_cost_bias_from_census(array $innerVariants, $census): array {
	if(getenv('FRACTAL_ZIP_FOLDER_BUNDLE_SCHED_COST_BIAS') !== '1' || !is_array($census) || !isset($census['textish_ratio'])) {
		return $innerVariants;
	}
	$ratio = (float) $census['textish_ratio'];
	$deltaLiteral = 0;
	$deltaFractalInner = 0;
	if($ratio >= 0.82) {
		$deltaLiteral = -4;
		$deltaFractalInner = 6;
	} elseif($ratio >= 0.65) {
		$deltaLiteral = -2;
		$deltaFractalInner = 3;
	} elseif($ratio >= 0.48) {
		$deltaLiteral = -1;
		$deltaFractalInner = 1;
	} else {
		return $innerVariants;
	}
	$out = array();
	foreach($innerVariants as $v) {
		if(!is_array($v)) {
			$out[] = $v;
			continue;
		}
		$lane = isset($v['lane']) ? (string) $v['lane'] : '';
		$ch = isset($v['cost_hint']) ? (int) $v['cost_hint'] : 0;
		if($lane === 'fractal_inner') {
			$v['cost_hint'] = max(0, $ch + $deltaFractalInner);
		} elseif($lane === 'literal') {
			$v['cost_hint'] = max(0, $ch + $deltaLiteral);
		}
		$out[] = $v;
	}

	return $out;
}

/**
 * Clears in-memory folder bundle scan cache (one zip_folder() invocation may call collect more than once for the same root).
 */
function reset_folder_bundle_structure_scan_state() {
	$this->folder_structure_was_made = false;
	$this->folder_structure_scan_root = '';
	$this->folder_structure_raw_files_by_path = null;
	$this->folder_bundle_census = null;
	$this->folder_metastruct_census = null;
	$this->literal_bundle_fzms_wrap_out = null;
}

/**
 * @return array<string,string> relative_path => raw_bytes
 */
function collect_raw_files_for_bundle($dir) {
	$iterRoot = realpath($dir);
	if($iterRoot === false) {
		$iterRoot = $dir;
	}
	if($this->folder_structure_was_made && $this->folder_structure_scan_root === $iterRoot && is_array($this->folder_structure_raw_files_by_path)) {
		return $this->folder_structure_raw_files_by_path;
	}
	$out = array();
	$censusExtBytes = array();
	$censusTextish = 0;
	$censusTotalBytes = 0;
	$rootN = rtrim(str_replace('\\', '/', $iterRoot), '/');
	$prefix = $rootN . '/';
	$prefixLen = strlen($prefix);
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($iterRoot, FilesystemIterator::SKIP_DOTS));
	foreach($it as $fileInfo) {
		if(!$fileInfo->isFile()) {
			continue;
		}
		$pathName = $fileInfo->getPathname();
		$pathReal = $fileInfo->getRealPath();
		$pathN = strtr($pathReal !== false ? $pathReal : $pathName, '\\', '/');
		if(!str_starts_with($pathN, $prefix)) {
			fractal_zip::warning_once('collect_raw_files_for_bundle: skipping path outside bundle root.');
			continue;
		}
		$rel = substr($pathN, $prefixLen);
		// Skip leftover in-tree containers (exact `.fz` / `.fzc` / `.fractalzip` basenames).
		if(fractal_zip::path_is_inplace_fractal_container_leaf($rel)) {
			continue;
		}
		$bytes = file_get_contents($pathName);
		if($bytes === false) {
			$bytes = '';
		}
		$raw = (string) $bytes;
		fractal_zip::folder_bundle_census_accumulate_raw_file($rel, $raw, $censusExtBytes, $censusTextish, $censusTotalBytes);
		$out[$rel] = $raw;
	}
	ksort($out, SORT_STRING);
	$this->folder_structure_was_made = true;
	$this->folder_structure_scan_root = $iterRoot;
	$this->folder_structure_raw_files_by_path = $out;
	$this->folder_bundle_census = fractal_zip::folder_bundle_census_pack($censusExtBytes, $censusTotalBytes, $censusTextish, count($out));
	if(getenv('FRACTAL_ZIP_FOLDER_BUNDLE_CENSUS_STDERR') === '1') {
		$js = bench_json_encode_try($this->folder_bundle_census, false);
		if(is_string($js)) {
			$err = @fopen('php://stderr', 'wb');
			if(is_resource($err)) {
				fwrite($err, '[fz folder bundle census] ' . $js . "\n");
				fclose($err);
			}
		}
	}

	return $out;
}

function fractal_inner_run_grammar_candidates_enabled() {
	$env = getenv('FRACTAL_ZIP_INNER_RUN_GRAMMAR');
	if($env === false || trim((string)$env) === '') {
		return true;
	}
	$v = strtolower(trim((string)$env));
	return !($v === '0' || $v === 'false' || $v === 'off' || $v === 'no');
}

function fractal_inner_run_grammar_max_raw_bytes() {
	$env = getenv('FRACTAL_ZIP_INNER_RUN_GRAMMAR_MAX_RAW_BYTES');
	if($env === false || trim((string)$env) === '') {
		return 4194304;
	}
	$n = (int)$env;
	return max(0, $n);
}

function fractal_inner_operator_candidate_max_raw_bytes() {
	$env = getenv('FRACTAL_ZIP_INNER_OPERATOR_MAX_RAW_BYTES');
	if($env === false || trim((string)$env) === '') {
		return 512;
	}
	$n = (int)$env;
	return max(0, $n);
}

function fractal_inner_peeler_candidates_enabled(): bool {
	$env = getenv('FRACTAL_ZIP_INNER_PEELER_CANDIDATES');
	if($env === false || trim((string)$env) === '') {
		return true;
	}
	$v = strtolower(trim((string)$env));
	return !($v === '0' || $v === 'false' || $v === 'off' || $v === 'no');
}

function fractal_inner_peeler_max_total_raw_bytes(): int {
	$env = getenv('FRACTAL_ZIP_INNER_PEELER_MAX_TOTAL_RAW_BYTES');
	if($env === false || trim((string)$env) === '') {
		return 4194304;
	}
	return max(0, (int)$env);
}

function fractal_inner_skip_native_compare_for_verified_tiny_payload(string $pick, string $fzcBody, array $rawFilesByPath): bool {
	$env = getenv('FRACTAL_ZIP_INNER_SKIP_NATIVE_COMPARE_TINY_PAYLOAD');
	if($env === false) {
		$env = getenv('FRACTAL_ZIP_INNER_SKIP_NATIVE_COMPARE_SINGLE_MEMBER');
	}
	if($env !== false) {
		$v = strtolower(trim((string)$env));
		if($v === '0' || $v === 'false' || $v === 'off' || $v === 'no') {
			return false;
		}
	}
	if(!str_starts_with($pick, 'inner_verified_ops') || count($rawFilesByPath) > 2) {
		return false;
	}
	$rawTotal = 0;
	$payloadMembers = 0;
	foreach($rawFilesByPath as $bytes) {
		$n = strlen((string)$bytes);
		$rawTotal += $n;
		if($n > 4096) {
			$payloadMembers++;
		}
	}
	return $payloadMembers === 1 && $rawTotal >= 65536 && strlen($fzcBody) <= 512;
}

/**
 * True when a verified run-grammar inner is so small relative to raw bytes that it is worth
 * skipping older candidate builders and moving directly to the raw-vs-inner outer chooser.
 *
 * @param list<array{inner:string,tag:string}> $variants
 * @param array<string,string> $rawFilesByPath
 */
function fractal_inner_run_grammar_variants_are_decisive(array $variants, array $rawFilesByPath): bool {
	if($variants === array()) {
		return false;
	}
	$rawTotal = 0;
	foreach($rawFilesByPath as $bytes) {
		$rawTotal += strlen((string)$bytes);
	}
	if($rawTotal < 4096) {
		return false;
	}
	$bestInner = PHP_INT_MAX;
	foreach($variants as $v) {
		if(isset($v['inner'])) {
			$bestInner = min($bestInner, strlen((string)$v['inner']));
		}
	}
	if($bestInner === PHP_INT_MAX) {
		return false;
	}
	return $bestInner <= max(512, (int)floor($rawTotal / 64));
}

function fractal_inner_run_grammar_include_loaded() {
	return fractal_zip_inner_include_loaded($this);
}

/**
 * Shift substring marker offsets when a member-local fractal_ref is appended to a shared folder-level reference tape.
 */
function fractal_inner_shift_substring_offsets(string $equiv, int $delta): string {
	if($delta === 0 || $equiv === '') {
		return $equiv;
	}
	list($Lq, $Mq, $Rq) = fractal_zip_marker_rx_quoted_delimiters();
	$pattern = '/' . $Lq . '([0-9]+)' . $Mq . '([0-9]+)' . $Mq . '*([0-9]*)\**([0-9]*)s*([0-9\.]*)' . $Rq . '/is';
	return preg_replace_callback($pattern, function(array $m) use ($delta): string {
		$off = (int)$m[1] + $delta;
		$out = $this->left_fractal_zip_marker . (string)$off . $this->mid_fractal_zip_marker . $m[2];
		if(isset($m[3]) && $m[3] !== '') {
			$out .= $this->mid_fractal_zip_marker . $m[3];
		}
		if(isset($m[4]) && $m[4] !== '') {
			$out .= '*' . $m[4];
		}
		if(isset($m[5]) && $m[5] !== '') {
			$out .= 's' . $m[5];
		}
		return $out . $this->right_fractal_zip_marker;
	}, $equiv) ?? $equiv;
}

/**
 * @return list<array<string,mixed>>
 */
function fractal_inner_run_grammar_rows_for_raw(string $raw) {
	return fractal_zip_inner_run_grammar_rows($this, $raw, $this->fractal_inner_run_grammar_max_raw_bytes());
}

/**
 * @return list<array<string,mixed>>
 */
function fractal_inner_candidate_rows_for_raw(string $raw) {
	return fractal_zip_inner_candidate_rows(
		$this,
		$raw,
		$this->fractal_inner_run_grammar_max_raw_bytes(),
		$this->fractal_inner_operator_candidate_max_raw_bytes()
	);
}

/**
 * Add generic, verified inner process candidates for run grammars and decoder-safe operators.
 *
 * These candidates are encoded as normal FZC containers and then compete in the existing
 * outer wire-size tournament. No fixture names or recipe hints are used; each member
 * candidate is derived from raw bytes and verified through the production decoder.
 *
 * @param array<string,string> $rawFilesByPath
 * @return list<array{inner:string,tag:string}>
 */
function collect_fractal_inner_run_grammar_variants_for_folder($rawFilesByPath) {
	if(!$this->fractal_inner_run_grammar_candidates_enabled() || !is_array($rawFilesByPath) || $rawFilesByPath === array()) {
		return array();
	}
	if(fractal_zip::folder_low_textish_skip_run_grammar_enabled()
		&& is_array($this->folder_bundle_census)
		&& isset($this->folder_bundle_census['textish_ratio'])
		&& (float) $this->folder_bundle_census['textish_ratio'] < fractal_zip::folder_census_low_textish_threshold()) {
		return array();
	}
	return fractal_zip_inner_candidates_for_folder(
		$this,
		$rawFilesByPath,
		$this->fractal_inner_run_grammar_max_raw_bytes(),
		$this->fractal_inner_operator_candidate_max_raw_bytes()
	);
}

function fractal_inner_add_peeler_view(&$views, &$seen, $source, $view, $disk, $restore = null) {
	$source = (string)$source;
	$view = (string)$view;
	$disk = (string)$disk;
	if($source === '' || $view === '' || $view === $disk || strlen($view) < 64) {
		return;
	}
	$maxTotal = $this->fractal_inner_peeler_max_total_raw_bytes();
	if($maxTotal > 0 && strlen($view) > $maxTotal) {
		return;
	}
	if(!$this->fractal_inner_peeler_view_proxy_promising($source, $view, $disk)) {
		return;
	}
	$key = $source . "\0" . sha1($view, true);
	if(isset($seen[$key])) {
		return;
	}
	$seen[$key] = true;
	$views[] = array('source' => $source, 'bytes' => $view, 'restore' => $restore === null ? $disk : $restore);
}

function fractal_inner_peeler_view_proxy_promising($source, $view, $disk): bool {
	$source = (string)$source;
	if($source === 'deep_unwrap' || $source === 'zlib_wrapper' || $source === 'raw_deflate_wrapper') {
		return true;
	}
	$view = (string)$view;
	$disk = (string)$disk;
	if(strlen($view) < strlen($disk)) {
		return true;
	}
	if(strlen($disk) > 2097152 || strlen($view) > 2097152) {
		return false;
	}
	$dg = gzdeflate($disk, 1);
	$vg = gzdeflate($view, 1);
	if($dg === false || $vg === false) {
		return false;
	}
	return strlen($vg) + 16 < (int)floor(strlen($dg) * 0.92);
}

function fractal_inner_chunk_payload_view($bytes) {
	$bytes = (string)$bytes;
	$n = strlen($bytes);
	if($n < 24) {
		return null;
	}
	if(substr($bytes, 0, 4) === 'RIFF' && $n >= 12) {
		$decl = unpack('Vlen', substr($bytes, 4, 4));
		if(is_array($decl) && isset($decl['len']) && (int)$decl['len'] + 8 <= $n) {
			$pos = 12;
			$hdrs = substr($bytes, 0, 12);
			$payloads = '';
			$count = 0;
			while($pos + 8 <= $n) {
				$type = substr($bytes, $pos, 4);
				$szU = unpack('Vlen', substr($bytes, $pos + 4, 4));
				if(!is_array($szU) || !isset($szU['len'])) {
					return null;
				}
				$sz = (int)$szU['len'];
				$payloadPos = $pos + 8;
				if($sz < 0 || $payloadPos + $sz > $n) {
					return null;
				}
				$hdrs .= $type . substr($bytes, $pos + 4, 4);
				$payloads .= substr($bytes, $payloadPos, $sz);
				$pos = $payloadPos + $sz + ($sz & 1);
				$count++;
			}
			if($count >= 2 && $pos <= $n) {
				return $payloads . $hdrs;
			}
		}
	}
	$pos = 0;
	$hdrs = '';
	$payloads = '';
	$count = 0;
	while($pos + 8 <= $n && $count < 4096) {
		$type = substr($bytes, $pos, 4);
		if(preg_match('/^[A-Za-z0-9_ .-]{4}$/', $type) !== 1) {
			break;
		}
		$be = unpack('Nlen', substr($bytes, $pos + 4, 4));
		if(!is_array($be) || !isset($be['len'])) {
			break;
		}
		$sz = (int)$be['len'];
		if($sz < 0 || $sz > $n || $pos + 8 + $sz > $n) {
			break;
		}
		$hdrs .= $type . substr($bytes, $pos + 4, 4);
		$payloads .= substr($bytes, $pos + 8, $sz);
		$pos += 8 + $sz;
		$count++;
	}
	if($count >= 3 && $pos === $n) {
		return $payloads . $hdrs;
	}
	return null;
}

function fractal_inner_record_delimiter_view($bytes) {
	$typed = $this->fractal_inner_record_delimiter_typed_view($bytes);
	return $typed === null ? null : (string)$typed[0];
}

function fractal_inner_record_delimiter_typed_view($bytes) {
	$bytes = (string)$bytes;
	$n = strlen($bytes);
	if($n < 128 || $n > 1048576) {
		return null;
	}
	$delim = null;
	foreach(array("\n", "\r\n", ",", "\t", "|") as $d) {
		if(substr_count($bytes, $d) >= 8) {
			$delim = $d;
			break;
		}
	}
	if($delim === null) {
		return null;
	}
	$rows = explode($delim, $bytes);
	if(count($rows) < 8 || count($rows) > 4096) {
		return null;
	}
	$max = 0;
	foreach($rows as $row) {
		$max = max($max, strlen($row));
	}
	if($max <= 0 || $max > 4096) {
		return null;
	}
	$lengths = array();
	$allMax = true;
	foreach($rows as $row) {
		$l = strlen($row);
		$lengths[] = $l;
		if($l !== $max) {
			$allMax = false;
		}
	}
	$cols = array_fill(0, $max, '');
	foreach($rows as $row) {
		$l = strlen($row);
		for($i = 0; $i < $max; $i++) {
			$cols[$i] .= ($i < $l) ? $row[$i] : "\0";
		}
	}
	return array(
		implode('', $cols),
		array(
			'__fz_restore' => 'record_transpose',
			'delim' => $delim,
			'max' => $max,
			'rows' => count($rows),
			'lengths' => $allMax ? array() : $lengths,
		),
	);
}

function fractal_inner_numeric_views($bytes) {
	$bytes = (string)$bytes;
	$n = strlen($bytes);
	$maxTotal = $this->fractal_inner_peeler_max_total_raw_bytes();
	if($n < 128 || ($maxTotal > 0 && $n > $maxTotal)) {
		return array();
	}
	$out = array();
	$delta = '';
	$prev = 0;
	for($i = 0; $i < $n; $i++) {
		$b = ord($bytes[$i]);
		$delta .= chr(($b - $prev) & 255);
		$prev = $b;
	}
	$out[] = array('numeric_delta', $delta, array('__fz_restore' => 'numeric_delta'));
	foreach(array(2, 4, 8) as $lanes) {
		$mod = $this->fractal_inner_modulo_lane_split_bytes($bytes, $lanes);
		$out[] = array(
			'modulo' . (string)$lanes . '_lane_split',
			$mod,
			$lanes === 4
				? array('__fz_restore' => 'modulo4_lane_split', 'len' => $n)
				: array('__fz_restore' => 'modulo_lane_split', 'lanes' => $lanes, 'len' => $n)
		);
	}
	$nibbles = '';
	for($i = 0; $i < $n; $i++) {
		$b = ord($bytes[$i]);
		$nibbles .= chr($b >> 4) . chr($b & 15);
	}
	$out[] = array('nibble_split', $nibbles, array('__fz_restore' => 'nibble_split'));
	$planes = array_fill(0, 8, '');
	for($bit = 0; $bit < 8; $bit++) {
		$acc = 0;
		$mask = 1;
		for($i = 0; $i < $n; $i++) {
			if((ord($bytes[$i]) & (1 << $bit)) !== 0) {
				$acc |= $mask;
			}
			$mask <<= 1;
			if($mask === 256) {
				$planes[$bit] .= chr($acc);
				$acc = 0;
				$mask = 1;
			}
		}
		if($mask !== 1) {
			$planes[$bit] .= chr($acc);
		}
	}
	$out[] = array('bitplane_split', implode('', $planes), array('__fz_restore' => 'bitplane_split', 'len' => $n));
	return $out;
}

function fractal_inner_modulo_lane_split_bytes($bytes, $lanes) {
	$bytes = (string)$bytes;
	$lanes = max(2, min(64, (int)$lanes));
	$n = strlen($bytes);
	$out = '';
	for($lane = 0; $lane < $lanes; $lane++) {
		for($i = $lane; $i < $n; $i += $lanes) {
			$out .= $bytes[$i];
		}
	}
	return $out;
}

function fractal_inner_sqlite_page_view($bytes) {
	$bytes = (string)$bytes;
	$n = strlen($bytes);
	if($n < 2048 || substr($bytes, 0, 16) !== "SQLite format 3\0") {
		return null;
	}
	$u = unpack('nps', substr($bytes, 16, 2));
	if(!is_array($u) || !isset($u['ps'])) {
		return null;
	}
	$pageSize = (int)$u['ps'];
	if($pageSize === 1) {
		$pageSize = 65536;
	}
	if($pageSize < 512 || $pageSize > 65536 || ($pageSize & ($pageSize - 1)) !== 0 || $n < $pageSize * 2) {
		return null;
	}
	$pages = intdiv($n, $pageSize);
	if($pages < 2 || $pages > 4096) {
		return null;
	}
	$headers = substr($bytes, 0, 100);
	$payloads = '';
	for($p = 0; $p < $pages; $p++) {
		$base = $p * $pageSize;
		$hdrLen = ($p === 0) ? 100 : 8;
		$headers .= substr($bytes, $base, $hdrLen);
		$payloads .= substr($bytes, $base + $hdrLen, $pageSize - $hdrLen);
	}
	return $payloads . $headers;
}

function fractal_inner_member_peeler_views($path, $disk) {
	fractal_zip_ensure_literal_pac_stack_loaded();
	$path = (string)$path;
	$disk = (string)$disk;
	$views = array();
	$seen = array();
	if($path !== '' && $disk !== '') {
		list($unwrapped) = fractal_zip_literal_deep_unwrap_with_layers($path, $disk, false);
		$this->fractal_inner_add_peeler_view($views, $seen, 'deep_unwrap', (string)$unwrapped, $disk);
	}
	if(strlen($disk) >= 16) {
		$z = @gzuncompress($disk);
		if(is_string($z)) {
			$this->fractal_inner_add_peeler_view($views, $seen, 'zlib_wrapper', $z, $disk);
		}
		$rawInflate = @gzinflate($disk);
		if(is_string($rawInflate)) {
			$this->fractal_inner_add_peeler_view($views, $seen, 'raw_deflate_wrapper', $rawInflate, $disk);
		}
	}
	$chunk = $this->fractal_inner_chunk_payload_view($disk);
	if($chunk !== null) {
		$this->fractal_inner_add_peeler_view($views, $seen, 'chunk_payload_split', $chunk, $disk);
	}
	$record = $this->fractal_inner_record_delimiter_typed_view($disk);
	if($record !== null) {
		$this->fractal_inner_add_peeler_view($views, $seen, 'record_transpose', (string)$record[0], $disk, $record[1] ?? null);
	}
	foreach($this->fractal_inner_numeric_views($disk) as $nv) {
		$this->fractal_inner_add_peeler_view($views, $seen, (string)$nv[0], (string)$nv[1], $disk, $nv[2] ?? null);
	}
	$sqlite = $this->fractal_inner_sqlite_page_view($disk);
	if($sqlite !== null) {
		$this->fractal_inner_add_peeler_view($views, $seen, 'sqlite_page_payload', $sqlite, $disk);
	}
	return $views;
}

/**
 * Run fractal-inner discovery on the existing reversible deep-unwrap byte view.
 *
 * This lane is intentionally separate from collect_fractal_inner_run_grammar_variants_for_folder():
 * peeled candidates carry restore bytes, so they must compete in the normal tournament where
 * append_fractal_gzip_peel_restore_trailer() accounts for those bytes.
 *
 * @param array<string,string> $rawFilesByPath
 * @return list<array{inner:string,tag:string,lane:string,source:string,restore:array<string,string>,cost_hint:int}>
 */
function collect_fractal_inner_peeler_variants_for_folder($rawFilesByPath) {
	if(!$this->fractal_inner_peeler_candidates_enabled() || !is_array($rawFilesByPath) || $rawFilesByPath === array()) {
		return array();
	}
	$totalRaw = 0;
	foreach($rawFilesByPath as $bytes) {
		$totalRaw += strlen((string)$bytes);
	}
	$maxTotal = $this->fractal_inner_peeler_max_total_raw_bytes();
	if($maxTotal > 0 && $totalRaw > $maxTotal) {
		return array();
	}
	fractal_zip_ensure_literal_pac_stack_loaded();
	$base = array();
	foreach($rawFilesByPath as $path => $bytes) {
		$base[(string)$path] = (string)$bytes;
	}
	ksort($base, SORT_STRING);
	$memberViews = array();
	$sourceOrder = array();
	$sources = array();
	$parallelPeel = fractal_zip_encode_pipeline::parallel_member_peeler_views_collect($this, $base);
	if($parallelPeel !== null) {
		$memberViews = $parallelPeel['memberViews'];
		$sourceOrder = $parallelPeel['sourceOrder'];
		$sources = $parallelPeel['sources'];
	} else {
		foreach($base as $p => $disk) {
			foreach($this->fractal_inner_member_peeler_views($p, $disk) as $view) {
				$source = (string)$view['source'];
				$memberViews[$p][$source] = $view;
				if(!isset($sources[$source])) {
					$sources[$source] = true;
					$sourceOrder[] = $source;
				}
			}
		}
	}
	if($sources === array()) {
		return array();
	}
	$out = array();
	$parallelSourceCands = fractal_zip_encode_pipeline::parallel_peeler_source_candidates_collect(
		$this,
		$base,
		$memberViews,
		$sourceOrder,
		$this->fractal_inner_run_grammar_max_raw_bytes(),
		$this->fractal_inner_operator_candidate_max_raw_bytes(),
		$maxTotal
	);
	foreach($sourceOrder as $source) {
		if($parallelSourceCands !== null && isset($parallelSourceCands[$source]) && is_array($parallelSourceCands[$source])) {
			foreach($parallelSourceCands[$source] as $candidate) {
				$out[] = $candidate;
				if(count($out) >= 12) {
					return $out;
				}
			}
			continue;
		}
		$files = $base;
		$restore = array();
		$totalView = $totalRaw;
		foreach($base as $p => $disk) {
			if(isset($memberViews[$p][$source])) {
				$view = $memberViews[$p][$source];
				$viewBytes = (string)$view['bytes'];
				$files[$p] = $viewBytes;
				$restore[$p] = $view['restore'];
				$totalView += strlen($viewBytes) - strlen((string)$disk);
			}
		}
		if($restore === array() || ($maxTotal > 0 && $totalView > $maxTotal)) {
			continue;
		}
		$typedRestoreOnly = true;
		foreach($restore as $spec) {
			if(!is_array($spec)) {
				$typedRestoreOnly = false;
				break;
			}
		}
		if($typedRestoreOnly) {
			$escaped = array();
			foreach($files as $p => $bytes) {
				$escaped[(string)$p] = $this->escape_literal_for_storage((string)$bytes);
			}
			$out[] = fractal_zip_candidate_from_inner(
				$this->encode_container_payload($escaped, ''),
				'peeler_literal:' . (string)$source,
				'literal',
				'peeler_literal:' . (string)$source,
				$restore,
				$totalView
			);
			if(count($out) >= 12) {
				return $out;
			}
		}
		$candidates = fractal_zip_inner_candidates_for_peeled_folder(
			$this,
			$files,
			$restore,
			$this->fractal_inner_run_grammar_max_raw_bytes(),
			$this->fractal_inner_operator_candidate_max_raw_bytes(),
			(string)$source
		);
		foreach($candidates as $candidate) {
			$out[] = $candidate;
			if(count($out) >= 12) {
				return $out;
			}
		}
	}
	return $out;
}

/**
 * Copy $src tree to $dst for native-Arc boxing, skipping existing fractal container files so a prior `.fz` beside sources
 * is not packed into the reference archive.
 */
function recursive_copy_directory_for_native_arc_box($src, $dst) {
	if(!is_dir($dst)) {
		mkdir($dst, 0755, true);
	}
	$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($src, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST);
	foreach($it as $item) {
		$sub = $it->getSubPathname();
		if($item->isFile()) {
			$low = strtolower($item->getFilename());
			if(str_ends_with($low, '.fz') || str_ends_with($low, '.fzc') || str_ends_with($low, '.fractalzip')) {
				continue;
			}
		}
		$target = $dst . DS . $sub;
		if($item->isDir()) {
			if(!is_dir($target)) {
				mkdir($target, 0755, true);
			}
		} else {
			$parent = dirname($target);
			if(!is_dir($parent)) {
				mkdir($parent, 0755, true);
			}
			copy($item->getPathname(), $target);
		}
	}
}

/**
 * Write collect_raw_files_for_bundle() map into $dst for native-Arc boxing (same skip rules as recursive_copy_directory_for_native_arc_box).
 *
 * @param array<string,string> $rawFilesByPath
 */
function materialize_raw_files_map_to_directory_for_native_arc_box($rawFilesByPath, $dst) {
	if(!is_dir($dst)) {
		mkdir($dst, 0755, true);
	}
	foreach($rawFilesByPath as $rel => $bytes) {
		$rel = (string) $rel;
		if($rel === '') {
			continue;
		}
		$low = strtolower(basename(str_replace('\\', '/', $rel)));
		if(str_ends_with($low, '.fz') || str_ends_with($low, '.fzc') || str_ends_with($low, '.fractalzip')) {
			continue;
		}
		$sub = str_replace('/', DS, $rel);
		$target = $dst . DS . $sub;
		$parent = dirname($target);
		if(!is_dir($parent)) {
			mkdir($parent, 0755, true);
		}
		file_put_contents($target, (string) $bytes);
	}
}

/**
 * Build a FreeArc archive of $sourceDir (real path) using the same flags as benchmarks/run_benchmarks.php benchArcFolderArchive
 * (<code>-m5</code>); when <code>$sumRawBytesHint</code> is within {@see fractal_zip::folder_native_freearc_dual_method_max_raw_bytes}, also tries <code>-m7</code> and returns the smaller blob.
 *
 * @param array<string,string>|null $rawFilesByPath When non-null and matches folder_structure_scan_root, avoids a second full disk tree read.
 * @param int|null $sumRawBytesHint merged raw byte total for dual-method gate; null skips <code>-m7</code>.
 * @param list<int>|null $forceMethods when non-null, only these Arc method numbers (e.g. array(3) for lifestyle Office).
 * @return string|null raw ARC file bytes or null on failure / unsupported OS
 */
function try_build_folder_freearc_native_archive_blob($sourceDir, $rawFilesByPathOrNull = null, $sumRawBytesHint = null, $forceMethods = null) {
	if(DIRECTORY_SEPARATOR === '\\') {
		return null;
	}
	$arcExe = fractal_zip::freearc_executable();
	if($arcExe === null) {
		return null;
	}
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	// Same temp naming pattern as benchmarks/run_benchmarks.php benchArcFolderArchive (path metadata can shift Arc bytes).
	$useMemMap = $rawFilesByPathOrNull !== null && is_array($rawFilesByPathOrNull)
		&& $this->folder_structure_was_made
		&& $this->folder_structure_scan_root === $rp;
	// Lifestyle: archive the source tree in place (skip temp-dir copy) — same idea as
	// 7z fsPassthrough. Copying dickens/webster (~10–40 MiB) before -m5 doubled walls.
	// Do not require !$useMemMap: warm folder maps still materialize 100+ files into a
	// temp box (~5 s on dense forests) and erase the Arc wall win. Tiny mid-hybrids
	// (187/192, &lt;1 MiB) keep the boxed copy for ±1 B wire stability.
	$inplace = fractal_zip::lifestyle_speed_profile_enabled()
		&& ($sumRawBytesHint === null || (int) $sumRawBytesHint >= 1024 * 1024);
	$box = null;
	$workDir = $rp;
	if(!$inplace) {
		$box = sys_get_temp_dir() . DS . 'fzarcbench_' . substr(md5((string) $rp . "\0fzarcbench"), 0, 16);
		if(is_dir($box)) {
			$this->recursive_remove_directory($box);
		}
		mkdir($box, 0755, true);
		if($useMemMap) {
			$this->materialize_raw_files_map_to_directory_for_native_arc_box($rawFilesByPathOrNull, $box);
		} else {
			$this->recursive_copy_directory_for_native_arc_box($rp, $box);
		}
		$workDir = $box;
	}
	$dualMax = fractal_zip::folder_native_freearc_dual_method_max_raw_bytes();
	$sumN = ($sumRawBytesHint !== null) ? (int) $sumRawBytesHint : -1;
	if(is_array($forceMethods) && $forceMethods !== array()) {
		$methods = array();
		foreach($forceMethods as $m) {
			$methods[] = max(1, min(9, (int) $m));
		}
		$methods = array_values(array_unique($methods));
	} else {
		$methods = array(5);
		// Dual -m5/-m7 only outside lifestyle (0.30× cannot afford the wall).
		if(!fractal_zip::lifestyle_speed_profile_enabled()
			&& $dualMax > 0 && $sumN > 0 && $sumN <= $dualMax) {
			$methods = array(5, 7);
		}
	}
	$prefix = $this->command_prefix_with_local_lib();
	$qArcExe = fractal_zip::shell_quote_arg_cached($arcExe);
	$arcPath = sys_get_temp_dir() . DS . 'fzarcbench_' . md5($workDir) . '.arc';
	$qArcPath = fractal_zip::shell_quote_arg_cached($arcPath);
	$exclFrag = $inplace
		? ' -x*.fz -x*.fzc -x*.fractalzip'
		: '';
	$cwd = getcwd();
	$best = null;
	$bestLen = PHP_INT_MAX;
	if(@chdir($workDir)) {
		foreach($methods as $methNum) {
			$methNum = max(1, min(9, (int) $methNum));
			if(is_file($arcPath)) {
				@unlink($arcPath);
			}
			$ret = -1;
			$cmd = $prefix . $qArcExe
				. ' a -m' . $methNum . fractal_zip::library_arc_compress_mt_shell_fragment_for_exec()
				. ' -ep1 -y' . $exclFrag . ' ' . $qArcPath . ' . 2>/dev/null';
			exec($cmd, $xo, $ret);
			if($ret === 0 && is_file($arcPath)) {
				$r = @file_get_contents($arcPath);
				if($r !== false && $r !== '') {
					$rLen = strlen($r);
					if($rLen < $bestLen) {
						$best = $r;
						$bestLen = $rLen;
					}
				}
			}
			if(is_file($arcPath)) {
				@unlink($arcPath);
			}
		}
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if($box !== null && is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	return $best;
}

/**
 * Native folder zpaq with {@code -noattributes}.
 *
 * Min-ext zpaq omits {@code -noattributes}; adding it typically saves 1–2 B while
 * restoring identical payload bytes. Single-member uses squash-style
 * {@code zpaq add arc rel}; multi-file (2–16 members, e.g. test_files165 WAVs) uses
 * {@code add .}. Cap 256 members so mid HTML (80), SC2 (56), php-langref (57),
 * raster forests (61), and format samples (201) still get the −noattributes sole tip.
 *
 * @param array<string,string> $rawFilesByPath
 * @return string|null raw .zpaq bytes
 */
function try_build_folder_zpaq_squash_noattr_blob(
	$sourceDir,
	array $rawFilesByPath,
	int $sumRawBytes,
	int $method = 5
): ?string {
	$nMembers = sizeof($rawFilesByPath);
	if(DIRECTORY_SEPARATOR === '\\' || $nMembers < 1 || $nMembers > 256) {
		return null;
	}
	// Singles: ≥1 MiB (squash literature). Multi-file: ≥512 KiB so format-sample
	// forests (test_files201 ~900 KiB) still get the −noattributes tip.
	// Single cap 128 MiB covers enwik8 (100 MiB) where zpaq -m5 reclaim ~1.1 MiB
	// vs Arc -m9, and mozilla (51 MiB). Multi stays at 48 MiB (wall headroom).
	$minRaw = ($nMembers === 1) ? (1024 * 1024) : (512 * 1024);
	$maxRaw = ($nMembers === 1) ? (128 * 1024 * 1024) : (48 * 1024 * 1024);
	if($sumRawBytes < $minRaw || $sumRawBytes > $maxRaw) {
		return null;
	}
	$method = max(1, min(5, $method));
	$zpaqExe = fractal_zip::zpaq_executable();
	if($zpaqExe === null) {
		return null;
	}
	$rel = null;
	foreach($rawFilesByPath as $k => $_b) {
		$rel = str_replace('\\', '/', (string) $k);
		// Singles: skip already-compressed containers (min-ext rarely uses zpaq_raw
		// there). Multi-file folder {@code add .} must include .zip packs — that is
		// exactly test_files65/82 (Genesis ROM zips) where -noattributes soles.
		if($nMembers === 1 && preg_match('/\\.(7z|zip|rar|gz|bz2|xz|zst)$/i', $rel)) {
			return null;
		}
		if($nMembers === 1) {
			break;
		}
	}
	if($nMembers === 1 && ($rel === null || $rel === '' || strpos($rel, '..') !== false)) {
		return null;
	}
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	$arcPath = sys_get_temp_dir() . DS . 'fzzp_squash_na_' . md5($rp . "\0" . (string) $nMembers . "\0" . (string) $rel . "\0m" . (string) $method) . '.zpaq';
	if(is_file($arcPath)) {
		@unlink($arcPath);
	}
	$prefix = $this->command_prefix_with_local_lib();
	$qZ = fractal_zip::shell_quote_arg_cached($zpaqExe);
	$qArc = fractal_zip::shell_quote_arg_cached($arcPath);
	$targetArg = ($nMembers === 1) ? fractal_zip::shell_quote_arg_cached((string) $rel) : '.';
	$cwd = getcwd();
	$ret = -1;
	$methodFrag = ' -method ' . (string) $method;
	if(@chdir($rp)) {
		$cmd = $prefix . $qZ . fractal_zip::zpaq_global_argv_shell_after_exe_from_env()
			. ' add ' . $qArc . ' ' . $targetArg
			. $methodFrag . ' -force -noattributes';
		exec($cmd . ' 2>/dev/null', $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if((int) $ret !== 0 || !is_file($arcPath)) {
		return null;
	}
	$blob = @file_get_contents($arcPath);
	@unlink($arcPath);
	if($blob === false || $blob === '') {
		return null;
	}
	fractal_zip::zpaq_set_last_method_from_argv_fragment($methodFrag);

	return $blob;
}

/**
 * Single-member FZpq v2 tip — mcm, and lpaq9l on OLE/PNG/archives where it
 * reclaim KiB (114/81/160). CSV/prose stay mcm-only (lpaq loses and only adds wall).
 * Small BMP (≤256 KiB): also race paq8px (34/64/157).
 * Small .zip (≤512 KiB): paq8px reclaim ~100 KiB vs brotli (158/161/163);
 * mid BMP paq8 (35) was dropped — same wall buys more suite bytes on .zip.
 *
 * @return string|null FZpq wire bytes
 */
function try_build_single_member_mcm_fzpq_wire(string $relPath, string $plainBytes): ?string {
	if($plainBytes === '' || strlen($plainBytes) < 3 * 1024 || strlen($plainBytes) > 48 * 1024 * 1024) {
		return null;
	}
	if(!function_exists('fractal_zip_paq_mcm_compress_bytes')) {
		require_once __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_paq.php';
	}
	$rel = str_replace('\\', '/', $relPath);
	if($rel === '' || strpos($rel, '..') !== false) {
		$rel = 'member.bin';
	}
	$best = null;
	$bestLen = PHP_INT_MAX;
	$raceLpaq = (bool) preg_match('/\\.(xls|doc|ppt|png|7z|zip)$/i', $rel);
	// .txt ≥64 KiB / .csv≥1 MiB / .xml≥256 KiB / .html≥8 KiB: parallel mcm+DRT.
	// DRT reclaim on Calgary prose, products CSV, silesia xml, phpinfo/cp HTML.
	// Mid CSV (53/151) keeps mcm-only — DRT loses. OLE/PNG keep mcm+lpaq w/o DRT.
	$raceDrt = !$raceLpaq && (
		((bool) preg_match('/\\.txt$/i', $rel) && strlen($plainBytes) >= 64 * 1024)
		|| ((bool) preg_match('/\\.csv$/i', $rel) && strlen($plainBytes) >= 1024 * 1024)
		|| ((bool) preg_match('/\\.xml$/i', $rel) && strlen($plainBytes) >= 256 * 1024)
		|| (strcasecmp(basename(str_replace('\\', '/', $rel)), 'xml') === 0
			&& strlen($plainBytes) >= 256 * 1024)
		|| ((bool) preg_match('/\\.html?$/i', $rel) && strlen($plainBytes) >= 8 * 1024)
		|| ((bool) preg_match('/\\.lsp$/i', $rel) && strlen($plainBytes) >= 3 * 1024)
		// Man pages (xargs.1): DRT reclaim ~0.3 KiB vs mcm.
		|| ((bool) preg_match('/\\.\\d+$/', $rel) && strlen($plainBytes) >= 3 * 1024
			&& strlen($plainBytes) <= 64 * 1024)
	);
	if(($raceLpaq || $raceDrt) && function_exists('fractal_zip_paq_cm_compress_bytes_parallel')) {
		$pack = fractal_zip_paq_cm_compress_bytes_parallel($plainBytes, $raceDrt);
		$lanes = $raceDrt
			? array(
				'mcm' => 'mcm',
				'drt_lpaq9lp' => 'drt_lpaq9lp',
				'drt_lpaq9l' => 'drt_lpaq9l',
				'lpaq9l' => 'lpaq9l',
			)
			: array('mcm' => 'mcm', 'lpaq9l' => 'lpaq9l');
		foreach($lanes as $key => $toolId) {
			if(!isset($pack[$key]) || !is_string($pack[$key]) || $pack[$key] === '') {
				continue;
			}
			$w = fractal_zip_paq_wrap_wire_v2($toolId, $pack[$key], $rel);
			if(is_string($w) && $w !== '' && strlen($w) < $bestLen) {
				$best = $w;
				$bestLen = strlen($w);
			}
		}
		// Small .zip: paq8 after mcm/lpaq (158/161/163). Cap 512 KiB — silesia-scale
		// zips stay on FZS1+br. Lifestyle uses −1 (wall); ultra uses −5 (bytes).
		if((fractal_zip::lifestyle_speed_profile_enabled()
				|| fractal_zip::ultra_compression_enabled())
			&& (bool) preg_match('/\\.zip$/i', $rel)
			&& strlen($plainBytes) <= 512 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$zipLvl = fractal_zip::ultra_compression_enabled() ? 5 : 1;
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, $zipLvl);
		}
		// Ultra mid .7z (160 raster_formats.7z ~1.1 MiB): paq8px −5 reclaim
		// ~82 KiB vs lpaq in ~106 s. Tiny .7z (159) stays FZS1 store.
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.7z$/i', $rel)
			&& strlen($plainBytes) > 512 * 1024
			&& strlen($plainBytes) <= 2 * 1024 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		// Ultra mid PNG (81 metis): paq8px −5 reclaim ~24 KiB vs mcm in ~200 s.
		// Lifestyle keeps mcm (1 s tip); −8 is worse than −5 on metis.
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.png$/i', $rel)
			&& strlen($plainBytes) >= 256 * 1024
			&& strlen($plainBytes) <= 2 * 1024 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		// Ultra mid OLE (114 kennedy.xls): paq8px −5 reclaim ~15 KiB vs mcm
		// in ~200 s — must live here; raceLpaq returns before the OOXML gate.
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.(xls|doc|ppt)$/i', $rel)
			&& strlen($plainBytes) >= 256 * 1024
			&& strlen($plainBytes) <= 2 * 1024 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		// Ultra mid HTML (49 phpinfo): paq8px −5 reclaim ~8 KiB vs DRT/mcm
		// in ~20 s — raceDrt returns before the mcm-only gates.
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.html?$/i', $rel)
			&& strlen($plainBytes) >= 8 * 1024
			&& strlen($plainBytes) <= 256 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		// Ultra mid CSV ≥1 MiB (167/174): paq8px −5 on raceDrt path.
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.csv$/i', $rel)
			&& strlen($plainBytes) >= 1024 * 1024
			&& strlen($plainBytes) <= 2 * 1024 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		// Ultra mid .txt (122 plrabn12): paq8px −5 reclaim ~2.7 KiB vs zstd/DRT.
		// Skip tiny already-crushed tips (alice/asyoulik brotli beat paq8).
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.txt$/i', $rel)
			&& strlen($plainBytes) >= 256 * 1024
			&& strlen($plainBytes) <= 1024 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		// Ultra Squash .lsp (113 grammar): paq8px −5 reclaim ~86 B vs DRT/mcm.
		if(fractal_zip::ultra_compression_enabled()
			&& (bool) preg_match('/\\.lsp$/i', $rel)
			&& strlen($plainBytes) >= 3 * 1024
			&& strlen($plainBytes) <= 64 * 1024
			&& function_exists('fractal_zip_paq_compress_file')
			&& function_exists('fractal_zip_paq_discover_executable')) {
			$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
		}
		return $best;
	}
	$m = fractal_zip_paq_mcm_compress_bytes($plainBytes);
	if(is_array($m) && isset($m['bytes']) && is_string($m['bytes']) && $m['bytes'] !== '') {
		$w = fractal_zip_paq_wrap_wire_v2('mcm', $m['bytes'], $rel);
		if(is_string($w) && $w !== '' && strlen($w) < $bestLen) {
			$best = $w;
			$bestLen = strlen($w);
		}
	}
	// Ultra mid OOXML (153/166/173 xlsx): paq8px −5 reclaim ~117 KiB vs 7z
	// in ~165 s — lifestyle keeps 7z (wall).
	if(fractal_zip::ultra_compression_enabled()
		&& (bool) preg_match('/\\.(xlsx|xlsm|docx|pptx)$/i', $rel)
		&& strlen($plainBytes) >= 64 * 1024
		&& strlen($plainBytes) <= 512 * 1024
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Ultra small .tar.gz / .gz (162) paq8 disabled: ~1.5 KiB / ~70 s
	// (~21 B/s) — wall returned to suite headroom.
	// Ultra large .json (152) paq8 disabled — see CM-first note (~6.6 B/s).
	// Ultra Squash canterbury micros: .c / .protodata (110 fields, 112 geo)
	// paq8px −5 reclaim ~0.4–2.7 KiB vs mcm in <80 s. Lifestyle keeps mcm.
	if(fractal_zip::ultra_compression_enabled()
		&& (bool) preg_match('/\\.(c|protodata)$/i', $rel)
		&& strlen($plainBytes) >= 3 * 1024
		&& strlen($plainBytes) <= 256 * 1024
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Ultra mid CSV <1 MiB (53/151): paq8px −5 reclaim ~12 KiB vs mcm in ~135 s.
	// (≥1 MiB CSV uses the raceDrt gate above.)
	if(fractal_zip::ultra_compression_enabled()
		&& (bool) preg_match('/\\.csv$/i', $rel)
		&& strlen($plainBytes) >= 256 * 1024
		&& strlen($plainBytes) < 1024 * 1024
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// BMP paq8px: lifestyle ≤256 KiB (34/64/157); ultra ≤5 MiB also takes rafale (35).
	$bmpPaqCap = fractal_zip::ultra_compression_enabled()
		? (5 * 1024 * 1024)
		: (256 * 1024);
	if((fractal_zip::lifestyle_speed_profile_enabled()
			|| fractal_zip::ultra_compression_enabled())
		&& (bool) preg_match('/\\.bmp$/i', $rel)
		&& strlen($plainBytes) <= $bmpPaqCap
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Ultra .bin/.smd ROM dumps (83 Genesis .bin; 82 peel .smd): paq8px
	// can untie zpaq_raw+1 / beat opaque Arc-of-zips.
	if(fractal_zip::ultra_compression_enabled()
		&& (bool) preg_match('/\\.(bin|smd)$/i', $rel)
		&& strlen($plainBytes) >= 1024 * 1024
		&& strlen($plainBytes) <= 5 * 1024 * 1024
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Ultra PDF paq8: mid (71) + small (121 paper-100k −13 KiB/~30 s)
	// + mid-large sniff/name (124 reymont ≤8 MiB).
	$pdfNameOrSniff = (bool) preg_match('/\\.pdf$/i', $rel)
		|| strncmp($plainBytes, '%PDF-', 5) === 0;
	$pdfPaqCap = 4 * 1024 * 1024;
	if(fractal_zip::ultra_compression_enabled()) {
		$pdfPaqCap = 8 * 1024 * 1024;
	}
	if(fractal_zip::ultra_compression_enabled()
		&& $pdfNameOrSniff
		&& strlen($plainBytes) >= 64 * 1024
		&& strlen($plainBytes) <= $pdfPaqCap
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Mid extensionless (ptt5): paq8px −5 reclaim ~20 KiB vs xz -9e in ~7 s.
	// Lifestyle wall absorbs it (suite still ≪ fair); ultra keeps the sole.
	// Ultra also takes small ELF dumps (127 sum, 16–256 KiB).
	$baseOnly = basename($rel);
	$extless = ($baseOnly !== '' && strpos($baseOnly, '.') === false);
	$extlessMin = fractal_zip::ultra_compression_enabled()
		? (16 * 1024)
		: (256 * 1024);
	if((fractal_zip::lifestyle_speed_profile_enabled()
			|| fractal_zip::ultra_compression_enabled())
		&& $extless
		&& strlen($plainBytes) >= $extlessMin
		&& strlen($plainBytes) < 4 * 1024 * 1024
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Ultra extensionless 4–12 MiB paq8: high-printable osdb (120) + opaque
	// x-ray (132). Skip mid-printable sao (126) — ~157 KiB / ~2400 s (~65 B/s)
	// returned to suite headroom so Squash 120 can soft-merge when 130 wall
	// trims ≥~300 s. Discriminate: high-print ≥0.75 (osdb) or non-mid & ≥8 MiB
	// (x-ray 0.275); sao is mid-print ~0.38 @ 6.9 MiB.
	$extlessPaq8 = false;
	if(fractal_zip::ultra_compression_enabled()
		&& $extless
		&& strlen($plainBytes) >= 4 * 1024 * 1024
		&& strlen($plainBytes) <= 12 * 1024 * 1024) {
		if($this->lifestyle_payload_high_printable_ratio($plainBytes)) {
			$extlessPaq8 = true;
		} elseif(!$this->lifestyle_payload_mid_printable_ratio($plainBytes)
			&& strlen($plainBytes) >= 8 * 1024 * 1024) {
			$extlessPaq8 = true;
		}
	}
	if($extlessPaq8
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}
	// Ultra mid odd-ext text dumps (128 urls.10K): paq8px −5 reclaim ~14 KiB
	// vs mx=9 7z in ~2 min.
	if(fractal_zip::ultra_compression_enabled()
		&& (bool) preg_match('/\\.(10[Kk]|\\d{2,4}[Kk])$/i', $rel)
		&& strlen($plainBytes) >= 256 * 1024
		&& strlen($plainBytes) <= 2 * 1024 * 1024
		&& function_exists('fractal_zip_paq_compress_file')
		&& function_exists('fractal_zip_paq_discover_executable')) {
		$this->lifestyle_race_paq8px_into_fzpq_best($plainBytes, $rel, $best, $bestLen, 5);
	}

	return $best;
}

/**
 * Race paq8px into an FZpq v2 tip; updates $best/$bestLen when smaller.
 *
 * @param int $level paq8px -N (1..12); zip tips use 1 for wall, BMP keeps 5.
 */
function lifestyle_race_paq8px_into_fzpq_best(
	string $plainBytes,
	string $rel,
	?string &$best,
	int &$bestLen,
	int $level = 5
): void {
	$exe = fractal_zip_paq_discover_executable('paq8px');
	if(!is_string($exe) || $exe === '') {
		return;
	}
	$level = max(1, min(12, $level));
	$savedLvl = getenv('FRACTAL_ZIP_PAQ8PX_LEVEL');
	putenv('FRACTAL_ZIP_PAQ8PX_LEVEL=' . (string) $level);
	$box = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'fzp8race_' . bin2hex(random_bytes(4));
	@mkdir($box, 0700, true);
	$inPath = $box . DIRECTORY_SEPARATOR . 'in.bin';
	if(@file_put_contents($inPath, $plainBytes) !== false) {
		$pack = fractal_zip_paq_compress_file('paq8px', $exe, $inPath);
		if(is_array($pack) && isset($pack['bytes']) && is_string($pack['bytes'])
			&& $pack['bytes'] !== '') {
			$w = fractal_zip_paq_wrap_wire_v2('paq8px', $pack['bytes'], $rel);
			if(is_string($w) && $w !== '' && strlen($w) < $bestLen) {
				$best = $w;
				$bestLen = strlen($w);
			}
		}
	}
	foreach(glob($box . DIRECTORY_SEPARATOR . '*') ?: array() as $f) {
		@unlink($f);
	}
	@rmdir($box);
	if($savedLvl === false) {
		putenv('FRACTAL_ZIP_PAQ8PX_LEVEL');
	} else {
		putenv('FRACTAL_ZIP_PAQ8PX_LEVEL=' . $savedLvl);
	}
}

/**
 * After a .fz is written for a single-file source, race squash zpaq -noattributes
 * and mcm FZpq; replace when strictly smaller (dickens GT store, nci/xml ties).
 *
 * @param bool $force When true, run even if lifestyle was runtime-disabled for a
 *        GT virtual folder (dickens path sets that flag for the call).
 */
function lifestyle_maybe_upgrade_single_source_fzc(string $sourceFilePath, string $fzcPath, bool $force = false): bool {
	if(!$force && !fractal_zip::lifestyle_speed_profile_enabled()) {
		return false;
	}
	if(!is_file($sourceFilePath) || !is_file($fzcPath)) {
		return false;
	}
	$plain = @file_get_contents($sourceFilePath);
	if($plain === false || $plain === '') {
		return false;
	}
	$sum = strlen($plain);
	if($sum < 4 * 1024 || $sum > 48 * 1024 * 1024) {
		return false;
	}
	$cur = @file_get_contents($fzcPath);
	if($cur === false || $cur === '') {
		return false;
	}
	$best = $cur;
	$bestCodec = is_string(fractal_zip::$last_written_container_codec)
		? fractal_zip::$last_written_container_codec
		: 'store';
	$rel = basename($sourceFilePath);
	$dir = dirname($sourceFilePath);
	$map = array($rel => $plain);
	$zp = $this->try_build_folder_zpaq_squash_noattr_blob($dir, $map, $sum);
	if(is_string($zp) && $zp !== '' && strlen($zp) < strlen($best)) {
		$best = $zp;
		$bestCodec = 'zpaq';
	}
	// Prose dumps (zpaq tip≥10% raw): skip mcm — same tip already soles zpaq_raw.
	// BMP/bin excluded: strong zpaq still loses to paq8px (35/83).
	$skipMcmProse = ($bestCodec === 'zpaq' && $sum > 0 && strlen($best) * 10 >= $sum
		&& !(bool) preg_match('/\\.(bmp|bin)$/i', $rel));
	if(!$skipMcmProse) {
		$mcm = $this->try_build_single_member_mcm_fzpq_wire($rel, $plain);
		if(is_string($mcm) && $mcm !== '' && strlen($mcm) < strlen($best)) {
			$best = $mcm;
			$bestCodec = 'paq';
		}
	}
	if($best === $cur) {
		return false;
	}
	if(@file_put_contents($fzcPath, $best) === false) {
		return false;
	}
	fractal_zip::$last_outer_codec = $bestCodec;
	fractal_zip::$last_written_container_codec = $bestCodec;
	fractal_zip::$folder_zip_wire_best_outer_codec = $bestCodec;
	fractal_zip::html_trace_print(
		'Lifestyle single-source upgrade: ' . htmlspecialchars($bestCodec)
		. ' wire ' . strlen($best) . ' B (was ' . strlen($cur) . ').<br>'
	);

	return true;
}

/**
 * Build a native 7z folder archive using the same folder command as the benchmark 7z column.
 *
 * @param array<string,string>|null $rawFilesByPathOrNull
 * @return string|null raw 7z bytes, or null on unsupported/failure
 */
/**
 * @param string|null $lzmaMethod 7z -m0= method (default lzma2). Pass "LZMA" for
 *        midsize PNG singles where LZMA soles soft xz and lzma2 does not (81).
 */
function try_build_folder_7z_native_archive_blob(
	$sourceDir,
	$rawFilesByPathOrNull = null,
	$fsPassthrough = false,
	$lzmaMethod = null
) {
	$seven = fractal_zip::seven_zip_executable();
	if($seven === null) {
		return null;
	}
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	$sumRaw = 0;
	if($rawFilesByPathOrNull !== null && is_array($rawFilesByPathOrNull)) {
		foreach($rawFilesByPathOrNull as $b) {
			$sumRaw += strlen((string) $b);
		}
	} else {
		$sumRaw = $this->folder_raw_total_bytes($rp);
	}
	$useMemMap = $rawFilesByPathOrNull !== null && is_array($rawFilesByPathOrNull)
		&& $this->folder_structure_was_made
		&& $this->folder_structure_scan_root === $rp;
	// Lifestyle passthrough: archive the source tree in place (skip temp-dir copy).
	// Excludes sibling .fz/.fzc containers. Mem-map materialize still uses a box.
	$inplace = $fsPassthrough && fractal_zip::lifestyle_speed_profile_enabled() && !$useMemMap;
	$box = null;
	$workDir = $rp;
	if(!$inplace) {
		$box = sys_get_temp_dir() . DS . 'fz7bench_' . substr(md5((string) $rp . "\0fz7bench_native"), 0, 16);
		if(is_dir($box)) {
			$this->recursive_remove_directory($box);
		}
		mkdir($box, 0755, true);
		if($useMemMap) {
			$this->materialize_raw_files_map_to_directory_for_native_arc_box($rawFilesByPathOrNull, $box);
		} else {
			$this->recursive_copy_directory_for_native_arc_box($rp, $box);
		}
		$workDir = $box;
	}
	$arc = sys_get_temp_dir() . DS . 'fz7bench_' . md5(($box ?? $rp) . "\0arc") . '.7z';
	if(is_file($arc)) {
		@unlink($arc);
	}
	$cwd = getcwd();
	$ret = -1;
	if(@chdir($workDir)) {
		$mx = 9;
		if($fsPassthrough && fractal_zip::fs_profile_enabled()) {
			$mx = fractal_zip::fs_profile_seven_zip_passthrough_mx(
				$sumRaw,
				is_array($rawFilesByPathOrNull) ? $rawFilesByPathOrNull : array(),
				is_array($rawFilesByPathOrNull) ? count($rawFilesByPathOrNull) : 0
			);
		} elseif($fsPassthrough && fractal_zip::lifestyle_speed_profile_enabled()) {
			// ≤8 MiB: mx=9 matches the bench 7z column (test_files35 BMP; midsize OLE).
			// Dense peel forests (test_files69): mx=9 × 100+ members blows 45s — use mx=5.
			// Scale mx down only above that so 45s/90s walls stay reachable.
			$memberHint = is_array($rawFilesByPathOrNull) ? count($rawFilesByPathOrNull) : 0;
			if($sumRaw > 0 && $sumRaw <= 8 * 1024 * 1024) {
				// Dense peel (69): mx=5. PHP-ref / singles: mx=9.
				$mx = ($memberHint >= 64) ? 5 : 9;
			} elseif($sumRaw <= 32 * 1024 * 1024 && $memberHint <= 1) {
				// Lifestyle high-print (osdb ~10 MiB): mx=5 soles soft (~255 KiB) in
				// ~3.6 s; mx=9 was ~5 s for ~20 KiB. Non-lifestyle keeps mx=9.
				$mx = 5;
			} elseif($sumRaw <= 48 * 1024 * 1024) {
				// webster single (~41 MiB): mx=9 ~8.39 MiB ≈ mx=7 wall; mx=5 leaves ~340 KiB
				// (test_files130). Multifile midsize keeps mx=5 for the 45s wall.
				$mx = ($memberHint <= 1) ? 9 : 5;
			} else {
				// >48 MiB: singles use mx=7 (mozilla: identical wire to mx=9, slightly
				// faster). Multifile monsters stay mx=3.
				$mx = ($memberHint <= 1) ? 7 : 3;
			}
		}
		// Lifestyle: strip FS times (-mtc/a/m=off) so archives stay byte-stable
		// (test_files62/63 ±1–10 B without this; same switches as outer_7z_metadata_strip_argv()).
		// Tiny trees: pin -mmt=1 (MT startup can push test_files76 over its ~0.07 s gate).
		// Larger lifestyle fs packs: default -mmt=on when unset — same wire bytes as
		// single-thread mx=9 (mozilla 116) and ~2× faster under load.
		$mmtFrag = ($fsPassthrough && fractal_zip::lifestyle_speed_profile_enabled()
			&& $sumRaw > 0 && $sumRaw <= 65536)
			? ' -mmt=1'
			: fractal_zip::seven_zip_mmt_shell_fragment_for_exec();
		if($mmtFrag === '' && $fsPassthrough
			&& fractal_zip::lifestyle_speed_profile_enabled()
			&& $sumRaw >= 4 * 1024 * 1024) {
			$mmtFrag = ' -mmt=on';
		}
		$metaFrag = '';
		$exclFrag = '';
		if($fsPassthrough && fractal_zip::lifestyle_speed_profile_enabled()) {
			$metaArgv = fractal_zip::outer_7z_metadata_strip_argv();
			if($metaArgv !== array()) {
				$metaFrag = ' ' . implode(' ', $metaArgv);
			}
			if($inplace) {
				$exclFrag = ' -xr!*.fz -xr!*.fzc -xr!*.fractalzip';
			}
		}
		// Phone-mix (test_files76): solid+qs saves ~40 B (6220 vs 6266) and beats gzip9
		// (6234). Use as the *primary* cmd on tiny lifestyle sums — a second 7z race
		// flakes the 0.07 s gate. Larger trees (62/63) stay non-solid.
		$solidFrag = ($fsPassthrough && fractal_zip::lifestyle_speed_profile_enabled()
			&& $sumRaw > 0 && $sumRaw <= 16384) ? ' -ms=on -mqs=on' : '';
		$m0 = 'lzma2';
		if(is_string($lzmaMethod) && $lzmaMethod !== ''
			&& preg_match('/^[A-Za-z0-9:.=]+$/', $lzmaMethod)) {
			$m0 = $lzmaMethod;
		}
		$cmd = fractal_zip::shell_quote_arg_cached($seven) . ' a -t7z -mx=' . (string) $mx
			. $mmtFrag
			. $metaFrag
			. $exclFrag
			. ' -m0=' . $m0 . $solidFrag . ' -bso0 -bsp0 -bd -y '
			. fractal_zip::shell_quote_arg_cached($arc) . ' . 2>/dev/null';
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	$blob = null;
	if($ret === 0 && is_file($arc)) {
		$r = @file_get_contents($arc);
		if($r !== false && $r !== '') {
			$blob = $r;
		}
	}
	if(is_file($arc)) {
		@unlink($arc);
	}
	if($box !== null && is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	return $blob;
}

/**
 * Same pipeline as benchmarks min-ext brotli: {@code tar cf - . | brotli -c -q N} in a temp dir (Unix).
 *
 * @param array<string,string>|null $rawFilesByPathOrNull
 * @return string|null raw .br bytes or null
 */
function try_build_folder_brotli_native_tar_br_blob($sourceDir, $rawFilesByPathOrNull = null) {
	if(PHP_OS_FAMILY === 'Windows') {
		return null;
	}
	$brotliExe = fractal_zip::brotli_executable();
	if($brotliExe === null || !fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_BROTLI')) {
		return null;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return null;
	}
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	$bq = getenv('FRACTAL_ZIP_BENCH_BROTLI_QUALITY');
	$q = ($bq === false || trim((string) $bq) === '') ? 11 : max(0, min(11, (int) trim((string) $bq)));
	// Lifestyle midsize under the 0.30× bar: q10 from 512 KiB (single .7z 160
	// soles soft at q10 in <1 s; q11 was ~2 s). q10 for 2–8 MiB. q8 for 8–12 MiB.
	if(($bq === false || trim((string) $bq) === '')
		&& fractal_zip::lifestyle_speed_profile_enabled()) {
		$sumHint = 0;
		if(is_array($rawFilesByPathOrNull)) {
			foreach($rawFilesByPathOrNull as $b) {
				$sumHint += strlen((string) $b);
			}
		} else {
			$sumHint = $this->folder_raw_total_bytes($rp);
		}
		if($sumHint >= 512 * 1024 && $sumHint <= 8 * 1024 * 1024) {
			$q = 10;
		} elseif($sumHint > 8 * 1024 * 1024 && $sumHint <= 12 * 1024 * 1024) {
			$q = 8;
		}
	}
	$compressorArgv = fractal_zip::shell_quote_arg_cached($brotliExe)
		. fractal_zip::brotli_compress_extra_argv_shell_fragment()
		. ' -c -q ' . $q;
	// Prefer in-place tar|brotli from the live tree (same bytes as min-ext when the
	// source has no .fz). Avoid PHP recursive_copy drift vs cp -a (test_files56 ±tens).
	// Include quality + pid so q9→q11 escalate (and concurrent benches) do not clobber.
	$outBr = sys_get_temp_dir() . DS . 'fzbrbench_' . md5($rp . "\0br\0" . (string) $q . "\0" . (string) getmypid()) . '.br';
	$cwd = getcwd();
	$ret = -1;
	$blob = null;
	$sumHintBr = 0;
	if(is_array($rawFilesByPathOrNull)) {
		foreach($rawFilesByPathOrNull as $b) {
			$sumHintBr += strlen((string) $b);
		}
	} else {
		$sumHintBr = $this->folder_raw_total_bytes($rp);
	}
	// Tiny/mid lifestyle trees: also race a reproducible tar (mtime/owner sorted).
	// Soft min-ext uses plain tar, so mtime drift can fake a tie (177 vs 154).
	// Raised to 2 MiB / ≤16 members so hard/ stress packs (150) sole (~3912 vs
	// soft 3925); previously only ≤256 KiB raced sorted tar.
	// Midsize lifestyle: also race ustar — soft uses GNU tar; ustar|br soles on
	// single .7z (160) and image grids (168). Skip ustar on multi-file all-precomp
	// packs (175/176): plain tar|q11 already soles, second q11 burns ~4–5 s.
	$tarVariants = array(
		'tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' .',
	);
	$nHintBr = is_array($rawFilesByPathOrNull) ? count($rawFilesByPathOrNull) : 0;
	$sortedTarCmd = 'tar cf - --sort=name --mtime=@0 --owner=0 --group=0 --numeric-owner'
		. ' --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' .';
	// Single small textlike (49/112) and small all-HTML packs (13): sorted
	// tar|br11 alone soles soft; racing plain+sorted+ustar triple-taxed q11
	// (~0.35 s / ~0.21 s vs ~0.11 s / ~0.07 s).
	$sortedOnlyBr = false;
	$allHtmlBrHint = false;
	if(is_array($rawFilesByPathOrNull) && $rawFilesByPathOrNull !== array()
		&& $nHintBr >= 2 && $nHintBr <= 16) {
		$allHtmlBrHint = true;
		foreach(array_keys($rawFilesByPathOrNull) as $htmlPath) {
			if(!preg_match('/\\.html?$/i', (string) $htmlPath)) {
				$allHtmlBrHint = false;
				break;
			}
		}
	}
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& $nHintBr === 1 && $sumHintBr > 0 && $sumHintBr < 256 * 1024) {
		$tarVariants = array($sortedTarCmd);
		$sortedOnlyBr = true;
	} elseif(fractal_zip::lifestyle_speed_profile_enabled()
		&& $allHtmlBrHint && $sumHintBr > 0 && $sumHintBr <= 256 * 1024) {
		$tarVariants = array($sortedTarCmd);
		$sortedOnlyBr = true;
	} elseif(fractal_zip::lifestyle_speed_profile_enabled()
		&& $sumHintBr > 0 && $sumHintBr <= 2 * 1024 * 1024
		&& ($sumHintBr <= 256 * 1024
			|| ($nHintBr >= 2 && $nHintBr <= 16))) {
		$tarVariants[] = $sortedTarCmd;
	}
	$allPrecompBr = false;
	$allArchiveBr = false;
	$allImageBr = false;
	$precompMemberHint = 0;
	if(is_array($rawFilesByPathOrNull) && $rawFilesByPathOrNull !== array()) {
		$allPrecompBr = true;
		$allArchiveBr = true;
		$allImageBr = true;
		foreach(array_keys($rawFilesByPathOrNull) as $prePath) {
			$precompMemberHint++;
			$pp = (string) $prePath;
			if(!preg_match('/\\.(zip|7z|rar|gz|bz2|xz|zst|br)$/i', $pp)) {
				$allPrecompBr = false;
				$allArchiveBr = false;
			}
			if(!preg_match('/\\.(zip|7z|rar)$/i', $pp)) {
				$allArchiveBr = false;
			}
			if(!preg_match('/\\.(png|jpe?g|gif|webp|bmp)$/i', $pp)) {
				$allImageBr = false;
			}
		}
	}
	// Skip ustar when any member path exceeds the 100-byte ustar name field —
	// GNU tar --format=ustar then emits a near-empty archive (dir only). That
	// compresses to ~70 B and falsely "wins" vs real GNU tar|br (test_files71
	// long Unicode PDF name). Soft min-ext uses GNU tar, which keeps long names.
	$maxPathLenBr = 0;
	if(is_array($rawFilesByPathOrNull) && $rawFilesByPathOrNull !== array()) {
		foreach(array_keys($rawFilesByPathOrNull) as $pathLenKey) {
			$pl = strlen(str_replace('\\', '/', (string) $pathLenKey));
			if($pl > $maxPathLenBr) {
				$maxPathLenBr = $pl;
			}
		}
	} else {
		$itLen = new RecursiveIteratorIterator(
			new RecursiveDirectoryIterator($rp, FilesystemIterator::SKIP_DOTS)
		);
		foreach($itLen as $fiLen) {
			if(!$fiLen->isFile()) {
				continue;
			}
			$relLen = substr($fiLen->getPathname(), strlen($rp) + 1);
			$pl = strlen(str_replace('\\', '/', (string) $relLen));
			if($pl > $maxPathLenBr) {
				$maxPathLenBr = $pl;
			}
		}
	}
	$ustarSafeBr = ($maxPathLenBr > 0 && $maxPathLenBr <= 100);
	// Skip ustar only for multi zip/7z/rar packs (175-class FZB+zpaq lane). Keep
	// ustar for mixed .br/.gz packs — sole margin vs soft brotli (176). Dense
	// mixed forests (≥64 members): ustar|br is usually larger than GNU tar|br and
	// doubles wall at q11 — skip the second pass. Mid all-image grids (168): same
	// — ustar|br11 doubles wall for no byte win.
	// Single already-compressed member: ustar|br beats GNU (160) — use ustar only
	// so we do not pay for a second q11 pass.
	$memberHintBr = is_array($rawFilesByPathOrNull) ? count($rawFilesByPathOrNull) : 0;
	// Skip ustar when sorted-only already selected (49/112/13).
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& !$sortedOnlyBr
		&& $ustarSafeBr
		&& $sumHintBr > 0 && $sumHintBr <= 4 * 1024 * 1024
		&& !($allArchiveBr && $precompMemberHint >= 2)
		&& $memberHintBr < 64
		&& !($allImageBr && $memberHintBr >= 8)
		&& !($memberHintBr === 1 && $sumHintBr < 256 * 1024 && !$allPrecompBr)) {
		$ustarCmd = 'tar --format=ustar -cf - --exclude=\'*.fz\' --exclude=\'*.fzc\''
			. ' --exclude=\'*.fractalzip\' .';
		if($memberHintBr === 1 && $allPrecompBr) {
			$tarVariants = array($ustarCmd);
		} else {
			$tarVariants[] = $ustarCmd;
		}
	}
	$bestBr = null;
	if(@chdir($rp)) {
		foreach($tarVariants as $ti => $tarCmd) {
			$outTry = $outBr . ($ti === 0 ? '' : ('.r' . (string) $ti));
			if(is_file($outTry)) {
				@unlink($outTry);
			}
			$cmd = $tarCmd . ' 2>/dev/null | '
				. $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($outTry) . ' 2>/dev/null';
			exec($cmd, $xo, $ret);
			if($ret === 0 && is_file($outTry)) {
				$sz = filesize($outTry);
				// Reject near-empty tar|br (ustar long-name drop): real soft tips
				// for ≥64 KiB corpora are never ≪0.1% raw.
				$absurdTiny = ($sumHintBr >= 64 * 1024 && is_int($sz)
					&& $sz > 0 && $sz * 1000 < $sumHintBr);
				if(is_int($sz) && $sz > 0 && !$absurdTiny
					&& ($bestBr === null || $sz < strlen($bestBr))) {
					$got = file_get_contents($outTry);
					if(is_string($got) && $got !== '') {
						$bestBr = $got;
					}
				}
			}
			if($outTry !== $outBr) {
				@unlink($outTry);
			}
		}
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if(is_file($outBr)) {
		@unlink($outBr);
	}
	if(is_string($bestBr) && $bestBr !== '') {
		return $bestBr;
	}
	// Fallback: materialize/copy into a sandbox (legacy path when in-place tar fails).
	$box = sys_get_temp_dir() . DS . 'fzbrbench_' . substr(md5((string) $rp . "\0fzbr_native"), 0, 16);
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	mkdir($box, 0755, true);
	$useMemMap = $rawFilesByPathOrNull !== null && is_array($rawFilesByPathOrNull)
		&& $this->folder_structure_was_made
		&& $this->folder_structure_scan_root === $rp;
	if($useMemMap) {
		$this->materialize_raw_files_map_to_directory_for_native_arc_box($rawFilesByPathOrNull, $box);
	} else {
		$this->recursive_copy_directory_for_native_arc_box($rp, $box);
	}
	$outBr = sys_get_temp_dir() . DS . 'fzbrbench_' . md5($box . "\0br") . '.br';
	if(is_file($outBr)) {
		@unlink($outBr);
	}
	$cwd = getcwd();
	$ret = -1;
	if(@chdir($box)) {
		$cmd = 'tar cf - . 2>/dev/null | ' . $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($outBr) . ' 2>/dev/null';
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	$blob = null;
	if($ret === 0 && is_file($outBr)) {
		$r = @file_get_contents($outBr);
		if($r !== false && $r !== '') {
			$blob = $r;
		}
	}
	if(is_file($outBr)) {
		@unlink($outBr);
	}
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}

	return $blob;
}

/**
 * Bench-aligned gzip9 packed bundle: zlib-deflate of concatenated
 * {@code u32 pathLen | path | u32 size | bytes} records (same as run_benchmarks gzip baseline).
 *
 * @param array<string,string>|null $rawFilesByPathOrNull
 * @return string|null raw zlib bytes or null
 */
function try_build_folder_gzip9_bundle_zlib_blob($sourceDir, $rawFilesByPathOrNull = null) {
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	$blob = '';
	if(is_array($rawFilesByPathOrNull) && $rawFilesByPathOrNull !== array()) {
		$paths = array_keys($rawFilesByPathOrNull);
		sort($paths, SORT_STRING);
		foreach($paths as $rel) {
			$body = (string) $rawFilesByPathOrNull[$rel];
			$rel = str_replace('\\', '/', (string) $rel);
			$blob .= pack('N', strlen($rel)) . $rel . pack('N', strlen($body)) . $body;
		}
	} else {
		$files = array();
		$it = new RecursiveIteratorIterator(
			new RecursiveDirectoryIterator($rp, FilesystemIterator::SKIP_DOTS)
		);
		foreach($it as $fi) {
			if(!$fi->isFile()) {
				continue;
			}
			$full = $fi->getPathname();
			$base = basename($full);
			if(preg_match('/\\.(fz|fzc|fractalzip)$/i', $base)) {
				continue;
			}
			$rel = substr($full, strlen($rp) + 1);
			$rel = str_replace('\\', '/', (string) $rel);
			$files[$rel] = $full;
		}
		ksort($files, SORT_STRING);
		foreach($files as $rel => $full) {
			$body = (string) file_get_contents($full);
			$blob .= pack('N', strlen($rel)) . $rel . pack('N', strlen($body)) . $body;
		}
	}
	if($blob === '') {
		return null;
	}
	$z = @gzcompress($blob, 9);
	if(!is_string($z) || $z === '') {
		return null;
	}
	return $z;
}

/**
 * Same pipeline as benchmarks min-ext zstd: {@code tar cf - . | zstd -N -c} in a temp dir (Unix).
 *
 * @param array<string,string>|null $rawFilesByPathOrNull
 * @return string|null raw .zst bytes or null
 */
function try_build_folder_zstd_native_tar_zst_blob($sourceDir, $rawFilesByPathOrNull = null) {
	if(PHP_OS_FAMILY === 'Windows') {
		return null;
	}
	$zstdExe = fractal_zip::zstd_executable();
	if($zstdExe === null || !fractal_zip::outer_skip_env_allows('FRACTAL_ZIP_SKIP_ZSTD')) {
		return null;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return null;
	}
	$rp = realpath((string) $sourceDir);
	if($rp === false || !is_dir($rp)) {
		return null;
	}
	$zl = getenv('FRACTAL_ZIP_BENCH_ZSTD_LEVEL');
	$lev = ($zl === false || trim((string) $zl) === '') ? 19 : max(1, min(22, (int) trim((string) $zl)));
	$levels = array($lev);
	$sumHint = 0;
	// Lifestyle: soft min-ext schedule first (≥48 MiB → -1; ≥16 → 10; ≥8 → 15; else 19)
	// so we always at least tie. Then race a stronger level when the wall allows —
	// soft only measures the weak level, so a cheap upgrade becomes a sole win
	// (enwik8 -10, mozilla -10, webster -15, silesia -19).
	if(fractal_zip::lifestyle_speed_profile_enabled() && ($zl === false || trim((string) $zl) === '')) {
		if(is_array($rawFilesByPathOrNull)) {
			foreach($rawFilesByPathOrNull as $b) {
				$sumHint += strlen((string) $b);
			}
		} else {
			$sumHint = $this->folder_raw_total_bytes($rp);
		}
		if($sumHint >= 48 * 1024 * 1024) {
			$lev = 1;
			$levels = array(1);
			$pre = false;
			$pathIter = array();
			if(is_array($rawFilesByPathOrNull) && $rawFilesByPathOrNull !== array()) {
				$pathIter = array_keys($rawFilesByPathOrNull);
			} else {
				try {
					$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($rp, FilesystemIterator::SKIP_DOTS));
					foreach($it as $fi) {
						if($fi->isFile()) {
							$pathIter[] = $fi->getFilename();
						}
					}
				} catch(Throwable $e) {
					$pathIter = array();
				}
			}
			foreach($pathIter as $zp) {
				if(preg_match('/\\.(zip|gz|bz2|xz|7z|rar)$/i', (string) $zp)) {
					$pre = true;
					break;
				}
			}
			// Precompressed ≤80 MiB: -19 (silesia) matches ref; soft pin covers ~20 s.
			if($pre && $sumHint <= 80 * 1024 * 1024) {
				$lev = 19;
				$levels = array(19);
			} elseif($sumHint <= 128 * 1024 * 1024) {
				// enwik8-class text: -10 soles vs soft -1; escalate to -19 when
				// still ≤35% raw (~3.6 MiB) — soft midsize pin keeps the wall free.
				$levels = array(1, 10);
			}
		} elseif($sumHint >= 16 * 1024 * 1024) {
			$lev = 6;
			$levels = array(6);
		} elseif($sumHint >= 8 * 1024 * 1024) {
			$lev = 6;
			$levels = array(6);
		} elseif($sumHint >= 2 * 1024 * 1024) {
			// Soft midsize: -6 under 0.30× (was -19/-15 dual).
			$lev = 6;
			$levels = array(6);
			if(is_array($rawFilesByPathOrNull) && $rawFilesByPathOrNull !== array()) {
				$allZip = true;
				foreach(array_keys($rawFilesByPathOrNull) as $zp) {
					if(!preg_match('/\\.zip$/i', (string) $zp)) {
						$allZip = false;
						break;
					}
				}
				if($allZip) {
					$levels = array(10);
				}
			}
		} else {
			$levels = array($lev);
		}
	}
	$bestBlob = null;
	$bestLen = null;
	foreach($levels as $tryLev) {
		$tryLev = max(1, min(22, (int) $tryLev));
		$ultraFrag = ($tryLev >= 20) ? ' --ultra' : '';
		$compressorArgv = fractal_zip::shell_quote_arg_cached($zstdExe)
			. $ultraFrag
			. ' -' . (string) $tryLev
			. fractal_zip::bench_zstd_thread_shell_fragment_for_exec()
			. ' -c';
		$outZst = sys_get_temp_dir() . DS . 'fzzsbench_' . md5($rp . "\0zst" . (string) $tryLev) . '.zst';
		if(is_file($outZst)) {
			@unlink($outZst);
		}
		$cwd = getcwd();
		$ret = -1;
		$blob = null;
		if(@chdir($rp)) {
			$cmd = 'tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' . 2>/dev/null | '
				. $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($outZst) . ' 2>/dev/null';
			exec($cmd, $xo, $ret);
		}
		if($cwd !== false) {
			chdir($cwd);
		}
		if($ret === 0 && is_file($outZst)) {
			$r = @file_get_contents($outZst);
			if($r !== false && $r !== '') {
				$blob = $r;
			}
		}
		if(is_file($outZst)) {
			@unlink($outZst);
		}
		if($blob === null || $blob === '') {
			continue;
		}
		$n = strlen($blob);
		if($bestLen === null || $n < $bestLen) {
			$bestBlob = $blob;
			$bestLen = $n;
		}
	}
	// After -10, -19 reclaims multi‑MiB on enwik8-class (≤35% raw). Appended
	// levels are not reliably visited by foreach — run a dedicated pass.
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& $bestLen !== null && $sumHint > 0
		&& $bestLen < (int) ($sumHint * 0.35)
		&& in_array(10, $levels, true) && !in_array(19, $levels, true)) {
		$tryLev = 19;
		$compressorArgv = fractal_zip::shell_quote_arg_cached($zstdExe)
			. ' -' . (string) $tryLev
			. fractal_zip::bench_zstd_thread_shell_fragment_for_exec()
			. ' -c';
		$outZst = sys_get_temp_dir() . DS . 'fzzsbench_' . md5($rp . "\0zst19") . '.zst';
		if(is_file($outZst)) {
			@unlink($outZst);
		}
		$cwd = getcwd();
		$ret = -1;
		if(@chdir($rp)) {
			$cmd = 'tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' . 2>/dev/null | '
				. $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($outZst) . ' 2>/dev/null';
			exec($cmd, $xo, $ret);
		}
		if($cwd !== false) {
			chdir($cwd);
		}
		if($ret === 0 && is_file($outZst)) {
			$r = @file_get_contents($outZst);
			if($r !== false && $r !== '' && strlen($r) < $bestLen) {
				$bestBlob = $r;
				$bestLen = strlen($r);
			}
		}
		if(is_file($outZst)) {
			@unlink($outZst);
		}
	}
	// After -19, --ultra -22 reclaims ~1.6 MiB on enwik8-class (still ≤30% raw).
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& $bestLen !== null && $sumHint > 0
		&& $sumHint >= 48 * 1024 * 1024 && $sumHint <= 128 * 1024 * 1024
		&& $bestLen < (int) ($sumHint * 0.30)) {
		$tryLev = 22;
		$compressorArgv = fractal_zip::shell_quote_arg_cached($zstdExe)
			. ' --ultra -' . (string) $tryLev
			. fractal_zip::bench_zstd_thread_shell_fragment_for_exec()
			. ' -c';
		$outZst = sys_get_temp_dir() . DS . 'fzzsbench_' . md5($rp . "\0zst22") . '.zst';
		if(is_file($outZst)) {
			@unlink($outZst);
		}
		$cwd = getcwd();
		$ret = -1;
		if(@chdir($rp)) {
			$cmd = 'tar cf - --exclude=\'*.fz\' --exclude=\'*.fzc\' --exclude=\'*.fractalzip\' . 2>/dev/null | '
				. $compressorArgv . ' > ' . fractal_zip::shell_quote_arg_cached($outZst) . ' 2>/dev/null';
			exec($cmd, $xo, $ret);
		}
		if($cwd !== false) {
			chdir($cwd);
		}
		if($ret === 0 && is_file($outZst)) {
			$r = @file_get_contents($outZst);
			if($r !== false && $r !== '' && strlen($r) < $bestLen) {
				$bestBlob = $r;
				$bestLen = strlen($r);
			}
		}
		if(is_file($outZst)) {
			@unlink($outZst);
		}
	}
	return $bestBlob;
}

/**
 * After fractal wire bytes are chosen (unified stream, bundle-only, gzip-fast adaptive, legacy multipass): try native FreeArc, 7z, tar|brotli, then zpaq when smaller.
 *
 * @param array<string,string> $rawFilesByPath
 * @return array{0: string, 1: string|null} Wire body and native pick label when replaced, else {@code null} pick.
 */
function folder_wire_after_literal_outer_try_native_folder_archives($rootDir, $fzcBody, array $rawFilesByPath, string $pipelineSegmentPrefix): array {
	$fzcBody = (string) $fzcBody;
	if($rawFilesByPath === array()) {
		return array($fzcBody, null);
	}
	if(fractal_zip::folder_native_wire_compare_fully_disabled()) {
		return array($fzcBody, null);
	}
	if(function_exists('fractal_zip_stacked_outer_skip_native_wire_compares')
		&& fractal_zip_stacked_outer_skip_native_wire_compares(is_array($this->enwik_zip_ctx ?? null) ? $this->enwik_zip_ctx : null)) {
		return array($fzcBody, null);
	}
	$sumRaw = 0;
	foreach($rawFilesByPath as $rb) {
		$sumRaw += strlen((string) $rb);
	}
	// Lifestyle: skip native compares when the fractal/RG body is already a decisive win
	// vs raw (showing_off multifile). Do NOT skip on weak bodies (test_files148 needs Arc).
	$wireLen = strlen($fzcBody);
	if(fractal_zip::lifestyle_speed_profile_enabled()
		&& $wireLen <= 8192
		&& $sumRaw >= 65536
		&& $wireLen * 50 < $sumRaw) {
		fractal_zip::$last_zpaq_method = null;
		return array($fzcBody, null);
	}
	$lifestyleTinyNative = fractal_zip::lifestyle_should_skip_heavy_startup_for_raw_bytes($sumRaw);
	// Lifestyle tiny: skip zpaq/xz storms; still race Arc+7z+brotli so near-tie
	// wires (test_files181 zstd 2045 vs br/7z ~2030) can match min-ext.
	if($lifestyleTinyNative) {
		$nativePick = null;
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
		$fzcArcNative = $this->maybe_folder_freearc_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_freearc_native_compare');
		if($fzcArcNative !== null) {
			$fzcBody = $fzcArcNative;
			$nativePick = 'arc_native';
		}
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
		$fzc7zNative = $this->maybe_folder_7z_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_7z_native_compare');
		if($fzc7zNative !== null) {
			$fzcBody = $fzc7zNative;
			$nativePick = '7z_native';
		}
		// Tiny HTML/misc (test_files13): Arc/7z alone lose to min-ext brotli — keep brotli in the race.
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
		$fzcBrNative = $this->maybe_folder_brotli_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_brotli_native_compare');
		if($fzcBrNative !== null) {
			$fzcBody = $fzcBrNative;
			$nativePick = 'brotli_native';
		}
		// test_files81: min-ext xz can edge 7z/brotli by tens of bytes on ≤512 KiB trees.
		if($sumRaw <= 8 * 1024 * 1024) {
			fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
			$fzcXzNative = $this->maybe_folder_xz_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
			fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_xz_native_compare');
			if($fzcXzNative !== null) {
				$fzcBody = $fzcXzNative;
				$nativePick = 'xz_native';
			}
		}
		fractal_zip::$last_zpaq_method = null;
		return array($fzcBody, $nativePick);
	}
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
	$fzcPassthrough = $this->maybe_folder_freearc_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_freearc_native_compare');
	$nativePick = null;
	if($fzcPassthrough !== null) {
		$fzcBody = $fzcPassthrough;
		$nativePick = 'arc_native';
	}
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
	$fzc7zNative = $this->maybe_folder_7z_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_7z_native_compare');
	if($fzc7zNative !== null) {
		$fzcBody = $fzc7zNative;
		$nativePick = '7z_native';
	}
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
	$fzcBrNative = $this->maybe_folder_brotli_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_brotli_native_compare');
	if($fzcBrNative !== null) {
		$fzcBody = $fzcBrNative;
		$nativePick = 'brotli_native';
	}
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
	$fzcXzNative = $this->maybe_folder_xz_native_smaller_than_fzc($rootDir, $fzcBody, $sumRaw, $rawFilesByPath);
	fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_xz_native_compare');
	if($fzcXzNative !== null) {
		$fzcBody = $fzcXzNative;
		$nativePick = 'xz_native';
	}
	if(fractal_zip::folder_native_skip_zpaq_after_tiny_wire(strlen($fzcBody), $sumRaw)) {
		fractal_zip::$last_zpaq_method = null;
		return array($fzcBody, $nativePick);
	}
	// Lifestyle: skip native zpaq storms by default (kennedy-class OLE; adaptive
	// zpaq already covers midsize singles). Explicit FRACTAL_ZIP_PAQ_NATIVE_COMPARE=1
	// still runs PAQ native so soles like test_files118 stay reproducible.
	$lifestyle = fractal_zip::lifestyle_speed_profile_enabled();
	$paqNativeOptIn = function_exists('fractal_zip_paq_native_compare_enabled')
		&& fractal_zip_paq_native_compare_enabled();
	$runZpaqNative = !$lifestyle;
	$runPaqNative = !$lifestyle || $paqNativeOptIn;
	if(!$runZpaqNative && !$runPaqNative) {
		fractal_zip::$last_zpaq_method = null;
		return array($fzcBody, $nativePick);
	}
	if($runZpaqNative) {
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
		$fzcZpaqNative = $this->maybe_folder_zpaq_native_smaller_than_fzc($rootDir, $fzcBody, $rawFilesByPath);
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_zpaq_native_compare');
		if($fzcZpaqNative !== null) {
			$fzcBody = $fzcZpaqNative;
			$nativePick = 'zpaq_native';
		}
	}
	if($runPaqNative) {
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_sync_clock();
		$fzcPaqNative = $this->maybe_folder_paq_native_smaller_than_fzc($rootDir, $fzcBody, $rawFilesByPath);
		fractal_zip_encode_pipeline::pipeline_outer_step_rollup_zip_folder_segment($pipelineSegmentPrefix . '_maybe_paq_native_compare');
		if($fzcPaqNative !== null) {
			$fzcBody = $fzcPaqNative;
			$nativePick = 'paq_native';
		}
	}
	if($nativePick === 'arc_native') {
		fractal_zip::$last_zpaq_method = null;
	}

	return array($fzcBody, $nativePick);
}

/**
 * @param array<string,string>|null $rawFilesByPath In-memory bundle from collect_raw_files_for_bundle (same root as $dir) to skip re-reading files for Arc.
 * @return string|null raw FreeArc folder archive bytes if smaller than $fzcBody, else null
 */
function maybe_folder_freearc_native_smaller_than_fzc($dir, $fzcBody, $sumRawBytes, $rawFilesByPath = null) {
	$fzcBody = (string) $fzcBody;
	if($fzcBody === '' || !fractal_zip::folder_native_freearc_compare_enabled()) {
		return null;
	}
	// Respect forced outer selection: do not swap final container codec via native Arc compare.
	if(fractal_zip::outer_force_codec_is_gzip() || fractal_zip::outer_force_codec_is_zpaq()) {
		return null;
	}
	// Already on FreeArc (lifestyle seed / prior compare): rebuilding Arc is pure wall.
	$curCodec = is_string(fractal_zip::$last_written_container_codec)
		? fractal_zip::$last_written_container_codec
		: (is_string(fractal_zip::$last_outer_codec) ? fractal_zip::$last_outer_codec : '');
	if($curCodec === 'arc') {
		return null;
	}
	$cap = fractal_zip::folder_native_freearc_compare_max_raw_bytes_effective((int) $sumRawBytes);
	if($cap > 0 && $sumRawBytes > $cap) {
		return null;
	}
	$native = $this->try_build_folder_freearc_native_archive_blob($dir, $rawFilesByPath, $sumRawBytes);
	if($native === null || $native === '') {
		return null;
	}
	$currentCodec = is_string(fractal_zip::$last_written_container_codec) ? fractal_zip::$last_written_container_codec : 'store';
	if(!fractal_zip::outer_candidate_beats_current('arc', strlen($native), $currentCodec, strlen($fzcBody))) {
		return null;
	}
	fractal_zip::$last_outer_codec = 'arc';
	fractal_zip::$last_written_container_codec = 'arc';
	return $native;
}

/**
 * @param array<string,string>|null $rawFilesByPath
 * @return string|null Bench-identical raw native folder {@code .7z} bytes when smaller than $fzcBody (matches min-ext 7z column). Legacy {@code N}/{@code FZ}+7z / {@code FZ7\x01} / {@code FZ7F\x01} still extract.
 */
function maybe_folder_7z_native_smaller_than_fzc($dir, $fzcBody, $sumRawBytes, $rawFilesByPath = null) {
	$fzcBody = (string) $fzcBody;
	if($fzcBody === '' || !fractal_zip::folder_native_7z_compare_enabled()) {
		return null;
	}
	if(fractal_zip::outer_force_codec_is_gzip() || fractal_zip::outer_force_codec_is_zpaq()) {
		return null;
	}
	$cap = fractal_zip::folder_native_7z_compare_max_raw_bytes();
	fractal_zip_ensure_folder_per_member_best_loaded();
	$cap = fractal_zip_folder_native_compare_cap_effective((int) $cap, (int) $sumRawBytes);
	if($cap > 0 && (int) $sumRawBytes > $cap) {
		return null;
	}
	$native = $this->try_build_folder_7z_native_archive_blob($dir, $rawFilesByPath);
	if($native === null || $native === '') {
		return null;
	}
	$currentCodec = is_string(fractal_zip::$last_written_container_codec) ? fractal_zip::$last_written_container_codec : 'store';
	if(!fractal_zip::outer_candidate_beats_current('7z', strlen($native), $currentCodec, strlen($fzcBody))) {
		return null;
	}
	fractal_zip::$last_outer_codec = '7z';
	fractal_zip::$last_written_container_codec = '7z';
	return $native;
}

/**
 * Native folder {@code tar cf - . | brotli} bytes prefixed with {@code FZLB\x01} (5 B) when smaller than $fzcBody (bench-aligned min-ext brotli).
 *
 * @param array<string,string>|null $rawFilesByPath
 * @return string|null
 */
function maybe_folder_brotli_native_smaller_than_fzc($dir, $fzcBody, $sumRawBytes, $rawFilesByPath = null) {
	$fzcBody = (string) $fzcBody;
	if($fzcBody === '' || !fractal_zip::folder_native_brotli_compare_enabled()) {
		return null;
	}
	if(fractal_zip::outer_force_codec_is_gzip() || fractal_zip::outer_force_codec_is_zpaq()) {
		return null;
	}
	$cap = fractal_zip::folder_native_brotli_compare_max_raw_bytes();
	fractal_zip_ensure_folder_per_member_best_loaded();
	$cap = fractal_zip_folder_native_compare_cap_effective((int) $cap, (int) $sumRawBytes);
	if($cap > 0 && (int) $sumRawBytes > $cap) {
		return null;
	}
	$native = $this->try_build_folder_brotli_native_tar_br_blob($dir, $rawFilesByPath);
	if($native === null || $native === '') {
		return null;
	}
	// Raw tar|brotli (no FZLB +5) so wire can tie min-ext .br; extractors accept raw + legacy FZLB.
	$currentCodec = is_string(fractal_zip::$last_written_container_codec) ? fractal_zip::$last_written_container_codec : 'store';
	if(!fractal_zip::outer_candidate_beats_current('brotli', strlen($native), $currentCodec, strlen($fzcBody))) {
		return null;
	}
	fractal_zip::$last_outer_codec = 'brotli';
	fractal_zip::$last_written_container_codec = 'brotli';

	return $native;
}

/**
 * Build a native zpaq folder archive (raw .zpaq bytes, no extra wrapper).
 * Returns archive bytes if smaller than $fzcBody; null otherwise.
 *
 * Runs whenever native zpaq on the raw tree beats the fractal container on wire bytes (not gated on adaptive outer=zpaq).
 * Raw total is capped by {@see fractal_zip::folder_native_zpaq_compare_max_raw_bytes} unless {@code FRACTAL_ZIP_FORCE_OUTER=zpaq}.
 * Disable entirely: {@code FRACTAL_ZIP_FOLDER_NATIVE_ZPAQ_COMPARE=0}.
 *
 * Default method ladder matches {@see outer_zpaq_blob} (m6 cap via {@see fractal_zip::ZPAQ_OUTER_METHOD_SIX_MAX_INNER_BYTES}
 * and {@see fractal_zip::zpaq_outer_auto_sweep_max_inner_bytes}; {@code FRACTAL_ZIP_ZPAQ_OUTER_SWEEP} non-empty adjusts the cap).
 * {@code FRACTAL_ZIP_ZPAQ_NATIVE_FULL_SWEEP_MAX_RAW_BYTES} (default 4 MiB) bounds the multi-method sweep; above it, a single m5 trial.
 *
 * @param array<string,string>|null $rawFilesByPath
 * @return string|null
 */
function maybe_folder_zpaq_native_smaller_than_fzc($dir, $fzcBody, $rawFilesByPath = null) {
	$fzcBody = (string) $fzcBody;
	if($fzcBody === '') {
		return null;
	}
	// Compare native zpaq folder archive wire bytes vs fractal container regardless of which outer won on the wrapped inner
	// (Squash-style raw tree; overlaps zpaq). Opt out: FRACTAL_ZIP_FOLDER_NATIVE_ZPAQ_COMPARE=0.
	if(getenv('FRACTAL_ZIP_FOLDER_NATIVE_ZPAQ_COMPARE') === '0') {
		return null;
	}
	if(!fractal_zip::outer_force_codec_is_zpaq()) {
		$sumCap = 0;
		if(is_array($rawFilesByPath)) {
			foreach($rawFilesByPath as $_b) {
				$sumCap += strlen((string) $_b);
			}
		}
		$capZ = fractal_zip::folder_native_zpaq_compare_max_raw_bytes();
		fractal_zip_ensure_folder_per_member_best_loaded();
		$capZ = fractal_zip_folder_native_compare_cap_effective((int) $capZ, $sumCap);
		if($capZ > 0 && $sumCap > $capZ) {
			return null;
		}
	}
	if(DIRECTORY_SEPARATOR === '\\') {
		return null;
	}
	$zpaqExe = fractal_zip::zpaq_executable();
	if($zpaqExe === null) {
		return null;
	}
	$rpZp = realpath((string) $dir);
	$boxKey = ($rpZp !== false) ? $rpZp : (string) $dir;
	$box = sys_get_temp_dir() . DS . 'fzzp_native_' . substr(md5($boxKey . "\0fzzp_native"), 0, 16);
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	mkdir($box, 0755, true);
	if(is_array($rawFilesByPath)) {
		foreach($rawFilesByPath as $rel => $bytes) {
			$rel = str_replace('\\', '/', (string) $rel);
			if($rel === '' || strpos($rel, '..') !== false) {
				continue;
			}
			$target = $box . DS . str_replace('/', DS, $rel);
			$parent = dirname($target);
			if(!is_dir($parent)) {
				mkdir($parent, 0755, true);
			}
			file_put_contents($target, (string) $bytes);
		}
	} else {
		$this->recursive_copy_directory($dir, $box);
	}
	$targetArg = '.';
	$sumRaw = 0;
	if(is_array($rawFilesByPath) && sizeof($rawFilesByPath) === 1) {
		foreach($rawFilesByPath as $rel => $_bytes) {
			$oneRel = str_replace('\\', '/', (string) $rel);
			if($oneRel !== '' && strpos($oneRel, '..') === false) {
				$targetArg = $oneRel;
			}
			$sumRaw += strlen((string) $_bytes);
			break;
		}
	} elseif(is_array($rawFilesByPath)) {
		foreach($rawFilesByPath as $_bytes) {
			$sumRaw += strlen((string) $_bytes);
		}
	}
	$candidates = fractal_zip::zpaq_outer_methods_argv_fragments_cached();
	if($candidates === []) {
		$v = fractal_zip::zpaq_method_env_trimmed_cached();
		if($v !== null) {
			$candidates[] = ($v !== '' && $v[0] === '-') ? (' ' . $v) : (' -method ' . $v);
		} else {
			// Align m6 trials with outer_zpaq_blob (sixCap + FRACTAL_ZIP_ZPAQ_OUTER_SWEEP). Optional
			// FRACTAL_ZIP_ZPAQ_NATIVE_FULL_SWEEP_MAX_RAW_BYTES (default 4 MiB) bounds the 6/5/4/3 ladder; above that, m5 only.
			$sw = fractal_zip::zpaq_outer_sweep_env_flags_cached();
			$sweepFromEnv = $sw['env_nonempty'];
			$autoMax = fractal_zip::zpaq_outer_auto_sweep_max_inner_bytes();
			$sixM = fractal_zip::ZPAQ_OUTER_METHOD_SIX_MAX_INNER_BYTES;
			$sixCap = $sweepFromEnv ? $sixM : (($autoMax > 0) ? min($sixM, $autoMax) : $sixM);
			$fullSweepMaxRaw = fractal_zip::zpaq_native_full_sweep_max_raw_bytes_cached();
			if($sumRaw > 0 && $fullSweepMaxRaw > 0 && $sumRaw <= $fullSweepMaxRaw) {
				$highMax = fractal_zip::zpaq_outer_high_method_max_inner_bytes();
				$highTail = ($highMax > 0 && $sumRaw <= $highMax) ? array(' -method 9', ' -method 8', ' -method 7') : array();
				$candidates = ($sumRaw <= $sixCap)
					? array_merge($highTail, array(' -method 6', ' -method 5', ' -method 4', ' -method 3'))
					: array_merge($highTail, array(' -method 5', ' -method 4', ' -method 3'));
			} else {
				$candidates = array(' -method 5');
			}
		}
	}
	$native = null;
	$nativeBestLen = PHP_INT_MAX;
	$winMeth = null;
	$cwd = getcwd();
	$fzcBodyLen = strlen($fzcBody);
	$currentFzcCodec = is_string(fractal_zip::$last_written_container_codec) ? fractal_zip::$last_written_container_codec : 'store';
	// One output path per call — unlink between method trials (same as a fresh temp name each time; avoids random_bytes + repeated shell-escape work).
	$arcPath = sys_get_temp_dir() . DS . 'fzzp_native_' . md5($box) . '.zpaq';
	if(@chdir($box)) {
		$prefix = $this->command_prefix_with_local_lib();
		$qZ = fractal_zip::shell_quote_arg_cached($zpaqExe);
		$qArc = fractal_zip::shell_quote_arg_cached($arcPath);
		$qTarg = fractal_zip::shell_quote_arg_cached($targetArg);
		$nativePar = null;
		if(sizeof($candidates) >= 2) {
			$boxAbs = realpath($box);
			if($boxAbs === false) {
				$boxAbs = $box;
			}
			$nativePar = fractal_zip_encode_pipeline::parallel_folder_native_zpaq_method_variant_trials($boxAbs, $candidates, $targetArg, $prefix, $zpaqExe);
		}
		$didParallelMerge = false;
		if(is_array($nativePar)) {
			$anyParBlob = false;
			foreach($nativePar as $_pb) {
				if(is_string($_pb) && $_pb !== '') {
					$anyParBlob = true;
					break;
				}
			}
			if($anyParBlob) {
				$didParallelMerge = true;
				foreach($candidates as $ci => $methArg) {
					if(!is_string($methArg)) {
						continue;
					}
					$r = isset($nativePar[$ci]) ? $nativePar[$ci] : null;
					if(!is_string($r) || $r === '') {
						continue;
					}
					$rLen = strlen($r);
					if(fractal_zip::outer_candidate_beats_current('zpaq', $rLen, $currentFzcCodec, $fzcBodyLen) && $rLen < $nativeBestLen) {
						$native = $r;
						$nativeBestLen = $rLen;
						$winMeth = $methArg;
					}
				}
			}
		}
		if(!$didParallelMerge) {
			foreach($candidates as $methArg) {
				if(is_file($arcPath)) {
					@unlink($arcPath);
				}
				$cmd = $prefix . $qZ . fractal_zip::zpaq_global_argv_shell_after_exe_from_env() . ' add ' . $qArc . ' ' . $qTarg . $methArg . ' -force';
				exec($cmd . ' 2>/dev/null', $xo, $ret);
				if($ret === 0 && is_file($arcPath)) {
					$r = @file_get_contents($arcPath);
					if($r !== false && $r !== '') {
						$rLen = strlen($r);
						if(fractal_zip::outer_candidate_beats_current('zpaq', $rLen, $currentFzcCodec, $fzcBodyLen) && $rLen < $nativeBestLen) {
							$native = $r;
							$nativeBestLen = $rLen;
							$winMeth = $methArg;
						}
					}
				}
				if(is_file($arcPath)) {
					@unlink($arcPath);
				}
			}
		}
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	if($native === null) {
		return null;
	}
	if($winMeth !== null) {
		fractal_zip::zpaq_set_last_method_from_argv_fragment($winMeth);
	}
	fractal_zip::$last_outer_codec = 'zpaq';
	fractal_zip::$last_written_container_codec = 'zpaq';
	return $native;
}

/**
 * Native PAQ-class passthrough (phda9/paq8px/cmix) when smaller than fractal wire.
 *
 * @param array<string,string>|null $rawFilesByPath
 * @return string|null FZpq-wrapped archive bytes
 */
function maybe_folder_paq_native_smaller_than_fzc($dir, $fzcBody, $rawFilesByPath = null) {
	$fzcBody = (string) $fzcBody;
	if($fzcBody === '' || !fractal_zip_paq_native_compare_enabled()) {
		return null;
	}
	if(DIRECTORY_SEPARATOR === '\\') {
		return null;
	}
	if(fractal_zip_paq_discover_tools() === array()) {
		return null;
	}
	$sumRaw = 0;
	if(is_array($rawFilesByPath)) {
		foreach($rawFilesByPath as $_b) {
			$sumRaw += strlen((string) $_b);
		}
	}
	$cap = fractal_zip_paq_native_max_raw_bytes();
	if($cap > 0 && $sumRaw > $cap) {
		return null;
	}
	$box = sys_get_temp_dir() . DS . 'fzpaq_native_' . substr(md5((string) $dir . "\0paq"), 0, 16);
	if(is_dir($box)) {
		$this->recursive_remove_directory($box);
	}
	mkdir($box, 0755, true);
	$targetRel = '.';
	if(is_array($rawFilesByPath)) {
		foreach($rawFilesByPath as $rel => $bytes) {
			$rel = str_replace('\\', '/', (string) $rel);
			if($rel === '' || strpos($rel, '..') !== false) {
				continue;
			}
			$target = $box . DS . str_replace('/', DS, $rel);
			$parent = dirname($target);
			if(!is_dir($parent)) {
				mkdir($parent, 0755, true);
			}
			file_put_contents($target, (string) $bytes);
		}
		if(sizeof($rawFilesByPath) === 1) {
			foreach($rawFilesByPath as $rel => $_b) {
				$oneRel = str_replace('\\', '/', (string) $rel);
				if($oneRel !== '' && strpos($oneRel, '..') === false) {
					$targetRel = $oneRel;
				}
				break;
			}
		}
	} else {
		$this->recursive_copy_directory($dir, $box);
	}
	$r = fractal_zip_paq_smallest_single_file_archive($box, $targetRel);
	$this->recursive_remove_directory($box);
	if(!is_string($r['bytes']) || $r['bytes'] === '' || !is_string($r['tool'])) {
		return null;
	}
	$wire = fractal_zip_paq_wrap_wire($r['tool'], $r['bytes']);
	$currentCodec = is_string(fractal_zip::$last_written_container_codec) ? fractal_zip::$last_written_container_codec : 'store';
	if(!fractal_zip::outer_candidate_beats_current('paq', strlen($wire), $currentCodec, strlen($fzcBody))) {
		return null;
	}
	fractal_zip::$last_outer_codec = 'paq';
	fractal_zip::$last_written_container_codec = 'paq';
	return $wire;
}

/**
 * Extract FZpq native PAQ passthrough into $destRootDir (single restored member).
 */
function paq_try_extract_native_folder_archive_to_directory($fullContents, $destRootDir, $debug) {
	$un = fractal_zip_paq_unwrap_wire((string) $fullContents);
	if($un === null) {
		return false;
	}
	$toolId = (string) $un['tool'];
	$exe = fractal_zip_paq_discover_executable($toolId);
	if($exe === null) {
		return false;
	}
	$sandbox = sys_get_temp_dir() . DS . 'fzpaq_x_' . getmypid() . '_' . substr(md5($un['payload'] . "\0" . microtime(true)), 0, 12);
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	@mkdir($sandbox, 0755, true);
	// paq8px v215 refuses / mis-handles a bare ".paq" name — keep the
	// compressor's preferred suffix when the payload looks like a paq8px archive.
	$arcName = 'in.paq';
	$payHead = substr((string) $un['payload'], 0, 16);
	if($toolId === 'paq8px' || $toolId === 'paq8pxd' || str_starts_with($payHead, 'paq8px')) {
		$arcName = 'in.paq8px215';
	}
	$arcPath = $sandbox . DS . $arcName;
	$outPath = $sandbox . DS . 'out.bin';
	if(@file_put_contents($arcPath, $un['payload']) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	if(!fractal_zip_paq_decompress_to_file($toolId, $exe, $arcPath, $outPath)) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$bytes = @file_get_contents($outPath);
	if($bytes === false || $bytes === '') {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$destRel = '';
	if(is_string($un['path'] ?? null) && (string) $un['path'] !== '') {
		$destRel = str_replace('\\', '/', (string) $un['path']);
		if(strpos($destRel, '..') !== false) {
			$destRel = basename($destRel);
		}
	}
	if($destRel === '' && is_array($this->array_fractal_zipped_strings_of_files) && sizeof($this->array_fractal_zipped_strings_of_files) === 1) {
		$keys = array_keys($this->array_fractal_zipped_strings_of_files);
		if(isset($keys[0]) && is_string($keys[0]) && $keys[0] !== '') {
			$destRel = str_replace('\\', '/', $keys[0]);
		}
	}
	if($destRel === '') {
		$destRel = 'enwik8';
	}
	$destFile = rtrim((string) $destRootDir, DS) . DS . str_replace('/', DS, $destRel);
	$parent = dirname($destFile);
	if(!is_dir($parent)) {
		mkdir($parent, 0755, true);
	}
	@file_put_contents($destFile, $bytes);
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array($destRel => '');
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted native PAQ passthrough (FZpq).<br>');
	}
	return true;
}

/**
 * If $fullContents is legacy `FZFA\x01` + arc, or raw native folder Arc (not single-member `i`), extract into $destRootDir
 * and clear fractal member state. Returns true when handled (caller skips adaptive_decompress).
 */
function freearc_try_extract_native_folder_arc_to_directory($fullContents, $destRootDir, $debug) {
	$fullContents = (string) $fullContents;
	if(strlen($fullContents) >= 5 && substr($fullContents, 0, 4) === 'FZFA' && $fullContents[4] === "\x01") {
		$this->extract_freearc_native_archive_blob_to_directory(substr($fullContents, 5), $destRootDir, $debug);
		$this->array_fractal_zipped_strings_of_files = array();
		$this->fractal_string = '';
		$this->fractal_gzip_peel_restore_map = array();
		return true;
	}
	if(strlen($fullContents) < 4 || $fullContents[0] !== 'A' || $fullContents[1] !== 'r' || $fullContents[2] !== 'C' || $fullContents[3] !== chr(1)) {
		return false;
	}
	if(DIRECTORY_SEPARATOR === '\\') {
		return false;
	}
	$arcExe = fractal_zip::freearc_executable();
	if($arcExe === null) {
		return false;
	}
	$u = substr(md5(fractal_zip::hot_string_digest($fullContents) . "\0fzfc_arc\0" . (string) spl_object_id($this)), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fzfc_s_' . $u;
	$tmpArc = $sandbox . DS . 'in.arc';
	$tmpOut = $sandbox . DS . 'out';
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		return false;
	}
	if(@file_put_contents($tmpArc, $fullContents) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$cwd = getcwd();
	$ret = -1;
	if(chdir($tmpOut)) {
		$prefix = $this->command_prefix_with_local_lib();
		$cmd = $prefix . fractal_zip::shell_quote_arg_cached($arcExe) . fractal_zip::library_arc_compress_mt_shell_fragment_for_exec() . ' x -y ' . escapeshellarg($tmpArc) . ' 2>/dev/null';
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if($ret !== 0) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$sd = @scandir($tmpOut);
	$entries = is_array($sd) ? array_values(array_diff($sd, array('.', '..'))) : array();
	$legacySingleI = (sizeof($entries) === 1 && isset($entries[0]) && $entries[0] === 'i' && is_file($tmpOut . DS . 'i'));
	if($legacySingleI) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted native FreeArc folder archive (raw ARC bytes in .fz).<br>');
	}
	return true;
}

/**
 * Run zpaq x on raw arc bytes into $destRootDir. Returns false for single-inner outer payloads (not folder archives).
 */
function zpaq_extract_arc_bytes_to_directory(string $arc, string $destRootDir, bool $debug): bool {
	if(DIRECTORY_SEPARATOR === '\\') {
		return false;
	}
	$zpaqExe = fractal_zip::zpaq_executable();
	if($zpaqExe === null || $arc === '') {
		return false;
	}
	$digest16 = substr(hash('sha256', $arc), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fzpa_s_' . $digest16;
	$tmpArc = $sandbox . DS . 'in.zpaq';
	$tmpOut = $sandbox . DS . 'out';
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		return false;
	}
	if(@file_put_contents($tmpArc, $arc) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$prefix = $this->command_prefix_with_local_lib();
	$timeoutPre = fractal_zip::zpaq_extract_exec_timeout_prefix_cached();
	$timeoutSec = fractal_zip::zpaq_extract_exec_timeout_seconds_cached();
	$cmd = $prefix . $timeoutPre . fractal_zip::shell_quote_arg_cached($zpaqExe) . fractal_zip::zpaq_global_argv_shell_after_exe_from_env() . ' x ' . escapeshellarg($tmpArc)
		. ' -to ' . escapeshellarg($tmpOut) . ' -force';
	fractal_zip_native_extract_cache_log('spawn zpaq digest16=' . $digest16 . ' dest=' . $destRootDir);
	$result = fractal_zip::exec_shell_with_timeout_and_kill($cmd . ' 2>/dev/null', $timeoutSec);
	$ret = (int) ($result['exit'] ?? 1);
	if(!$result['ok']) {
		$this->recursive_remove_directory($sandbox);
		fractal_zip_native_extract_cache_log('zpaq exit ' . $ret . ' digest16=' . $digest16);
		return false;
	}
	$sd = @scandir($tmpOut);
	$entries = is_array($sd) ? array_values(array_diff($sd, array('.', '..'))) : array();
	$singleInner = (sizeof($entries) === 1
		&& isset($entries[0])
		&& ($entries[0] === 'inner.bin' || $entries[0] === 'i')
		&& is_file($tmpOut . DS . $entries[0]));
	if($singleInner) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandbox);
	if($debug) {
		fractal_zip::html_trace_print('Extracted native zpaq folder archive (FZPA wrapper).<br>');
	}
	return true;
}

/**
 * Ensure persistent cache holds extracted native zpaq folder members; returns members root or null.
 */
function zpaq_ensure_native_folder_extract_cache(string $arc): ?string {
	if($arc === '' || DIRECTORY_SEPARATOR === '\\') {
		return null;
	}
	$self = $this;
	return fractal_zip_native_extract_cache_ensure('fzpa', $arc, static function (string $membersRoot) use ($self, $arc): bool {
		return $self->zpaq_extract_arc_bytes_to_directory($arc, $membersRoot, false);
	});
}

/** @return string|null member bytes when cache lane succeeds */
function zpaq_try_read_member_bytes_from_extract_cache(string $containerPath, string $memberRelPath): ?string {
	$raw = @file_get_contents($containerPath);
	if($raw === false || $raw === '') {
		return null;
	}
	$arc = fractal_zip_native_zpaq_arc_from_container_bytes($raw);
	if($arc === null) {
		return null;
	}
	$digest = fractal_zip_native_extract_cache_digest($arc);
	$fromManifest = fractal_zip_native_extract_cache_read_member_from_manifest($digest, $memberRelPath);
	if($fromManifest !== null) {
		return $fromManifest;
	}
	$membersRoot = $this->zpaq_ensure_native_folder_extract_cache($arc);
	if($membersRoot === null) {
		return null;
	}
	return fractal_zip_native_extract_cache_read_member($membersRoot, $memberRelPath);
}

/** @return array{bytes: string, lane: string}|null */
function zpaq_try_read_member_from_extract_cache_with_lane(string $containerPath, string $memberRelPath): ?array {
	$raw = @file_get_contents($containerPath);
	if($raw === false || $raw === '') {
		return null;
	}
	$arc = fractal_zip_native_zpaq_arc_from_container_bytes($raw);
	if($arc === null) {
		return null;
	}
	$digest = fractal_zip_native_extract_cache_digest($arc);
	$fromManifest = fractal_zip_native_extract_cache_read_member_from_manifest($digest, $memberRelPath);
	if($fromManifest !== null) {
		return array('bytes' => $fromManifest, 'lane' => 'fzpa_manifest_blob');
	}
	$membersRoot = $this->zpaq_ensure_native_folder_extract_cache($arc);
	if($membersRoot === null) {
		return null;
	}
	$fromTree = fractal_zip_native_extract_cache_read_member($membersRoot, $memberRelPath);
	if($fromTree === null) {
		return null;
	}
	return array('bytes' => $fromTree, 'lane' => 'fzpa_extract_cache');
}

/** @return list<string>|null sorted member relpaths when cache lane succeeds */
function zpaq_try_list_members_from_extract_cache(string $containerPath): ?array {
	$raw = @file_get_contents($containerPath);
	if($raw === false || $raw === '') {
		return null;
	}
	$arc = fractal_zip_native_zpaq_arc_from_container_bytes($raw);
	if($arc === null) {
		return null;
	}
	$digest = fractal_zip_native_extract_cache_digest($arc);
	$fromManifest = fractal_zip_native_extract_cache_list_members_from_manifest($digest);
	if($fromManifest !== null) {
		return $fromManifest;
	}
	$membersRoot = $this->zpaq_ensure_native_folder_extract_cache($arc);
	if($membersRoot === null) {
		return null;
	}
	$members = fractal_zip_native_extract_cache_list_members($membersRoot);
	return $members === array() ? null : $members;
}

/** @return array{members: list<string>, list_lane: string}|null */
function zpaq_try_list_members_from_extract_cache_with_lane(string $containerPath): ?array {
	$raw = @file_get_contents($containerPath);
	if($raw === false || $raw === '') {
		return null;
	}
	$arc = fractal_zip_native_zpaq_arc_from_container_bytes($raw);
	if($arc === null) {
		return null;
	}
	$digest = fractal_zip_native_extract_cache_digest($arc);
	$fromManifest = fractal_zip_native_extract_cache_list_members_from_manifest($digest);
	if($fromManifest !== null) {
		return array('members' => $fromManifest, 'list_lane' => 'fzpa_manifest');
	}
	$membersRoot = $this->zpaq_ensure_native_folder_extract_cache($arc);
	if($membersRoot === null) {
		return null;
	}
	$members = fractal_zip_native_extract_cache_list_members($membersRoot);
	if($members === array()) {
		return null;
	}
	return array('members' => $members, 'list_lane' => 'fzpa_extract_cache');
}

/**
 * If payload is raw native folder zpaq archive (or legacy FZPA\x01 wrapper), extract into $destRootDir.
 */
function zpaq_try_extract_native_folder_archive_to_directory($fullContents, $destRootDir, $debug) {
	$arc = fractal_zip_native_zpaq_arc_from_container_bytes((string) $fullContents);
	if($arc === null) {
		return false;
	}
	if(fractal_zip_native_extract_cache_enabled()) {
		$extractRoot = $this->zpaq_ensure_native_folder_extract_cache($arc);
		if($extractRoot === null) {
			// Short wait only — a dead/stale filler must not burn the full 120 s
			// then fail closed (squash zpaq .fz verify hung under gold).
			$extractRoot = fractal_zip_native_extract_cache_wait_ready('fzpa', $arc, 2.0);
		}
		if($extractRoot !== null) {
			$this->recursive_copy_archive_output_directory_safely($extractRoot, $destRootDir);
			if($debug) {
				fractal_zip::html_trace_print('Materialized native zpaq folder archive from extract cache.<br>');
			}
			$this->array_fractal_zipped_strings_of_files = array();
			$this->fractal_string = '';
			$this->fractal_gzip_peel_restore_map = array();
			return true;
		}
		// Cache miss/stall: extract directly (same as cache-off).
	}
	if(!$this->zpaq_extract_arc_bytes_to_directory($arc, $destRootDir, $debug)) {
		return false;
	}
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	return true;
}

/**
 * If payload is raw 7z ({@code 7z\\xBC\\xAF\\x27\\x1C…}), {@code N}+raw 7z, legacy compact {@code FZ}+raw 7z, {@code FZ7\x01}, or {@code FZ7F\x01} + native folder 7z archive, extract into $destRootDir.
 */
function seven_zip_try_extract_native_folder_archive_to_directory($fullContents, $destRootDir, $debug) {
	$fullContents = (string) $fullContents;
	$n = strlen($fullContents);
	$b7 = fractal_zip::NATIVE_FOLDER_7Z_WIRE_BYTE;
	$arc = null;
	if($n >= 5 && substr($fullContents, 0, 4) === 'FZ7F' && $fullContents[4] === "\x01") {
		$arc = substr($fullContents, 5);
	} elseif($n >= 4 && substr($fullContents, 0, 3) === 'FZ7' && $fullContents[3] === "\x01") {
		$arc = substr($fullContents, 4);
	} elseif($n >= 7 && $fullContents !== '' && $fullContents[0] === $b7 && fractal_zip::payload_has_raw_seven_zip_signature(substr($fullContents, 1))) {
		$arc = substr($fullContents, 1);
	} elseif($n >= 8 && substr($fullContents, 0, 2) === 'FZ' && fractal_zip::payload_has_raw_seven_zip_signature(substr($fullContents, 2))) {
		$arc = substr($fullContents, 2);
	} elseif($n >= 6 && fractal_zip::payload_has_raw_seven_zip_signature($fullContents)) {
		$arc = $fullContents;
	}
	if($arc === null) {
		return false;
	}
	if($arc === '' || strlen($arc) < 2 || $arc[0] !== '7' || $arc[1] !== 'z') {
		return false;
	}
	$seven = fractal_zip::seven_zip_executable();
	if($seven === null) {
		return false;
	}
	$u = substr(md5(fractal_zip::hot_string_digest($arc) . "\0fz7f_in\0" . (string) spl_object_id($this)), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fz7f_s_' . $u;
	$tmpArc = $sandbox . DS . 'in.7z';
	$tmpOut = $sandbox . DS . 'out';
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		return false;
	}
	if(@file_put_contents($tmpArc, $arc) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$cmd = fractal_zip::shell_quote_arg_cached($seven)
		. fractal_zip::seven_zip_mmt_shell_fragment_for_exec()
		. ' x ' . fractal_zip::shell_quote_arg_cached($tmpArc) . ' -aoa -o' . fractal_zip::shell_quote_arg_cached($tmpOut);
	exec($cmd . ' 2>/dev/null', $xo, $ret);
	if((int) $ret !== 0) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted native 7z folder archive (raw/N/FZ/FZ7/FZ7F).<br>');
	}
	return true;
}

/**
 * If payload is {@code FZLB\x01} + raw brotli, or a raw tar|brotli frame (no wrapper), extract into $destRootDir.
 */
function brotli_try_extract_native_folder_tar_br_to_directory($fullContents, $destRootDir, $debug) {
	$fullContents = (string) $fullContents;
