	if(@file_put_contents($tmpBr, $br) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$cwd = getcwd();
	$ret = -1;
	if(@chdir($tmpOut)) {
		$cmd = fractal_zip::shell_quote_arg_cached($brotliExe) . ' -d -c ' . fractal_zip::shell_quote_arg_cached($tmpBr) . ' 2>/dev/null | tar xf - 2>/dev/null';
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if((int) $ret !== 0) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted native tar|brotli folder archive.<br>');
	}

	return true;
}

/**
 * Extract bench-aligned gzip9 packed bundle (raw zlib of u32 pathLen|path|u32 size|bytes records).
 */
function gzip9_bundle_try_extract_to_directory($fullContents, $destRootDir, $debug) {
	$fullContents = (string) $fullContents;
	if(strlen($fullContents) < 2 || $fullContents[0] !== "\x78") {
		return false;
	}
	$raw = @gzuncompress($fullContents);
	if(!is_string($raw) || $raw === '') {
		return false;
	}
	$n = strlen($raw);
	$off = 0;
	$wrote = 0;
	while($off + 8 <= $n) {
		$plen = unpack('N', substr($raw, $off, 4));
		$off += 4;
		$pathLen = is_array($plen) ? (int) $plen[1] : -1;
		if($pathLen < 0 || $pathLen > 4096 || $off + $pathLen + 4 > $n) {
			return false;
		}
		$rel = substr($raw, $off, $pathLen);
		$off += $pathLen;
		$slen = unpack('N', substr($raw, $off, 4));
		$off += 4;
		$size = is_array($slen) ? (int) $slen[1] : -1;
		if($size < 0 || $off + $size > $n) {
			return false;
		}
		$body = substr($raw, $off, $size);
		$off += $size;
		$rel = str_replace('\\', '/', (string) $rel);
		if($rel === '' || str_contains($rel, '..')) {
			return false;
		}
		$outPath = rtrim((string) $destRootDir, '/\\') . DS . str_replace('/', DS, $rel);
		$parent = dirname($outPath);
		if(!is_dir($parent) && !@mkdir($parent, 0755, true) && !is_dir($parent)) {
			return false;
		}
		if(@file_put_contents($outPath, $body) === false) {
			return false;
		}
		$wrote++;
	}
	if($wrote <= 0 || $off !== $n) {
		return false;
	}
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted gzip9 packed-bundle (zlib) folder archive.<br>');
	}
	return true;
}

/**
 * Stream-extract FZLB+brotli or raw tar|brotli from a container path.
 */
function brotli_try_extract_native_folder_tar_br_from_path($filename, $destRootDir, $debug, $skipBytes = 0) {
	if(DIRECTORY_SEPARATOR === '\\') {
		return false;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return false;
	}
	$brotliExe = fractal_zip::brotli_executable();
	if($brotliExe === null || !is_file((string) $filename)) {
		return false;
	}
	$skipBytes = max(0, (int) $skipBytes);
	$u = substr(md5((string) $filename . "\0fzlb_path\0" . (string) $skipBytes . "\0" . (string) spl_object_id($this)), 0, 16);
	$destParent = dirname((string) $destRootDir);
	$sandboxBase = (is_dir($destParent) && @is_writable($destParent))
		? ($destParent . DS . '.fzlb_p_' . $u)
		: (sys_get_temp_dir() . DS . 'fzlb_p_' . $u);
	$tmpOut = $sandboxBase . DS . 'out';
	if(is_dir($sandboxBase)) {
		$this->recursive_remove_directory($sandboxBase);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		return false;
	}
	$cwd = getcwd();
	$ret = -1;
	if(@chdir($tmpOut)) {
		if($skipBytes > 0) {
			$cmd = 'dd if=' . fractal_zip::shell_quote_arg_cached((string) $filename)
				. ' bs=1M skip=' . (int) $skipBytes . ' iflag=skip_bytes status=none 2>/dev/null | '
				. fractal_zip::shell_quote_arg_cached($brotliExe) . ' -d -c 2>/dev/null | tar xf - 2>/dev/null';
		} else {
			$cmd = fractal_zip::shell_quote_arg_cached($brotliExe) . ' -d -c '
				. fractal_zip::shell_quote_arg_cached((string) $filename)
				. ' 2>/dev/null | tar xf - 2>/dev/null';
		}
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if((int) $ret !== 0) {
		$this->recursive_remove_directory($sandboxBase);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandboxBase);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	fractal_zip::$open_container_streaming_extract_used = true;
	if($debug) {
		fractal_zip::html_trace_print('Extracted native tar|brotli folder archive (path stream).<br>');
	}
	return true;
}

