	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandboxBase);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	fractal_zip::$open_container_streaming_extract_used = true;
	if($debug) {
		fractal_zip::html_trace_print('Extracted native tar|zstd folder archive (path stream).<br>');
	}

	return true;
}

/**
 * Stream-extract {@code FZLZ\x01}+zstd from a container path without loading the archive into PHP.
 */
function zstd_try_extract_native_folder_tar_zst_from_path($filename, $destRootDir, $debug) {
	if(!is_file((string) $filename)) {
		return false;
	}
	$fh = @fopen((string) $filename, 'rb');
	if($fh === false) {
		return false;
	}
	$magic = fread($fh, 5);
	fclose($fh);
	if($magic === false || strlen($magic) !== 5 || substr($magic, 0, 4) !== 'FZLZ' || $magic[4] !== "\x01") {
		return false;
	}
	return $this->zstd_try_extract_raw_tar_zst_from_path($filename, $destRootDir, $debug, 5);
}

/**
 * Stream-extract raw tar|gzip ({@code 1f 8b}) folder archives (video lakes, test_files203).
 * Matches min-ext gzip wire without loading GiB containers into PHP.
 */
function gzip_try_extract_raw_tar_gz_from_path($filename, $destRootDir, $debug, $skipBytes = 0) {
	if(PHP_OS_FAMILY === 'Windows') {
		return false;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return false;
	}
	if(!is_file((string) $filename)) {
		return false;
	}
	$gzip = trim((string) shell_exec('command -v gzip 2>/dev/null'));
	$pigz = trim((string) shell_exec('command -v pigz 2>/dev/null'));
	if($gzip === '' && $pigz === '') {
		return false;
	}
	$decExe = ($pigz !== '') ? $pigz : $gzip;
	$skipBytes = max(0, (int) $skipBytes);
	$u = substr(md5((string) $filename . "\0fzgz_path\0" . (string) $skipBytes . "\0" . (string) spl_object_id($this)), 0, 16);
	$destParent = dirname((string) $destRootDir);
	$sandboxBase = (is_dir($destParent) && @is_writable($destParent))
		? ($destParent . DS . '.fzgz_p_' . $u)
		: (sys_get_temp_dir() . DS . 'fzgz_p_' . $u);
	$tmpOut = $sandboxBase . DS . 'out';
	if(is_dir($sandboxBase)) {
		$this->recursive_remove_directory($sandboxBase);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		return false;
	}
	$cwd = getcwd();
	$ret = -1;
	if(@chdir($tmpOut)) {
		if($skipBytes > 0) {
			$cmd = 'dd if=' . fractal_zip::shell_quote_arg_cached((string) $filename)
				. ' bs=1M skip=' . (int) $skipBytes . ' iflag=skip_bytes status=none 2>/dev/null | '
				. fractal_zip::shell_quote_arg_cached($decExe) . ' -d -c 2>/dev/null | tar xf - 2>/dev/null';
		} else {
			$cmd = fractal_zip::shell_quote_arg_cached($decExe) . ' -d -c '
				. fractal_zip::shell_quote_arg_cached((string) $filename)
				. ' 2>/dev/null | tar xf - 2>/dev/null';
		}
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if((int) $ret !== 0) {
		$this->recursive_remove_directory($sandboxBase);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandboxBase);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	fractal_zip::$open_container_streaming_extract_used = true;
	if($debug) {
		fractal_zip::html_trace_print('Extracted native tar|gzip folder archive (path stream).<br>');
	}

	return true;
}

/**
 * In-memory tar|gzip extract (small archives). Large lakes use
 * {@see gzip_try_extract_raw_tar_gz_from_path}.
 */
function gzip_try_extract_native_folder_tar_gz_to_directory($fullContents, $destRootDir, $debug) {
	$fullContents = (string) $fullContents;
	if(strlen($fullContents) < 2 || $fullContents[0] !== "\x1F" || $fullContents[1] !== "\x8B") {
		return false;
	}
	if(PHP_OS_FAMILY === 'Windows') {
		return false;
	}
	if(trim((string) shell_exec('command -v tar 2>/dev/null')) === '') {
		return false;
	}
	$gzip = trim((string) shell_exec('command -v gzip 2>/dev/null'));
	if($gzip === '') {
		return false;
	}
	$u = substr(md5(fractal_zip::hot_string_digest($fullContents) . "\0fzgz_in\0" . (string) spl_object_id($this)), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fzgz_s_' . $u;
	$tmpGz = $sandbox . DS . 'in.gz';
	$tmpOut = $sandbox . DS . 'out';
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		return false;
	}
	if(@file_put_contents($tmpGz, $fullContents) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$cwd = getcwd();
	$ret = -1;
	if(@chdir($tmpOut)) {
		$cmd = fractal_zip::shell_quote_arg_cached($gzip)
			. ' -d -c ' . fractal_zip::shell_quote_arg_cached($tmpGz) . ' 2>/dev/null | tar xf - 2>/dev/null';
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if((int) $ret !== 0) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted native tar|gzip folder archive.<br>');
	}

	return true;
}

/**
 * True when $blob starts with a self-describing outer magic (7z, zstd, xz, gzip, FZ-prefix, Arc, etc).
 * Used to avoid treating those as raw tar|brotli.
 */
function container_payload_has_self_describing_outer_magic($blob): bool {
	$head = substr((string) $blob, 0, 32);
	if($head === '') {
		return false;
	}
	if(substr($head, 0, 2) === '7z') {
		return true;
	}
	if(strlen($head) >= 4 && $head[0] === "\x28" && $head[1] === "\xB5" && $head[2] === "\x2F" && $head[3] === "\xFD") {
		return true;
	}
	if(strlen($head) >= 6 && substr($head, 0, 6) === "\xFD\x37\x7A\x58\x5A\x00") {
		return true;
	}
	if(strlen($head) >= 2 && $head[0] === "\x1F" && $head[1] === "\x8B") {
		return true;
	}
	// zlib (gzip9 packed-bundle wire)
	if(strlen($head) >= 2 && $head[0] === "\x78"
		&& ($head[1] === "\x01" || $head[1] === "\x9C" || $head[1] === "\xDA" || $head[1] === "\x5E")) {
		return true;
	}
	if(strlen($head) >= 2 && substr($head, 0, 2) === 'FZ') {
		return true;
	}
	$b7 = fractal_zip::NATIVE_FOLDER_7Z_WIRE_BYTE;
	if(strlen($head) >= 1 && $head[0] === $b7) {
		return true;
	}
	if(strlen($head) >= 4 && substr($head, 0, 3) === 'ARC') {
		return true;
	}
	$bMagic = fractal_zip::OUTER_BROTLI_MAGIC;
	if(strlen($head) >= strlen($bMagic) && substr($head, 0, strlen($bMagic)) === $bMagic) {
		return true;
	}
	return false;
}

/**
 * FZCL extract: nested unified body → logical members → CLASSIC disk rebuild.
 */
function fzcl_try_extract_classic_peeled_to_directory($fullContents, $destRootDir, $debug) {
	$classic = __DIR__ . DIRECTORY_SEPARATOR . 'fractal_zip_classic_peel.php';
	if(is_readable($classic)) {
		require_once $classic;
	}
	fractal_zip_ensure_folder_logical_bundle_loaded();
	if(!function_exists('fractal_zip_classic_decode_fzcl_v1')) {
		return false;
	}
	$decoded = fractal_zip_classic_decode_fzcl_v1((string) $fullContents);
	if($decoded === null) {
		return false;
	}
	$body = (string) ($decoded['body'] ?? '');
	$restoreSpecs = is_array($decoded['restore'] ?? null) ? $decoded['restore'] : array();
	$ver = (int) ($decoded['ver'] ?? 1);
	if($body === '') {
		return false;
	}
	$u = substr(md5(fractal_zip::hot_string_digest($body) . "\0fzcl_ex\0" . (string) spl_object_id($this)), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fzcl_s_' . $u;
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($sandbox, 0700, true)) {
		return false;
	}
	$bodyPath = $sandbox . DS . 'inner' . $this->fractal_zip_container_file_extension;
	if(@file_put_contents($bodyPath, $body) === false) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	$inner = new fractal_zip($this->segment_length, $this->multipass, false, null, false);
	ob_start();
	try {
		$inner->open_container($bodyPath, false);
	} catch(Throwable $e) {
		ob_end_clean();
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	ob_end_clean();
	@unlink($bodyPath);
	$sidecarName = function_exists('fractal_zip_classic_fzcl_restore_sidecar_name')
		? fractal_zip_classic_fzcl_restore_sidecar_name()
		: '.fzcl_restore';
	if($ver === 3 || $restoreSpecs === array()) {
		$sidePath = $sandbox . DS . $sidecarName;
		if(!is_file($sidePath)) {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		$fzhrBlob = @file_get_contents($sidePath);
		@unlink($sidePath);
		if(!is_string($fzhrBlob) || $fzhrBlob === '' || !function_exists('fractal_zip_decode_fzhr_v1')) {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		$hrOff = 0;
		$restoreSpecs = fractal_zip_decode_fzhr_v1($fzhrBlob, $hrOff);
		if(!is_array($restoreSpecs) || $restoreSpecs === array()) {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
	}
	// Index every extracted file under sandbox for restore + passthrough copy.
	$memberFiles = array();
	try {
		$it = new RecursiveIteratorIterator(
			new RecursiveDirectoryIterator($sandbox, FilesystemIterator::SKIP_DOTS)
		);
		$rootLen = strlen($sandbox) + 1;
		foreach($it as $fi) {
			if(!$fi->isFile()) {
				continue;
			}
			$abs = $fi->getPathname();
			$rel = str_replace('\\', '/', substr($abs, $rootLen));
			if($rel === '' || strpos($rel, '..') !== false) {
				continue;
			}
			$memberFiles[$rel] = $abs;
		}
	} catch(Throwable $e) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	if($memberFiles === array()) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	if(!fractal_zip_apply_folder_disk_restore((string) $destRootDir, $memberFiles, $restoreSpecs, $this)) {
		$this->recursive_remove_directory($sandbox);
		return false;
	}
	// Copy passthrough files (e.g. README) that are not peel lumps under FZHR restores.
	$peelTops = array();
	$peelPrefixes = array();
	$classicKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC')
		? (int) FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC
		: 3;
	$zipKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI')
		? (int) FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI
		: 1;
	$verbKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_VERBATIM')
		? (int) FRACTAL_ZIP_FOLDER_RESTORE_VERBATIM
		: 2;
	// Flat ZIP_MULTI Arc peels (silesia lifestyle): members extract as short
	// basenames, not under diskPath/ — skip those names from passthrough copy.
	$zipMemberSkip = array();
	foreach($restoreSpecs as $diskPath => $spec) {
		if(!is_array($spec)) {
			continue;
		}
		$k = (int) ($spec['kind'] ?? -1);
		if($k === $classicKind || $k === $zipKind || $k === $verbKind) {
			$dp = str_replace('\\', '/', (string) $diskPath);
			$peelTops[$dp] = true;
			// Nested peels (test_files61): skip staged chunks under diskPath/
			$peelPrefixes[$dp . '/'] = true;
		}
		if($k === $zipKind) {
			$names = $spec['member_names'] ?? null;
			if(is_array($names)) {
				foreach($names as $mn) {
					$mnN = str_replace('\\', '/', (string) $mn);
					if($mnN === '' || str_contains($mnN, '..')) {
						continue;
					}
					$zipMemberSkip[$mnN] = true;
					$base = basename($mnN);
					if($base !== '' && $base !== '.' && $base !== '..') {
						$zipMemberSkip[$base] = true;
					}
				}
			}
		}
	}
	foreach($memberFiles as $rel => $abs) {
		if(!is_file($abs)) {
			continue;
		}
		$relN = str_replace('\\', '/', (string) $rel);
		$top = strpos($relN, '/') !== false ? strstr($relN, '/', true) : $relN;
		if(isset($peelTops[$top]) || isset($peelTops[$relN])) {
			continue;
		}
		if(isset($zipMemberSkip[$relN]) || isset($zipMemberSkip[basename($relN)])) {
			continue;
		}
		$underPeel = false;
		foreach($peelPrefixes as $pfx => $_true) {
			if(str_starts_with($relN, $pfx)) {
				$underPeel = true;
				break;
			}
		}
		if($underPeel) {
			continue;
		}
		if($relN === $sidecarName || str_starts_with($relN, '.fzcl_')
			|| str_starts_with($relN, '__share/')
			|| str_starts_with($relN, '__ole_stream/')
			|| str_starts_with($relN, '__ole_tmpl/')) {
			continue;
		}
		$destPath = rtrim((string) $destRootDir, "/\\") . DS . str_replace('/', DS, $relN);
		$this->build_directory_structure_for($destPath);
		if(!@rename($abs, $destPath)) {
			$data = @file_get_contents($abs);
			if($data === false || @file_put_contents($destPath, $data) === false) {
				$this->recursive_remove_directory($sandbox);
				return false;
			}
		}
	}
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted FZCL classic-peeled unified bundle.<br>');
	}
	return true;
}

/**
 * FZHM v1 per-member bundle: each member wire is a complete single-file .fz; extract via nested open_container.
 */
function fzhm_try_extract_per_member_bundle_to_directory($fullContents, $destRootDir, $debug) {
	fractal_zip_ensure_folder_per_member_best_loaded();
	fractal_zip_ensure_folder_logical_bundle_loaded();
	$fullContents = (string) $fullContents;
	$decoded = fractal_zip_decode_fzhm_container($fullContents);
	if($decoded === null) {
		return false;
	}
	$members = $decoded['members'];
	$restoreSpecs = is_array($decoded['restore'] ?? null) ? $decoded['restore'] : array();
	$diskReassembly = fractal_zip_folder_restore_requires_disk_reassembly($restoreSpecs);
	$u = substr(md5(fractal_zip::hot_string_digest($fullContents) . "\0fzhm_ex\0" . (string) spl_object_id($this)), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fzhm_s_' . $u;
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($sandbox, 0700, true)) {
		return false;
	}
	$memberFiles = array();
	foreach($members as $path => $wire) {
		$path = str_replace('\\', '/', (string) $path);
		if($path === '' || strpos($path, '..') !== false || isset($path[0]) && $path[0] === '/') {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		$caseDir = $sandbox . DS . 'm_' . bin2hex(substr(md5($path), 0, 8));
		if(!@mkdir($caseDir, 0700, true)) {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		// Nested logical paths (classic peel lumps, zip members): keep basename for the
		// single-file .fz leaf; open_container writes the restored file under caseDir.
		$leaf = basename($path);
		if($leaf === '' || $leaf === '.' || $leaf === '..') {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		$fzcPath = $caseDir . DS . $leaf . $this->fractal_zip_container_file_extension;
		if(@file_put_contents($fzcPath, (string) $wire) === false) {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		$inner = new fractal_zip($this->segment_length, $this->multipass, false, null, false);
		ob_start();
		try {
			$inner->open_container($fzcPath, false);
		} catch(Throwable $e) {
			ob_end_clean();
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		ob_end_clean();
		$extracted = $caseDir . DS . $leaf;
		if(!is_file($extracted)) {
			// Legacy wires that embedded a nested logical path (pre-flat isolated encode).
			$nested = $caseDir . DS . str_replace('/', DS, $path);
			if(is_file($nested)) {
				$extracted = $nested;
			} else {
				$this->recursive_remove_directory($sandbox);
				return false;
			}
		}
		$memberFiles[$path] = $extracted;
		if($debug) {
			fractal_zip::html_trace_print('FZHM member extracted: ' . htmlspecialchars($path) . '<br>');
		}
	}
	if($diskReassembly) {
		if(!fractal_zip_apply_folder_disk_restore($destRootDir, $memberFiles, $restoreSpecs, $this)) {
			$this->recursive_remove_directory($sandbox);
			return false;
		}
		// Passthrough files (README, etc.) are not in FZHR — copy leftovers.
		$classicTops = array();
		$classicKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC')
			? (int) FRACTAL_ZIP_FOLDER_RESTORE_CLASSIC
			: 3;
		$zipKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI')
			? (int) FRACTAL_ZIP_FOLDER_RESTORE_ZIP_MULTI
			: 1;
		$verbKind = defined('FRACTAL_ZIP_FOLDER_RESTORE_VERBATIM')
			? (int) FRACTAL_ZIP_FOLDER_RESTORE_VERBATIM
			: 2;
		foreach($restoreSpecs as $diskPath => $spec) {
			if(!is_array($spec)) {
				continue;
			}
			$k = (int) ($spec['kind'] ?? -1);
			if($k === $classicKind || $k === $zipKind || $k === $verbKind) {
				$classicTops[str_replace('\\', '/', (string) $diskPath)] = true;
			}
		}
		// ZIP_MULTI inners are consumed by rebuild — do not also copy them as
		// passthrough (82 ROM peels: leftover .bin/.smd broke verify).
		$zipMemberSkip = array();
		foreach($restoreSpecs as $_dp => $spec) {
			if(!is_array($spec)) {
				continue;
			}
			if((int) ($spec['kind'] ?? -1) !== $zipKind) {
				continue;
			}
			$names = $spec['member_names'] ?? null;
			if(!is_array($names)) {
				continue;
			}
			foreach($names as $mn) {
				$mnN = str_replace('\\', '/', (string) $mn);
				if($mnN === '' || str_contains($mnN, '..')) {
					continue;
				}
				$zipMemberSkip[$mnN] = true;
				$base = basename($mnN);
				if($base !== '' && $base !== '.' && $base !== '..') {
					$zipMemberSkip[$base] = true;
				}
			}
		}
		foreach($memberFiles as $path => $extracted) {
			$path = str_replace('\\', '/', (string) $path);
			$top = strpos($path, '/') !== false ? strstr($path, '/', true) : $path;
			if(isset($classicTops[$top])) {
				continue;
			}
			if(isset($zipMemberSkip[$path]) || isset($zipMemberSkip[basename($path)])) {
				continue;
			}
			if(!is_file($extracted)) {
				continue;
			}
			$destPath = $destRootDir . DS . str_replace('/', DS, $path);
			$this->build_directory_structure_for($destPath);
			if(!@rename($extracted, $destPath)) {
				$data = @file_get_contents($extracted);
				if($data === false || @file_put_contents($destPath, $data) === false) {
					$this->recursive_remove_directory($sandbox);
					return false;
				}
			}
		}
		if($debug) {
			fractal_zip::html_trace_print('FZHR disk layout restore applied.<br>');
		}
	} else {
		foreach($memberFiles as $path => $extracted) {
			$destPath = $destRootDir . DS . str_replace('/', DS, (string) $path);
			$this->build_directory_structure_for($destPath);
			if(!@rename($extracted, $destPath)) {
				$data = @file_get_contents($extracted);
				if($data === false || @file_put_contents($destPath, $data) === false) {
					$this->recursive_remove_directory($sandbox);
					return false;
				}
				@unlink($extracted);
			}
		}
	}
	$this->recursive_remove_directory($sandbox);
	$this->array_fractal_zipped_strings_of_files = array();
	$this->fractal_string = '';
	$this->fractal_gzip_peel_restore_map = array();
	if($debug) {
		fractal_zip::html_trace_print('Extracted FZHM per-member heterogeneous bundle.<br>');
	}
	return true;
}

/**
 * Extract native Arc bytes (no fractal outer) into an existing directory tree.
 */
function extract_freearc_native_archive_blob_to_directory($arcBlob, $destRootDir, $debug) {
	if(DIRECTORY_SEPARATOR === '\\') {
		fractal_zip::fatal_error('Native FreeArc folder extract requires Unix (not wired for Windows).');
	}
	$arcExe = fractal_zip::freearc_executable();
	if($arcExe === null) {
		fractal_zip::fatal_error('Native FreeArc extract requires `arc` on PATH.');
	}
	$arcBlob = (string) $arcBlob;
	$destRootDir = rtrim((string) $destRootDir, "\0");
	if(strlen($arcBlob) < 4 || $arcBlob[0] !== 'A' || $arcBlob[1] !== 'r' || $arcBlob[2] !== 'C' || $arcBlob[3] !== chr(1)) {
		fractal_zip::fatal_error('Payload is not a valid FreeArc archive.');
	}
	$u = substr(md5(fractal_zip::hot_string_digest($arcBlob) . "\0fzfa_in\0" . (string) spl_object_id($this)), 0, 16);
	$sandbox = sys_get_temp_dir() . DS . 'fzfa_s_' . $u;
	$tmpArc = $sandbox . DS . 'in.arc';
	$tmpOut = $sandbox . DS . 'out';
	if(is_dir($sandbox)) {
		$this->recursive_remove_directory($sandbox);
	}
	if(!@mkdir($tmpOut, 0755, true) && !is_dir($tmpOut)) {
		fractal_zip::fatal_error('Failed to create temp FreeArc extract directory.');
	}
	if(file_put_contents($tmpArc, $arcBlob) === false) {
		$this->recursive_remove_directory($sandbox);
		fractal_zip::fatal_error('Failed to write temp FreeArc archive file.');
	}
	$cwd = getcwd();
	$ret = -1;
	if(chdir($tmpOut)) {
		$prefix = $this->command_prefix_with_local_lib();
		$cmd = $prefix . fractal_zip::shell_quote_arg_cached($arcExe) . fractal_zip::library_arc_compress_mt_shell_fragment_for_exec() . ' x -y ' . escapeshellarg($tmpArc) . ' 2>/dev/null';
		exec($cmd, $xo, $ret);
	}
	if($cwd !== false) {
		chdir($cwd);
	}
	if($ret !== 0) {
		$this->recursive_remove_directory($sandbox);
		fractal_zip::fatal_error('Failed to extract native FreeArc archive (arc x).');
	}
	$this->recursive_copy_archive_output_directory_safely($tmpOut, $destRootDir);
	$this->recursive_remove_directory($sandbox);
	if($debug) {
		fractal_zip::html_trace_print('Extracted native FreeArc folder archive.<br>');
	}
}

