/**
 * FZB4 varint from an open stream (same encoding as decode_varint_u32).
 * @param resource $fh
 */
function read_varint_u32_from_stream($fh, $ctx) {
	$shift = 0;
	$out = 0;
	$steps = 0;
	while(true) {
		$b = fread($fh, 1);
		if($b === false || strlen($b) !== 1) {
			fractal_zip::fatal_error('Corrupt ' . $ctx . ' payload (varint truncated).');
		}
		$bb = ord($b);
		$out |= (($bb & 0x7F) << $shift);
		$steps++;
		if(($bb & 0x80) === 0) {
			break;
		}
		$shift += 7;
		if($steps > 5 || $shift > 28) {
			fractal_zip::fatal_error('Corrupt ' . $ctx . ' payload (varint too long).');
		}
	}
	return $out;
}

/**
 * Like {@see read_varint_u32_from_stream} but returns null on truncation / overflow instead of fatal_error.
 * @param resource $fh
 */
function read_varint_u32_from_stream_soft($fh): ?int {
	$shift = 0;
	$out = 0;
	$steps = 0;
	while(true) {
		$b = fread($fh, 1);
		if($b === false || strlen($b) !== 1) {
			return null;
		}
		$bb = ord($b);
		$out |= (($bb & 0x7F) << $shift);
		$steps++;
		if(($bb & 0x80) === 0) {
			break;
		}
		$shift += 7;
		if($steps > 5 || $shift > 28) {
			return null;
		}
	}
	return $out;
}

/**
 * Stream-decompress a single zlib/deflate/gzip member from disk to disk (chunked; avoids file_get_contents + gzuncompress OOM).
 * @return bool true if output file is non-empty
 */
function stream_inflate_file_to_path($srcPath, $dstPath, $encoding) {
	if(!function_exists('inflate_init') || !function_exists('inflate_add')) {
		return false;
	}
	$in = @fopen($srcPath, 'rb');
	if($in === false) {
		return false;
	}
	$out = @fopen($dstPath, 'wb');
	if($out === false) {
		fclose($in);
		return false;
	}
	$ctx = @inflate_init($encoding);
	if($ctx === false) {
		fclose($in);
		fclose($out);
		return false;
	}
	$written = 0;
	$readChunk = fractal_zip::stream_chunk_bytes();
	while(!feof($in)) {
		$chunk = fread($in, $readChunk);
		if($chunk === false) {
			$chunk = '';
		}
		$flags = feof($in) ? ZLIB_FINISH : ZLIB_SYNC_FLUSH;
		$dec = @inflate_add($ctx, $chunk, $flags);
		if($dec === false) {
			fclose($in);
			fclose($out);
			return false;
		}
		if($dec !== '' && fwrite($out, $dec) === false) {
			fclose($in);
			fclose($out);
			return false;
		}
		$written += strlen($dec);
	}
	fclose($in);
	fclose($out);
	if($written > 0) {
		return true;
	}
	$sz = @filesize($dstPath);
	return is_int($sz) && $sz > 0;
}

/**
 * Try RAW / zlib / gzip wrappers until inner payload starts with FZB4 or FZCD.
 * @param-out string $tmpPath path to temp inner file (caller must unlink)
 * @return bool
 */
function try_stream_inflate_to_fzb4_temp_file($srcPath, &$tmpPath) {
	$tmpPath = sys_get_temp_dir() . DS . 'fzfzin_' . substr(md5(fractal_zip::hot_string_digest((string) $srcPath) . "\0fzfi\0" . (string) spl_object_id($this)), 0, 16);
	$encodings = array(ZLIB_ENCODING_RAW, ZLIB_ENCODING_DEFLATE, ZLIB_ENCODING_GZIP);
	foreach($encodings as $enc) {
		if(is_file($tmpPath)) {
			@unlink($tmpPath);
		}
		if(!$this->stream_inflate_file_to_path($srcPath, $tmpPath, $enc)) {
			continue;
		}
		$h = @fopen($tmpPath, 'rb');
		if($h === false) {
			@unlink($tmpPath);
			continue;
		}
		$sig = fread($h, 4);
		fclose($h);
		if($sig === 'FZWS' || $sig === 'FZBD') {
			@unlink($tmpPath);
			$tmpPath = '';
			return false;
		}
		if($sig === 'FZB4' || $sig === 'FZCD') {
			return true;
		}
	}
	if(is_file($tmpPath)) {
		@unlink($tmpPath);
	}
	$tmpPath = '';
	return false;
}

/**
 * Stream whole-file xz decompress of $srcPath to a temp file (xz reads the path; stdout → file — no stdin pipe deadlock).
 * Caller inspects magic (FZB4/FZCD stream-extract, else load + decode_container_payload). Caller must unlink $tmpPath.
 *
 * @param-out string $tmpPath
 * @return bool
 */
function try_stream_xz_decompress_to_temp_file($srcPath, &$tmpPath) {
	$tmpPath = fractal_zip::outer_codec_temp_dir() . DS . 'fzXZn_' . substr(md5(fractal_zip::hot_string_digest((string) $srcPath) . "\0xzn\0" . (string) spl_object_id($this)), 0, 16);
	$xzExe = fractal_zip::xz_executable();
	if($xzExe === null || !is_file($srcPath) || !function_exists('proc_open')) {
		$tmpPath = '';
		return false;
	}
	$cmd = fractal_zip::shell_quote_arg_cached($xzExe) . fractal_zip::library_xz_decompress_thread_shell_fragment_for_exec() . ' -d -c ' . fractal_zip::shell_quote_arg_cached($srcPath);
	$pe = fractal_zip::proc_open_reusable_std_pipe_ends();
	$desc = array(0 => $pe['r'], 1 => array('file', $tmpPath, 'wb'), 2 => $pe['w']);
	$proc = @proc_open($cmd, $desc, $pipes);
	if(!is_resource($proc)) {
		@unlink($tmpPath);
		$tmpPath = '';
		return false;
	}
	fclose($pipes[0]);
	stream_get_contents($pipes[2]);
	fclose($pipes[2]);
	if(proc_close($proc) !== 0) {
		@unlink($tmpPath);
		$tmpPath = '';
		return false;
	}
	$sz = @filesize($tmpPath);
	if(!is_int($sz) || $sz < 4) {
		@unlink($tmpPath);
		$tmpPath = '';
		return false;
	}
	return true;
}

/**
 * Normalize a relative archive member path for web FS single-file reads (forward slashes; rejects traversal).
 */
public static function normalize_web_fs_member_relpath(string $rel): ?string {
	$rel = str_replace('\\', '/', trim($rel));
	if($rel === '' || str_contains($rel, "\0") || str_starts_with($rel, '/') || preg_match('/^[A-Za-z]:/', $rel) === 1) {
		return null;
	}
	foreach(explode('/', $rel) as $part) {
		if($part === '' || $part === '.' || $part === '..') {
			return null;
		}
	}
	return $rel;
}

public static function container_filename_looks_like_fractal_zip(string $path): bool {
	$low = strtolower($path);
	return str_ends_with($low, '.fz') || str_ends_with($low, '.fzc') || str_ends_with($low, '.fractalzip');
}

/** True for leftover in-tree container names (`.fz` / `.fzc` / `.fractalzip`), not `foo.fz` payloads. */
public static function path_is_inplace_fractal_container_leaf(string $relOrName): bool {
	$base = basename(str_replace('\\', '/', $relOrName));
	$low = strtolower($base);
	return $low === '.fz' || $low === '.fzc' || $low === '.fractalzip';
}

/**
 * Write decode_container_payload() output to disk (same layout as open_container legacy path).
 *
 * @param array{0: array<string,string>, 1: string, 2?: array<string,string>} $triple
 */
function safe_container_member_output_path($rootDir, $memberPath) {
	$root = rtrim((string)$rootDir, DS);
	if($root === '') {
		fractal_zip::fatal_error('Unsafe extract root.');
	}
	$rel = str_replace('\\', '/', (string)$memberPath);
	if($rel === '' || str_contains($rel, "\0") || str_starts_with($rel, '/') || preg_match('/^[A-Za-z]:/', $rel) === 1) {
		fractal_zip::fatal_error('Unsafe container member path.');
	}
	$parts = explode('/', $rel);
	$clean = array();
	foreach($parts as $part) {
		if($part === '' || $part === '.' || $part === '..') {
			fractal_zip::fatal_error('Unsafe container member path.');
		}
		$clean[] = $part;
	}
	return $root . DS . implode(DS, $clean);
}

function write_decoded_container_members_to_disk($rootDir, $triple, $debug, $markStreamingExtractUsed) {
	$this->array_fractal_zipped_strings_of_files = $triple[0];
	$this->fractal_string = $triple[1];
	$this->fractal_gzip_peel_restore_map = isset($triple[2]) && is_array($triple[2]) ? $triple[2] : array();
	fractal_zip::$open_container_streaming_extract_used = $markStreamingExtractUsed;
	foreach($this->array_fractal_zipped_strings_of_files as $index => $value) {
		$outPath = $this->safe_container_member_output_path($rootDir, $index);
		$this->build_directory_structure_for($outPath);
		$zipped_contents = $value;
		$unzipped_contents = $this->unzip($zipped_contents);
		if(isset($this->fractal_gzip_peel_restore_map[$index])) {
			$restore = $this->fractal_gzip_peel_restore_map[$index];
			if(is_array($restore)) {
				$unzipped_contents = $this->apply_fractal_restore_spec($restore, $unzipped_contents);
			} else {
				$unzipped_contents = $restore;
			}
		}
		file_put_contents($outPath, $unzipped_contents);
		if($debug) {
			fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
		}
		$this->files_counter++;
	}
}

function apply_fractal_restore_spec($restore, $peeledBytes) {
	if(is_array($restore) && ($restore['__fz_restore'] ?? '') === 'numeric_delta') {
		$peeledBytes = (string)$peeledBytes;
		$out = '';
		$acc = 0;
		for($i = 0, $n = strlen($peeledBytes); $i < $n; $i++) {
			$acc = ($acc + ord($peeledBytes[$i])) & 255;
			$out .= chr($acc);
		}
		return $out;
	}
	if(is_array($restore) && (($restore['__fz_restore'] ?? '') === 'modulo4_lane_split' || ($restore['__fz_restore'] ?? '') === 'modulo_lane_split')) {
		$peeledBytes = (string)$peeledBytes;
		$n = max(0, (int)($restore['len'] ?? 0));
		$lanesCount = (($restore['__fz_restore'] ?? '') === 'modulo4_lane_split') ? 4 : max(2, min(64, (int)($restore['lanes'] ?? 2)));
		if(strlen($peeledBytes) !== $n) {
			fractal_zip::fatal_error('Corrupt FZR1 modulo lane restore length.');
		}
		$laneLens = array();
		for($lane = 0; $lane < $lanesCount; $lane++) {
			$laneLens[$lane] = intdiv($n + $lanesCount - 1 - $lane, $lanesCount);
			if($n <= $lane) {
				$laneLens[$lane] = 0;
			}
		}
		$lanes = array();
		$at = 0;
		for($lane = 0; $lane < $lanesCount; $lane++) {
			$lanes[$lane] = substr($peeledBytes, $at, $laneLens[$lane]);
			$at += $laneLens[$lane];
		}
		$out = '';
		$idx = array_fill(0, $lanesCount, 0);
		for($i = 0; $i < $n; $i++) {
			$lane = $i % $lanesCount;
			$out .= $lanes[$lane][$idx[$lane]];
			$idx[$lane]++;
		}
		return $out;
	}
	if(is_array($restore) && ($restore['__fz_restore'] ?? '') === 'nibble_split') {
		$peeledBytes = (string)$peeledBytes;
		$n = strlen($peeledBytes);
		if(($n & 1) !== 0) {
			fractal_zip::fatal_error('Corrupt FZR1 nibble restore length.');
		}
		$out = '';
		for($i = 0; $i < $n; $i += 2) {
			$out .= chr(((ord($peeledBytes[$i]) & 15) << 4) | (ord($peeledBytes[$i + 1]) & 15));
		}
		return $out;
	}
	if(is_array($restore) && ($restore['__fz_restore'] ?? '') === 'bitplane_split') {
		$peeledBytes = (string)$peeledBytes;
		$n = max(0, (int)($restore['len'] ?? 0));
		$planeLen = intdiv($n + 7, 8);
		if(strlen($peeledBytes) !== $planeLen * 8) {
			fractal_zip::fatal_error('Corrupt FZR1 bitplane restore length.');
		}
		$out = array_fill(0, $n, 0);
		for($bit = 0; $bit < 8; $bit++) {
			$plane = substr($peeledBytes, $bit * $planeLen, $planeLen);
			for($j = 0, $pn = strlen($plane); $j < $pn; $j++) {
				$packed = ord($plane[$j]);
				for($k = 0; $k < 8; $k++) {
					$idx = ($j * 8) + $k;
					if($idx >= $n) {
						break;
					}
					if(($packed & (1 << $k)) !== 0) {
						$out[$idx] |= (1 << $bit);
					}
				}
			}
		}
		$s = '';
		foreach($out as $b) {
			$s .= chr($b);
		}
		return $s;
	}
	if(is_array($restore) && ($restore['__fz_restore'] ?? '') === 'record_transpose') {
		$peeledBytes = (string)$peeledBytes;
		$delim = (string)($restore['delim'] ?? "\n");
		$max = max(0, (int)($restore['max'] ?? 0));
		$rows = max(0, (int)($restore['rows'] ?? 0));
		if($max <= 0 || $rows <= 0 || strlen($peeledBytes) !== $max * $rows) {
			fractal_zip::fatal_error('Corrupt FZR1 record transpose restore dimensions.');
		}
		$lengths = (isset($restore['lengths']) && is_array($restore['lengths'])) ? $restore['lengths'] : array();
		if($lengths === array()) {
			$lengths = array_fill(0, $rows, $max);
		}
		if(sizeof($lengths) !== $rows) {
			fractal_zip::fatal_error('Corrupt FZR1 record transpose row lengths.');
		}
		$outRows = array_fill(0, $rows, '');
		for($col = 0; $col < $max; $col++) {
			$base = $col * $rows;
			for($row = 0; $row < $rows; $row++) {
				if($col < (int)$lengths[$row]) {
					$outRows[$row] .= $peeledBytes[$base + $row];
				}
			}
		}
		return implode($delim, $outRows);
	}
	fractal_zip::fatal_error('Unknown fractal restore spec.');
	return '';
}

/**
 * Outer formats that need full-file adaptive_decompress (7z, arc, brotli, zstd, xz) — not streamable here.
 */
function container_outer_needs_legacy_full_read($head) {
	if(strlen($head) < 2) {
		return false;
	}
	if(substr($head, 0, 2) === '7z') {
		return true;
	}
	$b7 = fractal_zip::NATIVE_FOLDER_7Z_WIRE_BYTE;
	if(strlen($head) >= 7 && isset($head[0]) && $head[0] === $b7 && fractal_zip::payload_has_raw_seven_zip_signature(substr($head, 1))) {
		return true;
	}
	if(strlen($head) >= 8 && substr($head, 0, 2) === 'FZ' && fractal_zip::payload_has_raw_seven_zip_signature(substr($head, 2))) {
		return true;
	}
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZLB' && $head[4] === "\x01") {
		return true;
	}
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZLX' && $head[4] === "\x01") {
		return true;
	}
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZLZ' && $head[4] === "\x01") {
		return true;
	}
	$bMagic = fractal_zip::OUTER_BROTLI_MAGIC;
	$bMagicLen = strlen($bMagic);
	if(strlen($head) >= $bMagicLen && substr($head, 0, $bMagicLen) === $bMagic) {
		return true;
	}
	if(strlen($head) >= 4 && substr($head, 0, 4) === 'ARC' && $head[3] === chr(1)) {
		return true;
	}
	if(strlen($head) >= 4 && substr($head, 0, 4) === "\x28\xB5\x2F\xFD") {
		return true;
	}
	if(strlen($head) >= 6 && substr($head, 0, 6) === "\xFD\x37\x7A\x58\x5A\x00") {
		return true;
	}
	return false;
}

/**
 * Stream-read FZB4 bundle from disk; write each member under $rootDir (same layout as open_container).
 * @return bool false if not attempted / not FZB4
 */
function extract_fzb4_bundle_streaming_from_path($bundlePath, $rootDir, $debug) {
	$fh = @fopen($bundlePath, 'rb');
	if($fh === false) {
		return false;
	}
	$sig = fread($fh, 4);
	if($sig !== 'FZB4') {
		fclose($fh);
		return false;
	}
	$this->fractal_string = '';
	$this->array_fractal_zipped_strings_of_files = array();
	fractal_zip::$open_container_streaming_extract_used = true;
	$prevPath = '';
	while(true) {
		$pos = ftell($fh);
		$probe = fread($fh, 4);
		if($probe === false || $probe === '') {
			break;
		}
		// General-text/enwik reassembly appends an FZEP trailer after the FZB4 body
		// (raw-FZB4 outers only; compressed outers end at the codec stream). It is
		// not a member row; the post-extract reassemble hook parses it separately.
		if($probe === 'FZEP') {
			break;
		}
		fseek($fh, $pos);
		$prefixLen = $this->read_varint_u32_from_stream($fh, 'FZB4');
		$suffixLen = $this->read_varint_u32_from_stream($fh, 'FZB4');
		if($prefixLen > strlen($prevPath)) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZB4 payload (prefix length exceeds previous path).');
		}
		$pathSuffix = $suffixLen > 0 ? fread($fh, $suffixLen) : '';
		if(strlen($pathSuffix) !== $suffixLen) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZB4 payload (path suffix truncated).');
		}
		$path = substr($prevPath, 0, $prefixLen) . $pathSuffix;
		$modeCh = fread($fh, 1);
		if($modeCh === false || strlen($modeCh) !== 1) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZB4 payload (mode missing).');
		}
		$mode = ord($modeCh);
		$dataLen = $this->read_varint_u32_from_stream($fh, 'FZB4');
		$rawStored = $dataLen > 0 ? fread($fh, $dataLen) : '';
		if(strlen($rawStored) !== $dataLen) {
			fclose($fh);
			fractal_zip::fatal_error('Corrupt FZB4 payload (data truncated).');
		}
		$raw = $this->decode_bundle_literal_member($mode, $rawStored);
		$escaped = $this->escape_literal_for_storage($raw);
		$unzipped = $this->unzip($escaped);
		// FZVL (lossless-video PAC): expand to FFV1 AVI bytes (semantic restore; VIDEOPAC encode path).
		if(is_string($unzipped) && strlen($unzipped) >= 4 && strncmp($unzipped, 'FZVL', 4) === 0) {
			fractal_zip_ensure_video_lossless_pac_loaded();
			if(function_exists('fractal_zip_video_lossless_pac_expand_member_bytes')) {
				$exp = fractal_zip_video_lossless_pac_expand_member_bytes($unzipped);
				if(is_string($exp) && $exp !== '') {
					$unzipped = $exp;
				}
			}
		}
		$outPath = $this->safe_container_member_output_path($rootDir, $path);
		$this->build_directory_structure_for($outPath);
		file_put_contents($outPath, $unzipped);
		if($debug) {
			fractal_zip::html_trace_print('Extracted ' . $outPath . '<br>');
		}
		$this->files_counter++;
		$this->array_fractal_zipped_strings_of_files[$path] = '';
		$prevPath = $path;
	}
	fclose($fh);
	if($debug) {
		$micro_time_taken = microtime(true) - $this->initial_micro_time;
		fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
	}
	return true;
}

/**
 * Scan an on-disk FZB4 bundle and return decoded bytes for one member without writing others.
 * Returns null if missing, corrupt at varint/path level, or decode/unzip fails without raising (best-effort for hostile blobs).
 */
function fzb4_try_read_member_bytes_from_bundle_path(string $bundlePath, string $normRel): ?string {
	$fh = @fopen($bundlePath, 'rb');
	if($fh === false) {
		return null;
	}
	if(fread($fh, 4) !== 'FZB4') {
		fclose($fh);
		return null;
	}
	$this->fractal_string = '';
	$prevPath = '';
	while(true) {
		$pos = ftell($fh);
		if($pos === false) {
			fclose($fh);
			return null;
		}
		$probe = fread($fh, 1);
		if($probe === false || $probe === '') {
			break;
		}
		fseek($fh, $pos);
		$prefixLen = $this->read_varint_u32_from_stream_soft($fh);
		if($prefixLen === null) {
			fclose($fh);
			return null;
		}
		$suffixLen = $this->read_varint_u32_from_stream_soft($fh);
		if($suffixLen === null) {
			fclose($fh);
			return null;
		}
		if($prefixLen > strlen($prevPath)) {
			fclose($fh);
			return null;
		}
		$pathSuffix = $suffixLen > 0 ? fread($fh, $suffixLen) : '';
		if(strlen($pathSuffix) !== $suffixLen) {
			fclose($fh);
			return null;
		}
		$path = substr($prevPath, 0, $prefixLen) . $pathSuffix;
		$modeCh = fread($fh, 1);
		if($modeCh === false || strlen($modeCh) !== 1) {
			fclose($fh);
			return null;
		}
		$mode = ord($modeCh);
		$dataLen = $this->read_varint_u32_from_stream_soft($fh);
		if($dataLen === null) {
			fclose($fh);
			return null;
		}
		$rawStored = $dataLen > 0 ? fread($fh, $dataLen) : '';
		if(strlen($rawStored) !== $dataLen) {
			fclose($fh);
			return null;
		}
		$want = ($path === $normRel);
		if(!$want) {
			$prevPath = $path;
			continue;
		}
		try {
			$raw = $this->decode_bundle_literal_member($mode, $rawStored);
			$escaped = $this->escape_literal_for_storage($raw);
			$unzipped = $this->unzip($escaped);
		} catch(Throwable $e) {
			fclose($fh);
			return null;
		}
		fclose($fh);
		return $unzipped;
	}
	fclose($fh);
	return null;
}

/**
 * @return list<string>|null member paths in order, or null if the bundle header/path layer is corrupt
 */
function fzb4_try_list_member_paths_from_bundle_path(string $bundlePath): ?array {
	$fh = @fopen($bundlePath, 'rb');
	if($fh === false) {
		return null;
	}
	if(fread($fh, 4) !== 'FZB4') {
		fclose($fh);
		return null;
	}
	$out = array();
	$prevPath = '';
	while(true) {
		$pos = ftell($fh);
		if($pos === false) {
			fclose($fh);
			return null;
		}
		$probe = fread($fh, 1);
		if($probe === false || $probe === '') {
			break;
		}
		fseek($fh, $pos);
		$prefixLen = $this->read_varint_u32_from_stream_soft($fh);
		if($prefixLen === null) {
			fclose($fh);
			return null;
		}
		$suffixLen = $this->read_varint_u32_from_stream_soft($fh);
		if($suffixLen === null) {
			fclose($fh);
			return null;
		}
		if($prefixLen > strlen($prevPath)) {
			fclose($fh);
			return null;
		}
		$pathSuffix = $suffixLen > 0 ? fread($fh, $suffixLen) : '';
		if(strlen($pathSuffix) !== $suffixLen) {
			fclose($fh);
			return null;
		}
		$path = substr($prevPath, 0, $prefixLen) . $pathSuffix;
		$modeCh = fread($fh, 1);
		if($modeCh === false || strlen($modeCh) !== 1) {
			fclose($fh);
			return null;
		}
		$dataLen = $this->read_varint_u32_from_stream_soft($fh);
		if($dataLen === null) {
			fclose($fh);
			return null;
		}
		if($dataLen > 0) {
			$skip = fread($fh, $dataLen);
			if($skip === false || strlen($skip) !== $dataLen) {
				fclose($fh);
				return null;
			}
		}
		$out[] = $path;
		$prevPath = $path;
	}
	fclose($fh);
	return $out;
}

/**
 * Avoid loading entire .fz into memory: plain FZB4, or deflate/zlib/gzip outer wrapping FZB4 (e.g. folder gzip-fast).
 */
function open_container_streaming_if_applicable($filename, $rootDir, $debug) {
	fractal_zip::$open_container_streaming_extract_used = false;
	$head = @file_get_contents($filename, false, null, 0, 32);
	if($head === false || $head === '') {
		return false;
	}
	// Native folder wires first (including raw zstd/xz that also trip legacy_full_read).
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZLZ' && $head[4] === "\x01") {
		return $this->zstd_try_extract_native_folder_tar_zst_from_path($filename, $rootDir, $debug);
	}
	if(strlen($head) >= 4 && $head[0] === "\x28" && $head[1] === "\xB5" && $head[2] === "\x2F" && $head[3] === "\xFD") {
		return $this->zstd_try_extract_raw_tar_zst_from_path($filename, $rootDir, $debug, 0);
	}
	// Raw tar|gzip (video lakes / min-ext gzip wire) — before legacy inflate→FZB4.
	if(strlen($head) >= 2 && $head[0] === "\x1F" && $head[1] === "\x8B") {
		return $this->gzip_try_extract_raw_tar_gz_from_path($filename, $rootDir, $debug, 0);
	}
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZLX' && $head[4] === "\x01") {
		return $this->xz_try_extract_native_folder_tar_xz_from_path($filename, $rootDir, $debug, 5);
	}
	if(strlen($head) >= 6 && substr($head, 0, 6) === "\xFD\x37\x7A\x58\x5A\x00") {
		// Raw xz may be either outer-xz-wrapped FZB4 (legacy path below) or tar|xz folder.
		// Prefer tar|xz folder extract; fall through on failure.
		if($this->xz_try_extract_native_folder_tar_xz_from_path($filename, $rootDir, $debug, 0)) {
			return true;
		}
	}
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZLB' && $head[4] === "\x01") {
		return $this->brotli_try_extract_native_folder_tar_br_from_path($filename, $rootDir, $debug, 5);
	}
	// xz outer: decompress via xz reading the file (no stdin pipe deadlock); FZB4/FZCD stream-read; FZBM/FZBF/etc. decode then write.
	if(strlen($head) >= 6 && substr($head, 0, 6) === "\xFD\x37\x7A\x58\x5A\x00") {
		$tmpXz = '';
		if($this->try_stream_xz_decompress_to_temp_file($filename, $tmpXz)) {
			$h = @fopen($tmpXz, 'rb');
			if($h === false) {
				@unlink($tmpXz);
				return false;
			}
			$sig = fread($h, 4);
			fclose($h);
			if($sig === 'FZCD') {
				$ok = $this->extract_fzcd_bundle_streaming_from_path($tmpXz, $rootDir, $debug);
				@unlink($tmpXz);
				return $ok;
			}
			if($sig === 'FZB4') {
				$ok = $this->extract_fzb4_bundle_streaming_from_path($tmpXz, $rootDir, $debug);
				@unlink($tmpXz);
				return $ok;
			}
			$inner = @file_get_contents($tmpXz);
			@unlink($tmpXz);
			if($inner === false || $inner === '') {
				return false;
			}
			$triple = $this->decode_container_payload($inner);
			$this->write_decoded_container_members_to_disk($rootDir, $triple, $debug, true);
			if($debug) {
				$micro_time_taken = microtime(true) - $this->initial_micro_time;
				fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
			}
			return true;
		}
	}
	if($this->container_outer_needs_legacy_full_read($head)) {
		return false;
	}
	if(substr($head, 0, 4) === 'FZB4') {
		return $this->extract_fzb4_bundle_streaming_from_path($filename, $rootDir, $debug);
	}
	if(substr($head, 0, 4) === 'FZCD') {
		return $this->extract_fzcd_bundle_streaming_from_path($filename, $rootDir, $debug);
	}
	if(strlen($head) >= 5 && substr($head, 0, 4) === 'FZWF' && $head[4] === "\x01") {
		return $this->extract_fzwf_v1_from_path($filename, $rootDir, $debug);
	}
	$tmp = '';
	if($this->try_stream_inflate_to_fzb4_temp_file($filename, $tmp)) {
		$h = @fopen($tmp, 'rb');
		if($h === false) {
			@unlink($tmp);
			return false;
		}
		$sig = fread($h, 4);
		fclose($h);
		if($sig === 'FZCD') {
			$ok = $this->extract_fzcd_bundle_streaming_from_path($tmp, $rootDir, $debug);
		} else {
			$ok = $this->extract_fzb4_bundle_streaming_from_path($tmp, $rootDir, $debug);
		}
		@unlink($tmp);
		return $ok;
	}
	// Last resort: raw tar|brotli (no magic) — only when head is not self-describing.
	if(!$this->container_payload_has_self_describing_outer_magic($head)
		&& $this->brotli_try_extract_native_folder_tar_br_from_path($filename, $rootDir, $debug, 0)) {
		return true;
	}
	return false;
}

function open_container($filename, $debug = false) {
	$root_directory_of_container_file = substr($filename, 0, fractal_zip::strpos_last($filename, DS));
	$this->container_open_fzc_path = $filename;
	try {
	if($debug) {
		fractal_zip::html_trace_print('Opening fractal zip container: ' . $filename . '<br>');
	}
	// Stream-extract first (monsters / raw zstd|xz|br) — avoid loading hundreds of MiB into PHP.
	fractal_zip::$open_container_streaming_extract_used = false;
	if($this->open_container_streaming_if_applicable($filename, $root_directory_of_container_file, $debug)) {
		$this->fractal_gzip_peel_restore_map = array();
		return;
	}
	$contents = (string) file_get_contents($filename);
	$contents = fractal_zip_web_ref_strip_fzwr_suffix($contents);
	$contents = fractal_zip_enwik_strip_fzep_suffix($contents);
	if($this->freearc_try_extract_native_folder_arc_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->zpaq_try_extract_native_folder_archive_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->paq_try_extract_native_folder_archive_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->seven_zip_try_extract_native_folder_archive_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->gzip9_bundle_try_extract_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->gzip_try_extract_native_folder_tar_gz_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->brotli_try_extract_native_folder_tar_br_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->xz_try_extract_native_folder_tar_xz_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->zstd_try_extract_native_folder_tar_zst_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->fzcl_try_extract_classic_peeled_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->fzhm_try_extract_per_member_bundle_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
		}
		return;
	}
	if($this->native_codec_single_member_try_extract_to_directory($contents, $root_directory_of_container_file, $debug)) {
		fractal_zip::$open_container_streaming_extract_used = false;
		if($debug) {
			$micro_time_taken = microtime(true) - $this->initial_micro_time;
			fractal_zip::html_trace_print('Time taken opening container (native codec leaf).<br>');
		}
		return;
	}
	// un-gzip or un-LZMA?
	//$contents = gzuncompress($contents);
	$contents = $this->adaptive_decompress($contents);
	//$contents = gzdecode($contents);
	//$contents = gzinflate($contents);
	//$contents = bzdecompress($contents);
	//$array_fractal_strings_and_equivalences = unserialize($contents);
	//$this->array_fractal_zipped_strings_of_files = $array_fractal_strings_and_equivalences[0];
	//$this->fractal_strings = $array_fractal_strings_and_equivalences[1];
	//print('$contents: ');var_dump($contents);
	$array_fractal_string_and_equivalences = $this->decode_container_payload($contents);
	//print('$array_fractal_string_and_equivalences: ');var_dump($array_fractal_string_and_equivalences);
	/*$this->array_fractal_zipped_strings_of_files = $array_fractal_string_and_equivalences[0];
	//print('$this->array_fractal_zipped_strings_of_files: ');var_dump($this->array_fractal_zipped_strings_of_files);
	$this->multipass = $array_fractal_string_and_equivalences[1];
	$this->branch_counter = $array_fractal_string_and_equivalences[2];
	$this->left_fractal_zip_marker = $array_fractal_string_and_equivalences[3];
	$this->mid_fractal_zip_marker = $array_fractal_string_and_equivalences[4];
	$this->right_fractal_zip_marker = $array_fractal_string_and_equivalences[5];
	$this->fractal_string = $array_fractal_string_and_equivalences[6];*/
	
	$this->write_decoded_container_members_to_disk($root_directory_of_container_file, $array_fractal_string_and_equivalences, $debug, false);
	if($debug) {
		$micro_time_taken = microtime(true) - $this->initial_micro_time;
		fractal_zip::html_trace_print('Time taken opening container: ' . $micro_time_taken . ' seconds.<br>');
	}
	} finally {
		$this->container_open_fzc_path = null;
		fractal_zip_enwik_try_reassemble_after_extract((string) $filename, (string) $root_directory_of_container_file);
	}
}

