//$subs = get_all_substrings("a b c", " ");
//print_r($subs);

function all_substrings_count($string, $minimum_count = 1, ?array $haystack_byte_presence = null) { // minimum_count is unused; optional haystack_byte_presence = fz_inner_byte_presence_map($string) to skip rebuild
	$slen = strlen($string);
	$maxFractal = fractal_zip::max_fractal_analysis_bytes();
	if($maxFractal > 0 && $slen > $maxFractal) {
		return array();
	}
	$coarseCfg = fractal_zip::fractal_substring_coarse_config_for_length($slen);
	$multidiffMetricsEnabled = fractal_zip::substring_multidiff_debug_metrics_enabled();
	$this->last_substring_multidiff_metrics = null;
	$multidiffMetrics = $multidiffMetricsEnabled ? array() : null;
	$counter = 0;
	$minimum_counter_skip = 1;
	$substr_records = array();
	// Sliding-window start length (legacy fractal_string scaling + clamp). **Not** the append slice gate: multipass uses
	// {@see fz_inner_append_min_corpus_slice_bytes()} at replace time (`end−start ≥ append_depth+1`). Lowering this floor
	// without revisiting counter_skip semantics changes which substrings appear — do not swap in step-index blindly.
	$minimum_substr_length = max(2, min($this->substr_scan_minimum_length(), 5));
	$baseMaxExpr = fractal_zip::maximum_substr_expression_length();
	$length_string = (string) $slen;
	$multiple = 15 - strlen($length_string);
	if($multiple < 3) {
		$multiple = 3;
	}
	if($coarseCfg['enabled'] && $coarseCfg['multiple_cap'] > 0) {
		$multiple = min($multiple, $coarseCfg['multiple_cap']);
	}
	$maximum_substr_length = $baseMaxExpr * $multiple;
	if($slen > 131072) {
		$hardCap = $baseMaxExpr * 24;
		if($maximum_substr_length > $hardCap) {
			$maximum_substr_length = $hardCap;
		}
	}
	if($coarseCfg['enabled'] && $coarseCfg['hardcap_mult'] > 0) {
		$hardCap2 = $baseMaxExpr * $coarseCfg['hardcap_mult'];
		if($maximum_substr_length > $hardCap2) {
			$maximum_substr_length = $hardCap2;
		}
	}
	$maxSubstrRecordEntries = $coarseCfg['max_records'];
	fractal_zip::warning_once('I believe there is room at this counter_skip to sacrifice compression for speed');
	fractal_zip::warning_once('hacking counter_skip');
	$ascProf = function_exists('fz_inner_profile_enabled') && function_exists('fz_inner_profile_add_ns') && fz_inner_profile_enabled();
	$tAscSeg = $ascProf ? hrtime(true) : 0;
	if ($haystack_byte_presence !== null) {
		$haystackByte = $haystack_byte_presence;
	} else {
		$haystackByte = array();
		for ($hb = 0; $hb < $slen; $hb++) {
			$haystackByte[$string[$hb]] = true;
		}
	}
	$ranMultidiff = false;
	$useMultidiff = fractal_zip::substring_multidiff_enabled()
		&& $slen >= fractal_zip::substring_multidiff_min_bytes()
		&& (int) $this->zip_folder_member_count !== 1
		&& ($coarseCfg['enabled'] || $slen >= 131072);
	$reciprocalSeeds = array();
	$reciprocalSkipIntervals = array();
	$reciprocalSeedKeys = array();
	$chainSeedKeys = array();
	$recipCfg = $this->substring_reciprocal_effective_config();
	$reciprocalSeedScoreScale = isset($recipCfg['seed_score_scale']) ? (float) $recipCfg['seed_score_scale'] : 1.0;
	$reciprocalProfileLabel = (string) $this->recursive_reciprocal_profile_label;
	$preferLegacyCandidateSet = ($reciprocalProfileLabel !== 'high');
	$skipReciprocalSeedsForSingleMember = ((int) $this->zip_folder_member_count === 1 && $reciprocalProfileLabel !== 'high');
	$enableReciprocalSeeds = !$skipReciprocalSeedsForSingleMember
		&& ($reciprocalProfileLabel === 'high' || fractal_zip::substring_multidiff_recursive_only_enabled());
	if($useMultidiff) {
		$ranMultidiff = true;
		$substr_records = $this->all_substrings_count_multidiff_candidates(
			$string,
			$minimum_substr_length,
			$maximum_substr_length,
			$haystackByte,
			$multidiffMetrics
		);
		if($enableReciprocalSeeds) {
			$reciprocalSeeds = $this->all_substrings_count_reciprocal_segment_seeds(
				$string,
				$minimum_substr_length,
				$maximum_substr_length,
				$haystackByte,
				$multidiffMetrics
			);
		}
		$mergeReciprocalSeeds = true;
		if($reciprocalSeeds !== array()) {
			$profileLabel = (string) $this->recursive_reciprocal_profile_label;
			$seedSupportBytes = 0;
			$longSeedHits = 0;
			foreach($reciprocalSeeds as $seedSubstr => $seedCount) {
				$seedLen = strlen((string) $seedSubstr);
				$seedN = max(1, (int) $seedCount);
				$seedSupportBytes += $seedLen * max(1, $seedN - 1);
				if($seedLen >= 64 && $seedN >= 3) {
					$longSeedHits++;
				}
			}
			$seedSupportRatio = ($slen > 0) ? ((float) $seedSupportBytes / (float) $slen) : 0.0;
			if($profileLabel === 'low') {
				$mergeReciprocalSeeds = false;
			} elseif($profileLabel === 'mixed' && $seedSupportRatio < 0.30 && $longSeedHits < 4) {
				$mergeReciprocalSeeds = false;
			}
		}
		if(!$mergeReciprocalSeeds) {
			$reciprocalSeeds = array();
		}
		if($reciprocalSeeds !== array()) {
			foreach($reciprocalSeeds as $seedSubstr => $seedCount) {
				$reciprocalSeedKeys[$seedSubstr] = true;
				if(!isset($substr_records[$seedSubstr]) || $substr_records[$seedSubstr] < $seedCount) {
					$substr_records[$seedSubstr] = $seedCount;
				}
			}
			$reciprocalSkipIntervals = $this->all_substrings_count_reciprocal_skip_intervals($string, $reciprocalSeeds);
		}
		if($preferLegacyCandidateSet) {
			// Low-fractal inputs still benefit from multidiff-derived skip intervals, but candidate ranking should
			// stay anchored to legacy verified tallies to avoid byte regressions on noisy corpora.
			$substr_records = array();
		}
	}
	$usedLegacyFallback = false;
	$skipIntervalIndex = 0;
	$skipIntervalCount = count($reciprocalSkipIntervals);
	$skippedLegacyBytes = 0;
	$recipReuseBytes = 0;
	foreach($reciprocalSeeds as $seedSubstr => $seedCount) {
		$recipReuseBytes += strlen($seedSubstr) * (int) $seedCount;
	}
	$recipReuseRatio = ($slen > 0) ? ((float) $recipReuseBytes / (float) $slen) : 0.0;
	$strongReciprocalEvidence = $reciprocalSeeds !== array()
		&& $recipCfg['legacy_skip_reuse_ratio'] > 0.0
		&& $recipReuseRatio >= (float) $recipCfg['legacy_skip_reuse_ratio'];
	$legacyFallbackAllowed = fractal_zip::substring_multidiff_legacy_fallback_enabled();
	$multidiffHasSignal = ($substr_records !== array() || $reciprocalSeeds !== array());
	$multidiffRecursiveOnly = fractal_zip::substring_multidiff_recursive_only_enabled();
	$needsLegacySlide = !$ranMultidiff
		|| ($substr_records === array() && $legacyFallbackAllowed && !$strongReciprocalEvidence);
	if($preferLegacyCandidateSet && $ranMultidiff) {
		$needsLegacySlide = true;
	}
	if($ranMultidiff && $multidiffRecursiveOnly && $multidiffHasSignal) {
		$needsLegacySlide = false;
	}
	if($needsLegacySlide && !$strongReciprocalEvidence) {
		$usedLegacyFallback = true;
		//$highest_substr_count = 0;
		while($counter < $slen - $minimum_substr_length) {
			if($skipIntervalCount > 0) {
				while($skipIntervalIndex < $skipIntervalCount && $reciprocalSkipIntervals[$skipIntervalIndex][1] <= $counter) {
					$skipIntervalIndex++;
				}
				if($skipIntervalIndex < $skipIntervalCount) {
					$iv = $reciprocalSkipIntervals[$skipIntervalIndex];
					if($counter >= $iv[0] && $counter < $iv[1]) {
						$jumpTo = (int) $iv[1];
						if($jumpTo > $counter) {
							$skippedLegacyBytes += ($jumpTo - $counter);
							$counter = $jumpTo;
							continue;
						}
					}
				}
			}
			if(count($substr_records) > $maxSubstrRecordEntries) {
				break;
			}
			//$best_substr = false;
			$counter_skip = 1;
			$sliding_counter = $minimum_substr_length;
			//while(($sliding_counter < $this->segment_length || $string[$counter + $sliding_counter + 1] === $string[$counter + $sliding_counter]) && $counter + $sliding_counter < $slen) {
			// (A || B) && C with A=sliding<max, B=ch[p+1]===ch[p], C=(p<slen) — $p = $counter + $sliding_counter; exit when !((A||B)&&C) (same as original while)
			while(true) {
				$p = $counter + $sliding_counter;
				if($p >= $slen) {
					break;
				}
				$nextSame = ($p + 1 < $slen && $string[$p + 1] === $string[$p]);
				if($sliding_counter >= $maximum_substr_length && !$nextSame) {
					break;
				}
				if($nextSame) {
				} else {
					$substr = substr($string, $counter, $sliding_counter);
					if(isset($substr_records[$substr])) {
						$substr_records[$substr]++;
						$counter_skip = $sliding_counter;
					} else {
						$substr_records[$substr] = 1;
					}
					//$best_substr = $substr;
				}
				$sliding_counter++;
				//$sliding_counter += $minimum_substr_length; // balls to the walls
			}
			$tailPiece = substr($string, $counter, $sliding_counter);
			if(isset($substr_records[$tailPiece])) {
				$substr_records[$tailPiece]++;
			} else {
				$substr_records[$tailPiece] = 1;
			}
			//if($best_substr !== false) {
			//	$substr_records[$best_substr]++;
			//}
			//$counter_skip = $sliding_counter;
			if($counter_skip < $minimum_counter_skip) {
				$counter_skip = $minimum_counter_skip;
			}
			//print('$counter_skip: ');var_dump($counter_skip);
			$counter += $counter_skip;
		}
	}
	if ($ascProf) {
		fz_inner_profile_add_ns('expand.asc.slide_probe', (int) (hrtime(true) - $tAscSeg));
		$tAscSeg = hrtime(true);
	}
	//print('$substr_records after first order: ');var_dump($substr_records);exit(0);
	// effectively doing second order processing?
	/*$scored_substr_records = array();
	foreach($substr_records as $substr => $count) {
		$scored_substr_records[$substr] = strlen($substr) * $count;
	}
	asort($scored_substr_records, SORT_NUMERIC);
	$scored_substr_records = array_reverse($scored_substr_records);
	$scored_substr_records = array_slice($scored_substr_records, 0, 1); // only keep the top one
	//$string2 = $scored_substr_records[0];
	foreach($scored_substr_records as $string2 => $count2) { break; }
	//print('$scored_substr_records, $string2: ');var_dump($scored_substr_records, $string2);
	$counter = 0;
	$minimum_counter_skip = 1;
	$substr_records = array();
	$minimum_substr_length = fractal_zip::maximum_substr_expression_length();
	$maximum_substr_length = fractal_zip::maximum_substr_expression_length() * 10;
	//$highest_substr_count = 0;
	while($counter < strlen($string2) - $minimum_substr_length) {
		$counter_skip = 1;
		$sliding_counter = $minimum_substr_length;
		while($counter + $sliding_counter < strlen($string2)) {
			$substr = substr($string2, $counter, $sliding_counter);
			$substr_records[$substr] = substr_count($string, $substr);
			$sliding_counter++;
		}
		$counter++;
	}*/
	//$substr_records = fractal_zip::get_all_substrings($string);
	// Sliding-window tallies above are a coarse probe, not true occurrence counts (short literals like `aaaaa`
	// can probe-count <2 while substr_count(raw,·)≥2). Gate duplicates on actual non‑overlapping counts and
	// store those for scoring so inner pass‑1 / duplicate‑substring candidates match theequiv/raw semantics.
	/** @var array<string, true> $haystackByte */
	$haystackRejectMask = '';
	for ($ib = 0; $ib < 256; $ib++) {
		$b = chr($ib);
		if(!isset($haystackByte[$b])) {
			$haystackRejectMask .= $b;
		}
	}
	if(!function_exists('fractal_zip_gpu_substring_verify_duplicate_records')) {
		require_once dirname(__FILE__) . DIRECTORY_SEPARATOR . 'fractal_zip_gpu_substring.php';
	}
	if(function_exists('fractal_zip_gpu_substring_slide_seeds_enabled')
		&& fractal_zip_gpu_substring_slide_seeds_enabled()
		&& function_exists('fractal_zip_gpu_substring_all_substrings_rust_slide_map')) {
		$rustSlide = fractal_zip_gpu_substring_all_substrings_rust_slide_map(
			$this,
			$string,
			$minimum_substr_length,
			$maximum_substr_length,
			$maxSubstrRecordEntries
		);
		if(is_array($rustSlide)) {
			foreach($rustSlide as $seedSub => $seedCnt) {
				if(!isset($substr_records[$seedSub]) || $substr_records[$seedSub] < $seedCnt) {
					$substr_records[$seedSub] = $seedCnt;
				}
			}
		}
	}
	if(function_exists('fractal_zip_gpu_substring_sa_merge_probe_map')) {
		$substr_records = fractal_zip_gpu_substring_sa_merge_probe_map(
			$this,
			$string,
			$substr_records,
			$minimum_substr_length,
			$maximum_substr_length
		);
	}
	if(function_exists('fractal_zip_gpu_substring_verify_enabled')
		&& fractal_zip_gpu_substring_verify_enabled()) {
		$substr_records = fractal_zip_gpu_substring_verify_duplicate_records(
			$this,
			$string,
			$substr_records,
			$haystackByte,
			$haystackRejectMask,
			$minimum_substr_length,
			$slen
		);
	} else {
		$substr_kept = array();
		foreach($substr_records as $substr => $_probeCount) {
			$needleLen = strlen($substr);
			// substr_count() counts non-overlapping occurrences; two hits need byte span ≥ 2·len(needle).
			if($needleLen === 0 || $needleLen * 2 > $slen) {
				continue;
			}
			if(strcspn($substr, $haystackRejectMask) !== $needleLen) {
				continue;
			}
			if(!fractal_zip::is_fractally_clean($substr)) {
				continue;
			}
			// Greedy left-to-right non-overlapping tally matches PHP substr_count(); single scan in core.
			$realCount = substr_count($string, $substr);
			if($realCount < 2) {
				continue;
			}
			$substr_kept[$substr] = $realCount;
		}
		$substr_records = $substr_kept;
	}
	if(!function_exists('fractal_zip_bio_multidiff_chain_enabled')) {
		require_once dirname(__FILE__) . DIRECTORY_SEPARATOR . 'fractal_zip_bioinformatics.php';
	}
	if($useMultidiff && fractal_zip_bio_multidiff_chain_enabled()) {
		$chainSeeds = fractal_zip_bio_multidiff_chain_seeds_from_string(
			$string,
			$minimum_substr_length,
			$maximum_substr_length,
			$haystackByte
		);
		$chainMerged = 0;
		$chainNew = 0;
		foreach($chainSeeds as $chainSub => $_chainProbe) {
			$needleLen = strlen($chainSub);
			if($needleLen === 0 || $needleLen * 2 > $slen) {
				continue;
			}
			if(strcspn($chainSub, $haystackRejectMask) !== $needleLen) {
				continue;
			}
			if(!fractal_zip::is_fractally_clean($chainSub)) {
				continue;
			}
			$realCount = substr_count($string, $chainSub);
			if($realCount < 2) {
				continue;
			}
			if(!isset($substr_records[$chainSub])) {
				$chainNew++;
				$chainSeedKeys[$chainSub] = true;
			}
			if(!isset($substr_records[$chainSub]) || $substr_records[$chainSub] < $realCount) {
				$substr_records[$chainSub] = $realCount;
			}
			$chainMerged++;
		}
		if($multidiffMetricsEnabled) {
			$multidiffMetrics['multidiff_bio_chain_seeds'] = count($chainSeeds);
			$multidiffMetrics['multidiff_bio_chain_merged'] = $chainMerged;
			$multidiffMetrics['multidiff_bio_chain_new'] = $chainNew;
		}
	}
	if ($ascProf) {
		fz_inner_profile_add_ns('expand.asc.verify_dup_counts', (int) (hrtime(true) - $tAscSeg));
		$tAscSeg = hrtime(true);
	}
	$prim = fractal_zip::pure_repetition_primitive_unit($string);
	if($prim !== null) {
		$pl = strlen($prim);
		if($pl >= $minimum_substr_length && fractal_zip::is_fractally_clean($prim)) {
			$nc = intdiv($slen, $pl);
			if($nc >= 2 && str_repeat($prim, $nc) === $string) {
				if(!isset($substr_records[$prim]) || $substr_records[$prim] < $nc) {
					$substr_records[$prim] = $nc;
				}
			}
		}
	}
	//print('$substr_records: ');var_dump($substr_records);
	fractal_zip::warning_once('sort the substrings according to the most promising and hopefully this in combination with only acting on better than average substrings will save some time');
	// could be smarter here!
	/** @var array<int, int> $markerLenByPieceLen */
	$markerLenByPieceLen = array();
	/** @var list<array{0:int,1:int,2:int,3:int,4:string,5:int}> $scoredRows estLin, len, -count, -(len²·count), substr, foreach-order tiebreak */
	$scoredRows = array();
	$foreachOrd = 0;
	$chainScoreScale = 1.0;
	if($chainSeedKeys !== array() && function_exists('fractal_zip_bio_multidiff_chain_score_scale')) {
		$chainScoreScale = fractal_zip_bio_multidiff_chain_score_scale();
	}
	foreach($substr_records as $substr => $count) {
		$len = strlen($substr);
		if(!isset($markerLenByPieceLen[$len])) {
			$markerLenByPieceLen[$len] = $this->estimate_inner_pass1_marker_strlen($len);
		}
		$mLen = $markerLenByPieceLen[$len];
		$estLin = $len + $slen - $count * ($len - $mLen);
		if(isset($reciprocalSeedKeys[$substr]) && $reciprocalSeedScoreScale > 0.0 && $reciprocalSeedScoreScale < 1.0) {
			$estLin = (int) floor($estLin * $reciprocalSeedScoreScale);
		}
		if(isset($chainSeedKeys[$substr]) && $chainScoreScale > 0.0 && $chainScoreScale < 1.0) {
			$estLin = (int) floor($estLin * $chainScoreScale);
		}
		if($estLin >= $slen) {
			$estLin = $slen;
		}
		// Primary: lowest naive pass-1 linear (empty dict). Tie: shorter piece. Tie: higher count. Legacy tie: len²·count. Final tie: substr_records iteration order.
		$scoredRows[] = array($estLin, $len, -$count, -($len * $len * $count), $substr, $foreachOrd++);
	}
	usort($scoredRows, static function (array $a, array $b): int {
		if($a[0] !== $b[0]) {
			return $a[0] <=> $b[0];
		}
		if($a[1] !== $b[1]) {
			return $a[1] <=> $b[1];
		}
		if($a[2] !== $b[2]) {
			return $a[2] <=> $b[2];
		}
		if($a[3] !== $b[3]) {
			return $a[3] <=> $b[3];
		}
		return $a[5] <=> $b[5];
	});
	//print('$scoredRows: ');var_dump($scoredRows);
	$baseTopK = $this->effective_substring_top_k();
	$topK = $coarseCfg['enabled'] ? min($baseTopK, $coarseCfg['top_k_cap']) : $baseTopK;
	// Bench / research: enumerate every scored duplicate substring (can be large on big inputs).
	static $allSubstringCandidatesTakeAll = null;
	if($allSubstringCandidatesTakeAll === null) {
		$envAll = getenv('FRACTAL_ZIP_ALL_SUBSTRING_CANDIDATES');
		$allSubstringCandidatesTakeAll = ($envAll === '1' || strtolower(trim((string) $envAll)) === 'true' || strtolower(trim((string) $envAll)) === 'yes');
	}
	if(!$allSubstringCandidatesTakeAll) {
		$scoredRows = array_slice($scoredRows, 0, $topK);
	}
	//$scored_substr_records = array_slice($scored_substr_records, 0, sizeof($segments_array)); // trying to balance for the fact that a very nice and long duplicated substring would be split of multiple segments
	//print('$scored_substr_records top1: ');var_dump($scored_substr_records);
	$sorted_substr_records = array();
	foreach($scoredRows as $row) {
		$substr = $row[4];
		$sorted_substr_records[$substr] = $substr_records[$substr];
	}
	//print('$substr_records, $sorted_substr_records: ');var_dump($substr_records, $sorted_substr_records);exit(0);
	//return $substr_records;
	if ($ascProf) {
		fz_inner_profile_add_ns('expand.asc.score_sort_topk', (int) (hrtime(true) - $tAscSeg));
	}
	if($multidiffMetricsEnabled) {
		$finalTopK = count($scoredRows);
		$finalVerifiedCount = count($substr_records);
		$finalVerifiedReuseBytes = 0;
		foreach($substr_records as $candSubstr => $candCount) {
			$finalVerifiedReuseBytes += strlen($candSubstr) * (int) $candCount;
		}
		$m = is_array($multidiffMetrics) ? $multidiffMetrics : array();
		$m['phase'] = 'multidiff_flow';
		$m['input_bytes'] = $slen;
		$m['multidiff_used'] = $ranMultidiff;
		$m['legacy_fallback_used'] = $usedLegacyFallback;
		$m['reciprocal_enabled'] = fractal_zip::substring_reciprocal_enabled();
		$m['reciprocal_seed_candidates_final'] = count($reciprocalSeeds);
		$m['reciprocal_skip_intervals_final'] = count($reciprocalSkipIntervals);
		$m['reciprocal_skipped_legacy_bytes'] = $skippedLegacyBytes;
		$m['reciprocal_depth'] = (int) $this->recursive_fractal_current_depth;
		$m['reciprocal_profile_label'] = (string) $this->recursive_reciprocal_profile_label;
		$m['reciprocal_profile_ratio'] = (float) $this->recursive_reciprocal_profile_ratio;
		$m['reciprocal_fractal_step_segments'] = count($this->recursive_reciprocal_fractal_step_segments);
		$m['reciprocal_reuse_ratio'] = round($recipReuseRatio, 6);
		$m['reciprocal_strong_evidence'] = $strongReciprocalEvidence;
		$m['multidiff_recursive_only'] = $multidiffRecursiveOnly;
		$m['multidiff_has_signal'] = $multidiffHasSignal;
		$m['reciprocal_legacy_skipped'] = $ranMultidiff && !$needsLegacySlide;
		$m['final_verified_candidates'] = $finalVerifiedCount;
		$m['final_topk_candidates'] = $finalTopK;
		$m['final_verified_reused_bytes'] = $finalVerifiedReuseBytes;
		$m['final_verified_reuse_ratio'] = ($slen > 0) ? round((float) $finalVerifiedReuseBytes / (float) $slen, 6) : 0.0;
		$m['ts_unix_ms'] = (int) floor(microtime(true) * 1000);
		$this->last_substring_multidiff_metrics = $m;
		$this->recursive_reciprocal_state_by_depth[(int) $this->recursive_fractal_current_depth] = array(
			'depth' => (int) $this->recursive_fractal_current_depth,
			'seed_candidates' => count($reciprocalSeeds),
			'skip_intervals' => count($reciprocalSkipIntervals),
			'skipped_legacy_bytes' => $skippedLegacyBytes,
			'final_candidates' => $finalVerifiedCount,
			'profile' => (string) $this->recursive_reciprocal_profile_label,
			'profile_ratio' => (float) $this->recursive_reciprocal_profile_ratio,
			'fractal_step_segments' => count($this->recursive_reciprocal_fractal_step_segments),
			'reuse_ratio' => round($recipReuseRatio, 6),
			'strong_evidence' => $strongReciprocalEvidence,
			'multidiff_signal' => $multidiffHasSignal,
			'recursive_only' => $multidiffRecursiveOnly,
			'legacy_skipped' => $ranMultidiff && !$needsLegacySlide,
		);
		$js = bench_json_encode_try($m, false);
		if(is_string($js)) {
			$err = @fopen('php://stderr', 'wb');
			if(is_resource($err)) {
				fwrite($err, '[fz multidiff metrics] ' . $js . "\n");
				fclose($err);
			}
		}
	}
	return $sorted_substr_records;
}

/**
 * Build fractal-step segment windows for reciprocal multidiff (marker splits, then chunking).
 *
 * @return list<array{0:int,1:int}>
 */
private function build_reciprocal_fractal_step_segments(string $string, int $segmentBytes): array {
	$n = strlen($string);
	if($n <= 0) {
		return array();
	}
	list($Lq, $Mq, $Rq) = fractal_zip_marker_rx_quoted_delimiters();
	$rxMarker = '/' . $Lq . '[0-9]+' . $Mq . '[0-9]+' . $Rq . '/s';
	$segments = array();
	$lastEnd = 0;
	if(preg_match_all($rxMarker, $string, $mm, PREG_OFFSET_CAPTURE) && isset($mm[0]) && count($mm[0]) > 0) {
		foreach($mm[0] as $m) {
			$start = (int) $m[1];
			if($start > $lastEnd) {
				$segments = array_merge($segments, $this->chunk_reciprocal_span($string, $lastEnd, $start, $segmentBytes));
			}
			$lastEnd = $start + strlen((string) $m[0]);
		}
		if($lastEnd < $n) {
			$segments = array_merge($segments, $this->chunk_reciprocal_span($string, $lastEnd, $n, $segmentBytes));
		}
		return $segments;
	}
	return $this->chunk_reciprocal_span($string, 0, $n, $segmentBytes);
}

/**
 * @return list<array{0:int,1:int}>
 */
private function chunk_reciprocal_span(string $string, int $start, int $end, int $segmentBytes): array {
	$span = $end - $start;
	if($span <= 0) {
		return array();
	}
	$segLen = max(1024, min($segmentBytes, max(4096, (int) $this->segment_length)));
	$out = array();
	for($off = $start; $off < $end; $off += $segLen) {
		$out[] = array($off, min($end, $off + $segLen));
	}
	return $out;
}

/**
 * Byte-level common-prefix/suffix seeds from a segment pair (fallback when token multidiff is empty).
 *
 * @return array<string,int>
 */
private function all_substrings_count_pair_byte_diff_seeds(string $sa, string $sb, string $haystack, int $minSeedBytes): array {
	$la = strlen($sa);
	$lb = strlen($sb);
	if($la < $minSeedBytes || $lb < $minSeedBytes) {
		return array();
	}
	$seeds = array();
	$limit = min($la, $lb);
	$pref = 0;
	while($pref < $limit && $sa[$pref] === $sb[$pref]) {
		$pref++;
	}
	$suff = 0;
	while($suff < $limit - $pref && $sa[$la - 1 - $suff] === $sb[$lb - 1 - $suff]) {
		$suff++;
	}
	if($pref >= $minSeedBytes) {
		$cand = substr($sa, 0, $pref);
		if($cand !== '' && fractal_zip::is_fractally_clean($cand)) {
			$rc = substr_count($haystack, $cand);
			if($rc >= 2) {
				$seeds[$cand] = $rc;
			}
		}
	}
	if($suff >= $minSeedBytes) {
		$cand = substr($sa, $la - $suff, $suff);
		if($cand !== '' && fractal_zip::is_fractally_clean($cand)) {
			$rc = substr_count($haystack, $cand);
			if($rc >= 2) {
				if(!isset($seeds[$cand]) || $seeds[$cand] < $rc) {
					$seeds[$cand] = $rc;
				}
			}
		}
	}
	if($sa === $sb && $la >= $minSeedBytes && fractal_zip::is_fractally_clean($sa)) {
		$rc = substr_count($haystack, $sa);
		if($rc >= 2) {
			if(!isset($seeds[$sa]) || $seeds[$sa] < $rc) {
				$seeds[$sa] = $rc;
			}
		}
	}
	return $seeds;
}

/**
 * Chunk-hash multidiff for fast long-span reuse discovery across many segment windows.
 *
 * @param list<array{0:int,1:int}> $segments
 * @param array<string, int|float|string|bool>|null $debugMetricsOut
 * @return array<string,int>
 */
private function all_substrings_count_chunkhash_diff_seeds(string $string, array $segments, int $minSubLen, int $maxSubLen, int $minSeedBytes, int $chunkBytes, int $chunkStride, int $pairBudget, ?array &$debugMetricsOut = null): array {
	$n = strlen($string);
	if($n <= 0 || $segments === array()) {
		return array();
	}
	$chunkBytes = max(64, $chunkBytes);
	$chunkStride = max(32, $chunkStride);
	$pairBudget = max(8, $pairBudget);
	$hashOffsets = array();
	$sampledChunks = 0;
	foreach($segments as $seg) {
		$s = (int) $seg[0];
		$e = (int) $seg[1];
		if($e - $s < $chunkBytes) {
			continue;
		}
		for($off = $s; $off + $chunkBytes <= $e; $off += $chunkStride) {
			$chunk = substr($string, $off, $chunkBytes);
			if($chunk === '') {
				continue;
			}
			$sampledChunks++;
			$h = sprintf('%u', crc32($chunk));
			if(!isset($hashOffsets[$h])) {
				$hashOffsets[$h] = array($off);
			} elseif(count($hashOffsets[$h]) < 24) {
				$hashOffsets[$h][] = $off;
			}
		}
	}
	$pairProbes = 0;
	$pairsHit = 0;
	$seeds = array();
	foreach($hashOffsets as $offs) {
		$k = count($offs);
		if($k < 2) {
			continue;
		}
		for($i = 0; $i < $k - 1; $i++) {
			for($j = $i + 1; $j < $k; $j++) {
				$pairProbes++;
				if($pairProbes > $pairBudget) {
					break 3;
				}
				$oa = (int) $offs[$i];
				$ob = (int) $offs[$j];
				if($oa === $ob) {
					continue;
				}
				$aChunk = substr($string, $oa, $chunkBytes);
				$bChunk = substr($string, $ob, $chunkBytes);
				if($aChunk === '' || $bChunk === '' || $aChunk !== $bChunk) {
					continue;
				}
				$pairsHit++;
				$left = 0;
				while($oa - 1 - $left >= 0 && $ob - 1 - $left >= 0) {
					if($string[$oa - 1 - $left] !== $string[$ob - 1 - $left]) {
						break;
					}
					if($chunkBytes + $left + 1 > $maxSubLen) {
						break;
					}
					$left++;
				}
				$right = 0;
				while($oa + $chunkBytes + $right < $n && $ob + $chunkBytes + $right < $n) {
					if($string[$oa + $chunkBytes + $right] !== $string[$ob + $chunkBytes + $right]) {
						break;
					}
					if($chunkBytes + $left + $right + 1 > $maxSubLen) {
						break;
					}
					$right++;
				}
				$candStart = $oa - $left;
				$candLen = $chunkBytes + $left + $right;
				if($candLen < $minSubLen || $candLen < $minSeedBytes || $candLen > $maxSubLen) {
					continue;
				}
				$cand = substr($string, $candStart, $candLen);
				if($cand === '' || !fractal_zip::is_fractally_clean($cand)) {
					continue;
				}
				$rc = substr_count($string, $cand);
				if($rc < 2) {
					continue;
				}
				if(!isset($seeds[$cand]) || $seeds[$cand] < $rc) {
					$seeds[$cand] = $rc;
				}
			}
		}
	}
	if($debugMetricsOut !== null) {
		$debugMetricsOut['reciprocal_chunkhash_chunk_bytes'] = $chunkBytes;
		$debugMetricsOut['reciprocal_chunkhash_chunk_stride'] = $chunkStride;
		$debugMetricsOut['reciprocal_chunkhash_chunks_sampled'] = $sampledChunks;
		$debugMetricsOut['reciprocal_chunkhash_hash_buckets'] = count($hashOffsets);
		$debugMetricsOut['reciprocal_chunkhash_pair_budget'] = $pairBudget;
		$debugMetricsOut['reciprocal_chunkhash_pair_probes'] = $pairProbes;
		$debugMetricsOut['reciprocal_chunkhash_pairs_hit'] = $pairsHit;
		$debugMetricsOut['reciprocal_chunkhash_seed_candidates'] = count($seeds);
	}
	return $seeds;
}

/**
 * Build reciprocal multidiff seeds by diffing fixed-size segment pairs from the current string.
 *
 * @param array<string,true> $haystackByte
 * @param array<string, int|float|string|bool>|null $debugMetricsOut
 * @return array<string,int> seed => non-overlap count
 */
private function all_substrings_count_reciprocal_segment_seeds(string $string, int $minSubLen, int $maxSubLen, array $haystackByte, ?array &$debugMetricsOut = null): array {
	$n = strlen($string);
	if(!fractal_zip::substring_reciprocal_enabled()) {
		return array();
	}
	$recipCfg = $this->substring_reciprocal_effective_config();
	if($n < (int) $recipCfg['min_bytes']) {
		return array();
	}
	$segBytes = (int) $recipCfg['segment_bytes'];
	$pairBudget = (int) $recipCfg['max_pair_probes'];
	$minSeedBytes = (int) $recipCfg['min_seed_bytes'];
	$chunkBytes = (int) $recipCfg['chunk_bytes'];
	$chunkStride = (int) $recipCfg['chunk_stride'];
	$chunkPairBudget = (int) $recipCfg['chunk_hash_pairs'];
	$segments = $this->recursive_reciprocal_fractal_step_segments;
	if($segments === array()) {
		$segments = $this->build_reciprocal_fractal_step_segments($string, $segBytes);
	}
	$sCount = count($segments);
	if($sCount < 2) {
		return array();
	}
	$pairProbes = 0;
	$byteDiffHits = 0;
	$chunkHashHits = 0;
	$chunkMetrics = array();
	$seeds = array();
	$chunkSeeds = $this->all_substrings_count_chunkhash_diff_seeds(
		$string,
		$segments,
		$minSubLen,
		$maxSubLen,
		$minSeedBytes,
		$chunkBytes,
		$chunkStride,
		$chunkPairBudget,
		$chunkMetrics
	);
	if($chunkSeeds !== array()) {
		foreach($chunkSeeds as $cand => $count) {
			if(!isset($seeds[$cand]) || $seeds[$cand] < $count) {
				$seeds[$cand] = $count;
			}
		}
	}
	if(isset($chunkMetrics['reciprocal_chunkhash_pairs_hit'])) {
		$chunkHashHits = (int) $chunkMetrics['reciprocal_chunkhash_pairs_hit'];
	}
	for($i = 0; $i < $sCount - 1; $i++) {
		for($j = $i + 1; $j < $sCount; $j++) {
			$pairProbes++;
			if($pairProbes > $pairBudget) {
				break 2;
			}
			$a = $segments[$i];
			$b = $segments[$j];
			$sa = substr($string, (int) $a[0], (int) ($a[1] - $a[0]));
			$sb = substr($string, (int) $b[0], (int) ($b[1] - $b[0]));
			if($sa === '' || $sb === '') {
				continue;
			}
			$pairBlob = $sa . "\n" . $sb;
			$pairMetrics = null;
			$pairCandidates = $this->all_substrings_count_multidiff_candidates($pairBlob, $minSubLen, $maxSubLen, $haystackByte, $pairMetrics);
			if($pairCandidates === array()) {
				$byteSeeds = $this->all_substrings_count_pair_byte_diff_seeds($sa, $sb, $string, $minSeedBytes);
				if($byteSeeds !== array()) {
					$byteDiffHits++;
					foreach($byteSeeds as $cand => $probeCount) {
						if(!isset($seeds[$cand]) || $seeds[$cand] < $probeCount) {
							$seeds[$cand] = $probeCount;
						}
					}
				}
				continue;
			}
			foreach($pairCandidates as $cand => $probeCount) {
				$cLen = strlen($cand);
				if($cLen < $minSeedBytes) {
					continue;
				}
				$realCount = substr_count($string, $cand);
				if($realCount < 2) {
					continue;
				}
				if(!isset($seeds[$cand]) || $seeds[$cand] < $realCount) {
					$seeds[$cand] = $realCount;
				}
			}
		}
	}
	if($debugMetricsOut !== null) {
		$debugMetricsOut['reciprocal_segments'] = $sCount;
		$debugMetricsOut['reciprocal_segment_source'] = ($this->recursive_reciprocal_fractal_step_segments !== array()) ? 'fractal_step' : 'built';
		$debugMetricsOut['reciprocal_pair_budget'] = $pairBudget;
		$debugMetricsOut['reciprocal_pair_probes'] = $pairProbes;
		$debugMetricsOut['reciprocal_byte_diff_hits'] = $byteDiffHits;
		$debugMetricsOut['reciprocal_chunkhash_hits'] = $chunkHashHits;
		foreach($chunkMetrics as $k => $v) {
			$debugMetricsOut[$k] = $v;
		}
		$debugMetricsOut['reciprocal_seed_candidates'] = count($seeds);
		$reuseBytes = 0;
		foreach($seeds as $k => $c) {
			$reuseBytes += strlen($k) * (int) $c;
		}
		$debugMetricsOut['reciprocal_seed_reused_bytes'] = $reuseBytes;
		$debugMetricsOut['reciprocal_seed_reuse_ratio'] = ($n > 0) ? round((float) $reuseBytes / (float) $n, 6) : 0.0;
	}
	return $seeds;
}

/**
 * Build merged skip intervals from the strongest reciprocal seeds.
 *
 * @param array<string,int> $reciprocalSeeds
 * @return list<array{0:int,1:int}> [start,endExclusive], sorted and merged
 */
private function all_substrings_count_reciprocal_skip_intervals(string $string, array $reciprocalSeeds): array {
	if($reciprocalSeeds === array()) {
		return array();
	}
	$rows = array();
	foreach($reciprocalSeeds as $seed => $count) {
		$rows[] = array($seed, (int) $count, strlen($seed) * (int) $count);
	}
	usort($rows, static function (array $a, array $b): int {
		if($a[2] !== $b[2]) {
			return $b[2] <=> $a[2];
		}
		return strlen($b[0]) <=> strlen($a[0]);
	});
	$maxSeeds = $this->substring_reciprocal_effective_config()['max_skip_seeds'];
	if(count($rows) > $maxSeeds) {
		$rows = array_slice($rows, 0, $maxSeeds);
	}
	$intervals = array();
	foreach($rows as $r) {
		$seed = (string) $r[0];
		$sLen = strlen($seed);
		if($sLen < 2) {
			continue;
		}
		$off = 0;
		while(true) {
			$p = strpos($string, $seed, $off);
			if($p === false) {
				break;
			}
			$intervals[] = array((int) $p, (int) $p + $sLen);
			$off = (int) $p + $sLen;
		}
	}
	if($intervals === array()) {
		return array();
	}
	usort($intervals, static function (array $a, array $b): int {
		return $a[0] <=> $b[0];
	});
	$merged = array();
	$cur = $intervals[0];
	for($i = 1, $n = count($intervals); $i < $n; $i++) {
		$iv = $intervals[$i];
		if($iv[0] <= $cur[1]) {
			if($iv[1] > $cur[1]) {
				$cur[1] = $iv[1];
			}
			continue;
		}
		$merged[] = $cur;
		$cur = $iv;
	}
	$merged[] = $cur;
	return $merged;
}

/**
 * Fast candidate discovery by diffing token streams at repeated anchors ("multidiff"), then validating with real non-overlap counts.
 *
 * @param array<string, true> $haystackByte
 * @param array<string, int|float|string|bool>|null $debugMetricsOut
 * @return array<string, int> candidate => probe count
 */
private function all_substrings_count_multidiff_candidates(string $string, int $minSubLen, int $maxSubLen, array $haystackByte, ?array &$debugMetricsOut = null): array {
	$maxTokens = fractal_zip::substring_multidiff_max_tokens();
	$maxAnchorOccurs = fractal_zip::substring_multidiff_max_anchor_occurs();
	$maxPairProbes = fractal_zip::substring_multidiff_max_pair_probes();
	$minAnchorBytes = fractal_zip::substring_multidiff_min_anchor_bytes();
	$maxCandidates = fractal_zip::substring_multidiff_max_candidates();
	$metricsOn = $debugMetricsOut !== null;
	if($metricsOn) {
		$debugMetricsOut = array(
			'multidiff_pair_probe_budget' => $maxPairProbes,
			'multidiff_max_tokens_budget' => $maxTokens,
			'multidiff_max_candidates_budget' => $maxCandidates,
			'multidiff_min_anchor_bytes' => $minAnchorBytes,
		);
	}
	$rxToken = '/[^\r\n\t ,;:|\/\\\\\-_=\+\.\(\)\[\]\{\}<>]+|[\r\n\t ,;:|\/\\\\\-_=\+\.\(\)\[\]\{\}<>]+/s';
	$mm = array();
	if(preg_match_all($rxToken, $string, $mm, PREG_OFFSET_CAPTURE) !== false && isset($mm[0])) {
	} else {
		return array();
	}
	$tokens = array();
	$anchorMap = array();
	$tokenCount = 0;
	$anchorOccurrencesKept = 0;
	foreach($mm[0] as $row) {
		$tok = (string) $row[0];
		$off = (int) $row[1];
		$len = strlen($tok);
		if($len <= 0) {
			continue;
		}
		$isDelim = strspn($tok, "\r\n\t ,;:|/\\-_=+.()[]{}<>") === $len;
		$tokens[] = array(
			's' => $tok,
			'o' => $off,
			'l' => $len,
			'd' => $isDelim,
		);
		$ti = $tokenCount;
		$tokenCount++;
		if($tokenCount > $maxTokens) {
			return array();
		}
		if($isDelim || $len < $minAnchorBytes) {
			continue;
		}
		if(!isset($anchorMap[$tok])) {
			$anchorMap[$tok] = array($ti);
			$anchorOccurrencesKept++;
			continue;
		}
		if(count($anchorMap[$tok]) < $maxAnchorOccurs) {
			$anchorMap[$tok][] = $ti;
			$anchorOccurrencesKept++;
		}
	}
	if($metricsOn) {
		$anchorTokensRepeated = 0;
		foreach($anchorMap as $idxListProbe) {
			if(count($idxListProbe) >= 2) {
				$anchorTokensRepeated++;
			}
		}
		$debugMetricsOut['multidiff_token_count'] = $tokenCount;
		$debugMetricsOut['multidiff_anchor_tokens_unique'] = count($anchorMap);
		$debugMetricsOut['multidiff_anchor_occurrences_kept'] = $anchorOccurrencesKept;
		$debugMetricsOut['multidiff_anchor_tokens_repeated'] = $anchorTokensRepeated;
	}
	if($tokenCount < 2 || $anchorMap === array()) {
		return array();
	}
	$substrRecords = array();
	$pairProbes = 0;
	$acceptedEvents = 0;
	$pairProbeLimitHit = false;
	$acceptedTokenSeen = $metricsOn ? array() : null;
	foreach($anchorMap as $anchorToken => $idxList) {
		$k = count($idxList);
		if($k < 2) {
			continue;
		}
		for($ii = 0; $ii < $k - 1; $ii++) {
			$a = (int) $idxList[$ii];
			$b = (int) $idxList[$ii + 1];
			if($a < 0 || $b < 0 || $a >= $tokenCount || $b >= $tokenCount || $a === $b) {
				continue;
			}
			$pairProbes++;
			if($pairProbes > $maxPairProbes) {
				$pairProbeLimitHit = true;
				break 2;
			}
			$leftA = $a;
			$leftB = $b;
			while($leftA > 0 && $leftB > 0) {
				$pa = $tokens[$leftA - 1];
				$pb = $tokens[$leftB - 1];
				if($pa['s'] !== $pb['s']) {
					break;
				}
				$candStart = (int) $tokens[$leftA - 1]['o'];
				$candEnd = (int) $tokens[$a]['o'] + (int) $tokens[$a]['l'];
				if(($candEnd - $candStart) > $maxSubLen) {
					break;
				}
				$leftA--;
				$leftB--;
			}
			$rightA = $a + 1;
			$rightB = $b + 1;
			while($rightA < $tokenCount && $rightB < $tokenCount) {
				$na = $tokens[$rightA];
				$nb = $tokens[$rightB];
				if($na['s'] !== $nb['s']) {
					break;
				}
				$candStart = (int) $tokens[$leftA]['o'];
				$candEnd = (int) $na['o'] + (int) $na['l'];
				if(($candEnd - $candStart) > $maxSubLen) {
					break;
				}
				$rightA++;
				$rightB++;
			}
			$candStart = (int) $tokens[$leftA]['o'];
			$lastIdx = $rightA - 1;
			if($lastIdx < $leftA) {
				continue;
			}
			$candEnd = (int) $tokens[$lastIdx]['o'] + (int) $tokens[$lastIdx]['l'];
			$candLen = $candEnd - $candStart;
			if($candLen < $minSubLen || $candLen > $maxSubLen) {
				continue;
			}
			$substr = substr($string, $candStart, $candLen);
			if($substr === '' || !fractal_zip::is_fractally_clean($substr)) {
				continue;
			}
			$needleLen = strlen($substr);
			if($needleLen * 2 > strlen($string)) {
				continue;
			}
			$okBytes = true;
			for($bi = 0; $bi < $needleLen; $bi++) {
				if(!isset($haystackByte[$substr[$bi]])) {
					$okBytes = false;
					break;
				}
			}
			if(!$okBytes) {
				continue;
			}
			$realCount = substr_count($string, $substr);
			if($realCount < 2) {
				continue;
			}
			$acceptedEvents++;
			if($metricsOn) {
				for($ti = $leftA; $ti <= $lastIdx; $ti++) {
					$acceptedTokenSeen[$ti] = true;
				}
			}
			if(!isset($substrRecords[$substr]) || $substrRecords[$substr] < $realCount) {
				$substrRecords[$substr] = $realCount;
			}
			if(count($substrRecords) >= $maxCandidates) {
				break 2;
			}
		}
	}
	if(!function_exists('fractal_zip_bio_multidiff_chain_enabled')) {
		require_once dirname(__FILE__) . DIRECTORY_SEPARATOR . 'fractal_zip_bioinformatics.php';
	}
	if(fractal_zip_bio_multidiff_chain_enabled()) {
		$chainSeeds = fractal_zip_bio_multidiff_self_chain_seeds(
			$string,
			$tokens,
			$anchorMap,
			$minSubLen,
			$maxSubLen,
			$haystackByte
		);
		foreach($chainSeeds as $chainSub => $chainCount) {
			if(!isset($substrRecords[$chainSub]) || $substrRecords[$chainSub] < $chainCount) {
				$substrRecords[$chainSub] = $chainCount;
			}
			if(count($substrRecords) >= $maxCandidates) {
				break;
			}
		}
		if($metricsOn) {
			$debugMetricsOut['multidiff_bio_chain_seeds'] = count($chainSeeds);
		}
	}
	if($metricsOn) {
		$acceptedUniqueCandidates = count($substrRecords);
		$acceptedUniqueBytes = 0;
		$acceptedReuseBytes = 0;
		foreach($substrRecords as $candSub => $candCount) {
			$candLen = strlen($candSub);
			$acceptedUniqueBytes += $candLen;
			$acceptedReuseBytes += $candLen * (int) $candCount;
		}
		$acceptedTokenCoverageCount = is_array($acceptedTokenSeen) ? count($acceptedTokenSeen) : 0;
		$debugMetricsOut['multidiff_anchor_pairs_probed'] = $pairProbes;
		$debugMetricsOut['multidiff_pair_probe_limit_hit'] = $pairProbeLimitHit;
		$debugMetricsOut['multidiff_accepted_events'] = $acceptedEvents;
		$debugMetricsOut['multidiff_accepted_candidates'] = $acceptedUniqueCandidates;
		$debugMetricsOut['multidiff_accepted_total_bytes'] = $acceptedUniqueBytes;
		$debugMetricsOut['multidiff_accepted_reused_bytes'] = $acceptedReuseBytes;
		$debugMetricsOut['multidiff_accepted_reuse_ratio'] = (strlen($string) > 0) ? round((float) $acceptedReuseBytes / (float) strlen($string), 6) : 0.0;
		$debugMetricsOut['multidiff_token_coverage_proxy_count'] = $acceptedTokenCoverageCount;
		$debugMetricsOut['multidiff_token_coverage_proxy_ratio'] = ($tokenCount > 0) ? round((float) $acceptedTokenCoverageCount / (float) $tokenCount, 6) : 0.0;
	}
	return $substrRecords;
}

