}

function walk_the_path($path, $fractal_paths) {
	//print('$path, $fractal_paths in walk_the_path: ');var_dump($path, $fractal_paths);
	//$this->walk_the_path_debug_counter++;
	//if($this->walk_the_path_debug_counter > 1) {
	//	fractal_zip::fatal_error('$this->walk_the_path_debug_counter > 1');
	//}
	if(count($path) > 1) {
		return fractal_zip::walk_the_path(array_slice($path, 1), $fractal_paths[$path[0]][0]);
	} else {
		return $fractal_paths[$path[0]];
	}
}

function recursive_fractal_substring($string, $fractal_string, $fractal_paths = array(), $path = array(), $recursion_counter = 0, $last_score = false) {
	if($last_score === false) {
		//$last_score = $this->fractal_path_branch_trimming_score;
		//$last_score = 1 / $this->fractal_path_branch_trimming_multiplier; // (identity)
		$last_score = 1; // (identity)
	}
	$best_score = $last_score;
	//print('$string, $fractal_string, $fractal_paths, $path at the start of recursive_fractal_substring: ');var_dump($string, $fractal_string, $fractal_paths, $path);
	//print('rfs0001<br>');exit(0);
	//$did_something = true;
	//while($did_something) {
	//	$did_something = false;	
		//$zipped_string = '';
		$initial_string = $string;
		$initial_fractal_string = $fractal_string;
		$initial_path = $path;
		if($recursion_counter === 0) {
			$this->recursive_fractal_entry_strlen = strlen($initial_string);
			$this->recursive_fractal_max_seconds = fractal_zip::max_recursive_fractal_seconds();
			$this->recursive_fractal_max_analysis_bytes = fractal_zip::max_fractal_analysis_bytes();
			$profile = fractal_zip::substring_reciprocal_profile($initial_string);
			$this->recursive_reciprocal_profile_label = (string) $profile[0];
			$this->recursive_reciprocal_profile_ratio = (float) $profile[1];
			$secondsScale = (float) $profile[3];
			if($this->recursive_fractal_max_seconds > 0 && $secondsScale > 0.0 && $secondsScale !== 1.0) {
				$this->recursive_fractal_max_seconds = max(0.25, $this->recursive_fractal_max_seconds * $secondsScale);
			}
		}
		if($this->recursive_fractal_max_seconds === null) {
			$this->recursive_fractal_max_seconds = fractal_zip::max_recursive_fractal_seconds();
		}
		if($this->recursive_fractal_max_analysis_bytes === null) {
			$this->recursive_fractal_max_analysis_bytes = fractal_zip::max_fractal_analysis_bytes();
		}
		$maxFractalRec = $this->recursive_fractal_max_analysis_bytes;
		$recStrLen = strlen($initial_string);
		if($maxFractalRec > 0 && $recStrLen > $maxFractalRec) {
			return $fractal_paths;
		}
		if($recursion_counter === 0 || $this->recursive_fractal_effective_max_depth === null) {
			$bd = fractal_zip::max_recursive_fractal_depth();
			$profileDepthAdjust = 0;
			if($recursion_counter === 0) {
				$profile = fractal_zip::substring_reciprocal_profile($initial_string);
				$profileDepthAdjust = (int) $profile[2];
			}
			$effective = fractal_zip::fractal_large_entry_effective_max_depth((int) $this->recursive_fractal_entry_strlen, $bd);
			$this->recursive_fractal_effective_max_depth = max(2, min(32, $effective + $profileDepthAdjust));
		}
		if($recursion_counter > $this->recursive_fractal_effective_max_depth) {
			fractal_zip::warning_once('recursive_fractal_substring depth limit reached; pruning deep branch');
			return $fractal_paths;
		}
		if($this->recursive_fractal_max_seconds > 0 && microtime(true) - $this->initial_micro_time > $this->recursive_fractal_max_seconds) {
			fractal_zip::warning_once('recursive_fractal_substring time budget reached; pruning deep branch');
			return $fractal_paths;
		}
		// Truncation-style guard: reciprocal recursion should shrink aggressively with depth.
		// Similar spirit as multifractal truncation — if a branch stays too large at depth, prune it.
		if($recursion_counter >= 2 && $this->recursive_fractal_entry_strlen > 0) {
			$profileMul = 1.0;
			if($this->recursive_reciprocal_profile_label === 'high') {
				$profileMul = 1.45;
			} elseif($this->recursive_reciprocal_profile_label === 'low') {
				$profileMul = 0.9;
			}
			$depthDen = pow((float) ($recursion_counter + 1), 1.35);
			$expectedMaxBytes = (int) ceil(((float) $this->recursive_fractal_entry_strlen * $profileMul) / max(1.0, $depthDen));
			$expectedMaxBytes = max(8192, $expectedMaxBytes);
			if($recStrLen > $expectedMaxBytes) {
				$prevState = $this->recursive_reciprocal_state_by_depth[$recursion_counter - 1] ?? null;
				$prevStrong = is_array($prevState) && !empty($prevState['strong_evidence']);
				if(!$prevStrong) {
					fractal_zip::warning_once('recursive_fractal_substring truncation guard pruned oversized non-shrinking branch');
					return $fractal_paths;
				}
			}
		}
