		$homeZstd = is_string($home) && $home !== '' ? rtrim($home, '/\\') . DIRECTORY_SEPARATOR . 'bin' . DIRECTORY_SEPARATOR . 'zstd' : null;
		foreach(array($homeZstd, '/usr/bin/zstd', '/usr/local/bin/zstd') as $abs) {
			if(is_string($abs) && $abs !== '' && is_executable($abs)) {
				$found = $abs;
